#include <pthread.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <list>
#include <mutex>
#include <condition_variable>

struct Connection {
    int sockfd;
    sockaddr_in peer_addr;
};

class TCPConnectionManager {
private:
    std::list<Connection> connections;
    std::mutex connections_mutex;
    std::condition_variable connections_cv;
    std::atomic_int num_connections{0};
    pthread_mutex_t external_service_mutex;
    bool external_service_available{true};

public:
    TCPConnectionManager() {
        pthread_mutex_init(&external_service_mutex, nullptr);
    }

    void addConnection(int sockfd, const sockaddr_in& peer_addr) {
        std::unique_lock<std::mutex> lock(connections_mutex);
        connections.emplace_back(Connection{sockfd, peer_addr});
        num_connections++;
        lock.unlock();
        connections_cv.notify_one();
    }

    bool removeConnection(int sockfd) {
        std::unique_lock<std::mutex> lock(connections_mutex);
        auto it = std::find_if(connections.begin(), connections.end(),
                               [&](const Connection &conn) { return conn.sockfd == sockfd; });

        if (it != connections.end()) {
            connections.erase(it);
            num_connections--;
            lock.unlock();
            return true;
        }
        lock.unlock();
        return false;
    }

    void listConnections() const {
        std::unique_lock<std::mutex> lock(connections_mutex);
        for (const auto &conn : connections) {
            printf("Socket: %d, Peer IP: %s, Port: %u\n", conn.sockfd,
                   inet_ntoa(conn.peer_addr.sin_addr), ntohs(conn.peer_addr.sin_port));
        }
    }

    void handleExternalService() {
        pthread_mutex_lock(&external_service_mutex);
        while (external_service_available) {
            // Periodic checks on connections...
            pthread_mutex_unlock(&external_service_mutex);
            std::unique_lock<std::condition_variable> external_service_cv(connections_cv);
            connections_cv.wait(external_service_cv, [&]() { return !external_service_available; });
            pthread_mutex_lock(&external_service_mutex);
        }
        pthread_mutex_unlock(&external_service_mutex);
    }
};
```

This code provides a basic structure for managing TCP connections in a multi-threaded environment. It uses a dynamic array (std::list) to store connection metadata, with thread synchronization using std::mutex and std::condition\_variable. The `addConnection`, `removeConnection`, and `listConnections` functions allow for adding, removing, and listing connections respectively.

The external service integration is handled by the `handleExternalService()` function which should be executed in a separate thread. This function periodically checks the status of the connections while considering potential network latencies. When the service becomes unavailable, it notifies other threads using the condition\_variable to wait for its availability again.']

