#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <stdbool.h>

typedef struct Record {
    int value;
} Record;

typedef struct Node {
    Record data;
    struct Node* left;
    struct Node* right;
} Node;

Node* create_node(Record data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    new_node->data = data;
    new_node->left = NULL;
    new_node->right = NULL;
    return new_node;
}

Node* rotate_left(Node* p) {
    Node* q = p->right;
    p->right = q->left;
    q->left = p;
    return q;
}

Node* rotate_right(Node* q) {
    Node* p = q->left;
    q->left = p->right;
    p->right = q;
    return p;
}

int get_balance(Node* node) {
    if (!node)
        return 0;
    return height(node->right) - height(node->left);
}

int height(Node* node) {
    if (!node)
        return 0;
    return 1 + (height(node->left) > height(node->right) ? height(node->left) : height(node->right));
}

void insert_record(Node** root, Record data) {
    if (*root == NULL) {
        *root = create_node(data);
        return;
    }

    int cmp = data.value - ((*root)->data).value;
    if (cmp < 0) {
        insert_record(&((*root)->left), data);
        balance(*root);
    } else if (cmp > 0) {
        insert_record(&((*root)->right), data);
        balance(*root);
    }
}

Record find_min(Node* node) {
    while (node->left != NULL) {
        node = node->left;
    }
    return node->data;
}

Record remove_record(Node** root, Record data) {
    if (*root == NULL) {
        perror("No such record");
        exit(EXIT_FAILURE);
    }

    int cmp = data.value - ((*root)->data).value;
    Node** node_to_remove = (cmp < 0) ? &((*root)->left) : (&(*root)->right);
    if ((*node_to_remove) == NULL) {
        perror("No such record");
        exit(EXIT_FAILURE);
    }

    Node* temp = *node_to_remove;
    Record min_value;
    if (temp->left == NULL) {
        *node_to_remove = temp->right;
        min_value = temp->data;
        free(temp);
    } else if (temp->right == NULL) {
        *node_to_remove = temp->left;
        min_value = temp->data;
        free(temp);
    } else {
        min_value = find_min(temp->right);
        (*node_to_remove)->data = min_value;
        *node_to_remove->right = remove_record((&(*root)->right), min_value);
    }

    balance(*root);
    return min_value;
}

void balance(Node* node) {
    int b = get_balance(node);

    if (b > 1) {
        if (get_balance(node->left) < 0)
            node->left = rotate_right(node->left);
        node = rotate_left(node);
    } else if (b < -1) {
        if (get_balance(node->right) > 0)
            node->right = rotate_left(node->right);
        node = rotate_right(node);
    }
}

void insert_long_offsets(int num_elements, long* offsets, int* keys, size_t record_size) {
    Record* records = (Record*)calloc(num_elements, sizeof(Record));
    if (!records) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < num_elements; ++i) {
        records[i].value = keys[i];
    }

    for (int i = 0; i < num_elements; ++i) {
        records[i].value += offsets[i % record_size];
    }

    // Insert records into the BST here...
}

