#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>

int max_valid_integer(void) {
    int *numbers = NULL;
    size_t capacity = 0, count = 0;
    char input[256];

    while (true) {
        printf("Enter an integer or type 'end' to quit: ");
        if (fgets(input, sizeof(input), stdin) == NULL || fgetc(stdin) == EOF) break;

        input[strcspn(input, "\n")] = '\0'; // Remove newline character
        if (strlen(input) > 1) {
            printf("Invalid input: Please enter an integer or 'end'\n");
            continue;
        }

        long long number;
        errno = 0;
        number = strtoll(input, NULL, 10);

        if (errno == ERANGE) {
            printf("Invalid input: Please enter a valid integer\n");
            continue;
        }

        if (number < INT_MIN || number > INT_MAX) {
            printf("Invalid input: The entered integer is out of the range of an int\n");
            continue;
        }

        // Reallocate memory and copy existing numbers
        if (capacity == count) {
            capacity *= 2;
            numbers = realloc(numbers, capacity * sizeof(int));
            if (!numbers) {
                perror("Reallocation failed");
                exit(EXIT_FAILURE);
            }
        }

        // Save the entered integer to the array and update count
        numbers[count++] = (int)number;
    }

    // Find the maximum valid integer
    int max = numbers[0];
    for (size_t i = 1; i < count; ++i) {
        if (numbers[i] > max) max = numbers[i];
    }

    // Free memory and return the result
    free(numbers);
    return max, count;
}
