['```c
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

// Custom Semaphore structure
typedef struct _semaphore {
    pthread_sem_t sem;
    unsigned int ref_count;
} Semaphore;

// Function to initialize and allocate a new semaphore with given value
Semaphore* init_semaphore(unsigned int initial_value) {
    Semaphore *s = malloc(sizeof(Semaphore));
    pthread_sem_init(&s->sem, NULL, initial_value);
    s->ref_count = 1;
    return s;
}

// Function to acquire a semaphore. If the semaphore cannot be acquired (because count reaches 0), the thread will block until it can.
void acquire(Semaphore *s) {
    pthread_sem_wait(&s->sem);
    ++s->ref_count;
}

// Function to release a semaphore, decreasing the current count and waking up a blocked thread if needed.
void release(Semaphore *s) {
    --s->ref_count;
    pthread_sem_post(&s->sem);
}

// Function to delete a semaphore and free its resources
void delete_semaphore(Semaphore **ptr) {
    Semaphore *s = *ptr;
    if (s == NULL) return;
    pthread_sem_destroy(&s->sem);
    free(s);
    *ptr = NULL;
}

// Function to manage dynamic allocation and deallocation of semaphores based on fluctuating thread counts and workload demands.
Semaphore** allocate_semaphores(unsigned int num_threads, unsigned int initial_value) {
    Semaphore **semaphores = calloc(num_threads, sizeof(Semaphore*));
    if (semaphores == NULL) return semaphores;

    for (size_t i = 0; i < num_threads; ++i) {
        semaphores[i] = init_semaphore(initial_value);
        // Log the creation of each semaphore here if desired
    }

    return semaphores;
}

// Function to deallocate semaphores when they are no longer needed.
void deallocate_semaphores(Semaphore **semaphores, unsigned int num_threads) {
    for (size_t i = 0; i < num_threads; ++i) {
        delete_semaphore(&semaphores[i]);
        // Log the deletion of each semaphore here if desired
    }

    free(semaphores);
}
```

This code provides a basic structure for managing dynamic semaphores in a multi-threaded environment. The `init_semaphore`, `acquire`, and `release` functions serve as building blocks for working with semaphores, while the `allocate_semaphores` and `deallocate_semaphores` functions handle the dynamic allocation and deallocation of semaphores. Developers can adjust the initial value of the semaphore when allocating to meet their desired level of concurrency and minimize contention.']

