        std::this_thread::sleep_for(std::chrono::milliseconds((1000 - duration % 1000)));
    }
}

bool rateLimiter(const std::chrono::steady_clock::time_point& startTime) {
    auto elapsed = std::chrono::duration_cast<std::chrono::seconds>(std::chrono::steady_clock::now() - startTime).count();
    if (elapsed >= 60) {
        requestCounter = 0;
    }
    return requestCounter++ < config.maxRequestsPerMinute;
}

