namespace RandomService {

class ThreadSafeRandom {
public:
    explicit ThreadSafeRandom(unsigned long seed) : mt_(seed), pool_() {
        for (size_t i = 0; i < numThreads_; ++i) {
            std::thread(&ThreadSafeRandom::initGenerator, this).detach();
        }
    }

    ~ThreadSafeRandom() {
        stop_.store(true);
        generators_.join_all();
    }

    int getInt(unsigned int min, unsigned int max) {
        std::lock_guard<std::mutex> lock(mutex_);
        size_t index = currentGenerator_;
        ++currentGenerator_ %= numThreads_;
        return generators_[index].twir_.minstd_rand0()(min, max);
    }

    double getDouble(double min, double max) {
        std::lock_guard<std::mutex> lock(mutex_);
        size_t index = currentGenerator_;
        ++currentGenerator_ %= numThreads_;
        return generators_[index].twir_.uniform_real2() * (max - min) + min;
    }

    unsigned long getSeed() const {
        std::lock_guard<std::mutex> lock(mutex_);
        return mt_.get_state().data();
    }

    void setSeed(unsigned long seed) {
        std::lock_guard<std::mutex> lock(mutex_);
        mt_.reseed(boost::mt19937::reseed_t{seed});
    }

    nlohmann::json getStatistics() const {
        std::lock_guard<std::mutex> lock(mutex_);
        nlohmann::json result;
        for (const auto& generator : generators_) {
            result[generator.name_] = generator.requests_;
        }
        return result;
    }

private:
    struct Generator {
        boost::mt19937 twir_;
        std::string name_;
        unsigned int requests_ = 0;

        Generator(size_t index) : twir_(index + seed_) {
            name_ = "Generator" + std::to_string(index);
        }
    };

    void initGenerator() {
        while (true) {
            if (stop_.load()) break;
            Generator generator(generators_.size());
            {
                std::lock_guard<std::mutex> lock(mutex_);
                generators_.emplace_back(generator);
            }
            ++numRequests_;
        }
    }

    unsigned long seed_;
    unsigned int numThreads_ = std::thread::hardware_concurrency();
    mutable std::mutex mutex_;
    std::atomic<size_t> currentGenerator_ = 0;
    boost::mt19937 mt_;
    std::vector<Generator> generators_;
    std::atomic_bool stop_{false};
    unsigned int numRequests_ = 0;
};

