```javascript
const express = require('express');
const bodyParser = require('body-parser');
const cors = require('cors');
const jwt = require('jsonwebtoken');
const bcryptjs = require('bcryptjs');
const redis = require('redis');
const client = redis.createClient();

// Database connection (using pg-promise)
const db = require('./db');

const app = express();
app.use(bodyParser.json());
app.use(cors());

// Helper function to verify the token and get user ID
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) return res.sendStatus(401); // Unauthorized

  jwt.verify(token, process.env.ACCESS_TOKEN_SECRET, (err, user) => {
    if (err) return res.sendStatus(403); // Forbidden
    req.user = user;
    next();
  });
}

// API routes for managing profiles
app.get('/profiles/:id', authenticateToken, async (req, res) => {
  try {
    const userId = req.user.id;
    const cacheKey = `profile_${req.params.id}`;
    const cachedProfile = await client.get(cacheKey);

    if (cachedProfile) return res.json(JSON.parse(cachedProfile));

    const profile = await db('profiles')
      .where({ id: req.params.id, user_id: userId })
      .first();

    if (!profile) return res.status(404).send('Profile not found.');

    await client.setex(cacheKey, 60 * 15, JSON.stringify(profile)); // Cache for 15 minutes
    res.json(profile);
  } catch (err) {
    console.error(err);
    res.status(500).send('Internal Server Error.');
  }
});

app.post('/profiles', authenticateToken, async (req, res) => {
  try {
    const userId = req.user.id;
    const { name, email, preferences } = req.body;

    // Validate input data and business rules here

    await db('profiles').insert({ user_id: userId, name, email, preferences })
      .onConflictDoUpdateSet(req.body)
      .returning('*');

    res.status(201).json(res.locals.profile); // Set the profile object in locals during the query execution
  } catch (err) {
    console.error(err);
    res.status(500).send('Internal Server Error.');
  }
});

app.put('/profiles/:id', authenticateToken, async (req, res) => {
  try {
    const userId = req.user.id;
    const profileId = parseInt(req.params.id);

    // Validate input data and business rules here

    const [numRowsAffected] = await db('profiles')
      .where({ id: profileId, user_id: userId })
      .update(req.body)
      .returning('*');

    if (numRowsAffected === 0) return res.status(404).send('Profile not found.');

    const updatedProfile = await db('profiles')
      .where({ id: profileId, user_id: userId })
      .first();

    // Update the cache if necessary
    await client.del(`profile_${profileId}`);
    await client.setex(`profile_${profileId}`, 60 * 15, JSON.stringify(updatedProfile));

    res.json(updatedProfile);
  } catch (err) {
    console.error(err);
    res.status(500).send('Internal Server Error.');
  }
});

// Run the server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`Server is running on port ${PORT}`));
```

Remember to create a `.env` file for environment variables and a `db` folder containing the database connection script (e.g., `index.js`) using a library like `pg-promise`. Additionally, you might want to add extra functionalities such as concurrent update handling, caching eviction policies, fallback mechanisms for the external authentication service, etc.

Lastly, consider implementing logging using libraries like Winston or Bunyan for comprehensive auditing purposes while minimizing overhead and storage costs."]

