        $id = isset($_REQUEST['id']) ? intval($_REQUEST['id']) : null;
        $name = trim($_REQUEST['name']);
        $email = trim($_REQUEST['email']);
        $password = trim($_REQUEST['password']);

        if (!$this->ValidateData($name, $email, $password)) {
