        $query = ($id ? "UPDATE users SET name = ?, email = ?, password = ? WHERE id = ?" : "INSERT INTO users (name, email, password) VALUES (?, ?, ?)");
        $stmt = $this->db->prepare($query);
        $params = [$name, $email, $password];
        if ($id) {
            array_push($params, $id);
        }
        $stmt->execute($params);
        return $id ?: $this->db->lastInsertId();
    }

    private function GetDataById($id) {
        $query = "SELECT * FROM users WHERE id = ?";
        $stmt = $this->db->prepare($query);
        $stmt->execute([$id]);
        return $stmt->fetch(PDO::FETCH_ASSOC);
    }

    private function DeleteAccount($id) {
        // Using transactions to ensure atomic deletion.
        try {
            $this->db->beginTransaction();
            $this->DeleteUserData($id);
            $this->DeleteAssociatedData($id);
            $this->db->commit();
        } catch (\Exception $e) {
            $this->db->rollback();
            // Log the error for debugging purposes.
