    private static final String DEFAULT_THEME_DIRECTORY = "themes";
    private static File themeDirectory;
    private static int appVersionCode;

    public void init(File themeDir, int version) {
        themeDirectory = themeDir != null ? themeDir : new File(DEFAULT_THEME_DIRECTORY);
        appVersionCode = version;
    }

    public ThemeState loadThemeStateFromCache(String cacheFileName) throws IOException, ClassNotFoundException {
        if (!themeDirectory.exists() || !themeDirectory.isDirectory()) {
            return null;
        }

        Path themeFilePath = Paths.get(themeDirectory.getPath(), cacheFileName);
        if (!Files.exists(themeFilePath) || !Files.isReadable(themeFilePath)) {
            return null;
        }

        File themeFile = themeFilePath.toFile();
        if (!themeFile.getParentFile().equals(themeDirectory)) {
            return null;
        }

        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(themeFile))) {
            ThemeState themeState = (ThemeState) ois.readObject();
            if (validateVersion(themeState)) {
                clearBitmapIfNeeded();
                return themeState;
            } else {
                logWarning("Loaded theme state has an incompatible version.");
                clearBitmapIfNeeded();
                return null;
            }
        } catch (ClassNotFoundException e) {
            logError("Unable to load cached theme state.", e);
            return null;
        }
    }

    private void clearBitmapIfNeeded() {
        Bitmap bitmap = getCurrentThemeBitmap();
        if (bitmap != null) {
            bitmap.recycle();
            bitmap = null;
        }
    }

    private boolean validateVersion(ThemeState themeState) {
        Manifest manifest = new JarFile(getClass().getProtectionDomain().getCodeSource().getLocation().getPath()).getManifest();
        int appVersion = manifest.getMainAttributes().getIntValue("Manifest-Version");
