template<typename Iterator, typename ValueType>
void insertAfter(Iterator target, const ValueType& value) {
    if (target == std::end(std::forward_list<ValueType>())) {
        *target = value;
    } else {
        Iterator prev = target;
        ++prev;
        *prev = value;
    }
}

int main() {
    std::forward_list<std::string> list = {"target", "value1", "value2"}; // Replace with actual values
    auto it = list.begin();
    std::string target = "target";
    std::string newValue = "new value";

    if (it != list.end() && *it == target) {
        insertAfter(it, newValue);
    } else {
        list.emplace_back(newValue);
    }

    // Iterate and print the list for demonstration purposes
    for (const auto& value : list) {
        std::cout << value << " ";
    }
    std::cout << std::endl;

    return 0;
}
