struct file_context {
    char *filename;
    int fd;
    pthread_mutex_t lock;
    struct stat st;
};

typedef struct file_context file_context_t;

void *load_file(void *arg) {
    file_context_t *ctx = arg;
    char *buffer = NULL;
    size_t buffer_size = 0;
    ssize_t bytes_read;

    while ((bytes_read = read(ctx->fd, &buffer[buffer_size], sizeof(buffer) - buffer_size)) > 0) {
        buffer_size += bytes_read;
        if (buffer_size == sizeof(buffer)) {
            buffer = realloc(buffer, buffer_size * 2);
        }
    }

    if (bytes_read < 0) {
        perror("Error reading file");
        free(buffer);
        close(ctx->fd);
        free(ctx);
        return NULL;
    }

    ctx->st.st_size = buffer_size;

    if (!is_valid_javascript(buffer, buffer_size)) {
        printf("Skipping invalid file: %s\n", ctx->filename);
        free(buffer);
        close(ctx->fd);
        free(ctx);
        return NULL;
    }

    json_object *file_info = parse_javascript(buffer, buffer_size);
    free(buffer);

    if (!file_info) {
        perror("Error parsing JavaScript file");
        close(ctx->fd);
        free(ctx);
        return NULL;
    }

