    // ...

    json_object_put(file_info);
    free(ctx);

    return NULL;
}

int process_files(char **filenames, size_t count) {
    file_context_t *files = malloc(count * sizeof(file_context_t));
    pthread_t threads[count];
    int err = 0;

    for (size_t i = 0; i < count; ++i) {
        files[i].filename = filenames[i];
        if ((files[i].fd = open(filenames[i], O_RDONLY)) < 0) {
            perror("Error opening file");
            err++;
            continue;
        }
        pthread_mutex_init(&files[i].lock, NULL);
        files[i].st.st_size = 0;
    }

    for (size_t i = 0; i < count; ++i) {
        if (!err && pthread_create(&threads[i], NULL, load_file, &files[i])) {
            perror("Error creating thread");
            err++;
        }
    }

    for (size_t i = 0; i < count; ++i) {
        if (!err && pthread_join(threads[i], NULL)) {
            perror("Error joining thread");
            err++;
        }
    }

    for (size_t i = 0; i < count; ++i) {
        close(files[i].fd);
        pthread_mutex_destroy(&files[i].lock);
    }

    free(files);

    return err;
}

