    private static final ScheduledExecutorService cacheInvalidator = Executors.newScheduledThreadPool(1);
    private static final int CACHE_INVALIDATION_INTERVAL_SECS = 60;

    public static Customer getCustomer(long customerId) {
        Customer customer = customerCache.get(customerId);
        if (customer != null) {
            return customer;
        }

        Response response = ClientBuilder.newClient().target("http://my-restful-api.com/api/customers/" + customerId).request().get();
        if (response.getStatusInfo().toBucket(Response.Status.class) == Response.Status.OK) {
            Customer newCustomer = response.readEntity(Customer.class);
            customerCache.putIfAbsent(customerId, newCustomer);
            return newCustomer;
        } else {
            logError(response);
            return null;
        }
    }

    private static void logError(Response response) {
        // Implement logging for debugging purposes.
    }

    public static void clearCache() {
        customerCache.clear();
    }

    private static void cacheInvalidatorTask() {
        clearCache();
    }

    public static void main(String[] args) {
        cacheInvalidator.scheduleWithFixedDelay(this::cacheInvalidatorTask, 0, CACHE_INVALIDATION_INTERVAL_SECS, TimeUnit.SECONDS);
        // ... Other initialization and system dependencies setup code.
