const fs = require('fs');
const path = require('path');
const yargs = require('yargs');
const asyncResourceManager = require('./asyncResourceManager');
const config = require('./config');

class Certificate {
  constructor(keyPath, certPath) {
    this.keyPath = keyPath;
    this.certPath = certPath;
  }
}

function generateCertificateBundle(oauthRequest) {
  const env = oauthRequest.env || 'development';
  const configKeyPath = path.join(config[env].paths.privateKeys, 'key.pem');
  const configCertPath = path.join(config[env].paths.certificates, 'cert.pem');

  return new Promise((resolve, reject) => {
    if (!fs.existsSync(configKeyPath)) {
      return reject(new Error(`Missing private key file at ${configKeyPath}`));
    }

    if (!fs.existsSync(configCertPath)) {
      return reject(new Error(`Missing certificate file at ${configCertPath}`));
    }

    const certificate = new Certificate(configKeyPath, configCertPath);

    asyncResourceManager.addTask('key', () => fs.readFileSync(certificate.keyPath));
    asyncResourceManager.addTask('cert', () => fs.readFileSync(certificate.certPath));

    asyncResourceManager.runTasks((err, results) => {
      if (err) return reject(err);

      const key = results['key'];
      const cert = results['cert'];

      if (!key || !cert) {
        return reject(new Error('Failed to read certificate files'));
      }

      resolve(Buffer.concat([key, cert]));
    });
  });
}
```

Here is the `asyncResourceManager` code:

```javascript
class AsyncResourceManager {
  constructor() {
    this.tasks = new Map();
    this.activeTasks = new Set();
  }

  addTask(name, func) {
    this.tasks.set(name, func);
  }

  runTasks(callback) {
    const runningTasks = [...this.tasks.values()].reduce((promiseChain, taskFunc) => {
      return promiseChain.then(() => new Promise((resolve, reject) => {
        const task = taskFunc();
        this.activeTasks.add(task);

        task.on('data', data => {
          this.emitTaskData(name, data);
        });

        task.on('error', error => {
          this.emitError(error);
        });

        task.on('end', () => {
          this.activeTasks.delete(task);
          this.cleanup();
        });
      }));
    }, Promise.resolve());

    runningTasks.then(() => callback(null, this.getTaskResults()));
  }

  emitTaskData(name, data) {
    if (this.activeTasks.has(name)) {
      this.tasks.get(name).push(data);
    } else {
      console.error(`Ignoring emitted data for task ${name}: task no longer active`);
    }
  }

  emitError(error) {
    if (this.activeTasks.size > 0) {
      this.activeTasks.forEach(task => {
        task.emit('error', error);
      });
    } else {
      console.error(`Ignoring emitted error: no active tasks`);
    }
  }

  getTaskResults() {
    const results = {};

    for (const [name, taskFunc] of this.tasks) {
      results[name] = taskFunc().getBuffer();
    }

    return results;
  }

  cleanup() {
    for (const task of this.activeTasks) {
      if (!task._destroyed) {
        task.destroy();
        task._destroyed = true;
      }
    }
  }
}
```"]

