typedef struct Element {
    size_t start, end;
    jsmntok_t token;
} Element;

Element* get_text_elements(const char *html, const char *selector, size_t limit) {
    jsmn_parser parser;
    jsmn_init(&parser);
    jsmn_size_t elements = 0;
    jsmn_token_t *tokens = NULL;

    // Parse the HTML document with JSMN, ignoring the CSS selector for now
    jsmn_parse(html, strlen(html), &parser, NULL, &elements);

    size_t allocated = 0;
    Element *result = malloc(allocated * sizeof(*result));
    for (size_t i = 0; i < elements; ++i) {
        // Allocate memory for the element array dynamically as needed
        if (allocated == allocated + 1) {
            allocated += 8;
            Element *new_result = realloc(result, allocated * sizeof(*result));
            if (!new_result) {
                free(result);
                return NULL;
            }
            result = new_result;
        }
        result[i].start = tokens[i].start;
        result[i].end = tokens[i].end;
    }

    size_t num_matches = 0;
    jsmn_parse(html, strlen(html), &parser, tokens + elements, sizeof(tokens) / sizeof(*tokens) - elements);

    for (size_t i = 0; i < elements + (sizeof(tokens) / sizeof(*tokens) - elements); ++i) {
        if (strncmp(selector, tokens[i].type, strlen(tokens[i].type)) == 0) {
            Element *element = &result[num_matches];
            element->start = tokens[i].start;
            element->end = tokens[i].end;

            size_t size = 0;
            for (size_t j = element->start; j < element->end && j < strlen(html); ++j) {
                if (html[j] == '\n' || html[j] == '\r') continue; // Ignore line breaks
                size++;
                if (size >= limit) break;
            }

            char *text = malloc(sizeof(*text) * (element->end - element->start));
            for (size_t j = element->start, k = 0; j < element->end && j < strlen(html); ++j) {
                if (html[j] == '\n' || html[j] == '\r') continue; // Ignore line breaks
                text[k++] = html[j];
            }
            text[k] = '\0';

            if (size < limit) {
                size_t new_size = num_matches + 1;
                Element *new_result = realloc(result, new_size * sizeof(*result));
                if (!new_result) {
                    free(text);
                    return NULL;
                }
                result = new_result;
                result[new_size - 1] = (Element){ .start = element->start, .end = element->end + strlen(text), .token = {0} };
                result[new_size - 1].token.type = text;
            } else {
                free(text);
                result[num_matches].token.type = NULL;
            }
            num_matches++;
        }
    }

    // Terminate the array with a NULL pointer
    result[num_matches] = (Element){0};

    return &result[0];
}
