typedef struct {
    int theme_id;
    int num_fields;
    void* fields;
} Theme;

typedef struct CacheNode {
    Theme theme;
    struct CacheNode *next;
} CacheNode;

CacheNode *cache_head = NULL;
int max_cache_size = 1000;
long long total_lines = 0;

void free_theme(Theme* theme) {
    if (theme->fields) {
        free(theme->fields);
    }
    free(theme);
}

void free_cache() {
    CacheNode *current = cache_head, *temp;
    while (current != NULL) {
        temp = current->next;
        free_theme(&current->theme);
        free(current);
        current = temp;
    }
    cache_head = NULL;
}

Theme* get_or_create_theme(int theme_id) {
    CacheNode *current = cache_head;
    while (current != NULL) {
        if (current->theme.theme_id == theme_id) {
            return &current->theme;
        }
        current = current->next;
    }
    Theme* new_theme = malloc(sizeof(Theme));
    new_theme->theme_id = theme_id;
    new_theme->num_fields = 0;
    new_theme->fields = NULL;

    CacheNode *new_node = malloc(sizeof(CacheNode));
    new_node->theme = *new_theme;
    new_node->next = cache_head;
    cache_head = new_node;
    if (cache_head->next != NULL && total_lines >= max_cache_size) {
        free_cache();
        max_cache_size *= 2;
    }
    return &new_theme->theme;
}

int parse_line(char* line, int* fields, int* num_fields) {
    char* token = strtok(line, ",");
    *num_field = 0;
    while (token != NULL) {
        if (*num_field >= 2) return -1; // Too many fields
        fields[*num_field] = atoi(token);
        token = strtok(NULL, ",");
        (*num_field)++;
    }
    return 0;
}

void process_theme_file(char* filepath) {
    FILE *file = fopen(filepath, "r");
    if (!file) return;

    char line[1024];
    int fields[3] = {0};
    int num_fields = 0;
    long long start_time = clock();

    while (fgets(line, sizeof(line), file)) {
        total_lines++;
