#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <libtiff/tiff.h>
#include <openssl/md5.h>

typedef struct {
    uint16_t bits_per_sample;
    uint16_t samples_per_pixel;
    int photometric_interpretation;
    int compression;
    uint32_t rows_per_strip;
    uint32_t strip_offsets[TIFFGetStripCount(tif)];
    uint32_t strip_bytecounts[TIFFGetStripCount(tif)];
    uint8_t md5_hash[MD5_DIGEST_LENGTH];
} TiffMetadata;

TiffMetadata parse_tiff_image(const char* filename) {
    TIFF *tif = TIFFOpen(filename, "r");
    if (!tif) {
        fprintf(stderr, "Error: Unable to open file %s\n", filename);
        exit(EXIT_FAILURE);
    }

    TiffMetadata metadata;

    metadata.bits_per_sample = TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE);
    metadata.samples_per_pixel = TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL);
    metadata.photometric_interpretation = TIFFGetField(tif, TIFFTAG_PHOTOMETRICINTERPRETATION);
    metadata.compression = TIFFGetField(tif, TIFFTAG_COMPRESSION);
    metadata.rows_per_strip = TIFFGetField(tif, TIFFTAG_ROWSPERSTRIP);

    int strip_count = TIFGetStripCount(tif);
    for (int i = 0; i < strip_count; ++i) {
        metadata.strip_offsets[i] = TIFFGetFieldPosition(tif, TIFFTAG_STRIP_OFFSETS);
        metadata.strip_bytecounts[i] = TIFFGetFieldPosition(tif, TIFFTAG_STRIP_BYTECOUNTS + i);
    }

    uint8_t* image_data = malloc((TIFFSizeof(tif) - TIFFCompressOffset(tif)) * metadata.samples_per_pixel);

    tsize_t datalen;
    uint32_t offset, bytecount;
    for (int i = 0; i < strip_count; ++i) {
        offset = metadata.strip_offsets[i];
        bytecount = metadata.strip_bytecounts[i];
        TIFFReadEncodedStrip(tif, i, image_data + offset * metadata.samples_per_pixel, &datalen);
    }

    uint8_t raw_image_data[TIFFSizeof(tif) - TIFFCompressOffset(tif)];
    memcpy(raw_image_data, image_data, sizeof(raw_image_data));

    MD5_CTX ctx;
    MD5_Init(&ctx);
    MD5_Update(&ctx, raw_image_data, TIFFSizeof(tif) - TIFFCompressOffset(tif));
    MD5_Final(metadata.md5_hash, &ctx);

    TIFFClose(tif);
    free(image_data);

    return metadata;
}
