size_t get_char_count(const char *filename, const char delimiter) {
    size_t count = 0;
    for (size_t i = 0; filename[i]; ++i) {
        if (filename[i] != delimiter) {
            ++count;
        }
    }
    return count;
}

int main(int argc, char **argv) {
    if (argc < 3 || strlen(argv[1]) >= sizeof(long) * CHAR_BIT + 1) {
        fprintf(stderr, "Invalid input: expected a filename smaller than %zu characters.\n", sizeof(long) * CHAR_BIT + 1);
        return EXIT_FAILURE;
    }

    const char *extension = ".txt";
    const char delimiter = '/'; // directory separator
    const size_t max_sequence_length = 5;

    // Replace spaces and special characters with underscores
    char *sanitized_filename = malloc(strlen(argv[1]) + 1);
    strcpy(sanitized_filename, argv[1]);
    for (size_t i = 0; sanitized_filename[i]; ++i) {
        if (!isalnum(sanitized_filename[i]) && sanitized_filename[i] != '_') {
            sanitized_filename[i] = '_';
        }
    }

    // Count character frequencies and construct numerical sequence
    long frequency[256];
    long total_frequency = 0;
    for (size_t i = 0, n = get_char_count(sanitized_filename, delimiter); i < n; ++i) {
        if (++frequency[(unsigned char)sanitized_filename[i]] > total_frequency) {
            total_frequency = frequency[(unsigned char)sanitized_filename[i]];
        }
    }

    long sequence[max_sequence_length];
    size_t sequence_length = 0;
    for (size_t i = 0, n = get_char_count(sanitized_filename, delimiter); i < n; ++i) {
        if (frequency[(unsigned char)sanitized_filename[i]] <= total_frequency) {
            sequence[sequence_length++] = sanitized_filename[i];
        }
    }

    // Ensure the numerical sequence does not exceed 5 digits
    if (sequence_length > max_sequence_length) {
        sequence[max_sequence_length - 1] = '9';
    }

    // Append the numerical sequence to the original filename
    char *output_filename = malloc(strlen(sanitized_filename) + max_sequence_length + strlen(extension) + 2);
    sprintf(output_filename, "%s_%ld", sanitized_filename, total_frequency);
    strcat(output_filename, ".");
    strcat(output_filename, extension);

    printf("Output filename: %s\n", output_filename);
    free(sanitized_filename);
    free(sequence);
    free(output_filename);
    return EXIT_SUCCESS;
}
```
