['1. For AES-256-CBC cipher initialization function (`aes_init.c`)

```c
#include <openssl/evp.h>
#include <openssl/pbkdf2.h>
#include <string.h>
#include <stdlib.h>

EVP_CIPHER_CTX* aes_init(const char *password, size_t *key_len, size_t *iv_len) {
    const EVP_CIPHER_idx_t cipher = EVP_aes_256_cbc();
    unsigned char key[EVP_MAX_KEY_LENGTH];
    unsigned char iv[EVP_MAX_IV_LENGTH];
    int password_len = strlen(password);

    if (password_len < 4) {
        fprintf(stderr, "Password is too weak\n");
        return NULL;
    }

    // Use PBKDF2 with HMAC-SHA256 as the key derivation function (KDF).
    int salt_len = 8;
    unsigned char salt[salt_len];
    memset(salt, 0x31, salt_len); // Use a simple constant salt.
    const int dkLen = EVP_CIPHER_key_length(cipher) * 8;
    unsigned char derivedKey[dkLen];
    PBKDF2_HMAC((EVP_sha256(), cipher->nid), password, password_len, salt, salt_len, dkLen, 100000, derivedKey);

    int key_idx = 0;
    for (size_t i = 0; i < sizeof(key) && i < dkLen; ++i) {
        if (EVP_CIPHER_keysize(cipher) > 1)
            key[key_idx++] = derivedKey[i >> 3] >> ((~i & 7) * 8 + 4) & 0x7f;
    }
    *key_len = key_idx;

    int iv_idx = 0;
    for (size_t i = 0; i < sizeof(iv) && i < dkLen; ++i) {
        if (EVP_CIPHER_iv_length(cipher) > 1)
            iv[iv_idx++] = derivedKey[i >> 3] >> ((~i & 7) * 8 + 4) & 0x7f;
    }
    *iv_len = iv_idx;

    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Failed to allocate cipher context\n");
        return NULL;
    }

    if (1 != EVP_EncryptInit_ex(ctx, cipher, NULL, key, iv)) {
        fprintf(stderr, "Error initializing AES-256-CBC cipher\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}
