**Main.java:**

```java
import java.io.File;
import java.util.concurrent.*;
import org.apache.commons.io.FilenameUtils;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class Main {
    private static final Logger LOGGER = LoggerFactory.getLogger(Main.class);

    public static void main(String[] args) throws InterruptedException, ExecutionException {
        if (args.length != 2) {
            System.out.println("Usage: java Main <numberOfFiles> <commandLineTool>");
            return;
        }

        int numberOfFiles = Integer.parseInt(args[0]);
        String commandLineTool = args[1];

        ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        BlockingQueue<Callable<Void>> taskQueue = new LinkedBlockingQueue<>(numberOfFiles);

        for (int i = 0; i < numberOfFiles; i++) {
            final int fileIndex = i;
            taskQueue.add(new Callable<Void>() {
                @Override
                public Void call() throws Exception {
                    File fileToProcess = File.createTempFile("generated", null);
                    LOGGER.info("Generated temporary file: {}", fileToProcess.getAbsolutePath());

                    ProcessBuilder processBuilder = new ProcessBuilder(commandLineTool, fileToProcess.getAbsolutePath());
                    Process process = processBuilder.start();

                    int exitValue = process.waitFor();
                    LOGGER.info("Command execution finished with exit value: {}", exitValue);

                    if (!fileToProcess.delete()) {
                        LOGGER.error("Failed to delete temporary file: {}", fileToProcess.getAbsolutePath());
                    }

                    return null;
                }
            });
        }

        Future<?> submitAll = executor.submit(() -> {
            while (!taskQueue.isEmpty()) {
                Callable<Void> task = taskQueue.take();
                try {
                    task.call();
                } catch (Exception e) {
                    LOGGER.error("Error processing file: {}", e.getMessage());
                }
            }
        });

        submitAll.get();
        executor.shutdownNow();
    }
}
```

