#include <stdio.h>
#include <stdbool.h>
#include <string.h>
#include <openssl/aes.h>
#include <openssl/des.h>
#include <openssl/err.h>
#include <pthread.h>

typedef struct {
    char* session_token;
    struct connection* conn;
    void (*callback)(char*, int);
} data_args;

struct connection {
    char* host;
    char* message; // Base64 encoded message to decrypt
    EVP_CIPHER_CTX *decr_ctx;
    bool network_ready;
    pthread_mutex_t mutex;
} conn;

int processSecureData(data_args* args) {
    if (!args->session_token || !args->conn || strlen(args->session_token) == 0 || args->conn->host[0] == '\0' || !args->conn->callback)
        return -1; // Invalid input

    pthread_mutex_lock(&args->conn->mutex);
    if (!args->conn->network_ready || !args->conn->decr_ctx) {
        pthread_mutex_unlock(&args->conn->mutex);
        return -2; // Network not ready or no decryption context
    }
    char* msg = args->conn->message;
    EVP_CIPHER_CTX *ctx = args->conn->decr_ctx;
    pthread_mutex_unlock(&args->conn->mutex);

    int len = strlen(msg);
    unsigned char in[len];
    unsigned char out[len + AES_BLOCK_SIZE];
    base64_decode((unsigned char*)in, msg, len);

    if (EVP_DecryptInit_ex(ctx, NULL, NULL, args->conn->key, args->conn->iv) <= 0) {
        ERR_print_errors_fp(stderr);
        return -3; // Decryption initialization error
    }

    if (1 > EVP_DecryptUpdate(ctx, out, &len, in, len) <= 0 || 1 > EVP_DecryptFinal_ex(ctx, out + len, &len) <= 0) {
        ERR_print_errors_fp(stderr);
        return -4; // Decryption update or final error
    }

    args->conn->callback(out, 0); // Call the callback with the decrypted message
    return 0; // Successful decryption
}
```

