using Serilog;

public class UserHashGenerator
{
    private readonly BlockingCollection<Task> _tasks = new BlockingCollection<Task>();
    private Timer _rateLimiter;
    private readonly MD5 _md5;

    public UserHashGenerator()
    {
        _md5 = MD5.Create();
        _rateLimiter = new Timer(RateLimitCallback, null, TimeSpan.Zero, TimeSpan.FromMinutes(1));
    }

    public async Task GenerateUserHash(string input)
    {
        if (input == null || string.IsNullOrWhiteSpace(input)) return;

        var task = Task.Run(() =>
        {
            _rateLimiter.Dispose(); // Ensure only one rate limiter per instance
            _rateLimiter = new Timer(RateLimitCallback, null, TimeSpan.Zero, TimeSpan.FromMinutes(1));

            try
            {
                var hash = _md5.ComputeHash(Encoding.ASCII.GetBytes(input));
                var hashedValue = BitConverter.ToString(hash).Replace("-", "").ToLowerInvariant();

                // Write your logging implementation here
                Log.Information($"Generated Hash: {hashedValue} for Input: {input}");

                AddToTasks(Task.FromResult(hashedValue));
            }
            catch (Exception ex)
            {
                Log.Error(ex, $"Failed to generate hash for Input: {input}");
            }
        });

        _tasks.Add(task);
    }

    private void RateLimitCallback(object state)
    {
        Interlocked.Decrement(ref _rateLimiter._dueTimeTicks);
    }

    private void AddToTasks(Task task)
    {
        _tasks.Add(task);
        Task.WhenAll(_tasks.GetConsumingEnumerable());
    }
}
