```java
import java.io.*;
import java.util.logging.Logger;
import java.util.Map;
import com.google.protobuf.InvalidProtocolBufferException; // If using Protocol Buffers or Thrift

public class Deserializer {
    private static final Logger LOGGER = Logger.getLogger(Deserializer.class.getName());
    private static final int MAGIC_NUMBER = 0xCAFEBABE; // Change this according to your needs
    private Map<Integer, Class<?>> classMap; // Store different versions of the class

    public Object deserialize(byte[] data) throws IOException {
        if (data == null || data.length < 4) {
            throw new InvalidDataFormatException("Invalid byte array length.");
        }

        if (data[0] != MAGIC_NUMBER) {
            throw new InvalidDataFormatException("Magic number does not match.");
        }

        try {
            ByteArrayInputStream bis = new ByteArrayInputStream(data);
            ObjectInputStream ois = new ObjectInputStream(bis);
            Class<?> clazz = classMap.get(data[1] & 0xFF); // Version identifier

            if (clazz == null) {
                for (Class<?> candidate : classMap.values()) {
                    if (candidate.isAssignableFrom(ObjectInputStream.getClass())) {
                        clazz = candidate;
                        break;
                    }
                }
            }

            if (clazz == null) {
                LOGGER.warning("Unknown version of the serialized object. Failed to deserialize.");
                throw new InvalidDataFormatException("Unknown version of the serialized object.");
            }

            Object result = ois.readObject();
            ois.close();
            return clazz.cast(result);
        } catch (ClassNotFoundException e) {
            LOGGER.warning("Failed to find class during deserialization: " + e.getMessage());
            throw new RuntimeException(e);
        }
    }
}
```

