    const params = {
        Bucket: storageBucket,
        Key: uniqueId,
        Body: url,
        ACL: 'public-read', // Adjust as per your requirements
        ContentType: response.headers['content-type']
    };

    let uploadPromise = s3.upload(params).promise();
    const promises = _.throttle(() => {
        uploadPromise = s3.upload(params, function (err, data) {
            if (err) {
                logger.error(`Error uploading file: ${JSON.stringify(err)}`);
                throw err;
            }
            return data;
        });
    }, THROTTLE_INTERVAL); // Adjust the interval as per your needs

    try {
        const result = await Promise.race(Array.from({ length: NUM_PARALLEL_UPLOADS }, () => promises()));
        return { uploadUrl: result.Location, timestamp: new Date(), fileHash };
    } catch (error) {
        logger.error(`Error during upload: ${JSON.stringify(error)}`);
