const { spawn, exec } = require('child_process');
const performance = require('perf_hooks').performance;
const log = console.log;
const monitoringTool = require('./monitoring-tool'); // Replace with your actual monitoring tool module

function executeShellCommand(command, options = {}) {
  if (!command) throw new Error('Command must be provided.');

  const startTime = performance.now();
  const maxMemoryUsage = options.maxMemoryUsage || 100; // Default to 100MB
  const maxCpuUsage = options.maxCpuUsage || 0.5; // Default to 0.5 CPU cores

  let childProcess;
  try {
    childProcess = spawn(command, {
      shell: true,
      maxMemoryUsage,
      cpuUsage: maxCpuUsage,
      stdio: 'inherit', // Inherit the parent process's stdio streams
    });

    monitoringTool.startMonitoring(childProcess);

    childProcess.on('error', (err) => {
      log(`Command execution error: ${err}`);
      monitoringTool.logError(err);
    });

    childProcess.on('exit', (code, signal) => {
      monitoringTool.stopMonitoring();
      if (code !== 0) {
        log(`Command execution failed with code ${code} and signal ${signal}`);
        monitoringTool.logError(`Command execution failed with code ${code} and signal ${signal}`);
      } else {
        const elapsedTime = performance.now() - startTime;
        log(`Command executed successfully in ${elapsedTime} ms`);
        monitoringTool.logSuccess(`Command executed successfully in ${elapsedTime} ms`);
      }
    });
  } catch (error) {
    log(`Error while spawning child process: ${error}`);
    monitoringTool.logError(error);
  }

  // If exec is required for cross-platform compatibility, handle it here.
}
