pub struct ConfigManager {
    config_dir: PathBuf,
    env_vars: HashMap<String, String>,
    log: logging::Logger,
}

impl ConfigManager {
    pub fn new() -> Self {
        let config_dir = self.create_or_get_config_dir();
        let env_vars = self.initialize_env_vars();
        let log = logging::init_logger("config_manager");

        ConfigManager { config_dir, env_vars, log }
    }

    fn create_or_get_config_dir(&self) -> PathBuf {
        let config_dir = self.get_env_var("CONFIG_DIR").unwrap_or_else(|_| {
            let home_dir = dirs::home_dir().expect("Home directory not found.");
            home_dir.join(".config")
        });

        if !config_dir.exists() {
            create_dir_all(&config_dir).unwrap();
        }

        config_dir
    }

    fn initialize_env_vars(&self) -> HashMap<String, String> {
        let mut env_vars = HashMap::new();
        for (key, val) in env::vars() {
            if key.starts_with("CONFIG_") {
                env_vars.insert(key, val);
            }
        }
        env_vars
    }

    pub fn set_env_var(&self, key: &str, value: &str) {
        self.log.info(&format!("Setting environment variable: {} = {}", key, value));
        env::set_var(key, value);
    }

    pub fn get_env_var<T>(&self, key: &str) -> std::result::Result<T, std::env::VarError> {
        self.log.debug(&format!("Retrieving environment variable: {}", key));
        env::var(key)
    }

    pub fn remove_dir_all(&self, path: &PathBuf) {
        if let Err(e) = remove_dir_all(path) {
            self.log.error(&format!("Failed to delete directory {}: {}", path.display(), e));
        } else {
            self.log.info(&format!("Deleted directory {}", path.display()));
        }
    }
}
```

