class DynamicJsonParser:
    def __init__(self, config: Config, service_registry: Dict[str, Callable[[Dict[str, Any]], Type]]):
        self.config = config
        self.service_registry = service_registry
        self.cache = redis.Redis(client_class=redis.StrictRedis, **config.cache_params)

    @lru_cache(maxsize=128, typed=True)
    def _get_cached(self, service_id: str, json_data: Dict[str, Any]):
        key = f"{service_id}:{json.dumps(json_data)}"
        return self.cache.get(key)

    @lru_cache(maxsize=128, typed=True)
    def _parse(self, service_id: str, json_data: Dict[str, Any]):
        model_class = self.service_registry[service_id](json_data)
        if not isinstance(_get_cached(self, service_id, json_data), bytes):
            result = model_class()
            for key, value in json_data.items():
                setattr(result, key, value)
            self._store_cache(service_id, json_data, result)
        else:
            result = pickle.loads(_get_cached(self, service_id, json_data))
        return result

    def _store_cache(self, service_id: str, json_data: Dict[str, Any], parsed_obj: Any):
        key = f"{service_id}:{json.dumps(json_data)}"
        self.cache.setex(key, self.config.cache_ttl, pickle.dumps(parsed_obj))

    def parse(self, service_id: str, json_payload: str) -> Any:
        try:
            parsed_json = json.loads(json_payload)
