// Key Derivation Function (Argon2id)
#define ARGON2_API_VERSION 0x0901
#include <argon2/argon2.h>

typedef struct {
    AES_KEY aes;
    unsigned char iv[AES_BLOCK_SIZE];
} AESContext;

void generateIV(unsigned char *iv) {
    memset(iv, 0, AES_BLOCK_SIZE);
    for (size_t i = 0; i < sizeof(iv); ++i) iv[i] ^= rand();
}

AESContext *aesInit(const char *password, size_t passwordLen) {
    if (!password || !passwordLen) return NULL;

    AESContext *ctx = malloc(sizeof(AESContext));
    if (!ctx) goto error;

    generateIV(ctx->iv);

    // Key derivation using Argon2id with default parameters
    argon2_ context;
    argon2t_out out;
    argon2i_params params = ARGON2_ID;

    argon2i_init(&context, password, passwordLen, ARGON2_API_VERSION, &params);
    argon2i_derivedKey(NULL, 32, 0, &context, &out.secret);

    AES_set_encrypt_key((const unsigned char *)out.secret, AES_KEYSIZE_256, &ctx->aes);

    return ctx;
error:
    free(ctx);
    return NULL;
}

int *readIntegers() {
    size_t capacity = 10;
    int *arr = malloc(capacity * sizeof(int));
    if (!arr) return NULL;

    size_t count = 0;
    while (1) {
        int input;
        if (scanf("%d", &input) != 1) break;

        // Resize array when needed
        if (count == capacity) {
            capacity *= 2;
            arr = realloc(arr, capacity * sizeof(int));
            if (!arr) goto error;
        }

        arr[count++] = input;
    }

error:
    // Free all memory except the array itself to avoid potential leaks
    free((void*)(&arr + 1));

    // If an error occurred, return NULL and reset count to 0
    if (arr) *((size_t *)((char*)arr + sizeof(int) * count)) = count;
    else count = 0;

    return arr;
}

int main() {
    const char password[] = "password123"; // Placeholder for actual password
    AESContext *ctx = aesInit(password, strlen(password));

    int *numbers = readIntegers();
    if (!numbers) return 1;

    // Encryption/Decryption or other functions would go here

    free(numbers);
    return 0;
}
