#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <pthread.h>

typedef struct _NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG ue_tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    // Additional fields can be added here if needed
} NFAPI_CRC_INDICATION_PDU_T;

struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
};

struct ue_list {
    struct node* head;
    size_t size;
    pthread_mutex_t lock;
};

void init_ue_list(struct ue_list* list) {
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_ue() {
    NFAPI_CRC_INDICATION_PDU_T* ue = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!ue) return NULL;
    memset(ue, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    return ue;
}

void add_ue(struct ue_list* list, NFAPI_CRC_INDICATION_PDU_T* ue) {
    pthread_mutex_lock(&list->lock);

    struct node *new_node = malloc(sizeof(struct node));
    if (!new_node) {
        free(ue);
        pthread_mutex_unlock(&list->lock);
        return;
    }

    new_node->data = *ue;
    new_node->next = list->head;
    list->head = new_node;
    ++list->size;

    pthread_mutex_unlock(&list->lock);
}

struct ue_list* create_ue_array(size_t max_ues) {
    struct ue_list* array = malloc(max_ues * sizeof(struct ue_list));
    if (!array) return NULL;

    for (size_t i = 0; i < max_ues; ++i)
        init_ue_list(&array[i]);

    return array;
}

void populate_ue_array(struct ue_list* array, size_t num_ues) {
    for (size_t i = 0; i < num_ues; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* ue = allocate_ue();
        if (!ue) break;

        ue->ue_tag = generate_ue_tag(); // Replace this with your UE tag generation function
        ue->rnti = i;
        ue->crc_indication.crcflag = rand() % 2;

        add_ue(&array[i%max_ues], ue);
    }
}

// Implement resize function here, taking into account the current size and the new maximum number of UEs
```

