    if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
        logError("Invalid email format for user {$userId}");
        return ['success' => false, 'message' => 'Invalid email format'];
    }

    if (strlen($name) < 3 || strlen($name) > 50) {
        logError("Name length is out of bounds for user {$userId}");
        return ['success' => false, 'message' => 'Name must be between 3 and 50 characters'];
    }

    if (filesize($picture) > 2_097_152) { // 2 MB file size limit
        logError("Profile picture exceeds the size limit for user {$userId}");
        return ['success' => false, 'message' => 'Profile picture size must be less than 2MB'];
    }

    try {
        $db = new PDO('mysql:host=main_db;dbname=user_data', 'username', 'password'); // Main database connection
        $db->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
        $stmt = $db->prepare("UPDATE users SET name=?, email=?, profile_picture=? WHERE id=?"));
        $stmt->execute([$name, $email, move_uploaded_file($picture, 'path/to/profile_pictures/' . $userId), $userId]); // Upload and store picture in cache layer before updating the database

        // Offload image resizing to a background worker
        dispatch(new App\Jobs\ResizeImage($userId));

        // Cache synchronization using Redis or another caching layer service
        $cache = new Predis\Client('cache_redis');
        $cache->hset("user_{$userId}", 'name', $name);
        $cache->hset("user_{$userId}", 'email', $email);
        $cache->hset("user_{$userId}", 'profile_picture', $picture);
    } catch (Exception $e) {
        logError($e->getMessage());
        return ['success' => false, 'message' => 'Database connection error'];
    }

    return ['success' => true];
}
