class DuplicateCharException : public std::runtime_error {
public:
    DuplicateCharException(const std::string& msg) : std::runtime_error(msg) {}
};

struct CharacterSetValidator {
    virtual ~CharacterSetValidator() {}
    virtual bool validate(const std::string& chars) const = 0;
};

class NetworkUnavailableException : public std::runtime_error {
public:
    NetworkUnavailableException(const std::string& msg) : std::runtime_error(msg) {}
};

struct UF {
    explicit UF(int size) : parent_(size, -1), rank_(size, 0) {}

    int findSet(int x) {
        if (parent_[x] < 0)
            return x;
        return parent_[x] = findSet(parent_[x]);
    }

    void unionSets(int x, int y) {
        int rootX = findSet(x);
        int rootY = findSet(y);
        if (rootX == rootY)
            return;

        if (rank_[rootX] > rank_[rootY])
            parent_[rootY] = rootX;
        else
            parent_[rootX] = rootY;

        if (rank_[rootX] == rank_[rootY])
            ++rank_[rootY];
    }

private:
    std::vector<int> parent_;
    std::vector<int> rank_;
};

class ValidCharacterSet : public CharacterSetValidator {
public:
    explicit ValidCharacterSet(const std::string& allowedChars) : allowed_(allowedChars) {}

    bool validate(const std::string& chars) const override {
        std::set<char> input_set(chars.begin(), chars.end());
        return input_set.size() == allowed_.size() && input_set.subsetof(allowed_);
    }

private:
    const std::string allowed_;
};

std::unique_ptr<CharacterSetValidator> createValidator(const std::string& allowedChars) {
    return std::make_unique<ValidCharacterSet>(allowedChars);
}

size_t writeFunction(void* contents, size_t size, size_t nmemb, void* userp) {
    auto* data = static_cast<std::string*>(userp);
    data->append(static_cast<char*>(contents), size * nmemb);
    return size * nmemb;
}

std::string processString(const std::string& inputStr, int sizeLimit) {
    // Implement the union-find structure and concurrency handling here.
    UF uf(inputStr.length());
    std::unordered_map<char, int> idMap;

    auto getID = [&](char c) {
        if (idMap.count(c))
            return idMap[c];
        int newID = uf.findSet(static_cast<int>(inputStr[0]));
        ++newID;
        idMap[c] = newID;
        uf.unionSets(static_cast<int>(c), newID);
        return newID;
    };

    std::vector<std::pair<char, int>> pairs;
    for (size_t i = 0; i < inputStr.length(); ++i) {
        char c1 = inputStr[i];
        for (size_t j = i + 1; j < inputStr.length(); ++j) {
            char c2 = inputStr[j];
            if (c1 == c2)
                throw DuplicateCharException("Duplicate characters found");
            int id1 = getID(c1);
            int id2 = getID(c2);
            if (uf.findSet(id1) == uf.findSet(id2))
                continue;
            pairs.emplace_back(c1, id1);
            pairs.emplace_back(c2, id2);
        }
    }

    std::sort(pairs.begin(), pairs.end());
    int components = uf.findSet(static_cast<int>(inputStr[0])).second;

    if (components > 1 && pairs.size() != components - 1)
        throw DuplicateCharException("Disjoint pairs count is incorrect");

    std::string allowedChars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    auto validator = createValidator(allowedChars);

    std::unique_ptr<CharacterSetValidator> validatorGuard;
    {
        std::lock_guard<std::mutex> lock(validatorMutex_);
        validatorGuard.swap(validator);
    }

    if (!validatorGuard->validate(inputStr)) {
        std::cout << "Warning: Invalid character set, continuing processing..." << std::endl;
    }

    if (inputStr.length() > sizeLimit)
        return nullptr;

    auto it = inputStr.cend();
    while (it != inputStr.begin()) {
        --it;
        if (*it == '/') {
            it = inputStr.erase(it);
            break;
        }
    }

    return inputStr + "/";
}

std::mutex validatorMutex_;

static size_t httpRequestThreadFunc(std::future<bool>& validationFuture, const std::string& url) {
    CURL *curl = curl_easy_init();
    if (!curl)
        throw NetworkUnavailableException("CURL initialization failed");

    curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, writeFunction);
    std::string response;

    auto *userData = new std::string();
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, userData);

    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        curl_easy_cleanup(curl);
        throw NetworkUnavailableException("CURL request failed");
    }

    validationFuture = std::async(std::launch::async, [url]() mutable {
        auto validatorGuard;
        {
            std::lock_guard<std::mutex> lock(validatorMutex_);
            validatorGuard.swap(validator_);
        }
        return validatorGuard->validate(*userData);
    });

    curl_easy_cleanup(curl);
    delete userData;

    std::this_thread::sleep_for(std::chrono::milliseconds(10)); // Simulate network delay

    return validationFuture.get() ? 0 : 1;
}

void processStringConcurrently(const std::string& inputStr, int sizeLimit) {
    auto validatorGuard;
    {
        std::lock_guard<std::mutex> lock(validatorMutex_);
        validatorGuard.swap(validator_);
    }

    constexpr size_t numThreads = 4;
    std::vector<std::future<bool>> validationFutures(numThreads);

    std::string urlBase = "https://example.com/validate?chars=";

    auto startPos = 0;
    auto endPos = inputStr.length() / numThreads;
    for (size_t i = 0; i < numThreads; ++i) {
        size_t pos = i == numThreads - 1 ? inputStr.length() : startPos + endPos;
        validationFutures[i] = std::async(std::launch::async, httpRequestThreadFunc,
                                         std::ref(validationFutures[(i + 1) % numThreads]),
                                         urlBase + inputStr.substr(startPos, endPos) + '&');
        startPos = pos;
    }

    bool allValidationsSuccessful = true;
    for (auto &future : validationFutures) {
        if (!future.get())
            allValidationsSuccessful = false;
    }

    if (!allValidationsSuccessful) {
        std::cout << "Warning: Network request(s) failed, continuing processing..." << std::endl;
    }
}

int main() {
    constexpr int sizeLimit = 100;
    const std::string inputString = "abcd/efghijklmnopqrstuvwxyz/ABCDEFGHIJKLMNOPQRSTUVWXYZ1234567890/";
    processStringConcurrently(inputString, sizeLimit);
}

