```c
#include <jpeglib.h>
#include <stddef.h>
#include <stdio.h>

typedef struct {
    jpeg_color_space cs;   // Color space
    int comp_ratio;        // Compression ratio
    int orientation;      // Orientation
    int interleave;        // Interleave status
    int num_prog_scans;    // Number of progressive scan segments
    int extra_metadata;    // Number of extra metadata blocks
} jpeg_info;

void parse_jpeg(const char *filename, jpeg_info *info) {
    struct jpeg_decompress_struct cinfo;
    struct jpeg_error_mgr jerr;
    FILE *input_file = fopen(filename, "rb");

    if (!input_file) {
        fprintf(stderr, "Error opening file: %s\n", filename);
        return;
    }

    jpeg_create_decompress(&cinfo);
    jpeg_stdio_src(&cinfo, input_file);
    jpeg_load_err(jerr.pub, &jerr);

    while (jpeg_read_header(&cinfo, TRUE) != 0) {
        if (cinfo.color_space == JCS_UNKNOWN || cinfo.color_space >= JCS_LAST) {
            fprintf(stderr, "Unsupported color space: %d\n", cinfo.color_space);
            jpeg_destroy_decompress(&cinfo);
            fclose(input_file);
            return;
        }

        info->cs = cinfo.color_space;
    }

    jpeg_read_scanlines(&cinfo, NULL, 0); // Read all scanlines to get comp ratio and interleave status
    info->comp_ratio = (int)(cinfo.output_width * cinfo.output_height * cinfo.num_components / cinfo.image_size);
    info->interleave = !cinfo.dct_method || cinfo.dct_method == JDCT_ISLOW;

    jpeg_get_progressive_mode(&cinfo);
    info->num_prog_scans = cinfo.saw_markers & (JPEG_MARKER_SOFn - 1); // Get number of progressive scan segments

    jpeg_read_coefficients(&cinfo, NULL, TRUE); // Read all coefficients to get extra metadata blocks
    info->extra_metadata = cinfo.num_scan_markers - 4; // Subtract required markers (SOF0, SOS, SOFn)

    jpeg_destroy_decompress(&cinfo);
    fclose(input_file);
}
