#include <pthread.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <semaphore.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <signal.h>
#include <sys/wait.h>

typedef struct {
    int sockfd;
    struct sockaddr_in addr;
} connection_t;

struct mon_svc {
    pid_t pid;
    int fd;
};

static sem_t connections_mutex;
static size_t num_connections = 0;
static connection_t *connections;
static struct mon_svc mon_service;

void init() {
    if (sem_init(&connections_mutex, 1, 1) != 0) {
        perror("sem_init failed\n");
        exit(EXIT_FAILURE);
    }

    // Initialize monitoring service here...
}

void cleanup() {
    sem_destroy(&connections_mutex);

    if (mon_service.pid > 0) {
        kill(mon_service.pid, SIGTERM);
        waitpid(mon_service.pid, NULL, 0);
    }

    if (connections != NULL) {
        free(connections);
    }
}

int add_connection(int sockfd, struct sockaddr_in *addr) {
    sem_wait(&connections_mutex);

    // Allocate memory for new connection array if needed
    if (num_connections >= 15000) {
        printf("Maximum number of connections reached\n");
        sem_post(&connections_mutex);
        return 0;
    }

    connection_t *new_connection = realloc(connections, sizeof(connection_t) * (num_connections + 1));
    if (!new_connection) {
        perror("Reallocation failed\n");
        sem_post(&connections_mutex);
        return 0;
    }
    connections = new_connection;

    // Fill in the new connection structure and increment the number of connections
    connections[num_connections].sockfd = sockfd;
    memcpy(&connections[num_connections].addr, addr, sizeof(struct sockaddr_in));
    num_connections++;

    sem_post(&connections_mutex);

    // Start monitoring service here...

    return 1;
}

int remove_connection(int sockfd) {
    sem_wait(&connections_mutex);

    int i;
    for (i = 0; i < num_connections; ++i) {
        if (connections[i].sockfd == sockfd) {
            break;
        }
    }

    if (i == num_connections) {
        sem_post(&connections_mutex);
        return 0;
    }

    // Move the last connection to the current position and decrement the number of connections
    connection_t temp = connections[num_connections - 1];
    connections[i] = temp;
    num_connections--;

    sem_post(&connections_mutex);

    return 1;
}

void list_connections() {
    sem_wait(&connections_mutex);

    int i;
    for (i = 0; i < num_connections; ++i) {
        printf("Socket descriptor: %d, IP address: %s, Port number: %d\n",
               connections[i].sockfd, inet_ntoa(connections[i].addr.sin_addr), ntohs(connections[i].addr.sin_port));
    }

    sem_post(&connections_mutex);
}
```

