        return;
    }

    memset(ds, 0, sizeof(*ds));
    ds->current = 0;
    ds->max_keys = capacity;
    pthread_mutex_init(&ds->lock, NULL);
}

bool ds_find_empty_record(struct data_structure *ds) {
    for (size_t i = 0; i < ds->current; ++i) {
        if (!ds->records[i].used) {
            return true;
        }
    }
    return false;
}

int ds_insert(struct data_structure *ds, int key, int value) {
    if (ds->max_keys == ds->current) {
        fprintf(stderr, "Data structure is full\n");
        return -1;
    }

    while (true) {
        pthread_mutex_lock(&ds->lock);

        size_t i = ds->current - 1;
        if (i >= ds->max_keys || (i > 0 && ds->records[i-1].value == value)) {
            pthread_mutex_unlock(&ds->lock);
            continue;
        }

        ds->offsets[key] = i + 1;
        ds->keys[i+1] = key;
        ds->records[i].value = value;
        ds->records[i].used = true;
        ++ds->current;

        pthread_mutex_unlock(&ds->lock);
        return i + 1;
    }
}

int ds_get(struct data_structure *ds, int key) {
    if (key >= ds->max_keys || ds->current == 0) {
        fprintf(stderr, "Invalid key or empty data structure\n");
        return -1;
    }

    pthread_mutex_lock(&ds->lock);

    size_t i = ds->offsets[key] - 1;
    if (i >= ds->max_keys || ds->records[i].value != key) {
        pthread_mutex_unlock(&ds->lock);
        return -1;
    }

    int value = ds->records[i].value;
    pthread_mutex_unlock(&ds->lock);
    return value;
}

void ds_clear(struct data_structure *ds) {
    memset(ds->records, 0, sizeof(ds->records));
    ds->current = 0;
}
```

This implementation uses a pre-allocated pool of record structures and a mutex to manage concurrent access. The function `ds_init()` initializes the data structure with a given capacity, and `ds_insert()` adds a new record while ensuring no two consecutive records have identical values. The `ds_get()` method retrieves a record by its key, and `ds_clear()` releases all allocated memory when the function is done using it.

The function handles allocation failures gracefully by returning appropriate error messages in case of capacity exceeding the limits or memory allocation failures.']

