        log("Starting processing: input=%s output=%s max_buffer_size_kb=%" PRIuSIZE " bytes\n",
            args.input_file, args.output_file, args.max_buffer_size_kb * KB);
    }

    read_length = read(input_fd, buffer, MAX(file_size, args.max_buffer_size_kb) * KB);
    if (read_length == -1) {
        perror("Error reading input file");
        exit(1);
