    off_t processed = 0;
    size_t chunk_size = read_length > args.max_buffer_size_kb * KB ? args.max_buffer_size_kb * KB : file_size;

    int output_fd = open(args.output_file, O_WRONLY | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
    if (output_fd == -1) {
