        size_t written = write(output_fd, buffer + processed, chunk_size);
        if (written == -1) {
            perror("Error writing to output file");
            exit(1);
        }

        processed += written;
        read_length -= written;

        if (read_length <= chunk_size) {
            chunk_size = read_length;
            if (read_length < args.max_buffer_size_kb * KB) {
                buffer += file_size - processed;
                memset(buffer, 0, MAX(file_size - processed, args.max_buffer_size_kb * KB));
