#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

typedef enum { INT, FLOAT } DataType;

struct ValidNumber {
    DataType type;
    union {
        int i_val;
        double f_val;
    } val;
};

int process_data(struct ValidNumber** integers, struct ValidNumber** floats, int* error_count) {
    size_t integers_capacity = 0, floats_capacity = 0;
    bool integers_full = false, floats_full = false;
    struct ValidNumber current;
    int c;

    while ((c = getchar()) != EOF) {
        if (c < '0' || c > '9') continue; // skip non-numbers

        current.type = INT;
        current.val.i_val = 0;
        integers_full = false;

        while (c >= '0' && c <= '9') {
            current.val.i_val = 10 * current.val.i_val + (c - '0');
            if (current.val.i_val > INT_MAX || (current.val.i_val > 0 && current.val.i_val < -INT_MAX)) {
                printf("Error: Integer out of range.\n");
                (*error_count)++;
                continue;
            }
            if (!integers_full && integers_capacity == integers_capacity) {
                integers_capacity *= 2;
                struct ValidNumber* tmp = realloc(integers, integers_capacity * sizeof(struct ValidNumber));
                if (!tmp) {
                    fprintf(stderr, "Error: Memory allocation failed.\n");
                    return -1;
                }
                integers = tmp;
            }
            integers[integers_capacity] = current;
            integers_full = true;
        }
        if (!isdigit(c)) continue; // handle floating-point input similarly

        ungetc(c, stdin);
        current.type = FLOAT;
        current.val.f_val = 0.0;
        floats_full = false;

        if (1 != scanf("%lf", &current.val.f_val)) {
            printf("Error: Invalid floating-point number.\n");
            (*error_count)++;
            continue;
        }
        if (!isnan(current.val.f_val) && !((current.val.f_val > FLT_MAX || current.val.f_val < -FLT_MAX))) {
            if (!floats_full && floats_capacity == 0) {
                floats_capacity = 1;
                struct ValidNumber* tmp = malloc(floats_capacity * sizeof(struct ValidNumber));
                if (!tmp) {
                    fprintf(stderr, "Error: Memory allocation failed.\n");
                    return -1;
                }
                floats = tmp;
            }
            floats[floats_capacity] = current;
            floats_full = true;
        }
    }

    if (error_count) return *error_count;
    return 0;
}
