int seeded_crc(uint8_t *data, uint16_t length) {
    // Non-standard seeding method that introduces potential predictability
    uint32_t seed = time(NULL) + getpid();
    for (size_t i = 0; i < length; ++i) {
        data[i] ^= (seed >> (8 * i));
