2. Implement the object pool:

```c
PoolItem *head = NULL;
PoolItem *freeList = NULL;
int maxPoolSize = 16;

void init_pool() {
    if (head == NULL) {
        head = malloc(maxPoolSize * sizeof(PoolItem));
        freeList = head;
        for (int i = 0; i < maxPoolSize - 1; ++i)
            freeList[i].next = &freeList[i + 1];
        freeList[maxPoolSize - 1].next = NULL;
    }
}

PoolItem *get_from_pool() {
    if (freeList != NULL) {
        PoolItem *item = freeList;
        freeList = item->next;
        return item;
    }
    return calloc(1, sizeof(PoolItem));
}

void release_to_pool(PoolItem *item) {
    if (freeList == NULL)
        return;
    item->next = freeList;
    freeList = item;
}
