/**
 * @brief Function to integrate NFAPI_CRC_INDICATION_PDU_T structures into graph database
 *
 * @param db Graph database object pointer
 * @param data Pointer to an array of NFAPI_CRC_INDICATION_PDU_T structures
 * @param size Size of the data array
 */
void integrateNFAPICRCIndications(GraphDB* db, const NFAPI_CRC_INDICATION_PDU_T* data, size_t size) {
    // Hash table for fast lookup and deduplication based on RNTI
    GHashTable* rntiMap = g_hash_table_new_full(g_int_to_pointer, g_int_equal, NULL, (GDestroyNotify)free);

    // Lock to prevent concurrent access to graph database
    pthread_mutex_lock(&db->lock);

    // Iterate through the input data array
    for (size_t i = 0; i < size; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* currentData = &data[i];

        // Skip structures with missing or invalid fields
        if (!currentData->RX_UE_INFORMATION_TAG || !currentData->RNTI || !currentData->RNTI_CRC_INDICATION_REL8_TAG) {
            continue;
        }

        // Check if the current structure is already present in the graph database
        gpointer existingRnti = g_hash_table_find(rntiMap, GINT_TO_POINTER(currentData->RNTI));
        if (existingRnti) {
            // Structure is a duplicate, continue to next iteration
            continue;
        }

        // Add the current structure to the hash table for fast lookup later
        g_hash_table_insert(rntiMap, GINT_TO_POINTER(currentData->RNTI), currentData);

        // Create a new vertex in the graph database if it doesn't exist yet
        Vertex* rntiVertex = findOrCreateVertexByRnti(db, currentData->RNTI);

        // Create an edge between the existing vertices based on CRCFLAG value
        Edge* crcEdge = findOrCreateEdge(db, rntiVertex, crcFlagToEdgeKey(currentData->CRCFLAG));

        // Connect the current structure to the appropriate vertex and edge in the graph database
        connectNFAPICRCIndication(rntiVertex, crcEdge, currentData);
    }

    // Unlock the graph database for other threads to access it
    pthread_mutex_unlock(&db->lock);

    // Free resources used during data integration
    g_hash_table_destroy(rntiMap);
}
