4. Removing existing files by file descriptor:
```c++
void remove_file(FileDescriptorManager* manager, int fd) {
    // lock the container before removing the file
    pthread_mutex_lock(&manager->mutex);
    auto it = std::find_if(manager->files.begin(), manager->files.end(), [fd](const FileDescriptor& f){ return f.fd == fd; });

    if (it != manager->files.end()) {
