    if (pool->current + N >= pool->capacity) {
        while (pool->current + N >= pool->capacity) {
            pool->capacity *= 2;
            pool->data = realloc(pool->data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * pool->capacity);
            if (!pool->data) {
                perror("realloc");
                return NULL;
            }
        }
    }

    for (size_t i = pool->current; i < pool->current + N; ++i) {
        pool->data[i].rx_ue_info.tag = rand() % MAX_RX_UE_INFORMATION_TAG;
        pool->data[i].rnti = rand() % MAX_RNTI;
        pool->data[i].crc_indication.tag = CRCI_INDICATION_REL8;
        pool->data[i].crc_indication.crcflag = (rand() % 2) == 0 ? 1 : 0; // Set CRCFLAG to 0 or 1 randomly
    }

    pool->current += N;

    return &pool->data[pool->current - N];
}
