#include <boost/lexical_cast.hpp>
#include <cmath>

struct Connection final {
    boost::asio::ip::tcp::socket socket;
    std::vector<double> numbers;
};

void processNumber(std::vector<double>& numbers, double number) {
    if (std::isfinite(number)) {
        numbers.push_back(number);
    }
}

void handleRead(Connection& connection, const boost::system::error_code& ec) {
    if (!ec) {
        std::istringstream ss(connection.socket.read_some_at_least(1).data());
        double number;
        if (ss >> number) {
            processNumber(connection.numbers, number);
        }
        connection.socket.async_read_some(boost::asio::buffer(connection.socket.read_some_at_least(1).data()),
                                           boost::bind(&handleRead, connection, boost::asio::placeholders::error));
    } else {
        // Handle the error and close the connection
    }
}

double findMin(const std::vector<double>& numbers) {
    double min = std::numeric_limits<double>::max();
    for (const auto& number : numbers) {
        if (number < min) {
            min = number;
        }
    }
    return min;
}

double findMax(const std::vector<double>& numbers) {
    double max = std::numeric_limits<double>::min();
    for (const auto& number : numbers) {
        if (number > max) {
            max = number;
        }
    }
    return max;
}

void printStats(const Connection& connection, const Logger& logger) {
    auto min = findMin(connection.numbers);
    auto max = findMax(connection.numbers);
    logger.log("Min: " + std::to_string(min) + ", Max: " + std::to_string(max));
}
```

