#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define NUM_THREADS 4
#define MAX_UE_ID 1000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint64_t RNTI;
    CRC_INDICATION_REL8_TAG CRC_INDICATION;
} NFAPI_CRC_INDICATION_PDU_T;

struct thread_data {
    NFAPI_CRAC_INDICATION_PDU_T** data;
    int start, end;
};

void* create_ue_pdus(void* args) {
    struct thread_data* data = (struct thread_data*)args;
    pthread_mutex_t* lock = *(pthread_mutex_t**)data->data;

    for (int i = data->start; i < data->end; ++i) {
        pthread_mutex_lock(lock);
        // Ensure uniqueness of RNTI values within the array
        while ((*data)[i].RNTI == (*data)[data->start].RNTI || i - data->start >= MAX_UE_ID) {
            (*data)[i].RNTI = ((uint64_t)time(NULL) * (i + 1)) % MAX_UE_ID;
        }
        pthread_mutex_unlock(lock);

        // Set CRCFLAG randomly for each structure
        (*data)[i].CRC_INDICATION.CRCFLAG = rand() % 2;
    }
}

void allocate_ue_pdus(int num_ues, NFAPI_CRAC_INDICATION_PDU_T*** data) {
    *data = (NFAPI_CRAC_INDICATION_PDU_T**)malloc(num_ues * sizeof(NFAPI_CRAC_INDICATION_PDU_T*));
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    int num_per_thread = num_ues / NUM_THREADS;
    struct thread_data threads_data[NUM_THREADS];

    for (int i = 0; i < NUM_THREADS; ++i) {
        threads_data[i].data = data;
        threads_data[i].start = i * num_per_thread;
        threads_data[i].end = (i == NUM_THREADS - 1) ? num_ues : (i + 1) * num_per_thread;
    }

    pthread_t threads[NUM_THREADS];

    for (int i = 0; i < NUM_THREADS; ++i) {
        pthread_create(&threads[i], NULL, create_ue_pdus, &threads_data[i]);
    }

    for (int i = 0; i < NUM_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Ensure proper deallocation and avoid memory leaks
    for (int i = 0; i < num_ues; ++i) {
        free(*data[i]);
    }
    free(*data);
    pthread_mutex_destroy(&lock);
}
```

