#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <stdbool.h>

typedef struct record {
    int key;
    long offset;
    char status;
} record_t;

struct collection {
    record_t* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
};

static inline void init_record(record_t* r) {
    r->key = 0;
    r->offset = (long)rand() % 2000000 - 1000000;
    r->status = 'a';
}

static inline void lock(pthread_mutex_t* mutex) {
    pthread_mutex_lock(mutex);
}

static inline void unlock(pthread_t* mutex) {
    pthread_mutex_unlock(mutex);
}

struct collection* create_collection(size_t size) {
    if (size > 10000) {
        fprintf(stderr, "Requested size exceeds 10,000\n");
        return NULL;
    }

    struct collection* coll = malloc(sizeof(struct collection));
    if (!coll) {
        perror("Failed to allocate memory for collection");
        return NULL;
    }

    coll->records = malloc(size * sizeof(record_t));
    if (!coll->records) {
        perror("Failed to allocate memory for records");
        free(coll);
        return NULL;
    }

    pthread_mutex_init(&(coll->mutex), NULL);
    coll->capacity = size;
    coll->size = 0;

    lock(&(coll->mutex));
    for (size_t i = 0; i < size; ++i) {
        record_t* r = &(coll->records[i]);
        init_record(r);
    }
    unlock(&(coll->mutex));

    return coll;
}

void destroy_collection(struct collection* coll) {
    if (!coll)
        return;

    free(coll->records);
    pthread_mutex_destroy(&(coll->mutex));
    free(coll);
}

int add_record(struct collection* coll, int key) {
    if (coll->size >= coll->capacity)
        return -1; // Collection is full

    lock(&(coll->mutex));
    while (true) {
        bool found = false;
        for (size_t i = 0; i < coll->size; ++i) {
            if (coll->records[i].key == key) {
                found = true;
                unlock(&(coll->mutex));
                return -2; // Key already exists
            }
        }

        if (!found) {
            record_t* r = &(coll->records[coll->size]);
            r->key = key;
            ++(coll->size);
            unlock(&(coll->mutex));
            return 0;
        }
    }
}

int remove_record(struct collection* coll, int key) {
    lock(&(coll->mutex));
    for (size_t i = 0; i < coll->size; ++i) {
        if (coll->records[i].key == key) {
            memmove(&(coll->records[i]), &(coll->records[i + 1]), (coll->size - i - 1) * sizeof(record_t));
            --coll->size;
            unlock(&(coll->mutex));
            return 0;
        }
    }
    unlock(&(coll->mutex));
    return -3; // Key not found
}
```']

