typedef struct mempool {
    void *pool;
    size_t size;
    size_t count;
} mempool;

void *mempool_alloc(mempool *mp) {
    if (mp->count == 0 || mp->pool == MAP_FAILED) {
        // Reallocate memory pool or allocate a new one with the given size
        void *new_pool = mremap(mp->pool, mp->size, mp->size * 2, MREMAP_MAYMOVE);
        if (new_pool == MAP_FAILED) {
            // Handle memory allocation failure gracefully
            return NULL;
        }
        mp->pool = new_pool;
    }
    void *data = (char *)mp->pool + mp->count * sizeof(NFAPI_CRC_INDICATION_PDU);
    mp->count++;
    return data;
}

void mempool_free(mempool *mp, void *ptr) {
    if (ptr == NULL || mp->pool == MAP_FAILED) return;
    mp->count--;
