        if (!tmp) {
            // Log the error and resume processing subsequent PDUs if possible
            return false;
        }
        pool->nodes = tmp;
        pool->capacity = new_capacity;
    }

    // Align memory access to minimize cache misses
    size_t index = pool->num_nodes % alignof(NFAPI_CRC_INDICATION_PDU_T);

    memset(&pool->nodes[index], 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    NFAPI_CRC_INDICATION_PDU_T* node_ptr = &pool->nodes[index];
