#include <semaphore.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/syscall.h>
#include <syslog.h>
#include <time.h>

#define MAX_THREADS 1024
#define LOG_FACILITY LOG_USER

// Define a custom error code for semaphore timeout
enum SemaphoreError { SEMAPHORE_SUCCESS = 0, SEMAPHORE_TIMEOUT = -1 };

typedef struct _Semaphore {
    sem_t sem;
    pthread_mutex_t log_mutex;
    pthread_t threads[MAX_THREADS];
    int active_threads;
    char *log_file;
    time_t last_access;
} Semaphore;

Semaphore* create_semaphore(int initial_value, const char *log_file) {
    Semaphore *semaphore = malloc(sizeof(Semaphore));
    semaphore->active_threads = 0;
    semaphore->log_file = log_file;
    semaphore->last_access = time(NULL);
    sem_init(&semaphore->sem, 0, initial_value);
    pthread_mutex_init(&semaphore->log_mutex, NULL);
    return semaphore;
}

void destroy_semaphore(Semaphore *semaphore) {
    if (semaphore != NULL) {
        sem_destroy(&semaphore->sem);
        pthread_mutex_destroy(&semaphore->log_mutex);
        free(semaphore);
    }
}

int acquire_semaphore(Semaphore *semaphore, long timeout_us) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    ts.tv_sec += timeout_us / 1000000;
    ts.tv_nsec += (timeout_us % 1000000) * 1000;

    if (sem_timedwait(&semaphore->sem, &ts)) {
        return SEMAPHORE_TIMEOUT;
    }

    pthread_mutex_lock(&semaphore->log_mutex);
    semaphore->active_threads++;
    log_acquire(semaphore);
    pthread_mutex_unlock(&semaphore->log_mutex);

    return SEMAPHORE_SUCCESS;
}

void release_semaphore(Semaphore *semaphore) {
    pthread_mutex_lock(&semaphore->log_mutex);
    semaphore->active_threads--;
    log_release(semaphore);
    pthread_mutex_unlock(&semaphore->log_mutex);
    sem_post(&semaphore->sem);
}

void log_acquire(Semaphore *semaphore) {
    char log_msg[256];
    snprintf(log_msg, sizeof(log_msg), "Thread %lu acquired semaphore at %s", syscall(SYS_gettid), ctime(&semaphore->last_access));
    openlog("Semaphore Log", LOG_PID | LOG_CONS | LOG_NDELAY, LOG_FACILITY);
    syslog(LOG_INFO, log_msg);
    closelog();
}

void log_release(Semaphore *semaphore) {
    char log_msg[256];
    snprintf(log_msg, sizeof(log_msg), "Thread %lu released semaphore at %s", syscall(SYS_gettid), ctime(&semaphore->last_access));
    openlog("Semaphore Log", LOG_PID | LOG_CONS | LOG_NDELAY, LOG_FACILITY);
    syslog(LOG_INFO, log_msg);
    closelog();
}
```

