           pdu->crc_indication_rel8_tag < CRC_INDICATION_REL8_TAG_MAX;
}

// Memory pool functions
void memory_pool_init(struct memory_pool *pool, int capacity) {
    pool->capacity = capacity;
    pool->head = pool->tail = NULL;
}

struct pool_item *memory_pool_alloc() {
    struct pool_item *new_item;

    if (pool->head == NULL) {
        new_item = malloc(sizeof(struct pool_item));
        if (!new_item) return NULL;

        pool->head = new_item;
        pool->tail = new_item;
        new_item->data = malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_item->data) {
            free(new_item);
            return NULL;
        }
        new_item->next = NULL;
    } else {
        pool->tail->next = malloc(sizeof(struct pool_item));
        if (!pool->tail->next) return NULL;

        new_item = pool->tail->next;
        pool->tail = new_item;
        new_item->data = (NFAPI_CRC_INDICATION_PDU_T *)((char *)pool->head->data + pool->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_item->data) {
            free(pool->tail->next);
            return NULL;
        }
        new_item->next = NULL;
    }

    return pool->tail;
}

void *memory_pool_free(void *data) {
    struct pool_item *current, *prev;

    current = pool->head;
    while (current != NULL) {
        prev = current;
        current = current->next;
        free(prev);
    }

    pool->head = pool->tail = NULL;

    return data;
}

