void add_element(NFAPI_CRC_INDICATION_PDU_T* element) {
    pthread_mutex_lock(&mutex);
    if (num_elements >= max_elements) {
        free(element);
        pthread_mutex_unlock(&mutex);
        return;
    }

    for (unsigned int i = 0; i < num_elements; ++i) {
        if (data_array[i].RNTI == element->RNTI) {
            free(element);
            pthread_mutex_unlock(&mutex);
            return;
        }
