NFAPI_CRC_INDICATION_PDU_T* generate_array(const char *filename) {
    size_t len = strlen(filename);
    if (len == 0) return NULL;

    NFAPI_CRC_INDICATION_PDU_T *arr, temp;
    uint32_t totalRNTI = 0, rnti = 0;
    const char *ext = strchr(filename, '.');
    bool hasExt = ext != NULL;

    if (!hasExt) {
        ext = ".generated";
        filename[len] = '\0';
        totalRNTI = atoi(ext + 1);
    } else {
        totalRNTI = atoi(ext + 1);
        len -= (ext - filename) + strlen(ext);
    }

    arr = malloc(totalRNTI * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!arr) return NULL;

    for (size_t i = 0; i < totalRNTI; ++i) {
        rnti = 0;
        for (size_t j = 0; j < len; ++j) {
            rnti += toupper((unsigned char)filename[j]) - 'A' + 10 * (j % 26);
        }
        rnti %= 0x10000;

        temp.RX_UE_INFORMATION_TAG = 0x03;
        temp.RNTI = htonl(rnti);
        temp.CRC_INDICATION_REL8_TAG = rand() % 2 ? 0x01 : 0x00;
        arr[i] = temp;
    }

    if (!hasExt) {
        char new_ext[9];
        sprintf(new_ext, "%zu.%s", totalRNTI, ext);
        strncpy(filename, new_ext, sizeof(filename));
    }

    return arr;
}
