        // Implement additional validation checks as needed
        num_structures++;
        sem_post(&sem_mutex);
        sem_post(&sem_data);
    }

    pthread_exit(NULL);
}

void log_entry(const char* message) {
    FILE* log_file = fopen("network.log", "a");
    if (!log_file) {
        perror("fopen");
        return;
    }

    pthread_mutex_t log_mutex;
    pthread_mutex_init(&log_mutex, NULL);
    pthread_mutex_lock(&log_mutex);

    fprintf(log_file, "%s\n", message);
    fflush(log_file);
    pthread_mutex_unlock(&log_mutex);

    pthread_mutex_destroy(&log_mutex);
}

void handle_load(double load) {
    static const double LOW_LOAD = 0.5;
    static const int MIN_THREADS = 4;
    static const int MAX_THREADS = 16;
    int num_threads = (int)((MAX_THREADS - MIN_THREADS) * load + MIN_THREADS);

