private void waitWithExponentialBackoff(int maxRetries, long initialWaitTimeMillis, long maxWaitTimeMillis) {
    long currentWaitTimeMillis = initialWaitTimeMillis;
    int retryCount = 0;
    while (retryCount < maxRetries) {
        try {
            // Execute the code that may fail here
            break;
        } catch (Exception e) {
            if (++retryCount >= maxRetries) {
                throw new RuntimeException("Failed to execute the code after " + retryCount + " retries.", e);
            }
            try {
                Thread.sleep(currentWaitTimeMillis);
            } catch (InterruptedException ignored) {}
            currentWaitTimeMillis *= 2;
            if (currentWaitTimeMillis > maxWaitTimeMillis) {
                currentWaitTimeMillis = maxWaitTimeMillis;
            }
        }
    }
}
