void resize_list() {
    if (max_size == 0) {
        max_size = GROWTH_FACTOR;
        return;
    }

    Node** current = &head;
    for (int i = max_size; i > max_size - GROWTH_FACTOR; --i) {
        *current = malloc(sizeof(Node));
        if (*current == NULL) {
            err_exit("Out of memory");
        }

        (*current)->next = *current;
        (*current)->data = (NFAPI_CRC_INDICATION_PDU_T){};
        *current = &((*current)->next);
    }

    max_size *= GROWTH_FACTOR;
}

void add_ue(NFAPI_CRC_INDICATION_PDU_T* ue) {
    pthread_mutex_lock(&mutex);

    if (size >= max_size) {
        resize_list();
    }

    Node* current = head;
    while (current->next != head) {
        current = current->next;
    }

    current->next = malloc(sizeof(Node));
    if (!current->next) {
        err_exit("Out of memory");
    }

    current->next->data = *ue;
    current->next->next = head;
    size++;

    pthread_mutex_unlock(&mutex);
}

