        current = current->next;
    }

    if (current->next == head) {
        pthread_mutex_unlock(&mutex);
        return;
    }

    Node* temp = current->next;
    current->next = temp->next;
    free(temp);
    size--;

    pthread_mutex_unlock(&mutex);
}

