```c
#include <stdio.h>
#include <dirent.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>

static const char *file_ext = ".txt";
static const int max_filename_len = 256;

void generate_and_save(const char *path, const char *new_filename) {
    // Implement the logic for saving the new filename here.
}

void process_directory(const char *dir_path, const char *prefix) {
    DIR *dp;
    struct dirent *entry;
    struct stat st;

    if (!(dp = opendir(dir_path))) {
        return;
    }

    while ((entry = readdir(dp)) != NULL) {
        if (strlen(entry->d_name) >= max_filename_len ||
            strchr(entry->d_name, '/') || strchr(entry->d_name, '.')) {
            continue;
        }

        char new_filename[max_filename_len];
        memset(new_filename, 0, max_filename_len);

        strcpy(new_filename, prefix);
        strcat(new_filename, entry->d_name); // Replace spaces and special characters with underscores if needed

        int len = strlen(new_filename);

        for (int i = len - 1; i >= 0 && len < max_filename_len; --i) {
            const char c = new_filename[i];
            if (!isalpha(c) && !isspace(c) && c != '_' && c != '.' && c != '/') {
                break;
            }
            if (len-- == 0) {
                break;
            }
            new_filename[len] = '\0';
        }

        // Sum character frequencies and append the resulting numerical sequence to the original filename
        int char_freqs[256] = { 0 };
        for (int i = 0; i < len && entry->d_name[i]; ++i) {
            const char c = entry->d_name[i];
            if (c >= 'a' && c <= 'z') {
                char_freqs[c - 'a']++;
            } else if (c >= 'A' && c <= 'Z') {
                char_freqs[c - 'A']++;
            }
        }

        int sequence = 0;
        for (int i = 0; i < 256; ++i) {
            sequence += char_freqs[i];
            if (sequence > 99999) {
                break;
            }
        }

        snprintf(&new_filename[len], max_filename_len - len, "%05d", sequence);
        strcat(new_filename, file_ext);

        if (stat(new_filename, &st) == 0 && S_ISDIR(st.st_mode)) {
            process_directory(new_filename, prefix);
        } else {
            generate_and_save(dir_path, new_filename);
        }
    }

    closedir(dp);
}
