        return;
    }

    pthread_mutex_lock(&list_mutex);
    new_node->data = data;
    new_node->next = NULL;

    if (head == NULL) {
        head = tail = new_node;
    } else {
        tail->next = new_node;
        tail = new_node;
    }

    list_size++;
    if (list_size > max_list_size) {
        ListNode* temp = head;
        while (--list_size > 0)
            head = head->next;
        free(temp);
    }

    pthread_mutex_unlock(&list_mutex);
}

void cleanup() {
    pthread_mutex_lock(&list_mutex);

    ListNode* current = head;
    while (current != NULL) {
        ListNode* temp = current;
        current = current->next;

        if (difftime(time(NULL), temp->timestamp) > timestamp_window) {
            free(temp);
            list_size--;
