fn compile_with_logging() -> i32 {
    let start = Instant::now();
    let mut cmd = Command::new("rustc");
    cmd.stdio(Stdio::piped());
    cmd.arg("your_source_file.rs");

    // Install custom logging hook here

    let output = cmd.spawn().expect("Failed to spawn process");
    let mut res = output.wait_with_output().expect("Error while waiting for process");

