    if let Some(ref err) = res.stderr {
        println!("{}", err);
    }
    if let Ok(exit_code) = res.code() {
        event!("compile_time", Level::INFO, &format!("{:?}", start.elapsed()));
        event!("resident_memory_usage", Level::INFO, get_resident_set_size().unwrap_or(-1));
        return exit_code;
    } else {
        match res.stderr.as_ref() {
