    pthread_t threads[N];
    for (size_t i = 0; i < N; ++i) {
        pthread_create(&threads[i], NULL, populateUE, &ued);
    }

    for (size_t i = 0; i < N; ++i) {
        pthread_join(threads[i], NULL);
    }
}

void* populateUE(void* ued_ptr) {
