    pdu->rnti = rand(); // Random RNTI value
    pdu->crc_indication.crcflag = rand() % 2; // Randomly set CRC flag
    return pdu;
}

void* populate_arrays(void *arg) {
    pthread_mutex_lock(&mutex);
    srs_indications = realloc(srs_indications, num_ues * sizeof(NR_API_SRS_INDICATION));
    if (!srs_indications) goto cleanup;
    crc_indications = realloc(crc_indications, num_ues * sizeof(NFAPI_CRD_INDICATION_PDU_T));
    if (!crc_indications) goto cleanup;
    for (size_t i = 0; i < num_ues; ++i) {
        srs_indications[i] = create_srs_indication(i);
        if (!srs_indications[i]) goto cleanup;
        crc_indications[i] = create_crc_indication(i);
        if (!crc_indications[i]) goto cleanup;
    }
cleanup:
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void free_arrays() {
    for (size_t i = 0; i < num_ues; ++i) {
        free(srs_indications[i]);
        free(crc_indications[i]);
    }
    free(srs_indications);
    free(crc_indications);
}

void setup_arrays(size_t num_ues_) {
    pthread_mutex_lock(&mutex);
    num_ues = num_ues_;
    srs_indications = malloc(num_ues * sizeof(NR_API_SRS_INDICATION));
    if (!srs_indications) goto cleanup;
    crc_indications = malloc(num_ues * sizeof(NFAPI_CRD_INDICATION_PDU_T));
    if (!crc_indications) goto cleanup;
    pthread_t threads[num_ues];
    for (size_t i = 0; i < num_ues; ++i) {
        if (pthread_create(&threads[i], NULL, populate_arrays, i)) goto cleanup;
    }
    for (size_t i = 0; i < num_ues; ++i) {
        pthread_join(threads[i], NULL);
    }
    free(threads);
    pthread_mutex_unlock(&mutex);
}
