pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t list_notfull = PTHREAD_COND_INITIALIZER;
pthread_cond_t list_notempty = PTHREAD_COND_INITIALIZER;
volatile sig_atomic_t list_should_cleanup = 0;
void *list_mem_map = NULL;
size_t list_capacity = 0;
size_t list_count = 0;

void cleanup_thread(void *arg) {
    while (1) {
        sleep(CLEANUP_INTERVAL);
        if (list_should_cleanup) {
            pthread_mutex_lock(&list_lock);
            // Perform clean up logic here, removing expired entries
            pthread_cond_signal(&list_notempty);
            pthread_mutex_unlock(&list_lock);
            list_should_cleanup = 0;
        }
    }
}

int init_list(size_t n) {
    size_t size = sizeof(struct list_head) * n;
    list_mem_map = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_SHARED | MAP_ANONYMOUS, -1, 0);
    if (list_mem_map == MAP_FAILED) {
        perror("mmap");
        return -1;
    }

    pthread_t cleanup_thread_id;
    if (pthread_create(&cleanup_thread_id, NULL, &cleanup_thread, NULL) != 0) {
        perror("pthread_create");
        munmap(list_mem_map, size);
        return -1;
    }

    list_capacity = n;
    struct list_head *head = list_mem_map;
    for (size_t i = 0; i < n; ++i) {
        head[i].data = calloc(1, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!head[i].data) {
            perror("calloc");
            munmap(list_mem_map, size);
            pthread_cancel(cleanup_thread_id);
            return -1;
        }
        head[i+1] = head[i];
    }
    return 0;
}

void *get_list_entry() {
    pthread_mutex_lock(&list_lock);
    while (list_count == list_capacity) {
        pthread_cond_wait(&list_notfull, &list_lock);
    }
    struct list_head *entry = &((struct list_head *)list_mem_map)[list_count];
    entry->data = calloc(1, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!entry->data) {
        perror("calloc");
        pthread_mutex_unlock(&list_lock);
        return MAP_FAILED;
    }
    ++list_count;
    pthread_mutex_unlock(&list_lock);
    return entry->data;
}

void put_list_entry(void *data) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = data;
    // Populate the PDU structure with required data

    pthread_mutex_lock(&list_lock);
    while (list_count == 0 || list_count >= (list_capacity / LIST_GROWTH_FACTOR)) {
        pthread_cond_wait(&list_notempty, &list_lock);
    }
    struct list_head *entry = &((struct list_head *)list_mem_map)[list_count - 1];
    entry->data = data;
    --list_count;
    pthread_mutex_unlock(&list_lock);
}
