typedef struct {
    uint16_t modulation_scheme;
    uint8_t antenna_config[2]; // Assuming 2x2 MIMO configuration
    float signal_strength;
} lte_ue_csi_config;

struct lte_phy_sim {
    pthread_mutex_t mutex;
    lte_ue_csi_config* ues;
    size_t capacity;
    size_t num_ues;
};

void* memalign_aligned(size_t alignment, size_t size) {
    return (void*)memalign(alignment, size);
}

struct lte_phy_sim* init_lte_phy_sim(size_t num_ues) {
    if (num_ues > 10000) {
        fprintf(stderr, "Error: Requested number of UE instances exceeds the maximum allowed limit of 10,000.\n");
        return NULL;
    }

    struct lte_phy_sim* sim = (struct lte_phy_sim*)memalign_aligned(64, sizeof(struct lte_phy_sim));
    pthread_mutex_init(&sim->mutex, NULL);
    sim->capacity = num_ues;
    sim->num_ues = 0;

    size_t ue_size = sizeof(lte_ue_csi_config);
    sim->ues = (lte_ue_csi_config*)memalign_aligned(64, num_ues * ue_size);

    return sim;
}

void configure_ue(struct lte_phy_sim* sim, size_t idx, const lte_ue_csi_config config) {
    pthread_mutex_lock(&sim->mutex);

    if (idx >= sim->capacity || sim->num_ues >= sim->capacity) {
        fprintf(stderr, "Error: Invalid UE index or simulation is at maximum capacity.\n");
        pthread_mutex_unlock(&sim->mutex);
        return;
    }

    memcpy((void*)&sim->ues[idx], &config, sizeof(lte_ue_csi_config));
    sim->num_ues++;

    pthread_mutex_unlock(&sim->mutex);
}
