// Function to initialize PhyRxFrames from a list of network devices.
int initializePhyRxFrames(LTE_PHY_RX_FRAME_INFO_T* frames, size_t frames_capacity, NetworkDevice* devices, size_t devices_count) {
    size_t processed_frames = 0;
    srand(time(NULL));

    for (size_t i = 0; i < devices_count; ++i) {
        if (!devices[i]) continue; // Handle null pointers gracefully.

        LTE_PHY_RX_FRAME_INFO_T* frame = NULL;
        if (processed_frames < frames_capacity) {
            frame = &frames[processed_frames];
            ++processed_frames;
        } else {
            break; // Exit loop once the capacity is reached.
        }

        frame->frame.FRAME_TYPE = devices[i]->getFrameType(); // Get FRAME_TYPE from network device.
        frame->cell_id = devices[i]->getCellID(); // Get CELL_ID from network device.

        frame->params.TX_POWER = (int)(frame->cell_id % 100); // Set TX_POWER based on modulus operation.
        if (frame->params.TX_POWER < -50 || frame->params.TX_POWER > 30) {
            continue; // Handle malformed data (out of range TX_POWER).
        }

        float interference = calculateInterference(frame->cell_id); // Calculate environmental factors such as interference based on CELL_ID.
        float distance = calculateDistance(frame->cell_id); // Calculate distance based on CELL_ID.

        frame->expected_signal_strength = calculateSignalStrength(frame->params.TX_POWER, interference, distance); // Calculate expected signal strength.
    }

    return processed_frames;
}

// Implementation of engineering tradeoffs:
float calculateInterference(int cell_id) {
    // Environmental factors calculation based on CELL_ID.
    float interference = cell_id * 0.1f + rand() % 20;
    return interference < 0 ? 0 : interference;
}

float calculateDistance(int cell_id) {
    // Distance calculation based on CELL_ID.
    float distance = sqrt(cell_id * 4.0f);
    return distance >= 1.0f ? distance : 1.0f;
}

float calculateSignalStrength(int txPower, float interference, float distance) {
    // Signal strength calculation formula.
    constexpr float K = -128.0f; // Path loss exponent (4-5 dB/km).
    float path_loss = 10 * log10(distance) + K * log10(distance);
    float signal_strength = txPower - interference - path_loss;
    return signal_strength >= -120.0f ? signal_strength : -120.0f; // Ensure the returned value remains within a defined operational range.
}
