#include <pthread.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct mem_pool {
    size_t capacity;
    size_t count;
    NFAPI_CRCI_INDICATION_PDU_T* data;
    pthread_mutex_t mutex;
    pthread_cond_t not_empty;
} MemPool;

MemPool* mem_pool_create(size_t capacity) {
    MemPool *pool = malloc(sizeof(MemPool));
    pool->capacity = capacity;
    pool->count = 0;
    pool->data = calloc(capacity, sizeof(NFAPI_CRCI_INDICATION_PDU_T));
    pool->mutex = PTHREAD_MUTEX_INITIALIZER;
    pool->not_empty = PTHREAD_COND_INITIALIZER;
    return pool;
}

void* mem_pool_acquire(MemPool *pool) {
    pthread_mutex_lock(&pool->mutex);
    while (pool->count == pool->capacity && !pool->data[0].crcflag) { // wait if pool is full and first element's crcflag is set
        pthread_cond_wait(&pool->not_empty, &pool->mutex);
    }

    size_t index = pool->count % pool->capacity;
    if (!pool->data[index].crcflag) { // set crcflag to indicate acquired element
        pool->data[index].crcflag = true;
    }
    ++pool->count;
    pthread_mutex_unlock(&pool->mutex);

    return &pool->data[index];
}

void mem_pool_release(MemPool *pool, void* elem) {
    pthread_mutex_lock(&pool->mutex);
    NFAPI_CRCI_INDICATION_PDU_T *p = (NFAPI_CRCI_INDICATION_PDU_T *)elem;
    p->crcflag = false; // reset crcflag to indicate available element

    if (!pthread_mutex_trylock(&pool->mutex)) { // fast-path: avoid contention when pool is almost empty
        pool->count--;
        pthread_mutex_unlock(&pool->mutex);
        return;
    }

    while (pool->count < pool->capacity && !pool->data[index].crcflag) { // wait if pool is not full and next element's crcflag is set
        index = (index + 1) % pool->capacity;
    }

    pthread_mutex_unlock(&pool->mutex);
    pthread_mutex_lock(&pool->mutex);

    pool->data[index] = *((NFAPI_CRCI_INDICATION_PDU_T *)elem);
    pool->count++;
    pthread_cond_signal(&pool->not_empty);
    pthread_mutex_unlock(&pool->mutex);
}

typedef void (*processing_callback)(NFAPI_CRCI_INDICATION_PDU_T*);
void *thread_func(void* arg) {
    processing_callback cb = (processing_callback)arg;
    NFAPI_CRCI_INDICATION_PDU_T* pdu = mem_pool_acquire((MemPool*)arg);
    cb(pdu); // process the PDU
    mem_pool_release((MemPool*)arg, pdu);
    return NULL;
}

void run_threads(MemPool *pool, size_t num_threads, processing_callback cb) {
    pthread_t threads[num_threads];
    for (size_t i = 0; i < num_threads; ++i) {
        if (pthread_create(&threads[i], NULL, thread_func, pool)) {
            fprintf(stderr, "Error creating thread\n");
            exit(1);
        }
    }
    for (size_t i = 0; i < num_threads; ++i) {
        if (pthread_join(threads[i], NULL)) {
            fprintf(stderr, "Error joining thread\n");
            exit(1);
        }
    }
}
