    uint16_t crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef void (*callback_func_t)(NFAPI_CRC_INDICATION_PDU_T* pdu);

struct callback {
    callback_func_t func;
    struct callback *next;
};

typedef struct memory_pool {
    NFAPI_CRC_INDICATION_PDU_T **data;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* mem_pool_create(size_t initial_capacity) {
    MemoryPool *pool = malloc(sizeof(MemoryPool));
    if (!pool) return NULL;
    pool->data = calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!pool->data) {
        free(pool);
        return NULL;
    }
    pool->capacity = initial_capacity;
    pool->count = 0;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void mem_pool_destroy(MemoryPool *pool) {
    if (!pool) return;
    free(pool->data);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

NFAPI_CRC_INDICATION_PDU_T* mem_pool_alloc(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->count < pool->capacity) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = pool->data[pool->count];
        memset(pdu, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pool->count++;
    } else {
        pthread_mutex_unlock(&pool->lock);
        // Handle pool overflow, e.g., by creating a new memory block or discarding old data
    }
    pthread_mutex_unlock(&pool->lock);
    return pool->data[pool->count - 1];
}

void mem_pool_free(MemoryPool *pool, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&pool->lock);
    pool->data[--pool->count] = pdu;
    pthread_mutex_unlock(&pool->lock);
}

void register_callback(MemoryPool *pool, callback_func_t func) {
    struct callback *new_callback = malloc(sizeof(struct callback));
    if (!new_callback) return;
    new_callback->func = func;
    new_callback->next = NULL;

    pthread_mutex_lock(&pool->lock);
    struct callback *cb = pool->data;
    while (cb && cb->next) {
        cb = cb->next;
    }
    if (cb) {
        cb->next = new_callback;
    } else {
        pool->data = new_callback;
    }
    pthread_mutex_unlock(&pool->lock);
}

void process_pdus(MemoryPool *pool, size_t count) {
    pthread_mutex_lock(&pool->lock);
    NFAPI_CRC_INDICATION_PDU_T *pdu = pool->data[0];
    for (size_t i = 0; i < count; ++i) {
        if (!pdu) break;
        struct callback *cb = pool->data;
        while (cb) {
            cb->func(pdu);
            cb = cb->next;
        }
        mem_pool_free(pool, pdu++);
    }
    pthread_mutex_unlock(&pool->lock);
}

void worker_thread(MemoryPool *mem_pool) {
