const axios = require('axios');
const Bluebird = require('bluebird');
const chokidar = require('chokidar');
const moment = require('moment');
const winston = require('winston');

// Configuration settings
const config = {
  directory: './files', // Directory to read from
  limit: 1048576, // File size limit in bytes
  auditUrl: 'https://audit-system.com/api/log' // URL for the central audit system
};

// Validate command line arguments and configuration settings
yargs
  .option('dir', {
    alias: 'd',
    description: 'Directory to read files from',
    type: 'string'
  })
  .option('limit', {
    alias: 'l',
    description: 'File size limit in bytes',
    type: 'number'
  })
  .option('auditUrl', {
    alias: 'a',
    description: 'URL for the central audit system',
    type: 'string'
  })
  .help()
  .argv;

Object.assign(config, yargs.argv);

// Function to sanitize content using a custom function (replace with your own implementation)
const sanitizeContent = content => content.toLowerCase();

// Function to log detailed operation logs to the central audit system
const logToAuditSystem = async (fileMetadata, processingTime) => {
  try {
    await axios.post(config.auditUrl, {
      file: fileMetadata.name,
      size: fileMetadata.size,
      processedAt: moment().format(),
      processingTime: processingTime,
      ...fileMetadata
    });
  } catch (error) {
    winston.error(`Error logging to audit system: ${error}`);
  }
};

// Function to read and validate a single file asynchronously
const processFile = async (filePath) => {
  try {
    const stats = await fs.stat(filePath);
    if (stats.size > config.limit) {
      throw new Error(`File ${filePath} exceeds the size limit of ${config.limit} bytes`);
    }
    const content = await fs.readFile(filePath, 'utf8');
    const sanitizedContent = sanitizeContent(content);
    // Process the sanitized content here (e.g., other validations, transformations, etc.)
    const fileMetadata = { name: path.basename(filePath), size: stats.size };
    winston.info(`Processing file ${filePath}...`);
    logToAuditSystem(fileMetadata, stats.mtime.getMilliseconds()); // Log the processing time in milliseconds
    return sanitizedContent;
  } catch (error) {
    winston.error(`Error processing file ${filePath}: ${error}`);
    throw error;
  }
};

// Function to process multiple files concurrently using Bluebird
const processFiles = Bluebird.map(fs.readdirSync(config.directory), async file => {
  return path.join(config.directory, file) + '.gz'; // Read .gz files for efficiency
}, { concurrency: Math.min(process.cpuUsage().totalCPU / 100 * 5, 10) })
  .map(processFile);

// Monitor the directory for new or modified files and trigger processing as needed
const watcher = chokidar.watch(config.directory, { usePolling: true });
watcher.on('add', filePath => processFiles.push(path.join(config.directory, filePath) + '.gz')); // Monitor .gz files for efficiency
watcher.on('change', filePath => processFiles.push(path.join(config.directory, filePath) + '.gz')); // Monitor .gz files for efficiency

// Catch all unhandled exceptions and log them to the console
process.on('uncaughtException', error => winston.error(`Uncaught exception: ${error}`));
