EVP_CIPHER *encrypt_init(const EVP_CIPHER_CTX **ctx, const char *encryption_mode, const unsigned char *key, size_t key_len) {
    const EVP_CIPHER *cipher;
    EVP_CIPHER_CTX *c;

    if (!(cipher = EVP_get_cipherbyname(encryption_mode))) {
        fprintf(stderr, "Invalid encryption mode: %s\n", encryption_mode);
        exit(EXIT_FAILURE);
    }

    c = EVP_CIPHER_CTX_new();
    if (!c) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    if (1 != EVP_EncryptInit_ex(c, cipher, key, NULL)) {
        fprintf(stderr, "Encryption initialization error\n");
        exit(EXIT_FAILURE);
    }

    *ctx = c;
    return cipher;
}

void encrypt(const EVP_CIPHER_CTX *ctx, unsigned char *out, const unsigned char *in, size_t len) {
    if (1 != EVP_EncryptUpdate(ctx, out, NULL, in, len)) {
        perror("Encryption error");
        exit(EXIT_FAILURE);
    }

    if (1 != EVP_EncryptFinal_ex(ctx, out + len, NULL)) {
        perror("Encryption error");
        exit(EXIT_FAILURE);
    }
}

unsigned char *hmac_sha256(const unsigned char *data, size_t data_len, const unsigned char *key, size_t key_len) {
