    size_t hmac_len = SHA256_DIGEST_LENGTH;

    hmac = malloc(hmac_len);
    if (!hmac) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    HMAC(EVP_sha256(), key, key_len, data, data_len, hmac, &hmac_len);

    return hmac;
}

