    encrypted_data = malloc(EVP_CIPHER_CTX_ctm(ctx) * list_size);
    if (!encrypted_data) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < list_size; ++i) {
        encrypt(ctx, encrypted_data + i * EVP_CIPHER_CTX_ctm(ctx), &list[i], sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    hmac_result = hmac_sha256(encrypted_data, EVP_CIPHER_CTX_ctm(ctx) * list_size, "mysecretkey", 16);

