        _mockingFramework = new MockingFramework();
        _serializer = new XmlSerializer(typeof(Configuration));
    }

    public void RunTests(Type testModule, Action<TestResult> onTestResult)
    {
        var configuration = LoadConfiguration("config.xml");

        ConfigureAppInterface(configuration);

        _mockingFramework.Reset();

        var testMethods = GetTestMethods(testModule);

        foreach (var testMethod in testMethods)
        {
            Console.WriteLine($"Executing test: {testMethod.Name}");

            try
            {
                object[] parameters = new object[0]; // replace with actual parameters if needed
                TestResult result = RunTest(testMethod, parameters);

                onTestResult(result);

                _mockingFramework.Reset();
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error executing test: {testMethod.Name}: {ex.Message}");
            }
        }
    }

    private Configuration LoadConfiguration(string filePath)
    {
        using var reader = System.Xml.XmlReader.Create(filePath);
        return (Configuration)_serializer.Deserialize(reader);
    }

    private void ConfigureAppInterface(Configuration configuration)
    {
        // Implement your logic here based on configuration settings
    }

    private IEnumerable<MethodInfo> GetTestMethods(Type testModule)
    {
        return testModule.GetMethods()
            .Where(m => m.GetCustomAttributes(typeof(TestAttribute), true).Any())
            .ToList();
    }

    private TestResult RunTest(MethodInfo testMethod, object[] parameters)
    {
        var result = new TestResult();

        try
        {
            testMethod.Invoke(Activator.CreateInstance(testModule), parameters);
            result.Success = true;
        }
        catch (TargetInvocationException tiex)
        {
            result.Success = false;
            result.Exception = tiex.InnerException;
        }

        return result;
    }
}

