typedef struct _NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_information;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

struct list {
    size_t capacity;
    size_t size;
    NFAPI_CRC_INDICATION_PDU_T* elements;
    pthread_mutex_t lock;
};

void init_list(struct list* list, size_t capacity) {
    list->capacity = capacity;
    list->size = 0;
    list->elements = (NFAPI_CRC_INDICATION_PDU_T*)calloc(capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->elements) {
        perror("malloc failed");
        exit(-1);
    }
    pthread_mutex_init(&list->lock, NULL);
}

void destroy_list(struct list* list) {
    free(list->elements);
    pthread_mutex_destroy(&list->lock);
}

void push(struct list* list, const RX_UE_INFORMATION_TAG* rx_ue_information, const RNTI rnti, const CRC_INDICATION_REL8_TAG* crc_indication) {
    if (list->size >= list->capacity) {
        pthread_mutex_lock(&list->lock);
            // Reallocate memory and update capacity
            size_t new_capacity = list->capacity * 2;
            NFAPI_CRC_INDICATION_PDU_T* new_elements = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->elements, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!new_elements) {
                perror("realloc failed");
                pthread_mutex_unlock(&list->lock);
                exit(-1);
            }
            list->capacity = new_capacity;
            list->elements = new_elements;
        pthread_mutex_unlock(&list->lock);
    }

    list->size++;

    // Fill in the structures with valid data and CRC flags
    NFAPI_CRC_INDICATION_PDU_T* element = &list->elements[list->size - 1];

    element->rx_ue_information = *rx_ue_information;
    element->rnti = rnti;

    // Implement your CRC calculation function here
    uint32_t hash = calculate_CRC(element->rx_ue_information.UE_IDENTIFIER, element->rx_ue_information.TIMESTAMP, element->rnti.CELL_IDENTITY);
    element->crc_indication.CRCFLAG = (hash & 1) ? 1 : 0;
}
