            it->second->cgiTags = cgiTags;
        } else {
            frames[cellID] = std::make_shared<LTE_DL_FRAME_MSG>();
            frames[cellID]->frameInfo = frameInfo;
            frames[cellID]->cgiTags = cgiTags;
        }
    }

    void updateFrame(const CellID& cellID, const DL_FRAME_INFO& newFrameInfo) {
        // Acquire lock before updating data structure
        std::lock_guard<std::mutex> guard(m_dataMutex);

        if (auto it = frames.find(cellID); it != frames.end()) {
            it->second->frameInfo = newFrameInfo;
        }
    }

    const LTE_DL_FRAME_MSG* getFrameByCellID(const CellID& cellID) const {
        std::lock_guard<std::mutex> guard(m_dataMutex);
        return frames.find(cellID) != frames.end() ? frames.at(cellID).get() : nullptr;
    }

    void logEvent(const CellID& cellID, const LogEntry& event) {
        // Write to the ring buffer without locking for better performance
        if (logBuffer.size() == LOG_BUFFER_SIZE)
            std::atomic_thread_fence(std::memory_order_release); // Ensure write order

        logBuffer[nextLogEntryIndex++].cellID = cellID;
        logBuffer[nextLogEntryIndex - 1] = event;
    }

    const LogEntry* getLogEventsForCell(const CellID& cellID) const {
        // Read from the ring buffer without locking for better performance
        std::atomic_thread_fence(std::memory_order_acquire); // Ensure read order

        auto it = frames.find(cellID);
        if (it != frames.end()) {
            auto logIt = std::lower_bound(logBuffer.cbegin(), logBuffer.cend(), nextLogEntryIndex,
                                         [](const LogEntry& lhs, uint64_t rhs) { return lhs.index < rhs; });

            if (it->second != nullptr && logIt != logBuffer.cend() && it->first == logIt->cellID)
                return &*logIt;
        }
        return nullptr;
    }
};
```

This implementation uses a ring buffer for the log entries to reduce contention, and a traditional lock when manipulating the data structures. The `std::shared_ptr` ensures that resources are correctly managed, while the `constexpr` static LOG_BUFFER_SIZE allows you to set an optimal size without recompiling the code."]

