const size_t max_nodes = 10000;
const size_t memory_pool_limit = 1 * (1024 * 1024); // 1 MB
size_t memory_pool_used = 0;

void log_memory_usage() {
    printf("Memory usage: %zu bytes\n", memory_pool_used);
}

void add_node(Node** head) {
    Node* new_node = malloc(sizeof(Node));
    if (!new_node || !(*head)) {
        *head = new_node;
        return;
    }

    Node* current = *head;
    while (current->next) {
        current = current->next;
    }
    current->next = new_node;
}

void reset_memory_pool() {
    while (num_nodes > 0 && memory_pool_used + sizeof(NFAPI_CRC_INDICATION_PDU_T) < memory_pool_limit) {
        free(*head);
        *head = (*head)->next;
        num_nodes--;
        memory_pool_used -= sizeof(NFAPI_CRC_INDICATION_PDU_T);
    }
}

void handle_memory_exhaustion() {
    if (memory_pool_limit - memory_pool_used < sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        log_memory_usage();
        printf("Memory exhaustion detected. Request larger memory pool size from the system administrator.\n");
        reset_memory_pool();
    }
}

void init() {
    head = malloc(sizeof(Node));
    if (!head) {
        fprintf(stderr, "Error: Cannot allocate memory for linked list header\n");
        exit(EXIT_FAILURE);
    }
    num_nodes++;
    memory_pool_used += sizeof(Node);
    head->next = NULL;
}

