    void* buffer;
    size_t used;
    size_t free;
} MemoryPool;

void initMemoryPool(MemoryPool* pool, size_t capacity, size_t elementSize) {
    pool->capacity = capacity;
    pool->elementSize = elementSize;
    pool->buffer = malloc(capacity * elementSize);
    pool->used = 0;
    pool->free = capacity;
}

NFAPI_CRC_INDICATION_PDU_T* memoryPoolAlloc(MemoryPool* pool) {
    if (pool->free == 0) {
