```c
#include <arpa/inet.h>
#include <netdb.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <unistd.h>

struct host_data {
    char hostname[256];
    struct sockaddr_in addr;
    pthread_mutex_t lock;
};

// Cache structure
typedef struct {
    struct host_data** cache;
    size_t size, capacity;
} HostCache;

HostCache dns_cache = { NULL, 0, 0 };

int get_ip(const char* hostname, u_char* ip) {
    // Cache lookup
    for (size_t i = 0; i < dns_cache.capacity && i < dns_cache.size; ++i) {
        pthread_mutex_lock(&dns_cache.cache[i]->lock);
        if (!strcmp(hostname, dns_cache.cache[i]->hostname)) {
            memcpy(ip, &dns_cache.cache[i]->addr, sizeof(struct sockaddr_in));
            pthread_mutex_unlock(&dns_cache.cache[i]->lock);
            return 0; // Found in cache
        }
        pthread_mutex_unlock(&dns_cache.cache[i]->lock);
    }

    // DNS resolution and logging
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;

    int err = getaddrinfo(hostname, NULL, &hints, &res);
    if (err != 0) {
        fprintf(stderr, "DNS error: %s\n", gai_strerror(err));
        return -1; // DNS error
    }

    struct sockaddr_in* addr = (struct sockaddr_in*)res->ai_addr;
    memcpy(ip, addr, sizeof(struct sockaddr_in));

    // Cache insertion and logging
    if ((dns_cache.capacity == dns_cache.size) && dns_cache.capacity > 0) {
        dns_cache.capacity *= 2;
        realloc(dns_cache.cache, sizeof(struct host_data*) * dns_cache.capacity);
    }

    struct host_data* new_entry = malloc(sizeof(struct host_data));
    strcpy(new_entry->hostname, hostname);
    memcpy(&new_entry->addr, ip, sizeof(struct sockaddr_in));
    pthread_mutex_init(&new_entry->lock, NULL);

    dns_cache.cache[dns_cache.size++] = new_entry;

    // ... Logging using libcurl or another HTTP library here ...

    return 0; // Successfully resolved IP
}
```']

