typedef struct _UE_SESSION_DATA {
    uint64_t pdu_session_id;
    int s_nssai;
    QoSLinkedList qos_rules;
} UE_SESSION_DATA;

struct memory_pool {
    void *memory;
    size_t capacity;
    size_t allocated;
};

void *ue_session_data_mem_alloc(struct memory_pool *pool) {
    if (pool->allocated >= pool->capacity) {
        if (expand_pool(pool)) return NULL;
    }

    return pool->memory + pool->allocated++;;
}

void ue_session_data_mem_free(struct memory_pool *pool, void *mem) {
    if (mem >= pool->memory && mem < (pool->memory + pool->capacity))
        pool->allocated--;
}

void expand_pool(struct memory_pool *pool) {
    size_t new_capacity = (pool->capacity + 512) / 2 * 2; // Round up to nearest power of two
    void *new_mem = mmap(NULL, new_capacity, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (new_mem == MAP_FAILED) {
        log_error("Failed to expand memory pool");
        return false;
    }

    memcpy(new_mem, pool->memory, pool->capacity);
    munmap((void *)pool->memory, pool->capacity); // Unmap old memory block
    pool->memory = new_mem;
    pool->capacity = new_capacity;
}

UE_SESSION_DATA* create_ue_session_data(const CONFIG *config) {
