class NFAPI_CRC_INDICATION_PDU {
public:
    explicit NFAPI_CRC_INDICATION_PDU(size_t n) : pdu_(n, {0, 0, 0, false}) {}

    void initialize() {
        if (n_ == 0) return;
        std::generate(std::begin(pdu_), std::end(pdu_), [this] () mutable {
            auto pdu = *this->begin();
            pdu.CRCFLAG = static_cast<bool>(rand() % 2);
            return pdu;
        });
    }

    void populate() {
        std::scoped_lock lock(mutex_);
        for (auto& pdu : pdu_) {
            pdu.RX_UE_INFORMATION_TAG = rand();
            pdu.RNTI = rand();
            pdu.CRC_INDICATION_REL8_TAG = rand();
        }
    }

    void validate() const {
        std::scoped_lock lock(mutex_);
        if (pdu_.empty()) return;

        size_t count = 0;
        for (const auto& pdu : pdu_) {
            if (!pdu.CRCFLAG && pdu.RX_UE_INFORMATION_TAG != pdu.RNTI) ++count;
        }

        if (count > 0) throw std::runtime_error("Memory leak detected!");
    }

    void monitor() {
        // Implement a monitoring tool here, e.g., printing the number of elements and memory usage periodically
    }

    ~NFAPI_CRC_INDICATION_PDU() {
        free(pdu_.data());
    }

private:
    std::vector<NFAPI_CRC_INDICATION_PDU_T> pdu_;
    size_t n_;
    pthread_mutex_t mutex_;
};

void threaded_populate(NFAPI_CRC_INDICATION_PDU& pdu) {
    pdu.populate();
}

int main() {
    const int N = 1000;
    try {
        auto pdu = NFAPI_CRC_INDICATION_PDU(N);
        pdu.initialize();
        pdu.validate();

        std::vector<std::thread> threads;
        for (int i = 0; i < std::thread::hardware_concurrency(); ++i) {
            threads.push_back(std::thread(threaded_populate, ref(pdu)));
        }

        for (auto& thread : threads) thread.join();
        pdu.validate();
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << '\n';
    }

    return 0;
}
