    // Add other relevant fields here
} NFAPI_CRC_INDICATION_PDU_T;

enum ErrorCodes {
    NO_ERROR = 0,
    INVALID_OPERATION = -1,
    MEMORY_ALLOCATION_FAILURE = -2,
    DUPLICATE_TAG = -3,
};

struct data_manager {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t length;
    pthread_mutex_t mutex;
    void *shared_memory_region;
    bool is_shared;
};

struct data_manager create_data_manager() {
    struct data_manager manager;
    manager.length = 0;
    manager.data = NULL;
    manager.mutex = PTHREAD_MUTEX_INITIALIZER;
    manager.shared_memory_region = NULL;
    manager.is_shared = false;
    return manager;
}

int add_data(struct data_manager *manager, const NFAPI_CRC_INDICATION_PDU_T *data) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->length >= MAX_ELEMENTS) {
        pthread_mutex_unlock(&manager->mutex);
        return DUPLICATE_TAG;
    }
    for (size_t i = 0; i < manager->length; ++i) {
        if (manager->data[i].RX_UE_INFORMATION_TAG == data->RX_UE_INFORMATION_TAG) {
            pthread_mutex_unlock(&manager->mutex);
            return DUPLICATE_TAG;
        }
    }

    manager->data[manager->length] = *data;
    ++manager->length;

    pthread_mutex_unlock(&manager->mutex);
    return NO_ERROR;
}

void reset_data(struct data_manager *manager) {
    pthread_mutex_lock(&manager->mutex);
    manager->length = 0;
    pthread_mutex_unlock(&manager->mutex);
}

struct data_manager *init_shared_memory(size_t size) {
    void *region;
    struct mprotect_args args = {.start_addr = MAP_FAILED, .len = 0};
    if (posix_memalign(&region, SYS_PAGE_SIZE, size) != 0 || mprotect(region, PROT_READ | PROT_WRITE, PROT_EXEC) == -1) {
        perror("Failed to initialize shared memory");
        return NULL;
    }

    args.start_addr = region;
    args.len = size;
    if (mprotect(region + size - MAX_ELEMENTS * sizeof(NFAPI_CRC_INDICATION_PDU_T), PROT_NONE) == -1) {
        perror("Failed to set protections on shared memory");
        free(region);
        return NULL;
    }

    struct data_manager manager = create_data_manager();
    manager.shared_memory_region = region;
    manager.is_shared = true;

    return &manager;
}

void destroy_data_manager(struct data_manager *manager) {
    if (manager->shared_memory_region != NULL) {
        munmap((void *)manager->shared_memory_region, manager->length * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    } else {
        free(manager->data);
    }
}
