};

void dynamic_array_init(struct dynamic_array *array, size_t initial_capacity, size_t max_buffer_size) {
    array->data = malloc(initial_capacity * sizeof(NFAPI_L2_RX_PDU_T*));
    array->capacity = initial_capacity;
    array->count = 0;
    array->max_buffer_size = max_buffer_size;
    array->ue_manager = UE_Information_Manager_create();
}

void dynamic_array_destroy(struct dynamic_array *array) {
    for (size_t i = 0; i < array->count; ++i) {
        free(array->data[i]->data);
    }
    free(array->data);
    UE_Information_Manager_destroy(array->ue_manager);
}

NFAPI_L2_RX_PDU_T* dynamic_array_push(struct dynamic_array *array) {
    if (array->count == array->capacity) {
        array->capacity *= 2;
        array->data = realloc(array->data, array->capacity * sizeof(NFAPI_L2_RX_PDU_T*));
    }
    NFAPI_L2_RX_PDU_T *new_pdu = malloc(sizeof(NFAPI_L2_RX_PDU_T));
    pthread_mutex_init(&new_pdu->lock, NULL);
    array->data[array->count++] = new_pdu;
    return new_pdu;
}

bool dynamic_array_update(struct dynamic_array *array, size_t index, const RX_UE_INFORMATION_TAG tag, const RNTI rnti) {
    if (index >= array->count || !array->data[index]) {
        return false;
    }
    pthread_mutex_lock(&array->data[index]->lock);
    array->data[index]->tag = tag;
    array->data[index]->rnti = rnti;
    UE_Information_Manager_update(array->ue_manager, array->data[index]->rnti, &array->data[index]->timestamp); // Update UE information
    pthread_mutex_unlock(&array->data[index]->lock);
    return true;
}

size_t dynamic_array_get_processed_pdus(const struct dynamic_array *array) {
    size_t processed_pdus = 0;
    for (size_t i = 0; i < array->count; ++i) {
        if (array->data[i]->timestamp > array->ue_manager->last_update_time) {
            ++processed_pdus;
        }
    }
    return processed_pdus;
}
