    RX_UE_INFORMATION_TAG rxtag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crcindTag;
};

std::mutex mtx;
std::vector<NFAPI_CRC_INDICATION_PDU_T> pduList;
boost::lockfree::spsc_queue<NFAPI_CRC_INDICATION_PDU_T*, boost::lockfree::capacity<1024>> queue;

// Function to generate and populate a list of PDU structures with random data
void generatePDUs(size_t count) {
    if (count > 50000) throw std::exception("Invalid input size");

    for (size_t i = 0; i < count; ++i) {
        std::unique_lock<std::mutex> lock(mtx);
        pduList.emplace_back();
        auto& pdu = pduList.back();

        // Set your structure data here
        pdu.rxtag = RX_UE_INFORMATION_TAG{};
        pdu.rnti = RNTI{};
        pdu.crcindTag.CRCIFlag = rand() % 2;
    }
}

// Function to enqueue PDUs for processing by other threads
void enqueuePDUs(NFAPI_CRC_INDICATION_PDU_T pdus[], size_t count) {
    for (size_t i = 0; i < count; ++i) queue.push(pdus + i);
}

// Function to process PDUs from the queue and store them in pduList, ensuring thread safety
void processPDUs() {
    while (!queue.empty()) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = queue.pop();
        std::unique_lock<std::mutex> lock(mtx);
        pduList.push_back(*pdu);
    }
}

// Function to calculate memory usage and print performance metrics in real-time
void monitor() {
    auto start = std::chrono::high_resolution_clock::now();
    size_t totalMemoryUsage = 0;

    while (true) {
        auto duration = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::high_resolution_clock::now() - start).count();
        totalMemoryUsage += pduList.size() * sizeof(NFAPI_CRC_INDICATION_PDU_T);

        std::cout << "Elapsed time: " << duration << "ms, Memory usage: " << totalMemoryUsage / (1024.0 * 1024.0) << "MB\n";
        std::this_thread::sleep_for(std::chrono::milliseconds(500)); // Adjust this sleep duration as needed
    }
}
