List* create_list(int initial_capacity) {
    List* list = malloc(sizeof(List));
    if (!list) {
        perror("malloc");
        return NULL;
    }
    list->capacity = initial_capacity;
    list->size = 0;
    list->head = list->tail = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    pthread_cond_init(&list->not_full, PTHREAD_COND_INITIALIZER);
    pthread_cond_init(&list->not_empty, PTHREAD_COND_INITIALIZER);
    return list;
}

void resize(List* list) {
    if (list->capacity * 2 >= MAX_CAPACITY)
        return;
    Node** nodes = realloc(list->head, sizeof(Node) * (list->capacity * 2));
    if (!nodes) {
        perror("realloc");
        return;
    }
    list->capacity *= 2;
    list->head = nodes;
}

int push_back(List* list, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    Node* node = malloc(sizeof(Node));
    if (!node) {
        perror("malloc");
        return -1;
    }
    node->data = *pdu;
    node->next = NULL;

    pthread_mutex_lock(&list->mutex);
    if (list->size == list->capacity) {
        resize(list);
    }
    if (!list->tail) {
        list->head = node;
        list->tail = node;
    } else {
        list->tail->next = node;
        list->tail = node;
    }
    list->size++;
    pthread_mutex_unlock(&list->mutex);
    pthread_cond_signal(&list->not_full);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* pop_front(List* list) {
    pthread_mutex_lock(&list->mutex);
    if (!list->size) {
        pthread_cond_wait(&list->not_empty, &list->mutex);
    }
    Node* node = list->head;
    if (node) {
        list->head = node->next;
        if (!list->head)
            list->tail = NULL;
        NFAPI_CRC_INDICATION_PDU_T* pdu = &node->data;
        free(node);
        list->size--;
    }
    pthread_mutex_unlock(&list->mutex);
    pthread_cond_signal(&list->not_empty);
    return pdu;
}

