#define MAX_KEY_SIZE 256
#define TIMEOUT_MS 10000L // 10 seconds timeout

typedef struct Cipher *CipherPtr;

struct Cipher {
    void* handle;
    void (*encrypt)(void*, const char*, char*);
    void (*decrypt)(void*, const char*, char*);
    int key_size;
};

// Function to check if a file exists and application has sufficient permissions.
bool validateFile(const char* path) {
    struct stat st;
    return (stat(path, &st) == 0 && S_ISREG(st.st_mode));
}

CipherPtr processFileOperation(const char* path, const char* operation, int key_size) {
    if (!validateFile(path)) {
        fprintf(stderr, "Error: Invalid file path.\n");
        return NULL;
    }

    CipherPtr cipher = loadCipher(operation);

    if (key_size == 0)
        key_size = generateKey(cipher);

    char *buffer = malloc(4096); // 4KB buffer for performance optimization

    FILE* fp = fopen(path, "rb");

    if (!fp) {
        fprintf(stderr, "Error: Failed to open file.\n");
        return NULL;
    }

    CipherPtr cipherResult = malloc(sizeof(struct Cipher));
    cipherResult->handle = cipher->handle;
    cipherResult->encrypt = cipher->encrypt;
    cipherResult->decrypt = cipher->decrypt;
    cipherResult->key_size = key_size;

    size_t bytesRead, totalBytes = 0;
    clock_t startTime = clock();

    while ((bytesRead = fread(buffer, 1, sizeof(buffer), fp))) {
        if (clock() - startTime > TIMEOUT_MS) {
            fprintf(stderr, "Warning: Operation timed out.\n");
            break;
        }

        if (operation[0] == 'e') // Encryption
            cipherResult->encrypt(cipherResult->handle, buffer, NULL);
        else                     // Decryption
            cipherResult->decrypt(cipherResult->handle, buffer, NULL);

        totalBytes += bytesRead;
    }

    fclose(fp);
    free(buffer);

    if (totalBytes == 0) {
        fprintf(stderr, "Error: No data read from file.\n");
        free(cipherResult);
        return NULL;
    }

    return cipherResult;
}
```

