#include <iostream>
#include <memory>
#include <new>
#include <unordered_map>
#include <mutex>
#include <cassert>
#include <stdexcept>

class LtePhyLayerConfig {
public:
    enum Modulation { QPSK, 16QAM, 64QAM };
    struct ConfigData {
        Modulation modulation;
        int bandwidth;
        std::vector<int> antennaPorts;

        constexpr ConfigData(Modulation m = QPSK, int bw = 0, const std::initializer_list<int>& ap = {}) noexcept
            : modulation(m), bandwidth(bw), antennaPorts(ap) {}
    };

    explicit LtePhyLayerConfig(int id) noexcept
        : id_(id), data_(nullptr) {}

    ConfigData& data() {
        if (!data_)
            throw std::runtime_error("LtePhyLayerConfig not initialized");
        return *data_;
    }

    const ConfigData& data() const {
        if (!data_)
            throw std::runtime_error("LtePhyLayerConfig not initialized");
        return *data_;
    }

    void set_data(ConfigData&& d) noexcept {
        if (data_)
            throw std::runtime_error("LtePhyLayerConfig already initialized");
        data_ = std::make_unique<ConfigData>(std::move(d));
    }

private:
    int id_;
    std::unique_ptr<ConfigData, std::default_delete<ConfigData>> data_;
};

class LtePhyLayerConfigManager {
public:
    LtePhyLayerConfig& add(LtePhyLayerConfig&& config) {
        std::scoped_lock guard(mutex_);
        if (configs_.count(config.id_))
            throw std::runtime_error("ID already in use");
        auto result = configs_.emplace(std::move(config));
        return *result.first;
    }

    LtePhyLayerConfig& get(int id) {
        std::scoped_lock guard(mutex_);
        auto it = configs_.find(id);
        if (it == configs_.end())
            throw std::runtime_error("Configuration not found");
        return *it->second;
    }

private:
    std::unordered_map<int, LtePhyLayerConfig> configs_;
    mutable std::mutex mutex_;
};
```

