typedef struct _MEM_POOL {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} MEM_POOL;

void mem_pool_init(MEM_POOL* pool, size_t capacity) {
    pool->data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pool->capacity = capacity;
    pool->count = 0;
    pthread_mutex_init(&pool->mutex, NULL);
}

void* mem_pool_acquire(MEM_POOL* pool) {
    void* ptr;

    pthread_mutex_lock(&pool->mutex);
    if (pool->count < pool->capacity) {
        ptr = &(pool->data[pool->count++]);
    } else {
        ptr = NULL;
    }
    pthread_mutex_unlock(&pool->mutex);

    return ptr;
}

void mem_pool_release(MEM_POOL* pool, void* data) {
    if (data != NULL) {
        pthread_mutex_lock(&pool->mutex);
        pool->data[--pool->count] = *(NFAPI_CRC_INDICATION_PDU_T*)data;
        pthread_mutex_unlock(&pool->mutex);
    }
}

// External data source to check RNTI uniqueness
int rnti_is_unique(uint16_t rnti);

void* worker(void* arg) {
    MEM_POOL* pool = (MEM_POOL*)arg;
    size_t i, num_pudus = BATCH_SIZE;

    NFAPI_CRC_INDICATION_PDU_T* pdu = mem_pool_acquire(pool);
    for (i = 0; i < num_pudus; ++i) {
        pthread_mutex_lock(&pool->mutex);
        while (!rnti_is_unique((pdu + i)->RNTI)) {
            // Log failed attempt to generate unique RNTI value
        }
        (pdu + i)->RX_UE_INFORMATION_TAG = i;
        (pdu + i)->CRC_INDICATION_REL8_TAG[0] = i & 0xFF;
        (pdu + i)->CRC_INDICATION_REL8_TAG[1] = (i >> 8) & 0xFF;
        (pdu + i)->CRC_INDICATION_REL8_TAG[2] = (i >> 16) & 0xFF;
        (pdu + i)->CRC_INDICATION_REL8_TAG[3] = (i >> 24) & 0xFF;
        pthread_mutex_unlock(&pool->mutex);
    }
    mem_pool_release(pool, pdu);

    return NULL;
}

void populate_list(MEM_POOL* pool, size_t list_size) {
    pthread_t threads[NUM_THREADS];

    mem_pool_init(pool, (list_size + BATCH_SIZE - 1) / BATCH_SIZE * BATCH_SIZE);

    size_t num_threads = NUM_THREADS < list_size / BATCH_SIZE ? NUM_THREADS : list_size / BATCH_SIZE;
    for (size_t i = 0; i < num_threads; ++i) {
        pthread_create(&threads[i], NULL, worker, pool);
    }

    // Wait for all threads to complete
    for (size_t i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }
}
```
