    double amount;
    double weight;
};

class TransactionFilteringSystem {
public:
    void enqueueTransaction(const Transaction& transaction);
    std::pair<double, size_t, double> processTransactions();

private:
    std::mutex mtx_;
    std::deque<Transaction> transactions_;
    std::atomic<size_t> valid_count_{0};
    std::atomic<double> max_weighted_sum_{0.0};
    std::atomic<double> avg_transaction_weight_{0.0};
    double weighted_sum_{0.0};
    constexpr static size_t max_transactions_per_second = 100;
    constexpr static size_t backlog_queue_size = 1000;
    std::thread worker_threads_;
    bool is_paused_{false};

    void worker();
};

void TransactionFilteringSystem::enqueueTransaction(const Transaction& transaction) {
    // Enqueuing transactions without lock to ensure concurrency
    transactions_.push_back(transaction);
}

std::pair<double, size_t, double> TransactionFilteringSystem::processTransactions() {
    // Lock for reading and updating metrics
    std::lock_guard<std::mutex> lck(mtx_);

    auto start = std::chrono::steady_clock::now();
    size_t processed_transactions = 0;
    double total_weight = 0.0;

    // Process transactions from the front of the queue, but limit the number of transactions per second
    for (auto it = transactions_.begin(); it != transactions_.end() && processed_transactions < backlog_queue_size; ) {
        auto now = std::chrono::steady_clock::now();
        if (std::chrono::duration_cast<std::chrono::seconds>(now - start).count() >= 1) {
            start = now;
            processed_transactions = 0;
        }

        if (processed_transactions < max_transactions_per_second && it != transactions_.end()) {
            auto transaction = *it++;
            total_weight += transaction.amount * transaction.weight;
            valid_count_++;
            avg_transaction_weight_ = valid_count_ / processed_transactions;

            if (total_weight > 0.9 * max_weighted_sum_) {
                is_paused_ = true;
                break;
            }
        }
    }

    // Update max_weighted_sum_ only when not paused, to avoid contention during pause
    if (!is_paused_) {
        max_weighted_sum_ = std::max(max_weighted_sum_, total_weight);
    }

    return { max_weighted_sum_.load(), valid_count_.load(), avg_transaction_weight_.load() };
}

void TransactionFilteringSystem::worker() {
    while (true) {
        auto [max_ws, count, avg_wt] = processTransactions();
        // Logging and error handling go here for invalid transactions or other issues
