#include <sys/mman.h>

typedef struct Node {
    int data;
    struct Node* next;
} Node;

Node* create_node(int data) {
    Node* new_node = (Node*) malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void append(Node** head_ref, Node* new_node) {
    if (*head_ref == NULL) {
        *head_ref = new_node;
        return;
    }

    Node* last = *head_ref;
    while (last->next != NULL)
        last = last->next;

    last->next = new_node;
}

int read_and_validate(FILE* file, int min, int max) {
    int num;
    if (!(fscanf(file, "%d", &num))) // end of file reached or input error
        return 0;

    if (num < min || num > max)
        return 0;
    else
        return num;
}

void find_largest(Node* head, int* largest) {
    Node* current = head;
    *largest = INT32_MIN;

    while (current != NULL) {
        if (current->data > *largest)
            *largest = current->data;

        current = current->next;
    }
}

void print_results(int* largest, int num_valid) {
    if (num_valid == 0)
        printf("No valid integers found\n");
    else
        printf("The largest integer is %d\n", *largest);
}

void free_list(Node** head_ref) {
    Node* current = *head_ref;
    Node* temp;

    while (current != NULL) {
        temp = current;
        current = current->next;
        free(temp);
    }

    *head_ref = NULL;
}

int main() {
    FILE* file = fopen("input.txt", "r");
    if (!file) {
        fprintf(stderr, "Failed to open input file\n");
        return EXIT_FAILURE;
    }

    int min = -1000;
    int max = 1000;
    Node* head = NULL;
    int num_valid = 0;
    int largest = INT32_MIN;
    int num;

    while ((num = read_and_validate(file, min, max))) {
        append(&head, create_node(num));
        num_valid++;
    }

    find_largest(head, &largest);
    print_results(&largest, num_valid);

    fclose(file);
    free_list(&head);

    return EXIT_SUCCESS;
}
