#include <stdint.h>
#include <tbb/concurrent_queue.h>
#include <tbb/tbb_thread.h>

typedef struct LTE_PHY_RX_FRAME_T {
    uint32_t RF_CHANNEL;
    uint64_t FRAME_NUMBER;
    uint16_t SUBFRAME_INDEX;
} LTE_PHY_RX_FRAME_T;

typedef struct FrameManager_s {
    LTE_PHY_RX_FRAME_T** frames;
    size_t capacity;
    size_t count;
    tbb::concurrent_queue<LTE_PHY_RX_FRAME_T> update_queue;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} FrameManager;

FrameManager* frame_manager_init(size_t initial_capacity) {
    FrameManager* manager = malloc(sizeof(FrameManager));
    if (!manager) return NULL;

    manager->frames = calloc(initial_capacity, sizeof(LTE_PHY_RX_FRAME_T*));
    if (!manager->frames) {
        free(manager);
        return NULL;
    }

    pthread_mutex_init(&manager->mutex, NULL);
    pthread_cond_init(&manager->cond, NULL);

    manager->capacity = initial_capacity;
    manager->count = 0;

    return manager;
}

void frame_manager_destroy(FrameManager* manager) {
    for (size_t i = 0; i < manager->capacity; ++i) {
        free(manager->frames[i]);
    }
    free(manager->frames);
    pthread_mutex_destroy(&manager->mutex);
    pthread_cond_destroy(&manager->cond);
    free(manager);
}

LTE_PHY_RX_FRAME_T* frame_manager_get_frame(FrameManager* manager) {
    pthread_mutex_lock(&manager->mutex);
    while (manager->count >= manager->capacity && !manager->update_queue.empty()) {
        pthread_cond_wait(&manager->cond, &manager->mutex);
    }

    LTE_PHY_RX_FRAME_T* frame = NULL;
    if (manager->count < manager->capacity) {
        frame = manager->frames[manager->count];
        manager->frames[manager->count++] = NULL;
    } else {
        frame = manager->update_queue.front();
        manager->update_queue.pop();
    }

    pthread_mutex_unlock(&manager->mutex);
    return frame;
}

void frame_manager_add_frame(FrameManager* manager, LTE_PHY_RX_FRAME_T* frame) {
    if (manager->count >= manager->capacity * 2 / 3) {
        manager->capacity *= 2;
        LTE_PHY_RX_FRAME_T** new_frames = realloc(manager->frames, manager->capacity * sizeof(LTE_PHY_RX_FRAME_T*));
        if (!new_frames) return;
        manager->frames = new_frames;
    }

    pthread_mutex_lock(&manager->mutex);
    manager->frames[manager->count] = frame;
    manager->count++;
    pthread_mutex_unlock(&manager->mutex);
}

void frame_manager_update(FrameManager* manager, LTE_PHY_RX_FRAME_T* frame) {
    manager->update_queue.push(frame);
    pthread_mutex_lock(&manager->mutex);
    pthread_cond_signal(&manager->cond);
    pthread_mutex_unlock(&manager->mutex);
}
```

