typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

// Synchronize access to the array with a thread-safe data structure
pthread_mutex_t array_lock = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T* pdu_array = NULL;
size_t user_count = 0;

// Logging function integrated with existing logging framework
void log_pdu_creation(size_t index) {
    char timestamp[20];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    printf("PDU creation [%lu]: Index: %lu, Timestamp: %s\n", threadid_current(), index, timestamp);
}

void* create_pdus(void* arg) {
    size_t* max_users = (size_t*)arg;
    for (size_t i = 0; i < *max_users; ++i) {
        pthread_mutex_lock(&array_lock);
        if (user_count >= *max_users) {
            pthread_mutex_unlock(&array_lock);
            break;
        }
        NFAPI_CRC_INDICATION_PDU_T* new_pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pdu) {
            pthread_mutex_unlock(&array_lock);
            continue;
        }
        memset(new_pdu, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        new_pdu->rx_ue_information_tag = RX_UE_INFORMATION_TAG_VALUE;
        new_pdu->rnti = i;
        new_pdu->crc_indication.crcflag = rand() % 2;
        pdu_array[user_count] = new_pdu;
        user_count++;
        log_pdu_creation(i);
        pthread_mutex_unlock(&array_lock);
    }
    return NULL;
}

void free_pdus() {
    for (size_t i = 0; i < user_count; ++i) {
        free(pdu_array[i]);
    }
    free(pdu_array);
    user_count = 0;
}

int main(int argc, char** argv) {
    if (argc != 2) {
        printf("Usage: %s <number of concurrent users>\n", argv[0]);
        return -1;
    }
    size_t max_users = atoi(argv[1]);
    pdu_array = malloc(max_users * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_array) {
        printf("Error: Failed to allocate memory for PDUs\n");
        return -1;
    }

    pthread_t threads[MAX_USERS];
    for (size_t i = 0; i < max_users; ++i) {
        if (pthread_create(&threads[i], NULL, create_pdus, &max_users)) {
            printf("Error: Failed to create thread\n");
            free_pdus();
            return -1;
        }
    }

    for (size_t i = 0; i < max_users; ++i) {
        pthread_join(threads[i], NULL);
    }

    free_pdus();
    return 0;
}
