struct managed_array {
    PDU_T* elements;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
};

void init_managed_array(struct managed_array* array) {
    array->elements = NULL;
    array->count = 0;
    array->capacity = 0;
    pthread_mutex_init(&array->lock, NULL);
}

static void grow_managed_array(struct managed_array* array) {
    if (array->capacity == 0) {
        array->capacity = 32;
    }

    if (array->count + 16 >= array->capacity) {
        size_t new_capacity = array->capacity * 2 > MAX_ELEMENTS ? MAX_ELEMENTS : array->capacity * 2;
        PDU_T* temp_elements = realloc(array->elements, sizeof(PDU_T) * new_capacity);
        if (!temp_elements) {
            fprintf(stderr, "Failed to resize managed array\n");
            exit(EXIT_FAILURE);
        }
        array->elements = temp_elements;
        array->capacity = new_capacity;
    }
}

void push_to_managed_array(struct managed_array* array, const PDU_T* pdu) {
    pthread_mutex_lock(&array->lock);

    grow_managed_array(array);
    array->elements[array->count] = *pdu;
    array->count++;

    pthread_mutex_unlock(&array->lock);
}

PDU_T* pop_from_managed_array(struct managed_array* array) {
    PDU_T* result = NULL;

    pthread_mutex_lock(&array->lock);

    if (array->count > 0) {
        result = &array->elements[--array->count];
    }

    pthread_mutex_unlock(&array->lock);

    return result;
}
```

