    void insertValueAfterTarget(std::forward_list<std::string>& list, const std::string& target, const std::string& value) {
        auto it = list.begin();
        if (it != list.end() && *it == target) {
            it++;
            list.insert(it, value);
        } else {
            list.push_back(target);
            list.push_back(value);
        }
    }
}

