#include <pthread.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <sys/mman.h>
#include <sys/sysinfo.h>

#define MAX_THREADS 100
#define MAX_ELEMENTS 15000
#define MEMORY_THRESHOLD 90

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

static NFAPI_CRC_INDICATION_PDU_T* data = NULL;
static size_t num_elements = 0;
static size_t allocated = 0;
static pthread_mutex_t resize_lock = PTHREAD_MUTEX_INITIALIZER;
static bool resizing = false;

void init() {
    if (data) return;
    allocated = MAX_ELEMENTS / MEMORY_THRESHOLD;
    data = mmap(NULL, allocated * sizeof(NFAPI_CRC_INDICATION_PDU_T), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANON, -1, 0);
    if (data == MAP_FAILED) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    num_elements = allocated;
}

void resize() {
    pthread_mutex_lock(&resize_lock);
    if (!resizing && (double)num_elements / (double)allocated >= MEMORY_THRESHOLD) {
        size_t new_allocated = num_elements * 2;
        NFAPI_CRC_INDICATION_PDU_T* temp = realloc(data, new_allocated * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (temp == NULL) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
        data = temp;
        allocated = new_allocated;
    }
    resizing = false;
    pthread_mutex_unlock(&resize_lock);
}

void log_resize() {
    struct sysinfo info;
    sysinfo(&info);
    printf("Array resized. Current memory usage: %f%%\n", (double)info.freeram / info.totalram * 100.0);
}

void push(NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&resize_lock);
    if (num_elements == allocated) resizing = true;
    memcpy(&data + num_elements, &data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    ++num_elements;
    pthread_mutex_unlock(&resize_lock);
}

void* thread_func() {
    NFAPI_CRC_INDICATION_PDU_T random_data;
    random_data.crc_indication.crcflag = rand() % 2;
    push(random_data);
    return NULL;
}
```

