#define MAX_EXT_LEN 5
#define EXT_DEFAULT ".default"
#define EXT_CRC ".crc"

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint64_t RNTI;
    uint16_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

char* get_extension(const char* filename) {
    size_t ext_len = 0;
    const char* ext_start = nullptr;

    for (size_t i = strlen(filename) - 1; i > 0; --i) {
        if (!isalnum((unsigned char)filename[i]) && ext_len < MAX_EXT_LEN) {
            ext_start = &filename[i];
            ext_len++;
        } else if (ext_start != nullptr && ext_len == MAX_EXT_LEN) {
            break;
        }
    }

    return ext_start ? ext_start : EXT_DEFAULT;
}

void log_info(const char* msg) {
    // Implement your logging framework here
    printf("%s\n", msg);
}

int is_valid_filename(const char* filename) {
    for (size_t i = 0; filename[i]; ++i) {
        if (!isalnum((unsigned char)filename[i]) && !strchr("._-", &filename[i])) {
            return 0;
        }
    }
    return 1;
}

char* generate_crc_indications(const char* filename) {
    if (!is_valid_filename(filename)) {
        log_info("Invalid filename.");
        return nullptr;
    }

    size_t num_structures = strlen(filename);
    const char* ext = get_extension(filename);
    char new_ext[MAX_EXT_LEN + 1];
    sprintf(new_ext, "%s%zu%s", ext + strlen(ext) - 1, num_structures, EXT_CRC);

    NFAPI_CRC_INDICATION_PDU_T* indications = (NFAPI_CRC_INDICATION_PDU_T*)calloc(num_structures, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!indications) {
        log_info("Failed to allocate memory.");
        return nullptr;
    }

    srand(time(NULL));
    for (size_t i = 0; i < num_structures; ++i) {
        uint32_t tag = i + 1;
        indications[i].RX_UE_INFORMATION_TAG = htonl(tag);

        uint64_t rnti = 0;
        for (size_t j = 0; filename[j]; ++j) {
            if (isalnum((unsigned char)filename[j])) {
                rnti |= (static_cast<uint64_t>(tolower((unsigned char)filename[j]) - 'a' + 10) << ((j * 5) % 63));
            }
        }
        indications[i].RNTI = htobe64(rnti);

        indications[i].CRC_INDICATION_REL8_TAG = rand() % 256;
    }

    log_info(std::to_string(num_structures) + " structures generated.");
    return filename;
}
