#include <vector>
#include <random>
#include <boost/crc.hpp>
#include <pthread.h>

// Define necessary structures
struct RX_UE_INFORMATION_TAG { uint8_t tag; };
struct RNTI { uint64_t rnti; };
struct CRC_INDICATION_REL8_TAG { bool crcflag; };
struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG ue_information_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
};

class NFAPI_CRC_INDICATION_PDU_LIST {
private:
    static constexpr uint32_t PDU_COUNT = 1000; // Change this value according to requirements
    std::vector<NFAPI_CRC_INDICATION_PDU_T> pduList_;
    pthread_mutex_t mutex;
    boost::crc_32_type crcGen_;

public:
    NFAPI_CRC_INDICATION_PDU_LIST(uint32_t numUsers) {
        pthread_mutex_init(&mutex, nullptr);
        crcGen_.reset();

        // Generate PDUs for N unique users
        std::mt19937 gen(std::random_device{}());
        std::uniform_int_distribution<> distrib(0, PDU_COUNT-1);
        for (uint32_t i = 0; i < numUsers; ++i) {
            auto ueInfoTag = static_cast<RX_UE_INFORMATION_TAG>(i);
            auto rnti = static_cast<RNTI>((i + distrib(gen)) << 32 | distrib(gen));
            pduList_.push_back({ueInfoTag, rnti, {true}});
            crcGen_.process_bytes(&pduList_[pduList_.size()-1], sizeof(NFAPI_CRC_INDICATION_PDU_T));
        }
    }

    ~NFAPI_CRC_INDICATION_PDU_LIST() {
        pthread_mutex_destroy(&mutex);
    }

    void getPDU(NFAPI_CRC_INDICATION_PDU_T& pdu) const {
        pthread_mutex_lock(&mutex);
        if (!pduList_.empty()) {
            auto pduToReturn = pduList_[0];
            pduList_.erase(pduList_.begin());
            pthread_mutex_unlock(&mutex);
            return;
        }
        pthread_mutex_unlock(&mutex);
    }

    uint32_t getCrc() const {
        crcGen_.finalize();
        return static_cast<uint32_t>(crcGen().checksum());
    }
};
```

