        for (auto &mode : config.get_child("modes")) {
            memcpy(&validConfigs[i], &mode.second, sizeof(Config));
            i++;
        }
        qsort(validConfigs, validConfigs->size(), sizeof(Config), compareConfig);

        Config currentConfig = validConfigs[0];
        strcpy(currentConfig.ifname, "eth0"); // Default interface name

