// Custom memory pool allocator
typedef struct MemBlock {
    void* data;
    size_t size;
    struct MemBlock *next;
} MemBlock;

MemBlock* mem_pool = NULL;
size_t mem_pool_capacity = 0;

void* mem_alloc(size_t size) {
    if (mem_pool_capacity == 0 || mem_pool == NULL) {
        // Initialize or extend the memory pool when needed
    }
    MemBlock *current = mem_pool;
    while (current != NULL) {
        if (!current->next) break;
        current = current->next;
    }
    if (!current->next) {
        current->next = malloc(sizeof(MemBlock));
        current = current->next;
    }
    current->data = malloc(size);
    current->size = size;
    return current->data;
}

void mem_free(void* ptr) {
    if (ptr == NULL) return;
    MemBlock *block = (MemBlock*)malloc(sizeof(MemBlock));
    block->data = ptr;
    block->size = 0;
    block->next = mem_pool;
    mem_pool = block;
}

