int process_media(ProcessMediaParams *params) {
    // Validate input paths and file types
    if (!access(params->source, F_OK)) {
        fprintf(stderr, "Error: Source file does not exist.\n");
        return -1;
    }

    struct stat source_stat;
    if (stat(params->source, &source_stat) == -1) {
        perror("stat");
        return -1;
    }

    const char *dest_dir = strdup(params->destination);
    size_t last_slash = strlen(dest_dir) - 1;
    while (last_slash > 0 && dest_dir[last_slash] != '/') last_slash--;
    if (!access(dest_dir, F_OK)) {
        // Directory exists, check for destination file existence
        char dest_file[PATH_MAX];
        strncpy(dest_file, params->destination + last_slash + 1, PATH_MAX);
        if (access(dest_file, F_OK) != -1) {
            fprintf(stderr, "Error: Destination file already exists.\n");
            return -1;
        }
    } else if (mkdir(dest_dir, S_IRWXU | S_IRWXG | S_IROTH | S_IXOTH) == -1) {
        perror("mkdir");
        return -1;
    }
    free(dest_dir);

    // Extract metadata and perform conversion based on media type
    void *metadata = malloc(sizeof(Metadata));
    extract_metadata(params->source, metadata);

    int quality = params->quality;
    int retries = 3;
    while (retries > 0) {
        if (params->type == IMAGE && quality >= LOW_QUALITY) {
            // Use convertimg for image conversion
            char cmd[1024];
            snprintf(cmd, sizeof(cmd), "convertimg -quality %d '%s' '%s/output.pdf' %s", quality, params->source, params->destination, metadata->image_format);
            if (system(cmd) == 0) {
                free(metadata);
                return 0;
            }
        } else if (params->type == VIDEO && quality >= LOW_QUALITY) {
            // Use ffmpeg for video conversion
            char cmd[1024];
            snprintf(cmd, sizeof(cmd), "ffmpeg -i '%s' -qscale:v %d '%s/output.pdf'", params->source, quality, params->destination);
            if (system(cmd) == 0) {
                free(metadata);
                return 0;
            }
        }

        --quality;
        retries--;
    }

    fprintf(stderr, "Error: Failed to convert media after %d attempts.\n", retries + 1);
    free(metadata);
    return -1;
}
