    void* value;
} ResourceBundleItem;

int convertImageToPdf(char* inputImageFile, char* outputPdfFile, char* configFile) {
    bool thirdPartyLibAvailable = true;
    int pdfConversionResult = 1;
    pid_t thirdPartyLibPid = 0;
    ResourceBundle* bundle = loadResourceBundle(configFile);

    // Use the third-party library if available
    if (thirdPartyLibAvailable) {
        thirdPartyLibPid = fork();

        if (thirdPartyLibPid == 0) {
            // Child process: Execute third-party command
            execl("/path/to/third_party_tool", "/path/to/third_party_tool", inputImageFile, outputPdfFile, configFile, NULL);
        } else if (thirdPartyLibPid > 0) {
            // Parent process: Wait for third-party command to complete
            waitpid(thirdPartyLibPid, &pdfConversionResult, 0);
        } else {
            thirdPartyLibAvailable = false;
        }
    }

    // Fallback mechanism if third-party library is unavailable or performs suboptimally
    if (!thirdPartyLibAvailable || (WIFSIGNALED(pdfConversionResult) && WTERMSIG(pdfConversionResult) != 0)) {
        // Implement image-to-PDF conversion using an alternative method
        // ...
    }

    int bundleSize = getResourceBundleSize(bundle);

    for (int i = 0; i < bundleSize; ++i) {
        free(bundle->items[i].key);
        free(bundle->items[i].value);
    }
    free(bundle);

    return thirdPartyLibAvailable && !WIFSIGNALED(pdfConversionResult);
}

ResourceBundle* loadResourceBundle(char* file) {
    int fd = open(file, O_RDONLY);
    ResourceBundle* bundle = malloc(sizeof(ResourceBundle));
    bundle->items = calloc(MAX_BUNDLE_SIZE, sizeof(ResourceBundleItem));

    if (fd < 0 || bundle == NULL) {
        perror("Error loading resource bundle");
        return NULL;
    }

    ssize_t bytesRead;
    ResourceBundleItem* currentItem = bundle->items;

    while ((bytesRead = read(fd, currentItem->key, sizeof(currentItem->key) - 1)) > 0) {
        currentItem->key[bytesRead] = '\0';
        currentItem++;

        if (read(fd, &currentItem->value, 1) < 1) {
            break;
        }

        currentItem++;
    }

    close(fd);
    bundle->size = currentItem - bundle->items;
    return bundle;
}

int getResourceBundleSize(const ResourceBundle* bundle) {
    return bundle->size;
}
