typedef struct HashNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct HashNode* next;
} HashNode;

const size_t MAX_LIST_SIZE = 10000; // Adjust according to system capabilities
HashNode** hashTable;
pthread_mutex_t mutex;

int create_list(size_t N) {
    if (N > MAX_LIST_SIZE) {
        perror("Exceeded maximum list size");
        return -1;
    }

    hashTable = malloc(sizeof(HashNode*) * 32); // Hash table of 32 buckets
    pthread_mutex_init(&mutex, NULL);

    for (size_t i = 0; i < 32; ++i) {
        hashTable[i] = NULL;
    }

    size_t count = 0;
    NFAPI_CRC_INDICATION_PDU_T* data = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!data) {
        perror("Failed to allocate memory for structures");
        return -1;
    }

    srand(time(NULL));

    // Fill and validate the data structures
    for (size_t i = 0; i < N && count < MAX_LIST_SIZE; ++i) {
        data[i].RX_UE_INFORMATION_TAG = rand();
        data[i].RNTI = get_RNTI(); // Assuming a function to fetch RNTI values is available

        pthread_mutex_lock(&mutex);
        bool unique = true;
        HashNode* current = hashTable[data[i].RNTI % 32];
        while (current) {
            if (current->data.RNTI == data[i].RNTI) {
                unique = false;
                break;
            }
            current = current->next;
        }
        pthread_mutex_unlock(&mutex);

        if (unique) {
            data[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
            data[i].CRC_INDICATION_REL8_TAG.CRC = validate_CRC(data[i].CRC_INDICATION_REL8_TAG);

            if (data[i].CRC) {
                count++;

                pthread_mutex_lock(&mutex);
                HashNode* node = malloc(sizeof(HashNode));
                if (!node) {
                    perror("Failed to allocate memory for hash node");
                    free(data);
                    return -1;
                }
                node->data = data[i];
                node->next = hashTable[data[i].RNTI % 32];
                hashTable[data[i].RNTI % 32] = node;
                pthread_mutex_unlock(&mutex);
            }
        }
    }

    free(data);
    return count;
}

