#include <list>
#include <mutex>
#include <memory>

class DynamicList {
private:
    std::list<std::unique_ptr<LTE_MEASUREMENT_REPORT_T>> data;
    mutable std::mutex mtx;
    int qualityThreshold;

public:
    // Constructor with initial threshold value
    DynamicList(int qualityThreshold) : qualityThreshold(qualityThreshold){}

    // Accessor for the threshold value
    int getQualityThreshold() const { return this->qualityThreshold; }

    // Function to set a new threshold value (requires locking to maintain consistency)
    void setQualityThreshold(int newThreshold) {
        std::lock_guard<std::mutex> guard(this->mtx);
        this->qualityThreshold = newThreshold;
    }

    // Function to add a measurement report to the list (requires locking to maintain consistency)
    void addReport(const LTE_MEASUREMENT_REPORT_T& report) {
        std::unique_ptr<LTE_MEASUREMENT_REPORT_T> newReport(new LTE_MEASUREMENT_REPORT_T(report));
        std::lock_guard<std::mutex> guard(this->mtx);
        this->data.push_back(std::move(newReport));
    }

    // Function to filter reports based on the quality threshold (requires locking to maintain consistency)
    void filter() {
        std::list<std::unique_ptr<LTE_MEASUREMENT_REPORT_T>> filtered;
        std::lock_guard<std::mutex> guard(this->mtx);

        for (auto& item : this->data) {
            if (item->getQualityScore() >= this->qualityThreshold) {
                filtered.push_back(std::move(item));
            }
        }

        this->data.clear();
        this->data.swap(filtered);
    }
};
