// Thread-safe cache for IP addresses with configurable TTL (Time To Live) in seconds
typedef struct _CacheEntry {
    char hostname[256];
    uint32_t ip_address;
    time_t expiration;
} CacheEntry;

typedef boost::circular_buffer<CacheEntry> CircularBuffer;
CircularBuffer g_cache;
const unsigned int MAX_CACHE_SIZE = 1024;

sem_t g_mutex;
unsigned int g_ttl = 60; // Default TTL is 60 seconds

// Logging system initialization
static log4cxx::LoggerPtr logger(log4cxx::Initializer::getInstance());

int dns_lookup(const char* hostname, u_char* ipaddr) {
    if (sem_init(&g_mutex, 0, 1) != 0) {
        fprintf(stderr, "Failed to initialize mutex\n");
        return -1;
    }

    // Concurrency control with a configurable maximum number of concurrent DNS queries
    static sem_t g_concurrency_mutex = SEM_INITIALIZER_UNLOCKED;
    int num_queries = 0;
    if (sem_wait(&g_concurrency_mutex) != 0) {
        fprintf(stderr, "Failed to acquire concurrency mutex\n");
        return -1;
    }
    num_queries++;
    if (num_queries > MAX_QUERIES) {
        sem_post(&g_concurrency_mutex);
        usleep(100000); // Back off before retrying
        return EAGAIN;
    }

    CacheEntry cache_entry = {hostname, 0, time(NULL) + g_ttl};
    if (find_cache(&g_cache, &cache_entry)) {
        memcpy(ipaddr, &cache_entry.ip_address, sizeof(u_char *));
        sem_post(&g_concurrency_mutex);
        return 0;
    }

    addrinfo hints, *result = NULL;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4 only for simplicity
    hints.ai_socktype = SOCK_STREAM;

    int errcode = getaddrinfo(hostname, NULL, &hints, &result);
    if (errcode != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(errcode));
        sem_post(&g_concurrency_mutex);
        return errcode;
    }

    u_char ipaddr4[4];
    void* addr;
    struct sockaddr_in *sockaddr_in = (struct sockaddr_in *)result->ai_addr;
    inet_pton(AF_INET, sockaddr_in->sin_addr.s_addr, ipaddr4);
    memcpy(&cache_entry.ip_address, ipaddr4, sizeof(u_char *));

    // Store the IP address in the cache
    sem_wait(&g_mutex);
    if (add_cache(&g_cache, &cache_entry)) {
        log4cxx::LoggerPtr logger = log4cxx::Logger::getLogger("dns");
        log4cxx::Level level;
        if (errcode == 0) {
            level = log4cxx:: Level::INFO;
        } else {
            level = log4cxx::Level::ERROR;
        }
        logger->log(level, "Resolved hostname '" + std::string(hostname) + "' to IP address: " + inet_ntoa(sockaddr_in->sin_addr));
        sem_post(&g_mutex);
    } else {
        sem_post(&g_concurrency_mutex);
        return ENOMEM; // Failed to add the cache entry due to memory allocation issues
    }

    freeaddrinfo(result);
    sem_post(&g_concurrency_mutex);

    return 0;
}
