    size_t num_elems;
    lte_phy_config* data;
    pthread_mutex_t mutex;
};

void lte_phy_array_init(struct lte_phy_array *array, size_t initial_capacity) {
    array->capacity = initial_capacity;
    array->num_elems = 0;
    array->data = malloc(initial_capacity * sizeof(lte_phy_config));
    if (!array->data) {
        fprintf(stderr, "Failed to allocate memory for LTE PHY array.\n");
        exit(EXIT_FAILURE);
    }
    array->mutex = PTHREAD_MUTEX_INITIALIZER;
}

void lte_phy_array_destroy(struct lte_phy_array *array) {
    free(array->data);
}

size_t lte_phy_array_add(struct lte_phy_array *array, const lte_phy_config *config) {
    if (array->num_elems >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        lte_phy_config* new_data = realloc(array->data, new_capacity * sizeof(lte_phy_config));
        if (!new_data) {
            fprintf(stderr, "Failed to resize LTE PHY array.\n");
            return 0;
        }
        array->data = new_data;
        array->capacity = new_capacity;
    }
    pthread_mutex_lock(&array->mutex);
    memcpy(&array->data[array->num_elems], config, sizeof(lte_phy_config));
    array->num_elems++;
    pthread_mutex_unlock(&array->mutex);
    return 1;
}

bool lte_phy_array_remove(struct lte_phy_array *array, size_t index) {
    if (index >= array->num_elems) {
        return false;
    }
    pthread_mutex_lock(&array->mutex);
    memmove(&array->data[index], &array->data[index + 1], (array->num_elems - index - 1) * sizeof(lte_phy_config));
    array->num_elems--;
    pthread_mutex_unlock(&array->mutex);
    return true;
}

bool lte_phy_array_update(struct lte_phy_array *array, size_t index, const lte_phy_config *new_config) {
    if (index >= array->num_elems) {
        return false;
    }
    pthread_mutex_lock(&array->mutex);
    memcpy(&array->data[index], new_config, sizeof(lte_phy_config));
    pthread_mutex_unlock(&array->mutex);
    return true;
}
```

