} Element;

#define MAX_ELEMENTS 1024
Element* list = NULL;
int num_elements = 0;
size_t elements_allocated = 0;
size_t chunk_size = MAX_ELEMENTS / 8; // Assume dynamic allocation in chunks of 8xMAX_ELEMENTS/1024

enum ErrorCodes {
    EC_SUCCESS,
    EC_NULL_NAME,
    EC_EMPTY_NAME,
    EC_INVALID_CONNECTION,
    EC_NULL_TITLE,
    EC_NULL_CALLBACK
};

int add_element(char* name, int connection_id, char* title, void(*callback)(void*), int* error) {
    if (!name || !title || !callback) {
        *error = EC_NULL_NAME + EC_NULL_TITLE + EC_NULL_CALLBACK;
        return EC_FAILURE;
    }

    if (!name[0]) {
        *error = EC_EMPTY_NAME;
        return EC_FAILURE;
    }

    for (Element* current = list; current != NULL; current = current->next) {
        if (strcmp(current->name, name) == 0) {
            *error = EC_DUPLICATE_ELEMENT;
            return EC_FAILURE;
        }
    }

    // Check connection validity...

    Element* new_element = malloc(sizeof(Element));
    if (!new_element) {
        *error = EC_MEMORY_ALLOCATION_FAIL;
        return EC_FAILURE;
    }

    new_element->name = strdup(name);
    new_element->connection_id = connection_id;
    new_element->title = strdup(title);
    new_element->callback = callback;
    new_element->next = NULL;

    if (num_elements + 1 >= elements_allocated) {
        size_t new_chunks = num_elements / chunk_size + ((num_elements % chunk_size) > 0);
        Element** new_list = realloc(list, sizeof(Element*) * (elements_allocated + chunk_size));
        if (!new_list) {
            free(new_element->name);
            free(new_element);
            *error = EC_MEMORY_ALLOCATION_FAIL;
            return EC_FAILURE;
        }
        list = new_list;
        elements_allocated += chunk_size;
    }

    list[num_elements] = new_element;
    num_elements++;

    *error = EC_SUCCESS;
    return EC_SUCCESS;
}

void clear_list(Element* current) {
    if (!current)
        return;

    free(current->name);
    free(current->title);
    free(current);

    current = current->next;
    while (current != NULL) {
        Element* temp = current;
        current = current->next;
        clear_list(temp);
    }
}

void reset_elements() {
    if (!list)
        return;

    for (Element* current = list; current != NULL; current = current->next) {
        current->name[0] = '\0';
        current->connection_id = 0;
        current->title[0] = '\0';
        current->callback = NULL;
    }
}

