int num_created = 0, failed_allocations = 0;

CRC_INDICATION_PDU* create_struct() {
    CRC_INDICATION_PDU* new_node = (CRC_INDICATION_PDU*)malloc(sizeof(CRC_INDICATION_PDU));
    if (!new_node) {
        failed_allocations++;
        return NULL;
    }
    struct timeval tv;
    gettimeofday(&tv, NULL);
    unsigned long seed = (unsigned long)(tv.tv_sec * 1000 + tv.tv_usec);
    new_node->data.CRC_INDICATION_REL8_TAG.CRCFLAG = seed % 2;
    new_node->next = NULL;
    return new_node;
}

