void HighPerformanceImageProcessingPipeline::start() {
    std::lock_guard<std::mutex> lock(mtx_);

    if (!isInitialized_) {
        throw std::runtime_error("Pipeline not initialized");
    }

    isRunning_ = true;
    // Start processing images in a separate thread
    std::thread processorThread([this]() {
        while (isRunning_) {
            std::unique_lock<std::mutex> lock(mtx_);
            cv_.wait(lock, [this]() { return !queue_.empty(); });

            auto image = std::move(queue_.front());
            queue_.pop();

            lock.unlock();
            processImage(image);
        }
    });
}

void HighPerformanceImageProcessingPipeline::stop() {
    std::lock_guard<std::mutex> lock(mtx_);

    if (!isInitialized_) {
        throw std::runtime_error("Pipeline not initialized");
    }

    isRunning_ = false;
    cv_.notify_all();
    processorThread.join();
