#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <pthread.h>
#include <stdbool.h>
#include <map>
#include <utility>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
} UE_OBJECT;

typedef struct {
    uint32_t CRCFLAG; // Adjust this range based on varying signal conditions
    uint32_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
} NFAPI_CRC_INDICATION_PDU_T;

std::map<uint32_t, UE_OBJECT> ueObjectMap; // Cache for UE_OBJECT lookup
pthread_mutex_t cacheMutex; // Mutex for safe concurrent access to the cache

NFAPI_CRC_INDICATION_PDU_T* createCRCPDUArray(const uint32_t* ueObjects, size_t numUEObjects) {
    if (numUEObjects == 0) return nullptr;

    pthread_mutex_init(&cacheMutex, NULL);

    NFAPI_CRC_INDICATION_PDU_T** pdus = (NFAPI_CRC_INDICATION_PDU_T**) calloc(numUEObjects, sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!pdus) {
        perror("Calloc failed");
        exit(1);
    }

    // Initialize cache mutex for concurrent access
    pthread_mutex_t tagMutex;
    pthread_mutex_init(&tagMutex, NULL);

    // Parallelize UE_OBJECT lookup using threads
    const uint32_t numThreads = std::max(1u, (uint32_t) std::min((numUEObjects + 15) / 16, 8));
    pthread_t* threads = (pthread_t*) malloc(numThreads * sizeof(pthread_t));

    for (size_t i = 0; i < numUEObjects; ++i) {
        pdus[i] = (NFAPI_CRC_INDICATION_PDU_T*) calloc(1, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdus[i]) {
            perror("Calloc failed");
            exit(1);
        }
    }

    // Populate the array with UE_OBJECT data
    for (size_t i = 0; i < numUEObjects; ++i) {
        pthread_create(&threads[i % numThreads], NULL, lookupAndFillPDU, (void*) &ueObjects[i]);
    }

    for (size_t i = 0; i < numThreads; ++i) {
        pthread_join(threads[i], nullptr);
    }

    free(threads);
    pthread_mutex_destroy(&cacheMutex);

    return pdus;
}

void* lookupAndFillPDU(void* index) {
    const size_t idx = *(size_t*)index;

    // Lock the cache mutex for safe concurrent access
    pthread_mutex_lock(&cacheMutex);

    auto it = ueObjectMap.find(ueObjects[idx].RX_UE_INFORMATION_TAG);
    if (it == ueObjectMap.end()) {
        // Add the UE_OBJECT to the cache if not found and unlock the mutex
        ueObjectMap.insert({ueObjects[idx].RX_UE_INFORMATION_TAG, ueObjects[idx]});
        pthread_mutex_unlock(&cacheMutex);

        // Lock the tag mutex for safe concurrent access to the current RX_UE_INFORMATION_TAG
        pthread_mutex_lock(&tagMutex);

        // Generate a random CRCFLAG within the specified range
        it = ueObjectMap.find(ueObjects[idx].RX_UE_INFORMATION_TAG);
        it->second.CRCFLAG = rand() % (MAX_CRCFLAG - MIN_CRCFLAG + 1) + MIN_CRCFLAG;

        // Unlock the tag mutex and return
        pthread_mutex_unlock(&tagMutex);
    } else {
        // Unlock the cache mutex if the UE_OBJECT is found in the cache
        pthread_mutex_unlock(&cacheMutex);
    }

    // Fill the PDU with the found UE_OBJECT data and return
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)calloc(1, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        perror("Calloc failed");
        exit(1);
    }
    pdu->RX_UE_INFORMATION_TAG = it->first;
    pdu->RNTI = it->second.RNTI;
    pdu->CRCFLAG = it->second.CRCFLAG;

    return pdu;
}
