    @SuppressWarnings("unchecked")
    public <T> T deserialize(byte[] data, Class<T> targetClass) throws IOException, ClassNotFoundException {
        try (ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(data))) {
            return (T) ois.readObject();
        } catch (ClassNotFoundException | StreamCorruptedException e) {
            throw new RuntimeException("Error during deserialization: " + e.getMessage(), e);
