    if (!file) {
        fprintf(stderr, "Error opening file: %s\n", filename);
        exit(1);
    }

    long count = 0;
    long* num_arr = NULL;
    char buffer[256];

    while (fgets(buffer, sizeof(buffer), file)) {
        if (sscanf(buffer, "%ld", num_arr + count) != 1) continue; // skip invalid lines
        count++;
    }

    rewind(file);

    num_arr = (long*)realloc(num_arr, count * sizeof(long));
    if (!num_arr) {
        fprintf(stderr, "Error reallocating memory\n");
        exit(1);
    }

    fseek(file, 0, SEEK_SET);
    size_t pos = 0;
    while (fgets(buffer, sizeof(buffer), file)) {
        if (sscanf(buffer, "%ld", num_arr + pos) != 1) continue; // skip invalid lines
        if (num_arr[pos] < INT32_MIN || num_arr[pos] > INT32_MAX) continue; // filter out overflow values
        pos++;
    }

    *nums = num_arr;
}

