    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256_Init(&sha256);
    SHA256_Update(&sha256, seed, sizeof(seed));
    SHA256_Final(hash, &sha256);

    RAND_seed(hash, sizeof(hash));
}

