container* init(int numOffsets, int numKeys, int numRecords, int minValue, int maxValue) {
    if (numOffsets <= 0 || numKeys < 0 || numKeys > numOffsets || numRecords < 0) {
        return NULL;
    }

    container *container = mmap(NULL, sizeof(container), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (container == MAP_FAILED) {
        return NULL;
    }

    container->offsets = malloc(numOffsets * sizeof(long));
    if (!container->offsets) {
        munmap(container, sizeof(container));
        return NULL;
    }

    container->keys = calloc(numKeys, sizeof(int));
    if (!container->keys) {
        free(container->offsets);
        munmap(container, sizeof(container));
        return NULL;
    }

    pthread_mutex_t keys_lock = PTHREAD_MUTEX_INITIALIZER;

    container->records = calloc(numRecords, sizeof(struct record));
    if (!container->records) {
        free(container->keys);
        free(container->offsets);
        munmap(container, sizeof(container));
        return NULL;
    }

    hash_node **hash_table = calloc(MAX_HASH_TABLE_SIZE, sizeof(hash_node*));
    if (!hash_table) {
        free(container->keys);
        free(container->offsets);
        free(container->records);
        munmap(container, sizeof(container));
        return NULL;
    }

    int *used_keys = calloc(numKeys + 1, sizeof(int));
    if (!used_keys) {
        free(hash_table);
        free(container->keys);
        free(container->offsets);
        free(container->records);
        munmap(container, sizeof(container));
        return NULL;
    }

    for (int i = 0; i < numRecords; ++i) {
        container->records[i].index = -1;
        int random_value = minValue + (rand() % (maxValue - minValue + 1));
        while (used_keys[random_value]) {
            random_value = minValue + (rand() % (maxValue - minValue + 1));
        }
        used_keys[random_value] = 1;
        container->records[i].value = random_value;
    }

    // Implement key uniqueness check and hash table here
    ...

    return container;
}
