void *connectionPool[MAX_CONNECTIONS];
pthread_mutex_t connectionMutex = PTHREAD_MUTEX_INITIALIZER;
int activeConnections = 0;

NFAPI_CRC_INDICATION_PDU_T *getConnection() {
    pthread_mutex_lock(&connectionMutex);
    if (activeConnections < MAX_CONNECTIONS) {
        // Create a new connection and return it
        NFAPI_CRC_INDICATION_PDU_T *newConnection = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        connectionPool[activeConnections++] = newConnection;
    } else {
        // Reuse an existing idle connection if available, otherwise block and wait for one to become free
        int i;
        for (i = 0; i < activeConnections; ++i) {
            if (!connectionPool[i]) {
                connectionPool[i] = getConnection();
                break;
            }
        }
    }
    pthread_mutex_unlock(&connectionMutex);

    return connectionPool[i];
}

void releaseConnection(NFAPI_CRC_INDICATION_PDU_T *connection) {
    pthread_mutex_lock(&connectionMutex);
    if (connection) {
        connection->CRCFLAG = 0;
        connectionPool[--activeConnections] = connection;
    }
    pthread_mutex_unlock(&connectionMutex);
}

void* computeMd5Hash(const char *data, size_t length) {
    unsigned char digest[MD5_DIGEST_LENGTH];
    SHA1_CTX shaContext;
    SHA1_Init(&shaContext);
    SHA1_Update(&shaContext, data, length);
    SHA1_Final(digest, &shaContext);

    return digest;
}
