C Function: dynamic_list.c (source file)

```cpp
#include "dynamic_list.h"

void dynamic_list_init(dynamic_list_t* list, size_t capacity) {
    if (!list || capacity <= 0) return;

    list->capacity = capacity > 1000 ? 1000 : capacity;
    list->length = 0;
    list->data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU) * list->capacity);
}

void dynamic_list_push(dynamic_list_t* list, const NFAPI_CRC_INDICATION_PDU* pdu) {
    if (!list || !pdu || list->length == list->capacity) return;

    list->data[list->length] = *pdu;
    list->length++;
}

NFAPI_CRC_INDICATION_PDU* dynamic_list_pop(dynamic_list_t* list) {
    if (!list || list->length <= 0) return NULL;

    size_t last_index = list->length - 1;
    NFAPI_CRC_INDICATION_PDU* pdu = &list->data[last_index];
    list->length--;
    return pdu;
}

bool dynamic_list_is_empty(const dynamic_list_t* list) {
    if (!list) return true;
    return list->length == 0;
}

void dynamic_list_destroy(dynamic_list_t* list) {
    free(list->data);
    memset(list, 0, sizeof(*list));
}
```

