function create_dynamic_list($capacity = 1000) {
    $list = new stdClass();
    $list->length = 0;
    $list->capacity = $capacity > 1000 ? 1000 : $capacity;
    $list->data = array_fill(0, $capacity, new StdClass());
    return $list;
}

function push_to_dynamic_list($list, $pdu) {
    $list->data[$list->length] = $pdu;
    $list->length++;
}

function pop_from_dynamic_list($list) {
    if ($list->length <= 0) return NULL;

    $lastIndex = $list->length - 1;
    $pdu = $list->data[$lastIndex];
    unset($list->data[$lastIndex]);
    $list->length--;
    return $pdu;
}

