Now, we implement the constructor and resize function:

```c
List* list_new(size_t initial_capacity) {
    if (initial_capacity <= 0) initial_capacity = INITIAL_LIST_SIZE;

    List* list = malloc(sizeof(List));
    if (!list) return NULL;

    list->data = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        return NULL;
    }

    list->size = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void list_resize(List* list) {
    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * GROWTH_FACTOR;
        NFAPI_CRC_INDICATION_PDU_T* new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!new_data) {
            printf("Out of memory\n");
            return;
        }

        list->data = new_data;
        list->capacity = new_capacity;
    }
}
```

