typedef struct _node {
    NFAPI_CRC_INDICATION_PDU data;
    struct _node* next;
} node;

void generateRandomCRCFLAG(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Generates a random CRCFLAG value ensuring it's not the same as the previous one.
    static uint32_t lastCRCFLAG = 0;
    do {
        pdu->crc_indication.CRCFLAG = rand();
    } while (pdu->crc_indication.CRCFLAG == lastCRCFLAG);
    lastCRCFLAG = pdu->crc_indication.CRCFLAG;
}

node* createList(int N) {
    node *head = NULL, *tail = NULL, *temp;

    for (int i = 0; i < N; ++i) {
        temp = (node*) malloc(sizeof(node));
        if (!temp) return NULL;

        generateRandomCRCFLAG(&temp->data.crc_indication);
        temp->data.tag.RX_UE_INFORMATION_TAG_value = i + 1; // replace this with actual RX_UE_INFORMATION_TAG value
        temp->data.rnti.RNTI_value = i * 2 + 3; // replace this with actual RNTI value

        if (head == NULL) {
            head = tail = temp;
        } else {
            tail->next = temp;
            tail = temp;
        }
    }

    return head;
}

void resetList(node* head) {
    node *temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}

