#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <semaphore.h>

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    bool crcflag; // ensure unique consecutive values
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRRC_INDICATION_PDU_T data;
    struct node *next;
} Node;

struct list {
    Node* head;
    Node* tail;
    unsigned int size;
    sem_t lock; // distributed lock manager
};

void init_list(struct list* list) {
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    sem_init(&list->lock, 0, 1);
}

void append_to_list(struct list* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) return; // handle memory allocation errors

    new_node->data = data;
    new_node->next = NULL;

    sem_wait(&list->lock);

    if (list->head == NULL) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }
    list->size++;

    sem_post(&list->lock);
}

void reset_list(struct list* list) {
    sem_wait(&list->lock);

    Node *current, *next;
    for (current = list->head; current != NULL; current = next) {
        next = current->next;
        free(current);
    }

    list->head = NULL;
    list->tail = NULL;
    list->size = 0;

    sem_post(&list->lock);
}

// Implement external API integration, error handling, caching, etc.
```

