struct Connection {
    int socket;
    sockaddr_in peerAddr;
    std::string state; // ESTABLISHED, CONNECTING, DISCONNECTED
};

class TCPConnectionManager {
private:
    std::list<Connection> connections;
    std::mutex connsMutex;
    std::condition_variable connsCV;
    std::atomic<int> purgeInterval; // in seconds
    std::atomic<int> maxConnections;
    std::function<sockaddr_in(const char*)> getPeerAddrFunc; // Custom function for retrieving peer IP and port
    bool useComplexDataStructure;

    void purgeInactiveConnections() {
        std::list<Connection> newConnections;
        auto it = connections.begin();
        auto end = connections.end();

        std::mutex::scoped_lock lock(connsMutex);
        for (; it != end;) {
            if (!it->socket || it->state == "DISCONNECTED") {
                it = connections.erase(it);
            } else {
                ++it;
            }
        }

        std::swap(connections, newConnections);
    }

public:
    TCPConnectionManager(int purgeInterval, int maxConnections,
                          std::function<sockaddr_in(const char*)> getPeerAddrFunc, bool useComplexDataStructure)
        : purgeInterval(purgeInterval), maxConnections(maxConnections), getPeerAddrFunc(getPeerAddrFunc),
          useComplexDataStructure(useComplexDataStructure) {}

    void addConnection(int socket, const char* host, int port) {
        Connection newConn;
        newConn.socket = socket;
        memset(&newConn.peerAddr, 0, sizeof(newConn.peerAddr));
        if (useComplexDataStructure) {
            auto peer = getPeerAddrFunc(host);
            memcpy(&newConn.peerAddr, &peer, sizeof(peer));
            newConn.peerAddr.sin_port = htons(port);
        } else {
            // Implement simple data structure here
        }
        newConn.state = "CONNECTING";

        std::unique_lock<std::mutex> lock(connsMutex);
        if (connections.size() >= maxConnections) {
            connsCV.wait(lock, [this] { return connections.size() < maxConnections; });
        }
        connections.push_back(newConn);
    }

    void removeConnection(int socket) {
        std::unique_lock<std::mutex> lock(connsMutex);
        auto it = std::find_if(connections.begin(), connections.end(), [socket](const Connection& c) { return c.socket == socket; });
        if (it != connections.end()) {
            it->state = "DISCONNECTED";
            connections.erase(it);
        }
    }

    void updateConnectionState(int socket, const std::string& newState) {
        std::unique_lock<std::mutex> lock(connsMutex);
        auto it = std::find_if(connections.begin(), connections.end(), [socket](const Connection& c) { return c.socket == socket; });
        if (it != connections.end()) {
            it->state = newState;
        }
    }

    void listActiveConnections() {
        std::unique_lock<std::mutex> lock(connsMutex);
        for (auto& c : connections) {
            if (c.state != "DISCONNECTED") {
                // Print connection details here
            }
        }
    }

    void run() {
        while (true) {
            purgeInactiveConnections();
            usleep(purgeInterval * 1000000); // Sleep for the specified purge interval in microseconds
        }
    }
};
