#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#define MAX_ELEMENTS 1024

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
    bool EXTRA_CQI_TAG;
    bool MCS_TAG;
    uint16_t crc;
} NFAPI_CRC_INDICATION_PDU_T;

void initDynamicList(NFAPI_CRC_INDICATION_PDU_T** list, size_t* numElements, size_t capacity) {
    *list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*list == NULL) {
        fprintf(stderr, "Failed to allocate memory\n");
        exit(EXIT_FAILURE);
    }
    *numElements = 0;
    *capacity = capacity > MAX_ELEMENTS ? MAX_ELEMENTS : capacity;
}

void resizeDynamicList(NFAPI_CRC_INDICATION_PDU_T** list, size_t* numElements, size_t newCapacity) {
    NFAPI_CRC_INDICATION_PDU_T* tempList = (NFAPI_CRC_INDICATION_PDU_T*)realloc(*list, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (tempList == NULL) {
        fprintf(stderr, "Failed to reallocate memory\n");
        exit(EXIT_FAILURE);
    }
    *list = tempList;
    (*capacity) = newCapacity;
}

void addElement(NFAPI_CRC_INDICATION_PDU_T** list, size_t* numElements, uint32_t RX_UE_INFORMATION_TAG, uint32_t RNTI, uint32_t CRC_INDICATION_REL8_TAG, bool EXTRA_CQI_TAG, bool MCS_TAG, uint16_t crc) {
    if (*numElements >= *capacity) {
        resizeDynamicList(list, numElements, *capacity * 2);
    }
    (*list)[*numElements].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    (*list)[*numElements].RNTI = RNTI;
    (*list)[*numElements].CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    (*list)[*numElements].EXTRA_CQI_TAG = EXTRA_CQI_TAG;
    (*list)[*numElements].MCS_TAG = MCS_TAG;
    (*list)[*numElements].crc = crc;
    (*numElements)++;
}
