    let cachedData = this.cache.get(`${model}-sentiment`);

    if (cachedData) { // Use cached data if available
      return cachedData;
    }

    const analysis = await this.nlpService.analyzeSentiment(review);

    let sentimentScore = {
      camera: analysis.cameraQualityScore,
      battery: analysis.batteryLifeScore,
      screen: analysis.screenResolutionScore
    };

    this.cache.set(`${model}-sentiment`, sentimentScore, { expires: 60 * 5 }); // Cache for 5 minutes

    return sentimentScore;
  }

