    let promise = new Promise((resolve) => {
      stream.on('data', (data) => {
        const review = JSON.parse(data);
        this.processReview(review.text, model).then((sentimentScore) => {
          review.sentimentScore = sentimentScore;
          resolve(review);
        });
      });
    });

