    let executedComponents = new Set();

    while (components.length > 0) {
      const component = components.find(c => !executedComponents.has(c.name));
      if (!component) break;

      await this.executeComponent(component);
      executedComponents.add(component.name);
    }
  }

  async executeComponent(component) {
    try {
      // load component and execute it with proper dependency resolution
      let module = await import(`./${component.name}`);
      const instance = new (module.default || component)(...this.resolveDependencies([...component.dependencies], this.components));
      await instance.execute();
    } catch (error) {
      // log error message based on deployment environment
    }
  }

  resolveDependencies(deps, componentsMap) {
    let resolvedDeps = [];

    for (const dep of deps) {
      if (!componentsMap.has(dep)) throw new Error(`Missing dependency: ${dep}`);

      const depInstance = componentsMap.get(dep);
      resolvedDeps.push(depInstance);
    }

    return resolvedDeps;
  }
}
