        pthread_mutex_lock(&batch_mutex);

        // Find the next chunk of elements to process
        if (!max_index) {
            pthread_mutex_unlock(&batch_mutex);
            continue;
        }

        start = current_index;
        end = (current_index + BATCH_SIZE > max_index) ? max_index : current_index + BATCH_SIZE;
        current_index = end;
