    return MAX_INTERFERENCE - distance + tx_power;
}

int processNetworkData(Device** devices, size_t num_devices, DataPair** offset_keys, size_t* offset_keys_len, Record** records, size_t* records_len, Frame** frames, size_t* frames_len) {
