    for (size_t i = 0; i < *frames_len; ++i) {
        Frame* frame = &((*frames)[i]);
        int signal_strength = get_signal_strength(frame->phy_frame_info.tx_power, frame->cell_id);
        // Handle discrepancies between expected and actual signal strengths
        // due to hardware and software variations across different network devices
        if (signal_strength < 0) continue;

        processed_frames++;
    }

    for (size_t i = 0, j = 0; i < *records_len && j < processed_frames; ++i, ++j) {
        Record* record = &((*records)[i]);
        Frame* frame = &((*frames)[j]);

        record->value = rand() % 100 + 1; // Initialize with random integer value within a specified range
    }

    size_t processed_records = i < *records_len ? i : processed_frames;

    free(temp_frames);

    return processed_records > 0 && processed_frames > 0 ? 1 : 0;
}
