        if ((i > 0) && (currentRnti == (*((*data) + i - 1)).rnti)) {
            do {
                currentRnti++;
            } while ((currentRnti <= *len) && ((i - 1) % (currentRnti - 1) != 0));
        }

        (*((*data) + i)).rxi = i;
        (*((*data) + i)).rnti = currentRnti++;
