void report_metrics() {
    // Implement real-time memory usage and performance metrics reporting here.
}

bool create_crc_indication_pdu(size_t N, bool* error) {
    if (N <= 0 || N > MAX_ELEMENTS) {
        *error = true;
        return false;
    }

    node** current = head;
    pthread_mutex_lock(&mutex);

    for (size_t i = *head == NULL ? 0 : (*head - head)[0].next->N; i < N; ++i) {
        node* new_node = (node*) malloc(sizeof(node));
        if (!new_node) {
