        log_pdu_creation(*error, N, (*head)[0].data.rnti, (*head)[0].data.crc_indication.crcflag); // Define log_pdu_creation function here
    }

    return true;
}

void free_memory() {
    pthread_mutex_lock(&mutex);
    node* current = *head;
    node* next_node;

    while (current != NULL) {
        next_node = current->next;
        free(current);
        current = next_node;
    }

    *head = NULL;
    pthread_mutex_unlock(&mutex);
}
