// Global variables for data and synchronization
DataPacket* packets = NULL;
size_t capacity = 0;
size_t num_packets = 0;
const size_t buffer_limit = 1000000; // Set your desired buffer limit here
pthread_mutex_t lock;

// Function to initialize DataPacket array with the specified initial size
void initDataPackets(size_t initial_size) {
    if (initial_size > buffer_limit) {
        fprintf(stderr, "Initial allocation size exceeds buffer limit\n");
        return;
    }

    packets = malloc(initial_size * sizeof(DataPacket));
    capacity = initial_size;
    num_packets = 0;
    pthread_mutex_init(&lock, NULL);
}

// Function to add a DataPacket to the array, handling potential overflows gracefully
void addPacket(DataPacket packet) {
    if (num_packets + 1 > capacity) {
        // Reallocate memory and increase capacity by a factor of 2
        size_t new_capacity = capacity * 2;
        DataPacket* temp_packets = realloc(packets, new_capacity * sizeof(DataPacket));

        if (!temp_packets) {
            fprintf(stderr, "Memory allocation failed\n");
            return;
        }

        packets = temp_packets;
        capacity = new_capacity;
    }

    pthread_mutex_lock(&lock);
    packets[num_packets] = packet;
    num_packets++;
    pthread_mutex_unlock(&lock);
}

// Function to clean up allocated memory and resources
void cleanup() {
    free(packets);
    capacity = 0;
    num_packets = 0;
    pthread_mutex_destroy(&lock);
}
