// Custom allocator using a memory pool
typedef struct MemBlock {
    void* ptr;
    size_t size;
    struct MemBlock* next;
} MemBlock;

MemBlock* mempool = NULL;
size_t num_allocated = 0;
size_t num_free = 0;
static pthread_mutex_t mempool_lock = PTHREAD_MUTEX_INITIALIZER;

void* pool_malloc(size_t size) {
    if (num_free == 0) {
        void* new_mem = malloc(size);
        if (!new_mem) {
            return NULL;
        }
        mempool = (MemBlock*)realloc(mempool, sizeof(MemBlock) * (num_allocated + 1));
        memset(&mempool[num_allocated], 0, sizeof(MemBlock));
        mempool[num_allocated].ptr = new_mem;
        mempool[num_allocated].size = size;
        num_allocated++;
    }
    MemBlock* block = &mempool[--num_free];
    void* result = block->ptr;
    block->next = mempool;
    mempool = block;
    return result;
}

void pool_free(void* ptr) {
    pthread_mutex_lock(&mempool_lock);
    MemBlock* current = mempool, *prev = NULL;
    while (current != NULL) {
        if (current->ptr == ptr) {
            if (prev == NULL) {
                mempool = current->next;
            } else {
                prev->next = current->next;
            }
            num_free++;
            break;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&mempool_lock);
}

NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu_list(size_t n) {
    if (n > 1000) {
        return NULL;
    }
    NFAPI_CRC_INDICATION_PDU_T* list = pool_malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * n);
    if (!list) {
        return NULL;
    }
    for (size_t i = 0; i < n; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = list + i;
        // Initialize RX_UE_INFORMATION_TAG, RNTI and CRC_INDICATION_REL8_TAG with suitable values
        pthread_mutex_lock(&pdu->crcflag); // Lock the flag to prevent modification after initialization
        pdu->crcflag = 0xFFFF; // Initialize flag as invalid
        pthread_mutex_unlock(&pdu->crcflag);
    }
    return list;
}
