// Custom allocator using memory pool
typedef struct MemoryBlock {
    void *data;
    size_t size;
    struct MemoryBlock *next;
} MemoryBlock;

MemoryPool* create_memory_pool(size_t chunk_size, size_t num_chunks) {
    MemoryPool *pool = (MemoryPool *) malloc(sizeof(MemoryPool));
    pool->chunk_size = chunk_size;
    pool->num_chunks = num_chunks;
    pool->free_list = NULL;
    pool->used_list = NULL;

    for (size_t i = 0; i < num_chunks; ++i) {
        MemoryBlock *new_block = (MemoryBlock *) malloc(sizeof(MemoryBlock));
        new_block->data = calloc(chunk_size, 1);
        new_block->size = chunk_size;
        new_block->next = NULL;

        if (i < num_chunks - 1) {
            pool->free_list = new_block;
        } else {
            pool->used_list = new_block;
        }
    }

    return pool;
}

void *mempool_malloc(MemoryPool *pool, size_t size) {
    if (size <= 0 || !pool) {
        return NULL;
    }

    MemoryBlock **list = (size < pool->chunk_size) ? &pool->free_list : &pool->used_list;
    MemoryBlock *current = *list;

    while (current != NULL) {
        if ((current->size >= size) && (current->next == NULL)) {
            void *data = current->data;
            *list = current->next;
            current->data = NULL;
            current->size = size;
            current->next = pool->free_list;
            pool->free_list = current;
            return data;
        }
        current = current->next;
    }

    void *new_mem = malloc(size);
    if (new_mem) {
        MemoryBlock *new_block = (MemoryBlock *) malloc(sizeof(MemoryBlock));
        new_block->data = new_mem;
        new_block->size = size;
        new_block->next = pool->free_list;
