#include <pthread.h>
#include <semaphore.h>

typedef struct NetworkEvent {
    int ue_id;
    time_t timestamp;
    double uplink_traffic;
    double downlink_traffic;
    sem_t lock;
} NetworkEvent;

sem_t events_mutex;
pthread_mutex_t heap_mutex = PTHREAD_MUTEX_INITIALIZER;
size_t event_count = 0;
NetworkEvent* events = NULL;

void init_heap(size_t capacity) {
    events = malloc(capacity * sizeof(NetworkEvent));
    if (!events) {
        perror("Failed to allocate heap memory");
        exit(EXIT_FAILURE);
    }
    event_count = 0;
}

void destroy_heap() {
    free(events);
    events = NULL;
    event_count = 0;
}

NetworkEvent* get_event() {
    pthread_mutex_lock(&heap_mutex);
    if (event_count < event_count) {
        NetworkEvent* current = &events[event_count - 1];
        sem_init(&current->lock, 0, 1);
        event_count++;
        pthread_mutex_unlock(&heap_mutex);
        return current;
    }
    pthread_mutex_unlock(&heap_mutex);

    NetworkEvent* new_event = realloc(events, ((event_count * 2) + 1) * sizeof(NetworkEvent));
    if (!new_event) {
        perror("Failed to expand heap memory");
        exit(EXIT_FAILURE);
    }
    events = new_event;

    NetworkEvent* current = &events[event_count - 1];
    sem_init(&current->lock, 0, 1);
    event_count++;
    return current;
}

void put_event(NetworkEvent* event) {
    pthread_mutex_lock(&heap_mutex);
    event_count--;
    events[event_count] = *event;
    sem_destroy(&event->lock);
    pthread_mutex_unlock(&heap_mutex);
}

void lock_events() {
    sem_wait(&events_mutex);
}

void unlock_events() {
    sem_post(&events_mutex);
}
```

This code provides a basic implementation of a dynamic collection of network event structures, supporting memory allocation and deallocation. The function `init_heap()` initializes the dynamic array for storing events, while `destroy_heap()` frees the allocated memory. The function `get_event()` allocates a new event structure and returns a pointer to it, dynamically expanding the heap if necessary. The function `put_event(NetworkEvent* event)` deallocates an event structure and frees its memory.

The code also includes mechanisms for synchronization using semaphores and mutexes, ensuring thread safety when accessing shared resources. The global variable `events_mutex` is used to lock the entire collection of events during modification, while `sem_t lock` is attached to each individual event structure for finer-grained synchronization during read/write operations.

Lastly, the code handles memory expansion by doubling the capacity of the heap when it becomes full, optimizing for space complexity. The time complexity of accessing events is O(1), as lookups are constant time operations. However, this implementation may not be suitable for very high loads due to potential delays in acquiring and releasing locks, which can impact system performance. To address this, consider using a concurrent data structure such as a Concurrent Skip List or Concurrent Queue. These structures provide better performance under high contention scenarios by allowing multiple threads to access the shared resource concurrently without lock contention.']

