using Microsoft.Maui.Graphics;

namespace MyMobileApp.Services
{
    public class ThemeCacheManager
    {
        private readonly string _cacheRootDirectory;
        private readonly float _minThemeValue;
        private readonly float _maxThemeValue;
        private readonly Random _random;
        private readonly Dictionary<string, Bitmap> _themeCache = new Dictionary<string, Bitmap>();

        public ThemeCacheManager()
        {
            _cacheRootDirectory = GetCacheRootDirectory();
            _minThemeValue = 0.1f;
            _maxThemeValue = 0.9f;
            _random = new Random();
        }

        private string GetCacheRootDirectory()
        {
            var directory = System.Environment.GetFolderPath(System.Environment.SpecialFolder.ApplicationData);
            if (!Directory.Exists($"{directory}/Themes")) Directory.CreateDirectory($"{directory}/Themes");
            return $"{directory}/Themes";
        }

        public float GetRandomFloat() => _random.NextSingle(_minThemeValue, _maxThemeValue);

        public int GetRandomInt() => (int)_random.Next((int)Math.Ceiling(_minThemeValue), (int)Math.Ceiling(_maxThemeValue + 1));

        public Bitmap GetThemeBitmap(string fileName)
        {
            if (_themeCache.TryGetValue(fileName, out var bitmap)) return bitmap;

            string filePath = $"{_cacheRootDirectory}/{fileName}.png";

            try
            {
                using (var stream = new FileStream(filePath, FileMode.Open))
                {
                    var decoder = BitmapFactory.DecodeStream(stream);
                    _themeCache[fileName] = decoder;
                    return decoder;
                }
            }
            catch (Exception ex)
            {
                // Handle potential external data source failures
                Console.WriteLine($"Error loading theme bitmap: {ex}");
                return null;
            }
        }

        public override string ToString() => $"[ThemeCacheManager, MinValue={_minThemeValue}, MaxValue={_maxThemeValue}]";
    }
}
