#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

typedef struct {
    int rnti; // UE ID
    NFAPI_CRC_INDICATION_PDU_T *crc_indication;
} RRC_MSG_DATA;

typedef struct list_node {
    RRC_MSG_DATA data;
    struct list_node *next;
} LIST_NODE;

struct dynamic_list {
    LIST_NODE **nodes; // Array of pointers to node structures
    size_t capacity;   // Maximum number of elements in the array
    size_t count;      // Current number of allocated elements
    semaphore_t mem_sem;  // Semaphore for memory access control
    pthread_mutex_t log_mtx; // Mutex for logging resource usage
};

// Function to initialize the dynamic list with the given capacity
void init_dynamic_list(struct dynamic_list *list, size_t capacity) {
    list->capacity = capacity;
    list->count = 0;
    list->nodes = malloc(capacity * sizeof(LIST_NODE*));
    for (size_t i = 0; i < capacity; ++i) {
        list->nodes[i] = NULL;
    }
    semaphore_init(&list->mem_sem, capacity);
    pthread_mutex_init(&list->log_mtx, NULL);
}

// Function to add an RRC message data to the dynamic list
void add_to_dynamic_list(struct dynamic_list *list, RRC_MSG_DATA data) {
    // Acquire memory semaphore
    semaphore_wait(&list->mem_sem);

    size_t index = list->count % list->capacity;
    while (list->nodes[index] != NULL) {
        ++index;
        if (index == list->capacity) index = 0;
    }

    LIST_NODE *new_node = malloc(sizeof(LIST_NODE));
    new_node->data = data;
    new_node->next = list->nodes[index];
    list->nodes[index] = new_node;
    ++list->count;

    // Release memory semaphore
    semaphore_post(&list->mem_sem);
}

// Other functions for handling RRC messages, error checking, resource monitoring, etc.
```

