static inline bool is_sync(LTE_DL_FRAMEINFO* current, LTE_DL_FRAMEINFO* next) {
    return (current->frameNumber == next->frameNumber &&
            (current->subframeNumber + 1) % 8 == next->subframeNumber);
}

static void log_operation(const char *operation, const LTE_DL_FRAMEINFO *frame) {
    // Integration with existing logging framework goes here
}

void resize_array(LTE_DL_FRAMEINFO** array, size_t* capacity, size_t* size) {
    *capacity *= 2;
    LTE_DL_FRAMEINFO* new_array = realloc(*array, sizeof(LTE_DL_FRAMEINFO)*(*capacity));
    if (!new_array) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }
    *array = new_array;
    *size = *capacity;
}

void initialize_frame_buffer(LTE_DL_FRAMEINFO** buffer, size_t* capacity, size_t* size) {
    *buffer = malloc(sizeof(LTE_DL_FRAMEINFO)*(*capacity));
    if (!*buffer) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }
    memset(*buffer, 0, sizeof(LTE_DL_FRAMEINFO)*(*capacity));
    *size = *capacity;
}

void add_frame(LTE_DL_FRAMEINFO** buffer, size_t* size, const LTE_DL_FRAMEINFO* frame) {
    if (*size == *size) {
        resize_array(buffer, capacity, size);
    }
    pthread_mutex_init(&((*buffer)[*size]).mutex, NULL);
    memcpy(&(*buffer)[*size], frame, sizeof(LTE_DL_FRAMEINFO));
    (*size)++;
}

void remove_frame(LTE_DL_FRAMEINFO** buffer, size_t* size, uint32_t frameNumber) {
    for (size_t i = 0; i < *size; ++i) {
        if ((*buffer)[i].frameNumber == frameNumber) {
            memmove(&(*buffer)[i], &((*buffer)[i+1]), (*size - (i + 1)) * sizeof(LTE_DL_FRAMEINFO));
            pthread_mutex_destroy(&((*buffer)[*size-1]).mutex);
            (*size)--;
            break;
        }
    }
}

void get_frame(const LTE_DL_FRAMEINFO** buffer, size_t size, uint32_t frameNumber, const LTE_DL_FRAMEINFO** result) {
    for (size_t i = 0; i < size; ++i) {
        if ((*buffer)[i].frameNumber == frameNumber) {
            *result = &((*buffer)[i]);
            pthread_mutex_lock(&((*result)->mutex));
            return;
        }
    }
    *result = NULL;
}

void thread_safe_access(const LTE_DL_FRAMEINFO** buffer, size_t size, uint32_t frameNumber, const LTE_DL_FRAMEINFO** result) {
    pthread_mutex_lock(&((*buffer)->mutex));
    get_frame(buffer, size, frameNumber, result);
    pthread_mutex_unlock(&((*result)->mutex));
}
