            free(list->nodes[i]);
            list->nodes[i] = NULL;
        }
    }
    free(list->nodes);
    pthread_mutex_destroy(&list->lock);
}

void list_insert(list_t *list, const NFAPI_CRC_INDICATION_PDU_T *data) {
    size_t index = data->RNTI % LIST_MAX_SIZE;
    pthread_mutex_lock(&list->lock);
    if (list->nodes[index]) { // If the list node at this index is already allocated
        list_node_t *new_node = malloc(sizeof(list_node_t));
        if (!new_node) {
            perror("malloc");
            pthread_mutex_unlock(&list->lock);
            exit(EXIT_FAILURE);
        }
        new_node->data = *data;
        new_node->next = list->nodes[index];
        list->nodes[index] = new_node;
    } else {
        list->nodes[index] = malloc(sizeof(list_node_t));
        if (!list->nodes[index]) {
            perror("malloc");
            pthread_mutex_unlock(&list->lock);
            exit(EXIT_FAILURE);
        }
        list->nodes[index]->data = *data;
    }
    ++list->size;
    pthread_mutex_unlock(&list->lock);
}

NFAPI_CRC_INDICATION_PDU_T* list_find(const list_t *list, uint32_t RNTI) {
    size_t index = RNTI % LIST_MAX_SIZE;
    pthread_mutex_lock(&list->lock);
    list_node_t *current = list->nodes[index];
    while (current) {
        if (current->data.RNTI == RNTI) {
            NFAPI_CRC_INDICATION_PDU_T *result = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            memcpy(result, &current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            pthread_mutex_unlock(&list->lock);
            return result;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return NULL;
}
