using ip::tcp = boost::asio::ip::tcp;

struct ConnectionMetadata {
    int sock;
    string peer_addr;
    uint16_t port;
    time_t last_healthy_check;
};

class TCPConnectionManager {
private:
    mutex connections_mutex;
    vector<ConnectionMetadata> connections;
    unordered_map<int, ConnectionMetadata*> connection_map;
    unsigned int max_connections;
    std::chrono::system_clock::time_point history_cutoff;

public:
    TCPConnectionManager(unsigned int max_connections) : max_connections(max_connections),
                                                        history_cutoff(std::chrono::system_clock::now() - 24h) {}

    void addConnection(int sock, const string& peer_addr, uint16_t port) {
        lock_guard<mutex> guard(connections_mutex);
        ConnectionMetadata newConn = {sock, peer_addr, port, std::time(nullptr)};
        connections.push_back(newConn);
        connection_map[sock] = &connections.back();
    }

    void removeConnection(int sock) {
        lock_guard<mutex> guard(connections_mutex);
        if (connection_map.find(sock) == connection_map.end()) return;
        auto it = connection_map.find(sock);
        connections.erase(it->second - &connections[0]); // Adjust the pointer to be relative to the first element of vector
        connection_map.erase(it);
    }

    void listConnections() {
        lock_guard<mutex> guard(connections_mutex);
        for (const auto& conn : connections) {
            cout << "Socket: " << conn.sock << ", Peer IP: " << conn.peer_addr << ", Port: " << conn.port << "\n";
        }
    }

    void probeConnection(int sock) {
        lock_guard<mutex> guard(connections_mutex);
        auto it = connection_map.find(sock);
        if (it == connection_map.end()) return;
        it->second->last_healthy_check = std::time(nullptr); // Update the timestamp upon success of probe
    }

    void checkAndProbeConnections() {
        lock_guard<mutex> guard(connections_mutex);
        for (auto& conn : connections) {
            auto now = std::time(nullptr);
            if (now - conn.last_healthy_check > 5m) { // Adjust timeout to suit your needs
                probeConnection(conn.sock);
            }
        }
    }

    void checkAndRemoveFaultyConnections() {
        lock_guard<mutex> guard(connections_mutex);
        auto it = connections.begin();
        while (it != connections.end()) {
            if (it->last_healthy_check < history_cutoff.time_since_epoch().count()) {
                connection_map.erase(it - connections.begin()); // Adjust the pointer to be relative to the first element of map
                it = connections.erase(it);
            } else {
                ++it;
            }
        }
    }

    const unordered_map<int, ConnectionMetadata*>& getConnectionHistory() {
        return connection_map;
    }
};
```

