import java.nio.channels.*;
import java.net.InetSocketAddress;
import java.util.concurrent.*;
import com.typesafe.config.*;
import org.slf4j.*;

public class ApiConnector {
    private static final Logger LOGGER = LogManager.getLogger(ApiConnector.class);
    private static final Config CONFIG = ConfigFactory.load();
    private static final ExecutorService EXECUTOR = Executors.newCachedThreadPool();
    private static final ScheduledExecutorService TIMEOUT_EXECUTOR = Executors.newScheduledThreadPool(1);
    private static final Duration CONNECTION_TIMEOUT = Duration.parse(CONFIG.getString("connection-timeout"));
    private final SelectorGroup group;
    private final SocketChannel socketChannel;

    public ApiConnector() throws IOException {
        ServerSocketChannel serverSocket = ServerSocketChannel.open();
        serverSocket.socket().setReuseAddress(true);
        serverSocket.bind(new InetSocketAddress(CONFIG.getInt("server-port")));
        group = SelectorGroup.open();
        serverSocket.configureBlocking(false);
        socketChannel = serverSocket.accept();
    }

    public void transferData(ByteBuffer buffer) throws IOException, TimeoutException {
        if (!socketChannel.isOpen()) throw new IOException("Socket is closed");
        socketChannel.write(buffer);
        buffer.clear();
        socketChannel.read(buffer);
    }

    public void handleConnection() {
        ScheduledFuture<?> timeoutHandler = TIMEOUT_EXECUTOR.schedule(() -> closeConnection(), CONNECTION_TIMEOUT.toMillis(), TimeUnit.MILLISECONDS);
        while (!socketChannel.isConnected()) {
            group.selectNow();
            SelectionKey key = socketChannel.keyFor();
            if (key == null || !key.isValid() || key.isReadable() || key.isWritable()) break;
        }
        timeoutHandler.cancel(false);
        // Handle authenticated API requests and configure transfer strategies here
    }

    private void closeConnection() {
        try {
            socketChannel.close();
        } catch (IOException e) {
            LOGGER.warn("Error while closing connection: {}", e.getMessage());
        }
    }
}
```

