    *array = calloc(num_pdus, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*array == NULL) {
        log_error("Failed to allocate memory for PDUs");
        return NULL;
    }

    pthread_attr_t attr[NUM_THREADS];
    for (size_t i = 0; i < NUM_THREADS; ++i) {
        pthread_attr_init(&attr[i]);
        pthread_attr_setdetachstate(&attr[i], PTHREAD_CREATE_JOINABLE);
    }

    for (size_t i = 0; i < num_pdus; ++i) {
        pthread_create(&threads[i % NUM_THREADS], &attr[i], randomize, NULL);
    }

    int retries = 0;
    while (retries < MAX_RETRIES && num_pdus > 0) {
        for (size_t i = 0; i < NUM_THREADS; ++i) {
            pthread_join(threads[i], NULL);
        }

        for (size_t i = 0; i < num_pdus; ++i) {
            NFAPI_CRC_INDICATION_PDU_T* pdu = &((*array)[i]);
            pdu->rx_ue.tag = (RX_UE_INFORMATION_TAG) rand(); // Replace with actual RX_UE_INFORMATION_TAG initialization
            pdu->rnti = (RNTI) rand(); // Replace with actual RNTI initialization
            pdu->crc_ind.crcflag = rand() % 256; // Replace with actual CRC_INDICATION_REL8_TAG initialization
        }

        for (size_t i = 0; i < num_pdus; ++i) {
            int calculated_crc = recalc_crc(&((*array)[i]));
            if (!compare_crc(&((*array)[i]), calculated_crc)) {
                log_error("Invalid CRC calculation");
                retries++;
                break;
            }
        }
    }

    for (size_t i = 0; i < NUM_THREADS; ++i) {
        pthread_attr_destroy(&attr[i]);
    }

    if (retries == MAX_RETRIES) {
        free(*array);
        *array = NULL;
    }

    return *array;
}
