import requests
import json
from datetime import timedelta
from functools import wraps
import redis

# Define API keys as environment variables or configuration files
API_KEYS = {"api1": "key1", "api2": "key2"}
API_URLS = {"api1": "https://api.provider1.com/data", "api2": "https://api.provider2.com/data"}
REDIS_CACHE = redis.Redis(host="localhost", port=6379, db=0)

def rate_limiter(max_calls=5):
    calls = REDIS_CACHE.incr("api_call_{}".format(func.__name__))
    if calls > max_calls:
        return REDIS_CACHE.expireat("api_call_{}".format(func.__name__), timedelta(minutes=1))

def api_authenticate(key):
    headers = {"Authorization": "Token {}".format(key)}
    return headers

def handle_error(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        try:
            return func(*args, **kwargs)
        except Exception as e:
            print("Error occurred: {}".format(e))
            REDIS_CACHE.setex("api_error", 600, json.dumps({"timestamp": datetime.now(), "error": str(e)}))
    return wrapper

def get_weather_data(api):
    headers = api_authenticate(API_KEYS[api])
    url = API_URLS[api]
    response = requests.get(url, headers=headers)
    if response.status_code == 200:
        return response.json()
    else:
        REDIS_CACHE.setex("api_error", 600, json.dumps({"timestamp": datetime.now(), "error": response.text}))
        get_weather_data(next(api for api in API_KEYS if api != api))

@cache.cached(REDIS_CACHE, timeout=60)
def get_latest_weather_data():
    for api in API_KEYS:
        data = get_weather_data(api)
        if data:
            return data
    raise Exception("All APIs unavailable")

if __name__ == "__main__":
    latest_data = get_latest_weather_data()
    print(latest_data)
```

