#define MAX_LIST_SIZE 1000

int create_list(FILE *outFile, size_t *numElements) {
    time_t now = time(NULL);
    unsigned long seed = (unsigned long)now;
    srand(seed);

    NFAPI_CRC_INDICATION_PDU_T *head = NULL, *tail = NULL;
    size_t i, capacity = 1;

    for (i = 0; i < MAX_LIST_SIZE; ++i) {
        if (!(head = realloc(head, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (capacity + 1)))) {
            perror("Memory allocation failure");
            return -1;
        }

        head[i].tag.value = rand() % 256; // Ensure the tag is within the acceptable range
        if (head[i].tag.value == 0) continue; // Ignore zero tags

        head[i].rnti.value = rand() % 65536; // Ensure the RNTI is within the acceptable range
        if (head[i].rnti.value < 1 || head[i].rnti.value > 0xffff) continue;

        head[i].crcflag.value = rand() % 2; // Set a random CRC flag value

        if (!tail) {
            tail = &head[i];
            continue;
        }

        tail->next = &head[i];
        tail = &head[i];
        ++capacity;
    }

    *numElements = i;

    if (outFile) {
        for (size_t j = 0; j < i; ++j) {
            fwrite(&head[j], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, outFile);
        }
    }

    return 0;
}
