["```cpp
#include <memory>
#include <vector>
#include <cassert>
#include <iostream>
#include <cmath>

struct OctreeNode {
    std::vector<std::unique_ptr<OctreeNode>> children; // 8 children for an octree
    double position[3]; // Coordinates of this node's center
    std::vector<double> data; // Holds the data for this node and its descendants

    OctreeNode(const double pos[], int depth) : position(pos), depth(depth) {}

    int depth;
};

class Octree {
public:
    using NodePtr = std::unique_ptr<OctreeNode>;

    Octree(double featureSize, int leafNodes, int maxDepth)
        : m_featureSize(featureSize), m_leafNodesPerLevel(leafNodes), m_maxDepth(maxDepth) {}

    void insert(const double pos[], const std::vector<double>& data) {
        NodePtr node = findNode(pos, 0);
        if (!node->data.empty()) return; // Lazy initialization

        if (node->depth == m_maxDepth) return; // Max depth reached, do not insert

        node->data = data; // Insert the data
        populateChildren(node, pos); // Initialize children nodes
    }

    std::vector<double> query(const double pos[], double tolerance) const {
        auto node = findNode(pos, 0);
        if (node == m_root.get()) return node->data; // Exact match found

        std::vector<double> result;
        for (const auto& child : node->children) {
            if (child && checkDistance(child->position, pos, tolerance)) {
                result.insert(result.end(), child->data.cbegin(), child->data.cend());
            }
        }
        return result;
    }

    void traverseInOrder(NodePtr node, std::function<void(const double pos[], const std::vector<double>& data)> callback) const {
        if (!node) return;
        for (const auto& child : node->children) traverseInOrder(child, callback);
        callback(node->position, node->data);
    }

private:
    NodePtr findNode(const double pos[], int depth) const {
        if (!m_root) return nullptr;
        auto current = m_root;
        while (current && depth < current->depth + 1) {
            int index = getIndexFromCoordinates(current->position, pos);
            current = current->children[index];
        }
        return current;
    }

    void populateChildren(NodePtr node, const double pos[]) {
        if (node->depth == m_maxDepth) return;

        for (int i = 0; i < 8; ++i) {
            double newPos[3];
            splitCoordinate(pos, newPos, i);
            node->children.emplace_back(std::make_unique<OctreeNode>(newPos, node->depth + 1));
        }
    }

    bool checkDistance(const OctreeNode* node, const double pos[], double tolerance) const {
        for (size_t i = 0; i < node->data.size(); ++i) {
            if (std::abs(node->data[i] - pos[i]) > tolerance) return false;
        }
        return true;
    }

    int getIndexFromCoordinates(const double parentPos[], const double coord[]) const {
        int index = 0;
        for (size_t i = 0; i < 3; ++i) {
            if (parentPos[i] <= coord[i]) index |= 1 << i;
        }
        return index;
    }

    void splitCoordinate(const double parentPos[], double dest[], int index) const {
        for (size_t i = 0; i < 3; ++i) {
            if (index & (1 << i)) dest[i] = parentPos[i] + m_featureSize / 2.0;
            else dest[i] = parentPos[i] - m_featureSize / 2.0;
        }
    }

    double m_featureSize;
    int m_leafNodesPerLevel;
    int m_maxDepth;
    std::unique_ptr<OctreeNode> m_root; // Root of the octree
};
```

This C++ code provides a basic implementation of an octree data structure that supports dynamic memory allocation and efficient data retrieval for large-scale spatial datasets. The Octree class has methods for inserting, querying, and traversing the tree. It utilizes lazy initialization and considers performance under varying load conditions by only allocating nodes when data is inserted.

The octree can handle large datasets efficiently without exceeding memory limits, while also accounting for potential integration issues with other components of a larger application. The solution makes trade-offs between memory usage, traversal speed, and data insertion latency based on the expected dataset characteristics and application requirements. It is designed to be scalable to accommodate future growth in data volume and complexity."]

