using System;
using System.Collections.Concurrent;
using System.Linq;
using System.Threading;
using UnityEngine;

public class DynamicRangeGenerator
{
    private float _minValue;
    private float _maxValue;
    private bool _isInclusive;
    private int _randomSeed;
    private ConcurrentDictionary<long, int> _statistics = new ConcurrentDictionary<long, int>();

    public event Action OnRangeAdjustment;

    public DynamicRangeGenerator(float minValue, float maxValue, bool isInclusive, int randomSeed)
    {
        SetRange(minValue, maxValue, isInclusive, randomSeed);
    }

    public void SetRange(float minValue, float maxValue, bool isInclusive, int randomSeed)
    {
        if (maxValue < minValue)
            throw new ArgumentOutOfRangeException(nameof(maxValue), "Max value must be greater than or equal to the minimum value.");

        _minValue = minValue;
        _maxValue = maxValue;
        _isInclusive = isInclusive;
        _randomSeed = randomSeed;
    }

    public float GenerateFloat()
    {
        var range = (_maxValue - _minValue) / 2f + _minValue;
        Interlocked.Increment(ref _statistics[Interlocked.Read(ref _randomSeed)]);
        return UnityEngine.Random.Range(_minValue, _maxValue, _isInclusive) * (1 / range);
    }

    public int GenerateInteger()
    {
        var range = (_int)Mathf.CeilToZero(_maxValue - _minValue + 1);
        Interlocked.Increment(ref _statistics[Interlocked.Read(ref _randomSeed)]);
        return UnityEngine.Random.Range((int)_minValue, (int)_maxValue + 1, _isInclusive).RoundToInt();
    }

    public void ResetStatistics()
    {
        _statistics.Clear();
    }

    public void DisplayStats()
    {
        Console.WriteLine("Float Statistics:");
        foreach (var stat in _statistics)
            Console.WriteLine($"Float Value: {stat.Key}, Frequency: {stat.Value}");

        Console.WriteLine("Integer Statistics:");
        foreach (var stat in _statistics)
            Console.WriteLine($"Integer Value: {stat.Key}, Frequency: {stat.Value}");
    }

    // External data source integration
    private float _externalAdjustmentFactor;
    public void SetExternalAdjustmentFactor(float factor)
    {
        lock (_statistics)
        {
            _externalAdjustmentFactor = factor;
            OnRangeAdjustment?.Invoke();
        }
    }

    public void AdjustRangeWithData()
    {
        if (_externalAdjustmentFactor != 0)
        {
            var adjustableRange = _maxValue - _minValue;
            var newMinValue = _minValue * (1 - _externalAdjustmentFactor);
            var newMaxValue = _maxValue * (1 + _externalAdjustmentFactor);

            if (newMaxValue < newMinValue)
                throw new InvalidOperationException("The external adjustment factor is too large for the current range.");

            SetRange(newMinValue, newMaxValue, _isInclusive, _randomSeed);
        }
    }
}
```

This `DynamicRangeGenerator` class provides methods to generate random floats and integers within a configurable dynamic range, with support for inclusive or exclusive boundaries. The class utilizes concurrent data structures to handle multiple threads, using `UnityEngine.Random.Range` while considering its multi-threaded environment implications. It also includes error handling for invalid range settings, statistics on generated values, an event for notifying about range adjustments, and a method to interact with external data sources for range adjustments. The integration with the external data source minimizes performance overhead and ensures data consistency. Additionally, there is a method to display current range and generation statistics in a user-friendly format.']

