    {
        var clampedMin = Mathf.Clamp(minValue, 0f, maxValue);
        var clampedMax = Mathf.Clamp(maxValue, clampedMin, float.MaxValue);
        return (clampedMax - clampedMin) * UnityEngine.Random.value + clampedMin;
    }

