using System;
using System.Collections.Generic;
using System.Linq;
using System.Reflection;
using System.Runtime.Serialization;
using System.Threading;

[DataContract]
public class RandomValueGenerator
{
    private readonly Random _random = new Random();
    private readonly Dictionary<Type, Func<Random>> _valueGenerators;
    private readonly HashSet<ulong> _cache;
    private readonly int _cacheSize;
    private bool _isLoggingEnabled;
    private TimeSpan _logInterval;

    [DataMember(Name = "min")] public double Min { get; set; }
    [DataMember(Name = "max")] public double Max { get; set; }
    [DataMember(Name = "percentageOffset")] public double PercentageOffset { get; set; }
    [DataMember(Name = "exclusiveMin")] public bool ExclusiveMin { get; set; }
    [DataMember(Name = "exclusiveMax")] public bool ExclusiveMax { get; set; }
    [DataMember(Name = "cacheSize")] public int CacheSize { get => _cacheSize; private set => _cacheSize = Math.Max(1, Math.Min(_cacheSize, int.MaxValue)); }
    [DataMember(Name = "isLoggingEnabled")] public bool IsLoggingEnabled { get => _isLoggingEnabled; set => _isLoggingEnabled = value; }
    [DataMember(Name = "logInterval")] public TimeSpan LogInterval { get => _logInterval; set => _logInterval = TimeSpan.FromMilliseconds(Math.Max(1, Math.Min(_logInterval.TotalMilliseconds, int.MaxValue))); }

    public RandomValueGenerator() : this(0, double.MaxValue, 0, false, false, 100, true, TimeSpan.FromSeconds(60)) { }
    public RandomValueGenerator(double min, double max, double percentageOffset, bool exclusiveMin, bool exclusiveMax, int cacheSize = 100, bool isLoggingEnabled = true, TimeSpan logInterval = TimeSpan.FromSeconds(60))
    {
        Min = min;
        Max = max;
        PercentageOffset = percentageOffset;
        ExclusiveMin = exclusiveMin;
        ExclusiveMax = exclusiveMax;
        CacheSize = cacheSize;
        IsLoggingEnabled = isLoggingEnabled;
        _cache = new HashSet<ulong>(CacheSize);
        if (IsLoggingEnabled)
            LoggingSystem.Instance.Start(LogInterval);
        _valueGenerators = new Dictionary<Type, Func<Random>>
        {
            [typeof(int)] = () => new Random((int)((Max - Min) * PercentageOffset / 100 + (Min > 0 ? (long)Min : 0)), (int)(Max - (ExclusiveMax ? Max - 1 : Max))),
            [typeof(float)] = () => new Random((int)((Max - Min) * PercentageOffset / 100 + (Min > 0 ? (long)Min : 0)), (int)(Math.Abs((int)(Max - (ExclusiveMax ? Max - 1 : Max)))))
        };
    }

    private Func<Random> GetValueGenerator(Type valueType) => _valueGenerators[valueType];

    public int GenerateInteger(bool exclusiveMin = false, bool exclusiveMax = false)
    {
        var generator = GetValueGenerator(typeof(int));
        return generator()
            .Next((int)(Min + (exclusiveMin ? 1 : 0)), (int)(Max + (exclusiveMax ? 1 : 0)));
    }

    public float GenerateFloat(bool exclusiveMin = false, bool exclusiveMax = false)
    {
        var generator = GetValueGenerator(typeof(float));
        return generator()
            .Next((int)((Min + (exclusiveMin ? Min - 1 : Min)) * 10000), (int)((Max + (exclusiveMax ? Max - 1 : Max)) * 10000)) / 10000F;
    }

    private ulong GenerateKey() => Interlocked.Increment(ref _cacheCount);

    public T Generate<T>(Func<Random, T> generator)
    {
        if (_cache.Contains(GenerateKey()))
            return _cache.First(key => _cache.Remove(key)); // Return a value from the cache and remove it.

        var result = generator(_random);
        _cache.Add(GenerateKey());

        if (_cache.Count > CacheSize)
            _cache.Clear();

        if (IsLoggingEnabled)
            LoggingSystem.Instance.Log(this, result);

        return result;
    }

    public void Reset()
    {
        _cache.Clear();
        _random = new Random();
        if (IsLoggingEnabled)
            LoggingSystem.Instance.Reset();
    }
}

public static class LoggingSystem
{
    private static readonly Lazy<LoggingSystem> Instance = new Lazy<LoggingSystem>(CreateInstance);

    public static void Start(TimeSpan logInterval) => _instance.Start(logInterval);
    public static void Reset() => _instance.Reset();

    private static LoggingSystem CreateInstance()
    {
        var instance = new LoggingSystem();
        instance._locker = new object();
        instance._usageLog = new Dictionary<Type, SortedDictionary<object, int>>();
        instance._logInterval = TimeSpan.Zero;
        return instance;

        private readonly object _locker;
        private readonly Dictionary<Type, SortedDictionary<object, int>> _usageLog;
        private readonly TimeSpan _logInterval;

        public void Log(RandomValueGenerator generator, object value)
        {
            lock (_locker)
            {
                var generatorType = generator.GetType();
                if (!_usageLog.ContainsKey(generatorType))
                    _usageLog[generatorType] = new SortedDictionary<object, int>();

                var usageLog = _usageLog[generatorType];
                if (!usageLog.ContainsKey(value))
                    usageLog[value] = 1;
                else
                    usageLog[value]++;
            }
        }

        public void Start(TimeSpan logInterval)
        {
            _logInterval = logInterval;
            if (_timer != null)
                return;
            _timer = new Timer(_ => LogStatistics(), null, logInterval, logInterval);
        }

        private void LogStatistics()
        {
            lock (_locker)
            {
                foreach (var pair in _usageLog.OrderByDescending(x => x.Value.Sum()))
                {
                    var generatorType = pair.Key;
                    Console.WriteLine($"Generator: {generatorType.Name}\nValues:\n{pair.Value}");
                }
            }
        }

        private Timer _timer;
    }
}

