['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <time.h>
#include <semaphore.h>

#define MAX_FRAMES 500
#define MAX_OPERATIONS 10

typedef struct MAC_FRAME_T {
    unsigned int FRAME_ID;
    unsigned int SEQUENCE_NUMBER;
    time_t TRANSMIT_TIMESTAMP;
} MAC_FRAME;

struct frame_queue_t {
    MAC_FRAME frames[MAX_FRAMES];
    size_t length;
    sem_t mutex;
    sem_t full, empty;
};

void init_frame_queue(struct frame_queue_t *q) {
    q->length = 0;
    sem_init(&q->mutex, 1, 1);
    sem_init(&q->full, 0, MAX_FRAMES - 1);
    sem_init(&q->empty, 0, MAX_FRAMES);
}

bool is_queue_full(struct frame_queue_t *q) {
    return sem_trywait(&q->full) == 0;
}

bool is_queue_empty(struct frame_queue_t *q) {
    return sem_trywait(&q->empty) == 0;
}

void enqueue(struct frame_queue_t *q, MAC_FRAME frame) {
    sem_wait(&q->mutex);

    while (is_queue_full(q)) {
        sem_post(&q->mutex);
        sem_wait(&q->empty);
    }

    q->frames[q->length++] = frame;
    sem_post(&q->full);
    sem_post(&q->mutex);
}

void dequeue(struct frame_queue_t *q, MAC_FRAME *frame) {
    sem_wait(&q->mutex);

    while (is_queue_empty(q)) {
        sem_post(&q->mutex);
        sem_wait(&q->full);
    }

    *frame = q->frames[--q->length];
    sem_post(&q->empty);
    sem_post(&q->mutex);
}

void update_sequence_number(struct frame_queue_t *q, unsigned int id, unsigned int seq) {
    bool found = false;
    MAC_FRAME frame;
    sem_wait(&q->mutex);

    for (size_t i = 0; i < q->length && !found; ++i) {
        if (q->frames[i].FRAME_ID == id) {
            found = true;
            frame = q->frames[i];
            q->frames[i] = (MAC_FRAME){frame.FRAME_ID, seq, frame.TRANSMIT_TIMESTAMP};
        }
    }

    sem_post(&q->mutex);
}

void add_frame(struct frame_queue_t *q, MAC_FRAME frame) {
    if (is_queue_full(q)) return;

    enqueue(q, frame);
    update_sequence_number(q, frame.FRAME_ID, frame.SEQUENCE_NUMBER);
}

void remove_frame(struct frame_queue_t *q, unsigned int id) {
    MAC_FRAME frame;
    dequeue(q, &frame);

    if (frame.FRAME_ID == id) {
        update_sequence_number(q, id, UINT_MAX); // set to invalid value
    }
}
```

