public sealed class DynamicValueGenerator
{
    private readonly Dictionary<Type, Generator> _generators = new();
    private readonly object _lockObject = new();

    public void AddGenerator<T>(Type type) where T : struct
    {
        if (_generators.ContainsKey(type)) return;

        _generators[type] = CreateGenerator<T>();
    }

    private Generator CreateGenerator<T>()
    {
        if (typeof(IConvertible).IsAssignableFrom(typeof(T)))
            return new ValueRangeGenerator<T>(this);

        throw new NotSupportedException($"Unsupported type: {typeof(T)}");
    }

    public T GenerateValue<T>() where T : struct
    {
        lock (_lockObject)
        {
            if (!_generators.TryGetValue(typeof(T), out var generator))
                throw new InvalidOperationException($"No valid generator found for type: {typeof(T)}");

            return (T)generator.Generate();
        }
    }

    public float GenerateProbabilityBasedBoolean() => UnityEngine.Random.value < Probability;

    private static readonly string _invalidRangeLogFile = "InvalidRangeLog.txt";
    private static readonly Stopwatch _performanceTimer = new();
    private static int _operationCount;

    public void ValidateAndUpdateRanges()
    {
        // Implement logic to validate and update the value ranges from external data sources like APIs or databases here
        Debug.Log($"Performed range validation and updates.");
    }

    public override string ToString()
    {
        var sb = new System.Text.StringBuilder();
        _generators.ForEach(kvp => sb.AppendLine($"{kvp.Key}: [{kvp.Value.Min}, {kvp.Value.Max})"));

        sb.AppendLine($"\nOperations: {_operationCount}");
        sb.AppendLine($"Elapsed time: {_performanceTimer.ElapsedMilliseconds} ms");

        if (File.Exists(_invalidRangeLogFile))
            sb.AppendLine("\nInvalid range logs:\n" + File.ReadAllText(_invalidRangeLogFile));

        return sb.ToString();
    }

    public void ResetToDefaults()
    {
        foreach (var generator in _generators.Values)
        {
            if (generator is ValueRangeGenerator<int> intGenerator) intGenerator.ResetToDefaults();
            else if (generator is ValueRangeGenerator<float> floatGenerator) floatGenerator.ResetToDefaults();
        }
    }

    private class Generator
    {
        public virtual void ResetToDefaults() {}

        protected virtual object Generate() => throw new NotImplementedException();
    }

    private sealed class ValueRangeGenerator<T> : Generator where T : struct, IConvertible
    {
        private readonly DynamicValueGenerator _outer;
        private double _min;
        private double _max;

        public ValueRangeGenerator(DynamicValueGenerator outer)
        {
            _outer = outer;
            ResetToDefaults();
        }

        public override void ResetToDefaults()
        {
            _min = double.MinValue;
            _max = double.MaxValue;
            _outer.OnRangeReset(GetType());
        }

        protected virtual object Generate() => UnityEngine.Random.Range((float)_min, (float)_max);
    }

    private void OnRangeReset(Type type)
    {
        try
        {
            if (!_generators.ContainsKey(type)) return;

            _performanceTimer.Restart();
            ValidateAndUpdateRanges();
        }
        catch (Exception ex)
        {
            File.AppendAllText(_invalidRangeLogFile, $"{DateTime.Now}: {ex}\n");
        }
    }
}
