    public Record[] GenerateArray(int size)
    {
        var records = new Record[size];
        for (int i = 0; i < size; ++i)
            records[i] = new Record(GetInt());
        return records;
    }

    public IDataReader GetSqlResult(List<Record> records, string connectionString, string commandTemplate)
    {
        var builder = new StringBuilder();
        for (int i = 0; i < records.Count; ++i)
        {
            if (i > 0)
                builder.Append(", ");
            builder.Append("@param").Append(i + 1);
        }

        var commandText = string.Format(commandTemplate, builder.ToString());

        using (var connection = new SqlConnection(connectionString))
        {
            connection.Open();
            using (var command = new SqlCommand(commandText, connection))
            {
                for (int i = 0; i < records.Count; ++i)
                    command.Parameters.AddWithValue($"@param{i + 1}", records[i].value);

                return command.ExecuteReader();
            }
        }
    }

    public struct Record
    {
        public int value;
        public Record(int value) => this.value = value;
    }
}
