#include <atomic>
#include "MAC_EVENT_RECORD_T.h" // Define MAC_EVENT_RECORD_T structure

struct mac_collection {
    struct MAC_EVENT_RECORD_T **records;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
    std::atomic<size_t> concurrent_ops{0};
    const size_t max_concurrent_ops;
};

void mac_collection_init(struct mac_collection *collection, size_t initial_capacity) {
    collection->records = calloc(initial_capacity, sizeof(MAC_EVENT_RECORD_T*));
    collection->capacity = initial_capacity;
    collection->size = 0;
    pthread_mutex_init(&collection->mutex, NULL);
    collection->max_concurrent_ops = 50000; // Adjust this value based on desired concurrency limit
}

MAC_EVENT_RECORD_T* mac_collection_find(struct mac_collection *collection, uint64_t event_id) {
    pthread_mutex_lock(&collection->mutex);
    for (size_t i = 0; i < collection->size; ++i) {
        if (collection->records[i]->event_id == event_id) {
            pthread_mutex_unlock(&collection->mutex);
            return collection->records[i];
        }
    }
    pthread_mutex_unlock(&collection->mutex);
    return NULL;
