        // Queue the operation to be executed when concurrency limit is available
        pthread_mutex_unlock(&collection->mutex);
        return;
    }
    if (collection->size == collection->capacity) {
        // Resize and reallocate memory
        MAC_EVENT_RECORD_T **new_records = realloc(collection->records, 2 * collection->capacity * sizeof(MAC_EVENT_RECORD_T*));
        if (!new_records) {
            fprintf(stderr, "Out of memory\n");
            pthread_mutex_unlock(&collection->mutex);
            return;
        }
        collection->records = new_records;
        collection->capacity *= 2;
    }
    collection->records[collection->size++] = record;
    pthread_mutex_unlock(&collection->mutex);
}

