    (*manager)->num_cells = initial_capacity;
    (*manager)->cells = calloc(initial_capacity, sizeof(NFPAPI_CELL_HEALTH_INFO_T));
    if ((*manager)->cells == NULL) {
        perror("calloc");
        exit(EXIT_FAILURE);
    }
}

size_t get_num_cells(const struct cell_manager *manager) {
    return manager->num_cells;
