    if (manager->num_cells >= SIZE_MAX / sizeof(NFPAPI_CELL_HEALTH_INFO_T)) {
        fprintf(stderr, "Exceeded maximum number of cells\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_lock(&manager->manager_lock);
    if (manager->num_cells < manager->num_cells) {
        manager->cells[manager->num_cells].CELL_ID = cell_id;
        manager->cells[manager->num_cells].SIGNAL_STRENGTH = 0;
        manager->cells[manager->num_cells].RX_QUALITY = 0;
        manager->cells[manager->num_cells].TX_POWER_LEVEL = 0;
        pthread_mutex_init(&manager->cells[manager->num_cells].mutex, NULL);
        manager->num_cells++;
    }
    pthread_mutex_unlock(&manager->manager_lock);
}

void update_cell(struct cell_manager *manager, int cell_id, int signal_strength, int rx_quality) {
    if (cell_id >= manager->num_cells) {
        fprintf(stderr, "Cell ID out of bounds\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_lock(&manager->manager_lock);
    pthread_mutex_lock(&manager->cells[cell_id].mutex);

    manager->cells[cell_id].SIGNAL_STRENGTH = signal_strength;
    manager->cells[cell_id].RX_QUALITY = rx_quality;

    pthread_mutex_unlock(&manager->cells[cell_id].mutex);
    pthread_mutex_unlock(&manager->manager_lock);
}

void remove_cell(struct cell_manager *manager, int cell_id) {
    if (cell_id >= manager->num_cells) {
        fprintf(stderr, "Cell ID out of bounds\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_lock(&manager->manager_lock);
    size_t i;
    for (i = cell_id; i < manager->num_cells - 1; i++) {
        manager->cells[i] = manager->cells[i + 1];
    }
    manager->num_cells--;
    pthread_mutex_unlock(&manager->manager_lock);
}
