NFAPI_CRC_INDICATION_PDU_T* allocate_pdus(size_t N) {
    size_t allocated = 0;
    NFAPI_CRC_INDICATION_PDU_T *pdus;

    // Use a pool to manage memory and handle fragmentation
    static NFAPI_CRC_INDICATION_PDU_T pool[MAX_ALLOC];
    static size_t pool_index = 0;

    if (N > MAX_ALLOC) {
        fprintf(stderr, "Error: Requested allocation exceeds MAX_ALLOC\n");
        return NULL;
    }

    pdus = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        fprintf(stderr, "Error: Failed to allocate memory for requested structures\n");
        return NULL;
    }

    // Log the allocation event
    log_allocation(N);

    for (size_t i = 0; i < N && pool_index < MAX_ALLOC; ++i) {
        if (pool[pool_index].crc_indication.crcflag == 0) {
            allocated++;
            pdus[i] = pool[pool_index];
            pool[pool_index].crc_indication.crcflag = 1;
            pool_index++;
        } else {
            // Use the next available structure from the pool if it is not in use
            for (size_t j = i + 1; j < N && pool[pool_index].crc_indication.crcflag == 1; ++j) {}
            if (j - i > 1) {
                // If there are empty structures between used ones, merge them into a single contiguous block
                memmove(pdus + i + 1 - allocated, pdus + i + 1, (j - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
                allocated--;
            }
            pdus[i] = pool[pool_index];
            pool_index++;
        }
    }

    if (allocated < N) {
        // If not enough structures were found in the pool, allocate the remaining ones dynamically
        pdus += allocated;
        size_t remaining = N - allocated;
        pdus = realloc(pdus, remaining * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdus) {
            fprintf(stderr, "Error: Failed to allocate additional memory for requested structures\n");
            free(pdus);
            return NULL;
        }
    }

    // Log the deallocation event of the used structures in the pool
    for (size_t i = 0; i < pool_index; ++i) {
        if (pool[i].crc_indication.crcflag == 1) {
            log_deallocation();
            pool[i].crc_indication.crcflag = 0;
        }
    }

    return pdus;
}
