// Custom comparator for the unordered_map, based on RNTI
struct RNTIComparator {
    bool operator()(const NFAPI_CRC_INDICATION_PDU_T* lhs, const NFAPI_CRC_INDICATION_PDU_T* rhs) const noexcept {
        return lhs->rnti < rhs->rnti;
    }
};

// Lock-free ring buffer for concurrent updates and additions
template<typename T> class LockFreeRingBuffer final {
public:
    explicit LockFreeRingBuffer(size_t capacity) noexcept : m_head{ new T[capacity] }, m_tail{ new T[capacity] } {}

    ~LockFreeRingBuffer() noexcept {
        delete[] m_head;
        delete[] m_tail;
    }

    void enqueue(T value) noexcept {
        auto* const next = (atomic_thread_fence_relaxed(), ++m_head);
        if (next != m_tail) {
            *next = std::move(value);
        } else { // Buffer is full, drop the element
            delete[] next;
            m_head = m_tail;
            enqueue(std::move(value));
        }
    }

    T dequeue() noexcept {
        auto* const next = (atomic_thread_fence_relaxed(), ++m_tail);
        if (next != m_head) {
            return std::move(*m_head);
        } else { // Buffer is empty, wait for new elements
            while (true) {
                const auto* const currentHead = m_head;
                if (currentHead == m_tail) break;
                if (atomic_compare_exchange_weak(m_tail, &next, currentHead)) { // Buffer has non-empty elements now
                    return std::move(*next);
                }
            }
        }
        throw std::runtime_error("LockFreeRingBuffer: Ring buffer underflow");
    }

private:
    T* m_head;
    T* m_tail;
};

// Custom lock-free queue for concurrent removal operations
template<typename KeyType, typename ValueType> class LockFreeQueue final {
public:
    explicit LockFreeQueue(size_t capacity) noexcept : m_items{ new std::pair<KeyType, std::unique_ptr<ValueType>>[capacity] } {}

    ~LockFreeQueue() noexcept {
        delete[] m_items;
    }

    void enqueue(const KeyType& key, ValueType&& value) noexcept {
        auto* const next = (atomic_thread_fence_relaxed(), ++m_head);
        if (next != m_tail) {
            new (&*next) std::pair<KeyType, std::unique_ptr<ValueType>>(key, std::move(value));
        } else { // Buffer is full, drop the element
            delete[] next;
            enqueue(key, std::move(value));
        }
    }

    std::pair<KeyType, std::unique_ptr<ValueType>> dequeue() noexcept {
        auto* const next = (atomic_thread_fence_relaxed(), ++m_tail);
        if (next != m_head) {
            return *m_head;
        } else { // Buffer is empty, wait for new elements
            while (true) {
                const auto* const currentHead = m_head;
                if (currentHead == m_tail) break;
                if (atomic_compare_exchange_weak(m_tail, &next, currentHead)) { // Buffer has non-empty elements now
                    return *m_head;
                }
            }
        }
        throw std::runtime_error("LockFreeQueue: Queue underflow");
    }

private:
    std::pair<KeyType, std::unique_ptr<ValueType>>* m_items[1]; // The buffer is simulated with a ring of pointers to the actual items
    std::atomic<std::ptrdiff_t> m_head{ static_cast<std::ptrdiff_t>(0) };
    std::atomic<std::ptrdiff_t> m_tail{ static_cast<std::ptrdiff_t>(1) };
};

// The dynamic list class managing NFAPI_CRC_INDICATION_PDU_T structures
class DynamicList final {
public:
    explicit DynamicList(size_t capacity) noexcept : m_list{}, m_lock(), m_ringBuffer{}, m_queue{} {}

    NFAPI_CRC_INDICATION_PDU_T* add(const NFAPI_CRC_INDICATION_PDU_T& pdu) noexcept {
        if (auto ptr = static_cast<NFAPI_CRC_INDICATION_PDU_T*>(::operator new(sizeof(NFAPI_CRC_INDICATION_PDU_T))) ) {
            std::copy(&pdu, &pdu + 1, ptr);
            m_list.emplace_hint(m_list.end(), ptr, std::move_if_noexcept(ptr));
            return ptr;
        } else {
            throw std::bad_alloc();
        }
    }

    void update(const NFAPI_CRC_INDICATION_PDU_T& pdu) noexcept {
        m_list.modify_if_present([&pdu](NFAPI_CRC_INDICATION_PDU_T* item) mutable { *item = pdu; });
    }

    bool remove(uint32_t rnti) noexcept {
        auto itr = m_list.find(rnti);
        if (itr != m_list.end()) {
            m_queue.enqueue(rnti, std::move(*itr));
            m_list.erase(itr);
            return true;
        } else {
            return false;
        }
    }

    NFAPI_CRC_INDICATION_PDU_T* get(uint32_t rnti) noexcept {
        std::unique_lock<std::mutex> lock(m_lock);
        m_ringBuffer.try_pop();
        if (auto itr = m_list.find(rnti)) {
            return *itr;
        } else {
            return nullptr;
        }
    }

private:
    LockFreeQueue<uint32_t, NFAPI_CRC_INDICATION_PDU_T> m_queue;
    std::unordered_map<uint32_t, NFAPI_CRC_INDICATION_PDU_T*, std::hash<uint32_t>, std::equal_to<uint32_t>> m_list;
    LockFreeRingBuffer m_ringBuffer{ 100 }; // Buffer size is set to 100 for demonstration purposes. Adjust according to your needs.
    std::mutex m_lock;
};

