            int seed;

        public:
            explicit RandomCRCGenerator(int seed);
            ~RandomCRCGenerator();
            std::vector<NFAPI_CRC_INDICATION_PDU_T> generateIndications(int num);
    };

    std::mt19937 RandomCRCGenerator::generator;

    RandomCRCGenerator::RandomCRCGenerator(int seed) : seed(seed) {
        std::random_device rd;
        if (seed > 0)
            generator = std::mt19937(seed);
        else
            generator = std::mt19937(rd());
    }

    RandomCRCGenerator::~RandomCRCGenerator() {}

    std::vector<NFAPI_CRC_INDICATION_PDU_T> RandomCRCGenerator::generateIndications(int num) {
        std::vector<NFAPI_CRC_INDICATION_PDU_T> indications;
        for (int i = 0; i < num; ++i) {
            NFAPI_CRC_INDICATION_PDU_T indication;
            indication.RX_UE_INFORMATION_TAG = i;
            indication.RNTI = seed + i;
            indication.CRC_INDICATION_REL8_TAG.CRCFLAG = (generator() & 0b1) ? 1 : 0; // XOR with 1 to get a random 0 or 1
            indications.push_back(indication);
        }
        return indications;
    }
}
