// Thread-safe function to calculate checksums for all packets in the array concurrently
void validate_checksums(PacketInfo *packets, size_t num_threads) {
    pthread_t threads[num_threads];
    PacketInfo *packet_array = mmap(NULL, sizeof(PacketInfo) * MAX_PACKETS, PROT_READ | PROT_WRITE, MAP_SHARED, 0, 0);
    for (size_t i = 0; i < num_threads; ++i) {
        pthread_create(&threads[i], NULL, checksum_validation_worker, (void *)packet_array + i * (MAX_PACKETS / num_ threads));
    }
    for (size_t i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }
    munmap(packet_array, sizeof(PacketInfo) * MAX_PACKETS);
}

// Worker function for validating checksums concurrently in the validate_checksums function
void *checksum_validation_worker(void *arg) {
    PacketInfo *packet_array = (PacketInfo *)arg;
    for (size_t i = 0; i < MAX_PACKETS / (size_t)pthread_getnum_processors_np(); ++i) {
