using System;
using System.Collections.Generic;
using UnityEngine;
using Org.BouncyCastle.Crypto;
using Org.BouncyCastle.Crypto.Engines;
using Org.BouncyCastle.Crypto.Modes;
using Org.BouncyCastle.Crypto.Parameters;

public class DynamicRangeGenerator
{
    private readonly float _minFloat;
    private readonly float _maxFloat;
    private readonly int _minInt;
    private readonly int _maxInt;

    public DynamicRangeGenerator(float minFloat, float maxFloat, int minInt, int maxInt)
    {
        _minFloat = minFloat;
        _maxFloat = maxFloat;
        _minInt = minInt;
        _maxInt = maxInt;
    }

    public float NextFloatInclusive() => UnityEngine.Random.Range(_minFloat, _maxFloat + 1);

    public float NextFloatExclusive() => UnityEngine.Random.Range(_minFloat, _maxFloat);

    public int NextIntInclusive() => UnityEngine.Mathf.FloorToInt(UnityEngine.Random.Range(_minInt, _maxInt + 1));

    public int NextIntExclusive() => UnityEngine.Mathf.FloorToInt(UnityEngine.Random.Range(_minInt, _maxInt));

    public class DynamicCipher
    {
        private readonly ICipherMode _cipherMode;
        private readonly IParameterSpec _key;

        public DynamicCipher(string cipherMode, string key)
        {
            if (string.IsNullOrEmpty(cipherMode))
                _cipherMode = null;
            else if (cipherMode.Equals("ECB", StringComparison.OrdinalIgnoreCase))
                _cipherMode = new ECBEngine().CreateCipher();
            else if (cipherMode.Equals("EDE", StringComparison.OrdinalIgnoreCase))
                _cipherMode = new CBCBlockCipher(new TripleDESengine()).CreateCipher();
            else if (cipherMode.Equals("EDE3", StringComparison.OrdinalIgnoreCase))
                _cipherMode = new CFBBlockCipher(new TripleDESEngine(), new ECBEngine()).CreateCipher();
            else if (cipherMode.Equals("CFB", StringComparison.OrdinalIgnoreCase))
                _cipherMode = new CFBBlockCipher(new RC2Engine(), new ECBEngine()).CreateCipher();
            else
                throw new ArgumentException($"Invalid cipher mode: {cipherMode}");

            if (!string.IsNullOrEmpty(key))
                _key = new ParametersWithIV(new KeyParameter(key), new byte[8]); // Assuming key length of 24 bytes (192-bit) for security reasons
        }

        public byte[] Encrypt(byte[] data, bool isLastBlock)
        {
            var cipher = _cipherMode.CreateEncryptor(_key);
            var encryptor = new PaddedBufferedBlockCipher(cipher);
            using (var output = new MemoryStream())
            {
                encryptor.Init(true, _key);
                encryptor.Update(data, 0, data.Length);
                if (isLastBlock)
                    encryptor.DoFinal(output);
                else
                    encryptor.Reset(); // Reset for the next block
            }
            return output.ToArray();
        }

        public byte[] Decrypt(byte[] data, bool isLastBlock)
        {
            var cipher = _cipherMode.CreateDecryptor(_key);
            var decryptor = new PaddedBufferedBlockCipher(cipher);
            using (var output = new MemoryStream())
            {
                decryptor.Init(false, _key);
                decryptor.Update(data, 0, data.Length);
                if (isLastBlock)
                    decryptor.DoFinal(output);
                else
                    decryptor.Reset(); // Reset for the next block
            }
            return output.ToArray();
        }
    }
}
