using System.Threading.Tasks;

public class RandomValueGenerator
{
    private readonly ConcurrentDictionary<string, Task> _tasks;
    private readonly ObjectCache _cache;
    private readonly SemaphoreSlim _semaphore = new SemaphoreSlim(Environment.ProcessorCount * 2);

    public RandomValueGenerator()
    {
        _tasks = new ConcurrentDictionary<string, Task>();
        _cache = MemoryCache.Default;
    }

    public void StartTask(string id, double minValue, double maxValue, string type)
    {
        var task = Task.Run(() => GenerateValues(id, minValue, maxValue, type));
        Interlocked.Increment(ref _tasksCount);
        _tasks[id] = task;
    }

    public double NextValue(string id)
    {
        if (!_tasks.TryGetValue(id, out var task))
            throw new KeyNotFoundException($"Task with ID '{id}' not found.");

        await task; // Wait for the task to complete if it has already started.

        return _tasks[id].Result;
    }

    public void StopTask(string id)
    {
        if (!_tasks.TryRemove(id, out var task))
            throw new KeyNotFoundException($"Task with ID '{id}' not found.");

        task.Stop();
    }

    public void ResetAllTasks()
    {
        foreach (var task in _tasks)
        {
            task.Value.Stop();
            StartTask(task.Key, task.Value.MinValue, task.Value.MaxValue, task.Value.Type);
        }
    }

    private async Task<double> GenerateValues(string id, double minValue, double maxValue, string type)
    {
        await _semaphore.WaitAsync();

        try
        {
            var currentState = GetTaskState(id);

            if (currentState != null)
            {
                // If the task is already running or has been paused, resume it.
                return currentState.Value;
            }

            var value = GenerateRandomNumber(minValue, maxValue, type);

            SetTaskState(id, value);

            // Implement dependency management, dynamic range adjustments, caching strategies, scaling, error handling, and periodic reviews here.

            return value;
        }
        finally
        {
            _semaphore.Release();
        }
    }

    private static object GetTaskState(string id) => _cache.GetOrCreateItem(id, item => new StoredValue { Value = -1 });

    private void SetTaskState(string id, double value) => _cache.Set(id, new StoredValue { Value = value });

    private class StoredValue
    {
        public double Value { get; set; }
    }

    private double GenerateRandomNumber(double minValue, double maxValue, string type)
    {
        if (type == "int") return new Random((int)DateTime.Now.Ticks).NextDouble() * (maxValue - minValue) + minValue;
        if (type == "float") return new Random().NextDouble() * (maxValue - minValue) + minValue;

        throw new ArgumentException("Invalid type specified. Supported types are 'int' and 'float'.");
    }

    public override string ToString()
    {
        var builder = new StringBuilder();

        foreach (var task in _tasks)
        {
            builder.AppendLine($"Task ID: {task.Key}, State: {GetTaskState(task.Key).Value}, Type: {task.Value.Type}");
        }

        return builder.ToString();
    }
}
