using System;
using System.Collections.Generic;
using System.Threading;
using UnityEngine;

public class RandomValueGenerator
{
    private int _seed;
    private float _minFloat, _maxFloat;
    private int _minInt, _maxInt;
    private int _callThrottleLimit;
    private double _nextCallTime = DateTime.UtcNow.Subtract(new TimeSpan(0, 0, 1)).TotalSeconds; // 1 second interval by default

    private readonly object _lockObject = new object();
    private readonly HashSet<int> _usedNumbersPool = new HashSet<int>();

    public RandomValueGenerator(int seed = 0)
    {
        _seed = seed;
        UnityEngine.Random.InitState(_seed);
    }

    public float NextFloat(float min = 0, float max = 1, bool inclusive = true)
    {
        if (inclusive)
        {
            return UnityEngine.Random.Range(min, max + (max - min > 1 ? 1e-6f : 0));
        }
        else
        {
            return UnityEngine.Random.Range(min + 1e-6f, max);
        }
    }

    public int NextInt(int min = int.MinValue, int max = int.MaxValue, bool inclusive = true)
    {
        if (inclusive)
        {
            return UnityEngine.Random.Range(Mathf.Clamp(min, int.MinValue, int.MaxValue)), Mathf.Clamp(max, int.MinValue, int.MaxValue));
        }
        else
        {
            return UnityEngine.Random.Range(Mathf.Clamp(min + 1, int.MinValue, int.MaxValue)), Mathf.Clamp(max, int.MinValue, int.MaxValue) - 1;
        }
    }

    public IEnumerable<int> GetUniqueRandomNumbers(int size, IEnumerable<int> pool)
    {
        lock (_lockObject)
        {
            var usedNumbers = new HashSet<int>();
            foreach (var number in pool)
            {
                _usedNumbersPool.Add(number);
            }

            for (int i = 0; i < size; ++i)
            {
                int number;
                do
                {
                    number = UnityEngine.Random.Range(int.MinValue, int.MaxValue);
                } while (_usedNumbersPool.Contains(number) || usedNumbers.Contains(number));

                _usedNumbersPool.Remove(number);
                yield return number;
                usedNumbers.Add(number);
            }
        }
    }

    public void ShuffleArray<T>(T[] array)
    {
        var length = array.Length;
        for (int i = length - 1; i > 1; --i)
        {
            int j = UnityEngine.Random.Range(0, i);
            SwapItems(ref array[j], ref array[i]);
        }
    }

    private void SwapItems<T>(ref T firstItem, ref T secondItem)
    {
        var temp = firstItem;
        firstItem = secondItem;
        secondItem = temp;
    }

    public float CallThrottleLimit
    {
        get => _callThrottleLimit;
        set
        {
            if (value <= 0) throw new ArgumentException("Call throttle limit must be greater than zero.");
            _callThrottleLimit = value;
        }
    }

    public double NextCallTime
    {
        get => _nextCallTime;
        private set => _nextCallTime = value;
    }

    public override string ToString()
    {
        return $"Seed: {_seed}, Float Range: ({_minFloat} - {_maxFloat}), Int Range: ({_minInt} - {_maxInt}), CallThrottle Limit: {_callThrottleLimit}, NextCallTime: {_nextCallTime.ToString("O")}";
    }

    public void Reset()
    {
        UnityEngine.Random.InitState(_seed);
    }

    public bool CanCallNow()
    {
        if (DateTime.UtcNow.Subtract(new TimeSpan(0, 0, 1)).TotalSeconds < _nextCallTime) return false;

        var elapsedMilliseconds = (DateTime.UtcNow - _nextCallTime).TotalMilliseconds;
        if (_callThrottleLimit > elapsedMilliseconds) return false;

        _nextCallTime += _callThrottleLimit / 1000f; // Adjust next call time based on the specified throttling limit (in calls per second)
        return true;
    }
}
