    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
    pthread_mutex_t lock;
} Node;

Node* create_node(NFAPI_CRCI_NDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;
    new_node->data = data;
    new_node->next = NULL;
    pthread_mutex_init(&new_node->lock, NULL);
    return new_node;
}

struct list {
    Node* head;
    int size;
    pthread_mutex_t lock;
};

bool is_valid(int N) {
    return (N > 0 && N <= INT_MAX / sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

List* create_list(int N) {
    if (!is_valid(N)) return NULL;

    List* list = (List*)malloc(sizeof(List));
    if (!list) return NULL;

    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);

    for (int i = 0; i < N; ++i) {
        Node* new_node = create_node((NFAPI_CRCI_NDICATION_PDU_T){});
        if (!new_node) return NULL;
        insert_node(list, new_node);
    }

    return list;
}

void insert_node(List* list, Node* node) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    if (!current) {
        list->head = node;
        ++(list->size);
        pthread_mutex_unlock(&list->lock);
        return;
    }

    while (current->next != NULL) current = current->next;
    current->next = node;
    ++(list->size);

    pthread_mutex_unlock(&list->lock);
}

