using System.Threading.Tasks;

public class ObjectPoolManager<T> where T : new()
{
    private readonly int _maxCapacity;
    private readonly ConcurrentDictionary<Guid, T> _pool;
    private readonly object _syncLock = new object();
    private readonly List<T> _activeObjects;

    public ObjectPoolManager(int maxCapacity)
    {
        _maxCapacity = maxCapacity;
        _pool = new ConcurrentDictionary<Guid, T>();
        _activeObjects = new List<T>();
    }

    public Guid AcquireObject()
    {
        lock (_syncLock)
        {
            if (_pool.Count < _maxCapacity)
            {
                var obj = new T();
                ConfigureObject(obj); // Custom configuration for each object (optional)
                _pool[Guid.NewGuid()] = obj;
                _activeObjects.Add(obj);
                return Guid.NewGuid();
            }
        }

        var availableObj = _pool.FirstOrDefault(kvp => !_activeObjects.Contains(kvp.Value));
        if (availableObj.Key != default)
        {
            _activeObjects.Remove(availableObj.Value);
        }
        return availableObj.Key;
    }

    public void ReleaseObject(Guid id, Action<T> onRelease = null)
    {
        if (_pool.TryRemove(id, out var obj))
        {
            lock (_syncLock)
            {
                _activeObjects.Add(obj);
            }

            Task.Run(() =>
            {
                onRelease?.Invoke(obj); // Custom action to handle object release (optional)
                Monitor.Wait(_syncLock);
            });
        }
    }

    public IEnumerable<T> GetActiveObjects()
    {
        return _activeObjects;
    }

    protected virtual void ConfigureObject(T obj) { } // Custom configuration for each object (optional)

    public override string ToString()
    {
        var totalObjects = _pool.Count + _activeObjects.Count;
        return $"Total Objects: {totalObjects}, Active Objects: {_activeObjects.Count}, Pools: {string.Join(", ", _pool.Keys)}";
    }
}
