#include <neo4cxx/database>
#include <random>

void create_graph_vertices_and_edges(size_t num_vertices, size_t num_edges) {
    neo4cxx::Database db("bolt://localhost");

    std::default_random_engine generator;
    std::uniform_int_distribution<int> distribution(0, INT_MAX);

    CypherQuery query("CREATE (v:Vertex {prop1: $prop1, prop2: $prop2})");
    for (size_t i = 0; i < num_vertices; ++i) {
        query.bind("$prop1", distribution(generator))
            .bind("$prop2", distribution(generator));
        db.run(query);
    }

    CypherQuery create_edge_query("CREATE (v1:Vertex)-[:EDGE {weight: $weight}]->(v2:Vertex)");
    for (size_t i = 0; i < num_edges; ++i) {
        int v1_id = distribution(generator) % num_vertices;
        int v2_id = (distribution(generator) % num_vertices + v1_id) % num_vertices;
        query.bind("$weight", distribution(generator))
            .bind("v1", db["Vertex"].matching({{"id", v1_id}}).getSingle())
            .bind("v2", db["Vertex"].matching({{"id", v2_id}}).getSingle());
        db.run(create_edge_query);
    }
}
