class RachIndicatorQueue final : boost::noncopyable {
public:
    RachIndicatorQueue(size_t capacity)
        : m_queue(capacity), m_numItems(std::atomic<size_t>(0)) {}

    void add(const NFAPI_RACH_INDICATION_PDU_T& item) {
        m_queue.push(item);
        ++m_numItems;
