#include <iostream>
#include <unordered_map>
#include <mutex>
#include <boost/asio/io_context.hpp>
#include <memory>
#include <boost/noncopyable.hpp>

struct NFAPI_RACH_INDICATION_PDU_T {
    int RACH_TRANSACTION_ID;
    std::string PREAMBLE_SEQUENCE;
    int RRC_CONFIGURATION_TAG;
};

class RachIndicatorQueue final : boost::noncopyable {
public:
    void add(const NFAPI_RACH_INDICATION_PDU_T& item) {
        std::unique_lock<std::mutex> lock(m_mutex);
        m_data[item.RACH_TRANSACTION_ID] = item;
    }

    bool remove(const int RACH_TRANSACTION_ID) {
        std::unique_lock<std::mutex> lock(m_mutex);
        auto it = m_data.find(RACH_TRANSACTION_ID);
        if (it == m_data.end()) return false;

        m_data.erase(it);
        return true;
    }

    NFAPI_RACH_INDICATION_PDU_T update(const int RACH_TRANSACTION_ID, const std::string& PREAMBLE_SEQUENCE) {
        std::unique_lock<std::mutex> lock(m_mutex);
        auto it = m_data.find(RACH_TRANSACTION_ID);
        if (it == m_data.end()) return {};

        it->PREAMBLE_SEQUENCE = PREAMBLE_SEQUENCE;
        return *it;
    }

private:
    std::unordered_map<int, NFAPI_RACH_INDICATION_PDU_T> m_data;
    mutable std::mutex m_mutex;
};

// Read a file synchronously from a specified directory and return its contents as a string.
std::string readFile(const std::string& path) {
    std::ifstream inputFile(path, std::ios::in | std::ios::ate);
    if (!inputFile) throw std::runtime_error("Failed to open file.");

    size_t length = static_cast<size_t>(inputFile.tellg());
    std::unique_ptr<char[]> buffer(new char[length]);

    inputFile.seekg(0);
    inputFile.read(buffer.get(), length);

    return {buffer.get(), length};
}
