void initializeNetworkEvents(NetworkEventRecord **networkEvents, size_t *capacity, size_t *size) {
    if (!networkEvents || !capacity || !size)
        return;

    *networkEvents = malloc(*capacity * sizeof(**networkEvents));
    if (!*networkEvents) {
        perror("malloc");
        return;
    }

    memset(*networkEvents, 0, *capacity * sizeof(**networkEvents));

    *size = 0;
    *capacity = 16;
}

void appendNetworkEvent(NetworkEventRecord **networkEvents, size_t *size, const char *eventSource, const char *eventMessage, int eventPriority) {
    if (!networkEvents || !size || !eventSource || !eventMessage)
        return;

    NetworkEventRecord *current = *networkEvents + *size;

    // Handle memory allocation and potential overflow
    if (*size == *capacity) {
        size_t newCapacity = *capacity * 2;
        NetworkEventRecord *newNetworkEvents = realloc(*networkEvents, newCapacity * sizeof(**networkEvents));
        if (!newNetworkEvents) {
            perror("realloc");
            return;
        }

        *networkEvents = newNetworkEvents;
        *capacity = newCapacity;
    }

    // Initialize event struct with current timestamp, event source, and default details (null pointer for message and priority of 0)
    current->timestamp = time(NULL);
    current->eventSource = strdup(eventSource);
    if (!current->eventSource) {
        perror("strdup");
        return;
    }
    current->eventMessage = NULL;
    current->eventPriority = 0;

    // Allocate memory for the event message and handle potential overflow
    size_t messageLength = strlen(eventMessage);
    if (messageLength > MAX_MESSAGE_LENGTH) {
        fprintf(stderr, "Event message exceeds maximum length of %d\n", MAX_MESSAGE_LENGTH);
        return;
    }

    current->eventMessage = malloc((messageLength + 1) * sizeof(char));
    if (!current->eventMessage) {
        perror("malloc");
        free(current->eventSource);
        return;
    }

    // Copy event message to allocated memory and null-terminate it
    strcpy(current->eventMessage, eventMessage);

    // Update the size of networkEvents array
    (*size)++;
}
