#include <random>
#include <atomic>
#include <mutex>
#include <chrono>
#include <cstdint>

struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication_tag;
};

// Thread-safe pool class with a custom allocator for unique RNTIs and other functionalities.
class NFAPI_CRC_INDICATION_PDU_POOL {
public:
    NFAPI_CRC_INDICATION_PDU_POOL(size_t max_capacity) : maxCapacity_(maxCapacity), currentSize_(0), uniqueRNTI_(0) {}

    // Add a new structure to the pool.
    // Returns true if the RNTI is unique and the structure was successfully added, false otherwise.
    bool addStructure(NFAPI_CRC_INDICATION_PDU_T& pdu) {
        std::unique_lock<std::mutex> lock(mutex_);
        while (currentSize_ == maxCapacity_) {
            // Wait for available space or handle temporary duplication checks failures.
            conditionVariable_.wait(lock, [this] { return currentSize_ < maxCapacity_; });
        }

        // Generate a new RNTI if not already in the pool.
        pdu.rnti = generateNewRNTI();

        // Set CRCFLAG randomly.
        pdu.crc_indication_tag.crcFlag = static_cast<uint8_t>(std::random_device{}() % 2);

        structures_.emplace_back(pdu);
        currentSize_++;

        lock.unlock();

        return true;
    }

    // Get a structure from the pool if one is available, returns an empty structure otherwise.
    NFAPI_CRC_INDICATION_PDU_T getStructure() {
        std::unique_lock<std::mutex> lock(mutex_);
        while (currentSize_ == 0) {
            conditionVariable_.wait(lock);
        }

        auto result = structures_.front();
        structures_.erase(structures_.begin());
        currentSize_--;

        lock.unlock();

        return result;
    }

    // Increment the total number of processed structures counter and return true if the CRC indication was successful.
    bool incrementSuccessfulCRCIndication() {
        ++totalProcessed_;
        ++successfulCRCIndications_;
        return true;
    }

    // Clean up resources when the pool is no longer needed.
    void cleanUp() {
        structures_.clear();
        currentSize_ = 0;
        uniqueRNTI_ = 0;
        totalProcessed_ = successfulCRCIndications_ = 0;
    }

private:
    // Generate a new RNTI if not already in the pool.
    uint32_t generateNewRNTI() {
        for (uint32_t rnti : uniqueRNTI_) {
            if (!std::atomic_compare_exchange_weak(&uniqueRNTI_, &rnti, ++rnti)) {
                return generateNewRNTI();
            }
        }
        return uniqueRNTI_.fetch_add(1);
    }

    size_t maxCapacity_;
    size_t currentSize_;
    std::vector<NFAPI_CRC_INDICATION_PDU_T> structures_;
    std::atomic<uint32_t> uniqueRNTI_;
    std::atomic<size_t> totalProcessed_;
    std::atomic<size_t> successfulCRCIndications_;
    std::mutex mutex_;
    std::condition_variable conditionVariable_;
};
```

