    struct MAC_TRANSPORT_CONTEXT_T* transport_contexts;
    size_t num_transport_contexts;
} MAC_CONTEXT_T;

typedef struct MAC_TRANSPORT_CONTEXT_T {
    uint16_t ssn;
    uint32_t gtpu_teid;
    char* p_cscf_address; // Dynamically allocated, use free() when done
} MAC_TRANSPORT_CONTEXT_T;

#define MAX_POOL_SIZE 1000
#define CACHE_SIZE 100
#define LOG_INTERVAL 60

static MAC_CONTEXT_T* pool = NULL;
static size_t pool_size = 0;
static size_t successful_setup_ops = 0;
static size_t failed_unique_checks = 0;
static time_t last_log = 0;
static bool cache[CACHE_SIZE][2] = {0}; // 0 - unused, 1 - validated

void init() {
    pool = malloc(MAX_POOL_SIZE * sizeof(MAC_CONTEXT_T));
    for (size_t i = 0; i < MAX_POOL_SIZE; ++i) {
        pool[i].entity_id = UINT64_MAX;
        pthread_mutex_init(&pool[i].context_mutex, NULL);
        pool[i].transport_contexts = NULL;
        pool[i].num_transport_contexts = 0;
    }
}

void cleanup() {
    for (size_t i = 0; i < pool_size; ++i) {
        for (size_t j = 0; j < pool[i].num_transport_contexts; ++j) {
            free(pool[i].transport_contexts[j].p_cscf_address);
        }
        free(pool[i].transport_contexts);
    }
    free(pool);
}

MAC_CONTEXT_T* find_or_create_entity(uint64_t entity_id) {
    for (size_t i = 0; i < pool_size; ++i) {
        if (pool[i].entity_id == entity_id) {
            pthread_mutex_lock(&pool[i].context_mutex);
            if (pool[i].transport_contexts != NULL && pool[i].num_transport_contexts > 0) {
                for (size_t j = 0; j < pool[i].num_transport_contexts; ++j) {
                    if (pool[i].transport_contexts[j].ssn == ssn &&
                        pool[i].transport_contexts[j].gtpu_teid == gtpu_teid) {
                        pthread_mutex_unlock(&pool[i].context_mutex);
                        return &pool[i];
                    }
                }
            }
            pthread_mutex_unlock(&pool[i].context_mutex);
        }
    }

    if (pool_size >= MAX_POOL_SIZE) {
        return NULL;
    }

    MAC_CONTEXT_T* context = &pool[pool_size];
    context->entity_id = entity_id;
    pthread_mutex_init(&context->context_mutex, NULL);
    context->transport_contexts = malloc(1 * sizeof(MAC_TRANSPORT_CONTEXT_T));
    context->num_transport_contexts = 1;
    ++pool_size;

    return context;
}

bool is_unique(uint64_t entity_id, uint16_t ssn) {
    for (size_t i = 0; i < CACHE_SIZE && cache[i][entity_id & (CACHE_SIZE - 1)] != 1; ++i) {
        if (find_or_create_entity(entity_id)->transport_contexts != NULL) {
            for (size_t j = 0; j < find_or_create_entity(entity_id)->num_transport_contexts; ++j) {
                if (find_or_create_entity(entity_id)->transport_contexts[j].ssn == ssn) {
                    return false;
                }
            }
        }
    }
    return true;
}

void setup_session(MAC_CONTEXT_T* context, MAC_TRANSPORT_CONTEXT_T transport_context) {
    if (is_unique(context->entity_id, transport_context.ssn)) {
        pthread_mutex_lock(&context->context_mutex);
        context->transport_contexts = realloc(context->transport_contexts, (context->num_transport_contexts + 1) * sizeof(MAC_TRANSPORT_CONTEXT_T));
        context->transport_contexts[context->num_transport_contexts] = transport_context;
        ++context->num_transport_contexts;
        pthread_mutex_unlock(&context->context_mutex);
        successful_setup_ops++;
    } else {
        failed_unique_checks++;
    }
}

void log_statistics() {
    if (time(NULL) - last_log >= LOG_INTERVAL) {
        printf("Successful setup ops: %zu\n", successful_setup_ops);
        printf("Failed unique checks: %zu\n", failed_unique_checks);
        printf("Pool size: %zu\n", pool_size);
        printf("Percentage of successful MAC session setups: %.2f%%\n",
               (successful_setup_ops / (pool_size > 0 ? pool_size : 1)) * 100);
        last_log = time(NULL);
    }
}
```

This implementation uses a thread-safe linked list to store the MAC context structures and a simple hash map for caching validated SSN-GTPU TEID combinations. The pool size is limited, and external data source's performance is assumed to be good enough to avoid delays.']

