NFAPI_CRC_INDICATION_PDU_T* generate_pdu_list(size_t n) {
    if (n <= 0) return NULL;

    NFAPI_CRC_INDICATION_PDU* buffer = malloc(BUFFER_SIZE);
    if (!buffer) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        return NULL;
    }

    for (size_t i = 0; i < n; ++i) {
        buffer[i].rxtag = RX_UE_INFORMATION_TAG_VALUE; // Replace with appropriate value
        buffer[i].rnti.value = i + 1; // Assign unique RNTI values

        // Generate pseudo-random CRCFLAG value
        uint32_t seed = (uint32_t)time(NULL) + i;
        uint32_t crcflag = (seed * 0x5DEECE66DUL + 0xBLL) >> 32;
        buffer[i].crc_indication.crcFlag = crcflag & 0xFFFF;
    }

    return buffer;
}

void* generate_pdus(void* data) {
    ThreadData* td = data;
    NFAPI_CRC_INDICATION_PDU* pdu_list = td->buffer;
    size_t index = td->index;
    pthread_mutex_lock(&td->mutex);

    for (size_t i = index; i < N; i += MAX_THREADS) {
        if (i >= N) break;

        // Access shared resource (pdu_list) in a thread-safe manner
        pthread_mutex_unlock(&td->mutex);

        // Process PDUs
        for (size_t j = 0; j < MAX_THREADS && i + j < N; ++j, ++index) {
            NFAPI_CRC_INDICATION_PDU* pdu = &pdu_list[i + j];
            // Perform routine data processing on the PDU
            // ...
        }

        pthread_mutex_lock(&td->mutex);
    }

    free(td->buffer);
    free(td);
    pthread_exit(NULL);
}

int main() {
    NFAPI_CRC_INDICATION_PDU* pdu_list = generate_pdu_list(N);

    if (!pdu_list) return 1;

    ThreadData* thread_data = malloc(MAX_THREADS * sizeof(ThreadData));
    if (!thread_data) {
        free(pdu_list);
        return 1;
    }

    for (size_t i = 0; i < MAX_THREADS; ++i) {
        thread_data[i].buffer = pdu_list;
        thread_data[i].index = i * N / MAX_THREADS;
        thread_data[i].mutex = PTHREAD_MUTEX_INITIALIZER;
    }

    pthread_t threads[MAX_THREADS];
    for (size_t i = 0; i < MAX_THREADS; ++i) {
        int rc = pthread_create(&threads[i], NULL, generate_pdus, &thread_data[i]);
        if (rc) {
            fprintf(stderr, "Error: Failed to create thread\n");
            free(pdu_list);
            free(thread_data);
            return rc;
        }
    }

    for (size_t i = 0; i < MAX_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(pdu_list);
    free(thread_data);
    return 0;
}
