#include "mqueue.h" // Assuming you have a MQueue implementation for messaging queue system

typedef struct {
    uint32_t nas_id;
    uint16_t seq_num;
    time_t timestamp;
    sem_t timer;
    void* payload;
} LTE_ENB_RRC_API_NAS_MESSAGE_T;

typedef struct message_queue {
    MQueue mq;
    pthread_mutex_t queue_lock;
    sem_t queue_not_empty;
    int num_clients;
    LTE_ENB_RRC_API_NAS_MESSAGE_T* messages;
} message_queue_t;

message_queue_t* create_message_queue(int max_clients, uint32_t timeout) {
    message_queue_t* mq = (message_queue_t*)malloc(sizeof(message_queue_t));
    if (!mq) return NULL;

    pthread_mutex_init(&(mq->queue_lock), NULL);
    sem_init(&(mq->queue_not_empty), 0, 0);
    mq->num_clients = 0;

    // Calculate required size for messages array
    int num_messages = (max_clients * timeout) / IPC_MAX;
    if ((mq->messages = (LTE_ENB_RRC_API_NAS_MESSAGE_T*)malloc(num_messages * sizeof(LTE_ENB_RRC_API_NAS_MESSAGE_T))) == NULL) {
        free(mq);
        return NULL;
    }

    for (int i = 0; i < num_messages; ++i) {
        mq->messages[i].payload = NULL;
        sem_init(&(mq->messages[i].timer), 0, timeout);
    }

    mq->mq = create_mq(); // Assuming you have a function to create the messaging queue

    return mq;
}

bool enqueue(message_queue_t* mq, LTE_ENB_RRC_API_NAS_MESSAGE_T message) {
    pthread_mutex_lock(&(mq->queue_lock));
    while (mq->num_clients >= mq->mq.max_connections && sem_wait(&(mq->queue_not_empty)) != 0) {
        pthread_mutex_unlock(&(mq->queue_lock));
        sleep(1);
        pthread_mutex_lock(&(mq->queue_lock));
    }
    if (++(mq->num_clients) > mq->mq.max_connections) {
        // Disconnect the oldest client and free its resources
        int oldest_client = 0;
        time_t oldest_time = message.timestamp;

        for (int i = 1; i < mq->num_clients; ++i) {
            if (mq->messages[i % num_messages].timestamp < oldest_time) {
                oldest_client = i;
                oldest_time = mq->messages[i % num_messages].timestamp;
            }
        }

        LTE_ENB_RRC_API_NAS_MESSAGE_T old_message = mq->messages[oldest_client % num_messages];
        free(old_message.payload);
        memset(&old_message, 0, sizeof(LTE_ENB_RRC_API_NAS_MESSAGE_T));

        pthread_mutex_unlock(&(mq->queue_lock));
        enqueue(mq, message);
    } else {
        mq->messages[mq->num_clients % num_messages] = message;
        sem_post(&(mq->queue_not_empty));
        pthread_mutex_unlock(&(mq->queue_lock));
    }

    return true;
}

LTE_ENB_RRC_API_NAS_MESSAGE_T* dequeue(message_queue_t* mq) {
    pthread_mutex_lock(&(mq->queue_lock));
    LTE_ENB_RRC_API_NAS_MESSAGE_T* message = &(mq->messages[mq->num_clients % num_messages]);

    if (--(mq->num_clients) == 0) {
        sem_destroy(&(mq->queue_not_empty));
        pthread_mutex_destroy(&(mq->queue_lock));
    }

    pthread_mutex_unlock(&(mq->queue_lock));
    return message;
}
