typedef struct hash_entry {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct hash_entry *next;
} hash_entry_t;

typedef struct {
    size_t capacity;
    size_t size;
    hash_entry_t **entries;
    pthread_mutex_t mutex;
    int verbosity;
    bool is_logged[UINT16_MAX];
} list_t;

list_t *nfapi_crc_indication_list_init(size_t capacity, int verbosity, unsigned int seed) {
    list_t *list = malloc(sizeof(list_t));
    if (!list) return NULL;
    list->capacity = capacity;
    list->size = 0;
    list->entries = calloc(capacity, sizeof(hash_entry_t*));
    if (!list->entries) {
        free(list);
        return NULL;
    }
    list->mutex = PTHREAD_MUTEX_INITIALIZER;
    list->verbosity = verbosity;
    srand(seed);
    return list;
}

void nfapi_crc_indication_list_destroy(list_t *list) {
    if (!list) return;
    for (size_t i = 0; i < list->capacity; ++i) {
        hash_entry_t *entry = list->entries[i];
        while (entry) {
            hash_entry_t *temp = entry;
            entry = entry->next;
            free(temp);
        }
    }
    free(list->entries);
    free(list);
}

hash_entry_t* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    hash_entry_t *new_node = malloc(sizeof(hash_entry_t));
    if (!new_node) return NULL;
    new_node->data = data;
    new_node->next = NULL;
