    pthread_mutex_lock(&list->mutex);
    size_t index = data.rnti % list->capacity;
    hash_entry_t *current = list->entries[index];
    if (!current) {
        list->entries[index] = create_node(data);
        if (list->size < list->capacity) ++list->size;
    } else {
        hash_entry_t *prev, *cur;
        for (prev = NULL, cur = current; cur != NULL; prev = cur, cur = cur->next) {
            if (cur->data.rnti == data.rnti) {
                if (list->verbosity >= 1) printf("Duplicate RNTI found: %u\n", data.rnti);
                break;
            }
        }
        if (cur == NULL) { // not found
            cur = create_node(data);
            if (prev) prev->next = cur;
            else list->entries[index] = cur;
            if (list->size < list->capacity) ++list->size;
        }
    }
    pthread_mutex_unlock(&list->mutex);
}

void* random_crcflag() {
    return rand() % 2;
}

void nfapi_crc_indication_list_add(list_t *list, NFAPI_CRC_INDICATION_PDU_T data) {
    data.crc_indication.crcflag = random_crcflag();
    insert_unique_rnti(list, data);
    if (data.crc_indication.crcflag && !list->is_logged[data.crc_indication.crcflag]) {
        list->is_logged[data.crc_indication.crcflag] = true;
        if (list->verbosity >= 2) printf("CRC_INDICATION_REL8_TAG added with CRCFLAG: true\n");
    }
}
