#include <atomic>
#include <cstdint>
#include <iostream>
#include <mutex>
#include <random>
#include <thread>
#include <vector>

struct RNTI { std::uint32_t value; };
struct CRC_INDICATION_REL8_TAG { bool crcflag; };
struct RX_UE_INFORMATION_TAG { RNTI rnti; };
struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_information;
    CRC_INDICATION_REL8_TAG crc_indication;
};

constexpr size_t MAX_UES = 10000;

// Memory pool for UEs
struct MemoryPool {
    std::vector<NFAPI_CRC_INDICATION_PDU_T> buffer_;
    std::mutex mtx_;

    NFAPI_CRC_INDICATION_PDU_T* acquire() {
        std::lock_guard<std::mutex> lock(mtx_);
        if (buffer_.empty()) return nullptr;
        auto it = buffer_.end();
        it--;
        buffer_.erase(it);
        return &*it;
    }

    void release(NFAPI_CRC_INDICATION_PDU_T* pdu) {
        std::lock_guard<std::mutex> lock(mtx_);
        buffer_.push_back(*pdu);
    }
};

// Multi-threaded hash table for unique RNTIs
class RNTIHasher {
public:
    explicit RNTIHasher(size_t numThreads) : threads_(numThreads) {}

    RNTI createRNTI() {
        std::lock_guard<std::mutex> lock(mtx_);
        auto it = rntiMap_.emplace(RNTI{});
        if (it.second) return it.first->second;
        // Fallback to a simple incremental RNTI if hash table is full
        return RNTI{next_++};
    }

    bool hasRNTI(const RNTI& rnti) {
        std::unique_lock<std::mutex> lock(mtx_);
        auto it = rntiMap_.find(rnti);
        if (it != rntiMap_.end()) return true;
        // Search the RNTIs in all worker threads concurrently
        for (auto& t : threads_) {
            if (t.get_lock().try_lock()) {
                auto found = it->second.count(rnti);
                t.unlock();
                if (found > 0) return true;
            }
        }
        return false;
    }

private:
    std::unordered_map<RNTI, std::unordered_set<RNTI>> rntiMap_;
    std::vector<std::thread> threads_;
    std::mutex mtx_;
    std::atomic<uint32_t> next_{1};
};

// Generates a CRC_INDICATION_REL8_TAG with a randomly set CRCFLAG
CRC_INDICATION_REL8_TAG generateCRCIndication() {
    std::uniform_int_distribution<> dist(0, 1);
    return {dist(randgen_)};
}

// Function to manage the dynamic list of NFAPI_CRC_INDICATION_PDU_T structures
void createPDUs(RNTIHasher& rnthasher, MemoryPool& memoryPool, std::mt19937& randgen, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        auto pdu = memoryPool.acquire();
        if (pdu) {
            auto rnti = rnthasher.createRNTI();
            pdu->rx_ue_information.rnti = rnti;
            pdu->crc_indication = generateCRCIndication();
        }
    }
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        std::cout << "Usage: " << argv[0] << " seed";
        return -1;
    }

    unsigned long seed = static_cast<unsigned long>(std::atol(argv[1]));
    std::mt19937 randgen{seed};

    RNTIHasher rnthasher{std::thread::hardware_concurrency()};
    MemoryPool memoryPool;

    size_t count = MAX_UES;
    createPDUs(rnthasher, memoryPool, randgen, count);

    // Logging and monitoring
    std::atomic<uint64_t> crcFlagCount{0};

    auto lambda = [&](const NFAPI_CRC_INDICATION_PDU_T* pdu) {
        if (pdu->crc_indication.crcflag)
            crcFlagCount++;
    };

    std::for_each(memoryPool.buffer_.begin(), memoryPool.buffer_.end(), lambda);

    // Print the number of CRC flags set to true for debugging purposes
    std::cout << "Number of CRC flags set to true: " << crcFlagCount << "\n";

    return 0;
}
```

