LTE_ENB_RRC_CONTEXT* create_enb_context(size_t num_ue_contexts) {
    if (num_ue_contexts > 512) {
        fprintf(stderr, "Error: Maximum number of UE contexts exceeded.\n");
        return NULL;
    }

    LTE_ENB_RRC_CONTEXT* enb_context = (LTE_ENB_RRC_CONTEXT*)malloc(sizeof(LTE_ENB_RRC_CONTEXT));
    if (!enb_context) {
        perror("Error: Memory allocation failed.\n");
        return NULL;
    }

    enb_context->mac_entity_id = 0;
    enb_context->cgi = 0;
    enb_context->num_ue_contexts = num_ue_contexts;
    enb_context->ue_contexts = (LTE_RRC_UE_CONTEXT**)calloc(num_ue_contexts, sizeof(LTE_RRC_UE_CONTEXT*));
    if (!enb_context->ue_contexts) {
        perror("Error: Memory allocation failed.\n");
        free(enb_context);
        return NULL;
    }

    pthread_mutex_init(&enb_context->mutex, NULL);

    for (size_t i = 0; i < num_ue_contexts; ++i) {
        enb_context->ue_contexts[i] = create_ue_context(i);
        if (!enb_context->ue_contexts[i]) {
            perror("Error: Memory allocation failed.\n");
            for (size_t j = 0; j < i; ++j) free(enb_context->ue_contexts[j]);
            free(enb_context->ue_contexts);
            free(enb_context);
            return NULL;
        }
    }

    return enb_context;
}

LTE_RRC_UE_CONTEXT* create_ue_context(size_t index) {
    LTE_RRC_UE_CONTEXT* ue_context = (LTE_RRC_UE_CONTEXT*)malloc(sizeof(LTE_RRC_UE_CONTEXT));
    if (!ue_context) {
        perror("Error: Memory allocation failed.\n");
        return NULL;
