    ue_context->rx_ue_info.tag = RX_UE_INFORMATION_TAG_VALID;
    ue_context->crc_indication.tag = CRC_INDICATION_REL8_TAG_VALID;
    ue_context->crc_indication.crccflag = 0; // Set to 1 for error and 0 for no error
    ue_context->num_active_radio_links = 3; // Assuming a minimum of 3 active radio links
    ue_context->active_radio_links = (int*)calloc(ue_context->num_active_radio_links, sizeof(int));
    if (!ue_context->active_radio_links) {
        perror("Error: Memory allocation failed.\n");
        free(ue_context);
        return NULL;
    }

    // Initialize active radio links with sample values (you may replace this with data from external sources)
    for (size_t i = 0; i < ue_context->num_active_radio_links; ++i) {
        ue_context->active_radio_links[i] = i + 1; // Sample values for active radio links
    }

