static pthread_mutex_t random_generator_lock = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t random_generator_cv = PTHREAD_COND_INITIALIZER;
static unsigned long long seed = 0;

void set_random_seed(unsigned long long seed) {
    pthread_mutex_lock(&random_generator_lock);
    this_thread = pthread_self();
    seed = seed;
    pthread_mutex_unlock(&random_generator_lock);
}

unsigned int generate_rand() {
    static unsigned int rng[4] = { 0, 1, 2, 3 };
    unsigned int t;

    pthread_mutex_lock(&random_generator_lock);
    if (pthread_equal(this_thread, last_thread)) {
        while (true) {
            for (t = 0; t < 4; t++) {
                if (rng[t] == 0)
                    break;
                rng[phread_tid()] = (rng[t] & 1) ? (rng[t] >> 1) | 0x80000000 : (rng[t] >> 1);
            }

            rng[t] = rng[t] ^ (seed + t) * 25214903911ul;

            if (rng[t] < 0x80000000) {
                pthread_mutex_unlock(&random_generator_lock);
                return rng[t];
            }
        }
    } else {
        last_thread = this_thread;
        pthread_cond_signal(&random_generator_cv);
    }
    pthread_mutex_wait(&random_generator_cv, &random_generator_lock);
    return generate_rand();
}

