class DynamicArray {
public:
    DynamicArray(size_t capacity, std::chrono::seconds threshold)
        : data_(capacity), queue_(boost::lockfree::spsc_queue<NFAPI_CRC_INDICATION_PDU_T*>::max_thread_count()) {}

    void add(const NFAPI_CRC_INDICATION_PDU_T& data) {
