unsigned int RETRY_DELAY_BASE = 1000; // in milliseconds

void init_lock(Lock* lock) {
    pthread_mutex_init(&lock->mtx, NULL);
    lock->ref_count = 1;
}

void destroy_lock(Lock* lock) {
    pthread_mutex_destroy(&lock->mtx);
}

int try_lock(Lock* lock) {
    int result = pthread_mutex_trylock(&lock->mtx);
    if (result == 0)
        ++lock->ref_count;
    return result;
}

void unlock(Lock* lock) {
    assert(lock->ref_count > 0);
    --lock->ref_count;
    if (lock->ref_count == 0)
        pthread_mutex_unlock(&lock->mtx);
}

Config* alloc_config() {
