    while (retries > 0) {
        if (!fetch_config(config_out)) {
            --retries;
            unsigned int delay = RETRY_DELAY_BASE * pow(2, retries);
            struct timespec ts = { .tv_sec = delay / 1000, .tv_nsec = (delay % 1000) * 1000000 };
            nanosleep(&ts, NULL);
        } else {
            break;
        }
