using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using UnityEngine;

public class DynamicValueGenerator
{
    private readonly Random _random;
    private float _minValue, _maxValue;
    private int _seed;
    private double _sphereRadius;
    private Vector3Int _prismDimensions;
    private string _logFilePath;
    private LogLevel _logLevel;
    private int _resetInterval;
    private readonly Dictionary<string, Action> _externalSources = new Dictionary<string, Action>();

    public enum LogLevel { Debug, Info, Warning, Error }

    public DynamicValueGenerator(int seed = 0)
    {
        _random = new Random((int)DateTime.Now.Ticks + seed);
        _seed = seed;
    }

    public void SetMinMaxValues(float minValue, float maxValue)
    {
        _minValue = minValue;
        _maxValue = maxValue;
    }

    public void SetSphereRadius(double radius) => _sphereRadius = radius;

    public void SetPrismDimensions(Vector3Int dimensions) => _prismDimensions = dimensions;

    public void SetLogFilePath(string filePath) => _logFilePath = filePath;

    public void SetLogLevel(LogLevel level) => _logLevel = level;

    public void SetResetInterval(int interval) => _resetInterval = interval;

    public void AddExternalSource(string name, Action action) => _externalSources[name] = action;

    public float NextFloat() => (_maxValue - _minValue) * _random.NextDouble() + _minValue;

    public int NextInt() => (int)((_maxValue - _minValue) * _random.NextDouble()) + MathF.Ceiling(_minValue);

    public int NextInt(int maxValueExclusive) => (int)((maxValueExclusive - _minValue) * _random.NextDouble()) + MathF.Ceiling(_minValue);

    public Vector3 NextVector3()
    {
        var v = new Vector3((NextFloat() * (_prismDimensions.x - 1)) + 0.5f,
                            (NextFloat() * (_prismDimensions.y - 1)) + 0.5f,
                            (NextFloat() * (_prismDimensions.z - 1)) + 0.5f);
        return v;
    }

    public Vector3 NextVector3(float xMin, float xMax, float yMin, float yMax, float zMin, float zMax)
    {
        var v = new Vector3(NextFloat(xMin, xMax), NextFloat(yMin, yMax), NextFloat(zMin, zMax));
        return v;
    }

    public Vector3 NextOnSphereSurface(float radius)
    {
        var theta = 2 * MathF.PI * _random.NextDouble();
        var phi = MathF.Acos(_random.NextDouble());
        return new Vector3((float)(radius * MathF.Sin(phi) * MathF.Cos(theta)),
                           (float)(radius * MathF.Sin(phi) * MathF.Sin(theta)),
                           radius * MathF.Cos(phi));
    }

    public override string ToString() => $"Range: [{_minValue}, {_maxValue}]";

    private void Log(string message, LogLevel level)
    {
        if (level >= _logLevel)
        {
            Console.WriteLine($"[{level}] {message}");

            if (!string.IsNullOrEmpty(_logFilePath))
                File.AppendAllText(_logFilePath, $"[{level}] {message}\n");
        }
    }

    private void Reset()
    {
        _resetInterval--;

        if (_resetInterval <= 0)
        {
            _random = new Random((int)DateTime.Now.Ticks + _seed);
            _resetInterval = _seed;
        }
    }

    public void GenerateRandomValues(Action<float> action, int count)
    {
        for (var i = 0; i < count; i++)
        {
            action(_random.NextFloat());
            Reset();
        }
    }

    public void AdjustParameters()
    {
        foreach (var source in _externalSources)
            source.Value?.Invoke();
    }
}
