void* populate_list(void* arg) {
    static NFAPI_CRC_INDICATION_PDU_T** list = NULL;
    static size_t current_idx = 0, capacity = 0;

    if (!list) {
        list = malloc(MAX_ELEMENTS * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        if (!list) return NULL;
        capacity = MAX_ELEMENTS;
    }

    while (current_idx < capacity && current_idx < MAX_ELEMENTS) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = create_pdu();
        if (!pdu) break;
        set_crcflag(pdu);
        list[current_idx++] = pdu;
    }

    return NULL;
}

