    for (; idx < MAX_ELEMENTS && list[idx]; ++idx);
    if (idx < MAX_ELEMENTS) {
        pthread_mutex_lock(&pdu->mutex);
        pdu->delivery_status = NOT_DELIVERED;
        list[idx] = pdu;
        pthread_mutex_unlock(&pdu->mutex);
