static struct memory_pool memory_pool;
static pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;

static void* allocate_memory_block(void) {
    pthread_mutex_lock(&pool_mutex);
    if (memory_pool.free_index != memory_pool.blocks_count) {
        size_t index = memory_pool.free_index;
        memory_pool.free_index++;
        pthread_mutex_unlock(&pool_mutex);
        return &memory_pool.memory_blocks[index];
    }
    pthread_mutex_unlock(&pool_mutex);

    struct memory_block *new_block = malloc(sizeof(struct memory_block));
    if (!new_block) {
        perror("malloc");
        return NULL;
    }

    new_block->capacity = INITIAL_CAPACITY;
    new_block->current = 0;
    new_block->data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_block->capacity);
    if (!new_block->data) {
        free(new_block);
        perror("malloc");
        return NULL;
    }

    pthread_mutex_lock(&pool_mutex);
    memory_pool.memory_blocks = realloc(memory_pool.memory_blocks, sizeof(struct memory_block) * (memory_pool.blocks_count + 1));
    if (!memory_pool.memory_blocks) {
        free(new_block->data);
        free(new_block);
        perror("realloc");
        pthread_mutex_unlock(&pool_mutex);
        return NULL;
    }
    memory_pool.memory_blocks[memory_pool.blocks_count] = new_block;
    memory_pool.blocks_count++;
    pthread_mutex_unlock(&pool_mutex);

    return &memory_pool.memory_blocks[memory_pool.blocks_count - 1];
}

