typedef struct {
    unsigned char crcflag;
    RX_UE_INFORMATION_TAG rx_ue_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t mutex;

void* generateEntry(void* arg) {
    int* entries = (int*)arg;
    for(int i=0;i<*entries;++i){
        Node* node = (Node*)malloc(sizeof(Node));
        node->data.crcflag = rand()%2;
        node->data.rx_ue_tag = RX_UE_INFORMATION_TAG_init(); // Initialize tag structure
        node->data.rnti = RNTI_init(RNTI_TYPE_eUTRA_RNTI); // Initialize RNTI structure
        node->data.crc_indication.tag = CRC_INDICATION_REL8_TAG_init(); // Initialize tag structure
        head = insert(head, node->data);
    }
    return NULL;
}

Node* insert(Node* head, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->data = data;
    node->next = head;
    head = node;
    return node;
}

unsigned char* computeMD5(const unsigned char* input, size_t length) {
    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5_CTX ctx;
    MD5_Init(&ctx);
    MD5_Update(&ctx, input, length);
    MD5_Final(digest, &ctx);
    static unsigned char result[32];
    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        sprintf((char*)&result[i*2], "%02x", digest[i]);
    }
    return result;
}

void init() {
    pthread_mutex_init(&mutex, NULL);
}

int main(int argc, char** argv) {
    if (argc < 2){
        printf("Usage : %s <number of entries>\n", argv[0]);
        return -1;
    }
    int number_of_entries = atoi(argv[1]);
    pthread_t threads[number_of_entries];

    init();
    for (int i = 0; i < number_of_entries; ++i) {
        pthread_create(&threads[i], NULL, generateEntry, &number_of_entries);
    }
    for (int i = 0; i < number_of_entries; ++i) {
        pthread_join(threads[i], NULL);
    }

    char* md5hash = computeMD5("some-input", strlen("some-input")); // Replace with the appropriate input string
    printf("Number of entries generated : %d\nMD5 hash : %s\n", number_of_entries, md5hash);

    return 0;
}
