    structure->crci.crcflag = (rand() % 2 == 0) ? true : false;
}

struct list* create_list(size_t size, uint64_t min_seq_num, uint64_t max_seq_num) {
    struct list *list = malloc(sizeof(struct list));
    if (!list) {
        fprintf(stderr, "Error allocating memory for the list.\n");
        return NULL;
    }

    list->size = size;
    list->data = calloc(size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        fprintf(stderr, "Error allocating memory for the data structures.\n");
        free(list);
        return NULL;
    }

    pthread_mutex_init(&list->list_lock, NULL);
    for (size_t i = 0; i < size; ++i) {
        if (!pthread_mutex_init(&(list->data[i].lock), NULL)) {
            fprintf(stderr, "Error initializing mutex for data structure #%lu.\n", i);
            free_list(list);
            return NULL;
        }
        init_structure(&(list->data[i]));
        list->data[i].sequence_number = max(min_seq_num, list->data[i].sequence_number) + i;
    }

    return list;
}

void free_list(struct list* list) {
    if (!list)
        return;

    pthread_mutex_destroy(&list->list_lock);
    for (size_t i = 0; i < list->size; ++i) {
