struct nfapi_context {
    size_t size;
    NFAPI_CRCI_PDU_T *data;
    pthread_mutex_t lock;
};

void nfapi_init(struct nfapi_context **ctx, size_t size) {
    *ctx = malloc(sizeof(struct nfapi_context));
    if (!(*ctx)) return;
    (*ctx)->size = size;
    (*ctx)->data = calloc(size, sizeof(NFAPI_CRCI_PDU_T));
    if (!(*ctx)->data) {
        free(*ctx);
        *ctx = NULL;
        return;
    }
    pthread_mutex_init(&(*ctx)->lock, NULL);
}

void nfapi_destroy(struct nfapi_context **ctx) {
    if (!*ctx) return;
    free((*ctx)->data);
    pthread_mutex_destroy(&(*ctx)->lock);
    free(*ctx);
    *ctx = NULL;
}

void nfapi_update(struct nfapi_context *ctx, size_t index, RX_UE_INFORMATION_TAG tag, RNTI rnti) {
    pthread_mutex_lock(&ctx->lock);
    ctx->data[index].tag = tag;
    ctx->data[index].rnti = rnti;
    ctx->data[index].crc_indication.CRCFLAG = rand();
    pthread_mutex_unlock(&ctx->lock);
}

NFAPI_CRCI_PDU_T *nfapi_query(struct nfapi_context *ctx, size_t index) {
    NFAPI_CRCI_PDU_T *pdu = NULL;

    pthread_mutex_lock(&ctx->lock);
    if (index < ctx->size && ctx->data[index].tag != INVALID_TAG) {
        pdu = &ctx->data[index];
    }
    pthread_mutex_unlock(&ctx->lock);

    return pdu;
}
