public class DynamicValueGenerator
{
    private float minValue;
    private float maxValue;
    private int seed;
    private bool isInitialized;
    private bool isConfigUpdated;

    private Action<float, float> OnConfigUpdate;

    public event Action<float, float> OnValueGenerated;

    public DynamicValueGenerator(float minValue, float maxValue, int seed = 0)
    {
        this.minValue = minValue;
        this.maxValue = maxValue;
        this.seed = seed;
        Initialize();
    }

    public void SetConfigService(Action<float, float> onConfigUpdate)
    {
        OnConfigUpdate += onConfigUpdate;
    }

    private async Task Initialize()
    {
        if (isInitialized) return;

        try
        {
            await LoadConfiguration(); // Replace with your configuration service method
            isInitialized = true;
        }
        catch (Exception ex)
        {
            Debug.LogError($"Failed to initialize DynamicValueGenerator: {ex}");
        }
    }

    private async Task LoadConfiguration()
    {
        if (OnConfigUpdate != null) OnConfigUpdate(minValue, maxValue);
        isConfigUpdated = true;
    }

    public float GenerateFloat(bool inclusiveMin, bool inclusiveMax)
    {
        CheckRange();
        return UnityEngine.Random.Range(inclusiveMin ? minValue : minValue + 0.001f, inclusiveMax ? maxValue : maxValue - 0.001f);
    }

    public int GenerateInt(bool inclusiveMin, bool inclusiveMax)
    {
        CheckRange();
        return (int)(UnityEngine.Random.Range(inclusiveMin ? minValue : Mathf.Ceil(minValue), inclusiveMax ? maxValue : Mathf.Floor(maxValue)) + 0.5f);
    }

    private void CheckRange()
    {
        if (!isInitialized || !isConfigUpdated)
        {
            Debug.LogError("DynamicValueGenerator not initialized or configuration not updated");
            throw new InvalidOperationException("DynamicValueGenerator not ready for use.");
        }

        if (maxValue <= minValue)
        {
            Debug.LogError($"Invalid range: maxValue={maxValue} <= minValue={minValue}");
            throw new ArgumentOutOfRangeException(nameof(maxValue), "Max value must be greater than min value.");
        }
    }

    public void Reset(int seed = 0)
    {
        UnityEngine.Random.InitState(seed);
        Initialize();
    }
}
