struct dns_query {
    char hostname[MAX_HOSTNAME_LENGTH];
    in_addr_t *ip_address;
    pthread_mutex_t lock;
    int status;
};

int initialize_arr(NFAPI_CRC_INDICATION_PDU_T* arr) {
    memset(arr, 0, NUM_ELEMENTS * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < NUM_ELEMENTS; ++i) {
        arr[i].rx_ue_information_tag = i + 1;
        arr[i].rnti = i + 2;
        arr[i].crc_indication_rel8_tag = rand() % 2;
    }

    return 0;
}

void* dns_query_func(void* arg) {
    struct dns_query* query = (struct dns_query*)arg;
    int res;
    char buffer[MAX_HOSTNAME_LENGTH + 256];

    res = getnameinfo(query->hostname, MAX_HOSTNAME_LENGTH, buffer, sizeof(buffer), NULL, 0, NI_NUMERICHOST | NI_NOFQDN);

    if (res == 0) {
        inet_ntop(AF_INET, &((struct sockaddr_in*)query->ip_address)->sin_addr, query->ip_address->s_addr, INET6_ADDRSTRLEN);
        strcpy(query->ip_address->ip, buffer);
    } else {
        query->status = -1;
    }

    return NULL;
}

int populate_arr(char** hostnames, int num_hostnames, NFAPI_CRC_INDICATION_PDU_T* arr) {
    struct dns_query* queries = calloc(num_hostnames, sizeof(struct dns_query));
    pthread_t* threads = malloc(num_hostnames * sizeof(pthread_t));
    int i, status;

    for (i = 0; i < num_hostnames; ++i) {
        queries[i].hostname = hostnames[i];
        queries[i].ip_address = &(arr[i].ip);
        pthread_mutex_init(&(queries[i].lock), NULL);
        threads[i] = 0;
    }

    for (i = 0; i < num_hostnames; ++i) {
        pthread_create(&threads[i], NULL, dns_query_func, &queries[i]);
    }

    for (i = 0; i < num_hostnames; ++i) {
        pthread_join(threads[i], NULL);

        pthread_mutex_lock(&(queries[i].lock));

        if (queries[i].status == -1) {
            status = -2;
            break;
        }

        status = queries[i].status;
        memcpy(&(arr[i]), &(queries[i].ip_address), sizeof(arr[0]));

        pthread_mutex_unlock(&(queries[i].lock));
    }

    free(queries);
    free(threads);

    return status;
}
