```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

typedef struct {
    unsigned int rxi;
    uint16_t rnti;
    uint32_t crc_indication;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

struct dynamic_array {
    size_t capacity;
    size_t size;
    NFAPI_CRC_INDICATION_PDU_T* data;
};

void swap(NFAPI_CRC_INDICATION_PDU_T *a, NFAPI_CRC_INDICATION_PDU_T *b) {
    NFAPI_CRC_INDICATION_PDU_T tmp = *a;
    *a = *b;
    *b = tmp;
}

int partition(NFAPI_CRC_INDICATION_PDU_T* arr, size_t low, size_t high) {
    NFAPI_CRC_INDICATION_PDU_T pivot = arr[high];
    size_t i = (low - 1);

    for (size_t j = low; j < high; j++) {
        if (arr[j].rnti <= pivot.rnti) {
            i++;
            swap(&arr[i], &arr[j]);
        }
    }

    swap(&arr[i + 1], &arr[high]);
    return (i + 1);
}

void quicksort(NFAPI_CRC_INDICATION_PDU_T* arr, size_t low, size_t high) {
    if (low < high) {
        size_t p = partition(arr, low, high);
        quicksort(arr, low, p - 1);
        quicksort(arr, p + 1, high);
    }
}

bool is_valid_rnti(NFAPI_CRC_INDICATION_PDU_T* arr, size_t len, size_t rnti) {
    for (size_t i = 0; i < len; i++) {
        if (arr[i].rnti == rnti && i != len - 1) {
            return false;
        }
    }

    return true;
}

void generate_array(struct dynamic_array* array, size_t capacity, size_t size) {
    if (capacity < size) {
        printf("Insufficient capacity.\n");
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T* new_data = realloc(array->data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * capacity);

    if (!new_data) {
        printf("Memory allocation failed.\n");
        return;
    }

    array->capacity = capacity;
    array->size = size;
    array->data = new_data;

    for (size_t i = 0; i < size; i++) {
        array->data[i].rxi = rand();
        array->data[i].rnti = rand() % 65536;
        array->data[i].crc_indication = rand();
        array->data[i].crcflag = rand() % 2 == 0;
    }

    quicksort(array->data, 0, size - 1);

    size_t j = 0;
    for (size_t i = 1; i < size; i++) {
        if (!is_valid_rnti(array->data, j, array->data[i].rnti)) {
            NFAPI_CRC_INDICATION_PDU_T temp = array->data[j];
            while (j > 0 && !is_valid_rnti(array->data, j - 1, temp.rnti)) {
                array->data[j] = array->data[j - 1];
                j--;
                temp = array->data[j];
            }
            array->data[j] = temp;
        } else {
            j++;
        }
    }
}

bool verify_array(NFAPI_CRC_INDICATION_PDU_T* arr, size_t len) {
    for (size_t i = 0; i < len - 1; i++) {
        if (arr[i].rnti == arr[i + 1].rnti || !arr[i].crcflag == !arr[i + 1].crcflag) {
            return false;
        }
    }

    return true;
}
