// Custom memory pool for minimizing heap fragmentation
typedef struct MemPool {
    size_t capacity;
    void** elements;
} MemPool;

// Define the structure to be managed in the list
typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint32_t rnti;
    // Add other fields as needed
} NFAPI_CRC_INDICATION_PDU_T;

// Dynamic list structure, leveraging a custom memory pool
typedef struct glist {
    size_t size;
    MemPool* mem_pool;
    void** data;
    pthread_mutex_t lock;
} glist;

void init_glist(glist* list, size_t initial_capacity) {
    list->size = 0;
    list->mem_pool = malloc(sizeof(MemPool));
    memset(list->mem_pool, 0, sizeof(MemPool));
    list->mem_pool->capacity = initial_capacity;
    list->data = calloc(initial_capacity, sizeof(void*));
    pthread_mutex_init(&list->lock, NULL);
}

void push_back_glist(glist* list, void* data) {
    pthread_mutex_lock(&list->lock);
    if (list->size == list->mem_pool->capacity) {
        resize_glist(list, list->mem_pool->capacity * 2);
    }
    list->data[list->size] = data;
    list->size++;
    pthread_mutex_unlock(&list->lock);
}

void* pop_front_glist(glist* list) {
    void* data;
    pthread_mutex_lock(&list->lock);
    if (list->size > 0) {
        data = list->data[0];
        memmove(list->data, list->data + 1, sizeof(void*) * (--list->size));
    } else {
        data = NULL;
    }
    pthread_mutex_unlock(&list->lock);
    return data;
}

// Implement other functions such as resize_glist() and cleanup() as needed.

