[System.Serializable]
public class RandomValueGenerator
{
    private float minValue;
    private float maxValue;

    public float MinValue { get => minValue; set { if (value > maxValue) throw new ArgumentOutOfRangeException(nameof(value), "Min value cannot exceed Max value."); minValue = value; } }
    public float MaxValue { get => maxValue; set { if (value < minValue) throw new ArgumentOutOfRangeException(nameof(value), "Max value cannot be less than Min value."); maxValue = value; } }

    private System.Random _random;

    public RandomValueGenerator(float minValue, float maxValue)
    {
        MinValue = minValue;
        MaxValue = maxValue;
        _random = new System.Random();
    }

    public float GetRandomFloat()
    {
        return (_random.NextDouble() * (MaxValue - MinValue)) + MinValue;
    }

    public float GetRandomExclusiveFloat(Func<float> seedGenerator)
    {
        var seed = seedGenerator();
        _random = new System.Random(seed.GetHashCode());
        return (_random.NextDouble() * (MaxValue - MinValue)) + MinValue;
    }

    public int GetRandomInt()
    {
        return Mathf.Clamp(_random.Next((int)(MinValue / 0.01f)), (int)Mathf.Floor(MinValue), (int)Mathf.Ceil(MaxValue));
    }

    public int GetRandomExclusiveInt()
    {
        return Mathf.Clamp(_random.Next((int)((MaxValue - MinValue) * 0.99f)) + (int)Mathf.Floor(MinValue), (int)Mathf.Ceiling(MinValue), (int)Mathf.Floor(MaxValue));
    }

    public Vector2 GetRandomVector2(bool isInclusive = true)
    {
        float x = isInclusive ? (_random.NextDouble() * (MaxValue - MinValue)) + MinValue : (_random.NextDouble() * (MaxValue - MinValue)) + MinValue + (1 - _random.NextDouble()) * 0.5f * (MinValue - MaxValue);
        float y = isInclusive ? (_random.NextDouble() * (MaxValue - MinValue)) + MinValue : (_random.NextDouble() * (MaxValue - MinValue)) + MinValue + (1 - _random.NextDouble()) * 0.5f * (MinValue - MaxValue);
        return new Vector2(x, y);
    }

    public override string ToString()
    {
        return $"Range: [{MinValue}, {MaxValue}]";
    }
}
