void executeCommand(const char *command, char **outputBuf, char **errorBuf) {
    pid_t pid = fork();
    if (pid == -1) {
        perror("fork");
        exit(EXIT_FAILURE);
    }

    if (!pid) {
        // Child process
        dup2(dup2(STDOUT_FILENO, STDOUT_FILENO), STERR_FILENO);
        execl("/bin/sh", "/bin/sh", "-c", command, NULL);
        perror("execl");
        exit(EXIT_FAILURE);
    } else {
        // Parent process
        int wstatus;
        waitpid(pid, &wstatus, 0);

        *outputBuf = getenv("OUTPUT_BUFFER");
        if (!*outputBuf) {
            char output[1024];
            ssize_t nread = read(STDOUT_FILENO, output, sizeof(output));
            if (nread > 0) {
                *outputBuf = malloc(nread + 1);
                strcpy(*outputBuf, output);
            }
        }

        *errorBuf = getenv("ERROR_BUFFER");
        if (!*errorBuf) {
            char error[1024];
            ssize_t nread = read(STDERR_FILENO, error, sizeof(error));
            if (nread > 0) {
                *errorBuf = malloc(nread + 1);
                strcpy(*errorBuf, error);
            }
        }
    }
}

