#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_MEMORY_BUDGET (10 * 1024 * 1024) // Replace with your desired maximum memory budget
#define NUM_ELEMENTS (100000) // Replace with your desired number of elements

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct element {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct element *next;
} Element;

static Element** head = NULL;
static size_t count = 0;
static size_t total_allocated = 0;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void create_random_data(NFAPI_CRC_INDICATION_PDU_T* data) {
    // Replace this with your function to generate valid random data within acceptable ranges
}

int add_element(const NFAPI_CRC_INDICATION_PDU_T* data) {
    Element *new_element, **prev;

    pthread_mutex_lock(&mutex);

    if (total_allocated + sizeof(Element) + sizeof(NFAPI_CRC_INDICATION_PDU_T) > MAX_MEMORY_BUDGET) {
        pthread_mutex_unlock(&mutex);
        return -1; // Memory allocation failed
    }

    new_element = (Element*)malloc(sizeof(Element));
    if (!new_element) {
        pthread_mutex_unlock(&mutex);
        return -2; // Malloc failed
    }

    total_allocated += sizeof(Element) + sizeof(NFAPI_CRC_INDICATION_PDU_T);
    new_element->data = *data;
    new_element->next = NULL;

    prev = head;
    while (*prev && (*prev)->next != NULL) {
        prev = &((*prev)->next);
    }

    if (*prev == NULL) {
        *head = new_element;
    } else {
        (*prev)->next = new_element;
    }

    count++;
    pthread_mutex_unlock(&mutex);

    return 0; // Successfully added element
}

void log(const char* message) {
    // Replace this with your logging function
}

void cleanup() {
    Element *current, *next;

    pthread_mutex_lock(&mutex);

    current = *head;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    *head = NULL;
    count = 0;
    total_allocated = 0;

    pthread_mutex_unlock(&mutex);
}
```

