    printf("%s\n", message);
    pthread_mutex_unlock(&logging_mutex);
}

void* create_and_populate_pdus(size_t num_elements) {
    struct task task = {num_elements, NULL};
    NFAPI_CRCI_INDICATION_PDU_T** pdus;

    sem_init(&task_queue, 0, 0);
    sem_init(&pool, 0, THREAD_POOL_SIZE);
    pthread_mutex_init(&logging_mutex, NULL);

    if (!create_pdus(num_elements, &pdus)) {
        report(false, "Failed to allocate memory for pdus.");
        return NULL;
    }

    populate_pdus(num_elements, pdus);

    sem_post(&pool);
    struct task* task_to_process = malloc(sizeof(struct task));
    memcpy(task_to_process, &task, sizeof(struct task));

    for (size_t i = 0; i < num_elements; ++i) {
        report(true, "Successfully created and populated pdu[" + std::to_string(i) + "].");
    }

    while (num_elements > 0) {
        sem_wait(&task_queue);
        task.num_elements -= 1;
        if (task.num_elements == 0) {
            free(task_to_process);
        }

        struct task* processed_task = malloc(sizeof(struct task));
        memcpy(processed_task, &task, sizeof(struct task));
        pthread_t worker_id;
        void* result = NULL;

        if (pthread_create(&worker_id, NULL, worker, processed_task)) {
            report(false, "Failed to create worker thread.");
            free(processed_task);
        } else {
            pthread_detach(worker_id);
        }
    }

    sem_wait(&pool);

    for (size_t i = 0; i < num_elements; ++i) {
        free(pdus[i]);
    }
    free(pdus);

    return NULL;
}
