#else
    return mmap(NULL, length, MMAP_PROT, MAP_ANONYMOUS | MAP_PRIVATE, -1, 0);
#endif
}

void mem_pool_cleanup(void *addr) {
#ifdef _WIN32
    munmap(addr, *(size_t*)addr);
#else
    munmap(addr, *(size_t*)addr);
#endif
}

bool is_valid_N(size_t N) {
