    struct MemPool old_mem_pool = allocator->mem_pool;

    void *new_mem_pool_start = mem_pool_init(new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (old_mem_pool.used > 0) {
        memcpy((char*)new_mem_pool_start + old_mem_pool.used, old_mem_pool.start, old_mem_pool.length - old_mem_pool.used);
    }

    allocator->capacity = new_capacity;
    allocator->elements = (NFAPI_CRC_INDICATION_PDU_T*)new_mem_pool_start;
    allocator->mem_pool.start = new_mem_pool_start;
