#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>

typedef struct LTE_PDCP_RX_PDU_T {
    uint32_t pdcp_sn;
    void* mac_entity; // Pointer to external MAC entity
    // Security parameters
} LTE_PDCP_RX_PDU_T;

struct pdcp_manager {
    size_t capacity;
    size_t count;
    LTE_PDCP_RX_PDU_T* data;
    pthread_mutex_t lock;
};

void* get_mac_entity(LTE_PDCP_RX_PDU_T* pdcp, void** old_val) {
    return pdcp->mac_entity;
}

void set_mac_entity(LTE_PDCP_RX_PDU_T* pdcp, void* new_val) {
    pdcp->mac_entity = new_val;
}

void pdcp_manager_init(struct pdcp_manager** manager, size_t capacity) {
    *manager = malloc(sizeof(struct pdcp_manager));
    if (!*manager) {
        return;
    }

    (*manager)->capacity = capacity;
    (*manager)->count = 0;
    (*manager)->data = calloc(capacity, sizeof(LTE_PDCP_RX_PDU_T));
    if (!(*manager)->data) {
        free(*manager);
        *manager = NULL;
        return;
    }

    pthread_mutex_init(&(*manager)->lock, NULL);
}

void pdcp_manager_free(struct pdcp_manager** manager) {
    if (!*manager) {
        return;
    }

    free((*manager)->data);
    pthread_mutex_destroy(&(*manager)->lock);
    free(*manager);
    *manager = NULL;
}

size_t pdcp_manager_push(struct pdcp_manager* manager, LTE_PDCP_RX_PDU_T pdcp) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity) {
        pthread_mutex_unlock(&manager->lock);
        return 0;
    }

    size_t index = manager->count++;
    LTE_PDCP_RX_PDU_T* data = &manager->data[index];

    *data = pdcp;
    pthread_mutex_unlock(&manager->lock);

    return 1;
}

LTE_PDCP_RX_PDU_T* pdcp_manager_get(struct pdcp_manager* manager, size_t index) {
    if (index >= manager->count || !manager->data) {
        return NULL;
    }

    pthread_mutex_lock(&manager->lock);

    LTE_PDCP_RX_PDU_T* data = &manager->data[index];
    pthread_mutex_unlock(&manager->lock);

    return data;
}
