   #include "dynamic_list.h"
   #include <stdlib.h>
   #include <string.h>
   #include <unistd.h>

   static void lte_dynamic_list_grow(struct lte_dynamic_list* list) {
      if (list->capacity >= MAX_POOL_SIZE * 2) return;
      LTEPHY_PHY_PDU_T* newPool = realloc(list->pool, sizeof(LTEPHY_PHY_PDU_T) * (list->capacity * 2));
      if (!newPool) {
         // Handle memory allocation failure gracefully
      }
      list->pool = newPool;
      list->capacity *= 2;
   }

   void lte_dynamic_list_init(struct lte_dynamic_list* list) {
      memset(list, 0, sizeof(*list));
      list->pool = malloc(sizeof(LTEPHY_PHY_PDU_T) * PREFETCH_BUFFER_SIZE);
      if (!list->pool) {
         // Handle memory allocation failure gracefully
      }
      list->capacity = PREFETCH_BUFFER_SIZE;
      pthread_mutex_init(&(list->lock), NULL);
      pthread_cond_init(&(list->cond_full), NULL);
      pthread_cond_init(&(list->cond_empty), NULL);
   }

   LTEPHY_PHY_PDU_T* lte_dynamic_list_alloc(struct lte_dynamic_list* list) {
      if (list->count >= list->capacity) lte_dynamic_list_grow(list);
      pthread_mutex_lock(&(list->lock));
      while (list->count == list->capacity) pthread_cond_wait(&(list->cond_empty), &(list->lock));
      LTEPHY_PHY_PDU_T* item = &list->pool[list->count++];
      memset(item, 0, sizeof(*item));
      pthread_mutex_unlock(&(list->lock));
      return item;
   }

   LTEPHY_PHY_PDU_T* lte_dynamic_list_fetch(struct lte_dynamic_list* list) {
      if (list->count <= 0) pthread_cond_wait(&(list->cond_full), &(list->lock));
      pthread_mutex_lock(&(list->lock));
      LTEPHY_PHY_PDU_T* item = &list->pool[--list->count];
      pthread_mutex_unlock(&(list->lock));
      return item;
   }

   void lte_dynamic_list_free(struct lte_dynamic_list* list, LTEPHY_PHY_PDU_T* item) {
      pthread_mutex_lock(&(list->lock));
      *item = (LTEPHY_PHY_PDU_T){0}; // Initialize the structure as empty
      pthread_cond_signal(&(list->cond_empty));
      pthread_mutex_unlock(&(list->lock));
   }
