```cpp
#include <list>
#include <memory>
#include <mutex>
#include <vector>

class NFAPI_CRC_INDICATION_PDU_T {
public:
    int RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    bool CRCFLAG;

    // Add more fields as needed
};

class UEArray {
private:
    std::list<std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T>> data;
    const int MAX_UE = 2048;
    std::mutex readMutex;
    std::mutex writeMutex;

public:
    UEArray() {
        for (int i = 0; i < MAX_UE; ++i) {
            data.emplace_back(std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T>(new NFAPI_CRC_INDICATION_PDU_T()));
        }
    }

    void setCRCFlag(int index, bool value) {
        std::unique_lock<std::mutex> writeLock(writeMutex);
        data[index]->CRCFLAG = value;
    }

    const NFAPI_CRC_INDICATION_PDU_T* getUEInfo(int index) const {
        std::unique_lock<std::mutex> readLock(readMutex);
        return data[index].get();
    }

    int findUEByTag(int tag) const {
        for (size_t i = 0; i < data.size(); ++i) {
            if (data[i]->RX_UE_INFORMATION_TAG == tag) {
                return static_cast<int>(i);
            }
        }
        return -1; // UE not found
    }

    void resize(int newSize) {
        std::unique_lock<std::mutex> writeLock(writeMutex);
        if (newSize > MAX_UE) {
            throw std::runtime_error("Array cannot be resized above maximum capacity.");
        }
        for (size_t i = data.size(); i < newSize; ++i) {
            data.emplace_back(std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T>(new NFAPI_CRC_INDICATION_PDU_T()));
        }
        MAX_UE = newSize;
    }
};
```

