typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

// External data source interface
typedef void* EXTERNAL_DATA_SOURCE;
typedef int (*EXTERNAL_GET_CONFIG)(EXTERNAL_DATA_SOURCE, int*, int*);
typedef int (*EXTERNAL_INITIALIZE)(EXTERNAL_DATA_SOURCE*);
typedef void (*EXTERNAL_TERMINATE)(EXTERNAL_DATA_SOURCE);

// Function prototypes for logging and monitoring
void log(int level, const char* message);
void monitor(const char* message);

NFAPI_CRC_INDICATION_PDU_T* create_pdus(EXTERNAL_DATA_SOURCE* data_source) {
    EXTERNAL_INITIALIZE init = (EXTERNAL_INITIALIZE)dlsym(RTLD_DEFAULT, "external_initialize");
    EXTERNAL_GET_CONFIG get_config = (EXTERNAL_GET_CONFIG)dlsym(RTLD_DEFAULT, "external_get_config");
    EXTERNAL_TERMINATE terminate = (EXTERNAL_TERMINATE)dlsym(RTLD_DEFAULT, "external_terminate");

    if (!init || !get_config || !termsitate) {
        log(ERROR, "Failed to initialize external data source");
        return NULL;
    }

    EXTERNAL_DATA_SOURCE src = NULL;
    int max_rnti, bitfield_size;
    if (init(&src) < 0) {
        log(ERROR, "Failed to initialize external data source");
        goto cleanup;
    }

    int attempts = 0;
    while (1) {
        if (get_config(src, &max_rnti, &bitfield_size) < 0) {
            if (attempts >= MAX_ATTEMPTS) {
                log(ERROR, "Failed to retrieve configuration parameters from external data source");
                goto cleanup;
            }
            monitor("Retrying to get configuration parameters...");
            sleep(RETRY_INTERVAL);
            attempts++;
            continue;
        }
        break;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdus = malloc(max_rnti * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        log(ERROR, "Failed to allocate memory for PDUs");
        goto cleanup;
    }

    uint32_t assigned_rntis[max_rnti] = {0};
    uint32_t bitfield = 1;
    for (size_t i = 0; i < max_rnti; ++i) {
        // Find an available RNTI index
        while (assigned_rntis[bitfield - 1]) {
            bitfield++;
            if (bitfield > (1 << bitfield_size)) {
                log(ERROR, "Requested number of structures exceeds available system resources");
                goto cleanup;
            }
        }

        pdus[i].tag = INVALID_TAG;
        pdus[i].rnti = (RNTI)bitfield - 1;
        assigned_rntis[(pdus[i].rnti)] = 1;

        pdus[i].crc_indication.crcflag = (bitfield & (1 << (bitfield % bitfield_size))) ? 1 : 0;
        bitfield++;
    }

cleanup:
    if (src) terminate(src);
    return pdus;
}
