typedef struct _DynamicValueGenerator {
    float currentMinValue;
    float currentMaxValue;

    void SetBounds(float min, float max) {
        if (min > max) {
            this->currentMinValue = max;
            this->currentMaxValue = min;
        } else {
            this->currentMinValue = min;
            this->currentMaxValue = max;
        }
    }

    float GenerateRandomFloat(float min, float max) {
        SetBounds(min, max);
        return (this->currentMinValue + ((rand() / (RAND_MAX / (max - min))) * (max - this->currentMinValue)) + this->currentMinValue);
    }

    int GenerateRandomInt(int min, int max) {
        SetBounds(min, max);
        return (this->currentMinValue + ((rand() / (RAND_MAX / (max - min))) * (max - this->currentMinValue)) + this->currentMinValue);
    }

    const char* ToString() {
        return (std::to_string(currentMinValue) + " -> " + std::to_string(currentMaxValue));
    }
