#include <iostream>
#include <random>
#include <boost/circular_buffer.hpp>
#include <boost/asio/steady_timer.hpp>
#include <boost/lockfree/slist.hpp>
#include <boost/atomic.hpp>
#include <boost/log/trivial.hpp>

struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
};

class CRCList {
public:
    explicit CRCList(size_t capacity) : buffer_(capacity), list_(), free_list_(), log_buffer_(1024), timer_(io_service_) {}

    void push(const NFAPI_CRC_INDICATION_PDU_T& data);

private:
    boost::circular_buffer<NFAPI_CRC_INDICATION_PDU_T> buffer_;
    boost::lockfree::slist_base_hookless_policy<NFAPI_CRC_INDICATION_PDU_T> list_;
    boost::lockfree::slist<boost::lockfree::slist_base<NFAPI_CRC_INDICATION_PDU_T>> free_list_;
    boost::circular_buffer<char> log_buffer_;
    boost::asio::io_service io_service_;
    boost::asio::steady_timer timer_;

    bool add_to_buffer(NFAPI_CRC_INDICATION_PDU_T& data);
};

bool CRCList::add_to_buffer(NFAPI_CRC_INDICATION_PDU_T& data) {
    boost::lock guard(mutex_);

    if (list_.empty() || list_.back().rnti != data.rnti) {
        data.crc_indication.crcflag = rand();
        boost::log::trivial::info("Adding structure with RNTI {} to the list", data.rnti);
        list_.push_back(data);
        return true;
    }

    return false;
}

void CRCList::push(const NFAPI_CRC_INDICATION_PDU_T& data) {
    bool inserted = add_to_buffer(data);

    if (!inserted) {
        // Remove the least recently used structure from the free list and try again.
        NFAPI_CRC_INDICATION_PDU_T leastRecentlyUsed;
        if (free_list_.pop_front(leastRecentlyUsed)) {
            boost::log::trivial::info("Reusing structure with RNTI {} from the free list", leastRecentlyUsed.rnti);
            if (add_to_buffer(leastRecentlyUsed)) {
                // Copy and update data before returning.
                data = leastRecentlyUsed;
            }
        }
    }

    // Maintain running checksum of all CRCFLAG values.
    boost::atomic<uint32_t> checksum(0);
    BOOST_LOCK_Guard<boost::mutex> guard(mutex_);
    if (inserted) {
        checksum += data.crc_indication.crcflag;
    } else {
        checksum -= leastRecentlyUsed.crc_indication.crcflag;
        checksum += data.crc_indication.crcflag;
    }
}
