#include <pthread.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

#define MAX_UES (your_max_ues)
typedef struct _NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

struct list_node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct list_node* next;
};

struct dynamic_list {
    struct list_node* head;
    struct list_node* tail;
    size_t num_elements;
    pthread_mutex_t lock;
};

static void init_dynamic_list(struct dynamic_list *list) {
    list->head = NULL;
    list->tail = NULL;
    list->num_elements = 0;
    pthread_mutex_init(&list->lock, NULL);
}

static struct list_node* create_node(const NFAPI_CRC_INDICATION_PDU_T *data) {
    struct list_node *new_node = malloc(sizeof(struct list_node));
    if (!new_node) return NULL;
    new_node->data = *data;
    new_node->next = NULL;
    return new_node;
}

static void add_to_list(struct dynamic_list *list, struct list_node *node) {
    pthread_mutex_lock(&list->lock);
    if (list->num_elements < MAX_UES) {
        if (!list->head) {
            list->head = node;
            list->tail = node;
        } else {
            list->tail->next = node;
            list->tail = node;
        }
        list->num_elements++;
    }
    pthread_mutex_unlock(&list->lock);
}

static bool remove_from_list(struct dynamic_list *list, uint32_t rnti) {
    pthread_mutex_lock(&list->lock);
    struct list_node* current = list->head;
    if (!current) {
        pthread_mutex_unlock(&list->lock);
        return false;
    }

    while (current != NULL) {
        if (current->data.rnti == rnti) {
            if (current == list->head) {
                list->head = current->next;
            }
            if (current == list->tail) {
                list->tail = current->next;
            }
            free(current);
            list->num_elements--;
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return true;
}

static void randomize_crcflag(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pdu->crc_indication.crcFlag = rand() % 2;
}

void manage_dynamic_list(struct dynamic_list *list, const RX_UE_INFORMATION_TAG* tag, uint32_t rnti) {
    NFAPI_CRC_INDICATION_PDU_T new_pdu = { *tag, rnti, { .crcFlag = 0 } };
    randomize_crcflag(&new_pdu.crc_indication);

    struct list_node* new_node = create_node(&new_pdu);
    if (!new_node) return;

    pthread_mutex_lock(&list->lock);
    if (list->num_elements < MAX_UES) {
        add_to_list(list, new_node);
    } else {
        free(new_node);
        pthread_mutex_unlock(&list->lock);
    }
    pthread_mutex_unlock(&list->lock);
}
