public:
    DynamicValueGenerator(float min = 0.0f, float max = 1.0f) : currentMinValue(min), currentMaxValue(max) {}

    float GenerateRandomFloat(float min, float max) {
        if (currentMinValue > currentMaxValue || min > currentMaxValue || min < currentMinValue)
            throw std::invalid_argument("Invalid range bounds.");
        float range = currentMaxValue - currentMinValue;
        return currentMinValue + (static_cast<float>(rand()) / RAND_MAX * range);
