#include "log_library.h" // External logging library header

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct list_node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct list_node *next;
    pthread_mutex_t lock; // Thread-safe access lock
} list_node_t;

struct dynamic_list {
    list_node_t* head;
    size_t length;
    uint32_t running_checksum;
};

// Custom memory manager for efficient allocation and deallocation of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* mem_alloc(size_t num) {
    NFAPI_CRC_INDICATION_PDU_T* data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!data) return NULL;

    for (size_t i = 0; i < num; ++i) {
        data[i].crc_indication.crcflag = rand();
    }

    return data;
}

void mem_free(NFAPI_CRC_INDICATION_PDU_T* data, size_t num) {
    free(data);
}

// Initialize and clean up the dynamic list
void init_list(struct dynamic_list* list) {
    list->head = NULL;
    list->length = 0;
    list->running_checksum = 0;
}

void destroy_list(struct dynamic_list* list) {
    list_node_t *current, *next;

    pthread_mutex_lock(&list->head->lock);
    current = list->head;
    next = current->next;
    while (next != NULL) {
        free(current);
        current = next;
        next = current->next;
    }
    free(current);
    pthread_mutex_unlock(&list->head->lock);
}

void push_to_list(struct dynamic_list* list, NFAPI_CRC_INDICATION_PDU_T data) {
    list_node_t *new_node;

    new_node = (list_node_t*)malloc(sizeof(list_node_t));
    if (!new_node) return; // Failed to allocate memory, attempt to reclaim resources

    new_node->data = data;
    new_node->next = NULL;
    pthread_mutex_init(&new_node->lock, NULL);

    pthread_mutex_lock(&list->head->lock);
    if (!list->length) { // Empty list
        list->head = new_node;
    } else {
        list_node_t *last = list->head;
        while (last->next != NULL) last = last->next;
        last->next = new_node;
    }

    // Check for consecutive RNTIs and update the running checksum
    list_node_t* current = list->head;
    size_t consecutive = 0;
    while (current != NULL) {
        if (current->data.rnti == data.rnti) {
            consecutive++;
            if (consecutive > 1) break; // Found two consecutive structures with the same RNTI, fail the push operation
        } else {
            consecutive = 0;
        }
        current = current->next;
    }
    if (!current) return; // Failed to find a non-matching RNTI, append the new structure and update the running checksum

    list->length++;
    list->running_checksum += data.crc_indication.crcflag;
    log_timestamped("Add NFAPI_CRC_INDICATION_PDU_T to dynamic list");
    pthread_mutex_unlock(&list->head->lock);
}

bool validate_list(struct dynamic_list* list) {
    if (list->length == 0) return true;

    size_t checksum = 0;
    list_node_t* current = list->head;
    while (current != NULL) {
        checksum += current->data.crc_indication.crcflag;
        current = current->next;
    }

    return checksum == list->running_checksum;
}

// Batch processing API, supporting multiple additions and validation with error handling for partial failures
bool process_batch(struct dynamic_list* list, NFAPI_CRC_INDICATION_PDU_T* batch, size_t num_batch) {
    bool success = true;
    for (size_t i = 0; i < num_batch; ++i) {
        if (!push_to_list(list, batch[i])) { // If push_to_list fails due to RNTI collisions or memory issues, set success to false and continue processing the rest of the batch
            success = false;
            continue;
        }
    }

    if (success) {
        if (!validate_list(list)) return false; // If the list is invalid after processing the entire batch, indicate failure

        size_t checksum = 0;
        list_node_t* current = list->head;
        while (current != NULL) {
            checksum += current->data.crc_indication.crcflag;
            current = current->next;
        }

        if (checksum == list->running_checksum) { // If the list is valid and has the correct running checksum, indicate success
            return true;
        }
