#define RNTI_MAX    1000000

static pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
static NFAPI_CRC_INDICATION_PDU_T* list = NULL;
static size_t capacity = 0, used = 0;

void* create_element() {
    NFAPI_CRC_INDICATION_PDU_T* element = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!element) return NULL;

    element->RNTI = rand() % (RNTI_MAX - RNTI_MIN + 1) + RNTI_MIN;
    element->CRC_INDICATION_REL8_TAG = rand() & 0xFFF;
    return element;
}

int dynamic_list_init(size_t n) {
    if (n > MAX_MEMORY / sizeof(NFAPI_CRC_INDICATION_PDU_T)) return -1; // Memory check

    list = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) return -1; // Allocation failure

    capacity = n;
    used = 0;
    return 0;
}

int dynamic_list_push(const NFAPI_CRC_INDICATION_PDU_T* element) {
    pthread_mutex_lock(&list_mutex);
    if (used >= capacity) {
        free(list);
        list = realloc(list, ++capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!list) { // Reallocation failure
            pthread_mutex_unlock(&list_mutex);
            return -1;
        }
    }

    list[used] = *element;
    used++;
    pthread_mutex_unlock(&list_mutex);
    return 0;
}

int dynamic_list_pop(NFAPI_CRC_INDICATION_PDU_T* element) {
    pthread_mutex_lock(&list_mutex);
    if (used == 0) {
        pthread_mutex_unlock(&list_mutex);
        return -1; // List empty
    }

    *element = list[0];
    memmove(list, list + 1, --used * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    used--;
    pthread_mutex_unlock(&list_mutex);
    return 0;
}
