    struct node *next;
} Node;

typedef struct {
    Node* head;
    size_t capacity;
    size_t count;
    pthread_rwlock_t lock;
    // Add error codes or return values as needed
} RX_PDU_QUEUE;

RX_PDU_QUEUE* create_rx_pdu_queue(size_t initial_capacity) {
    if (initial_capacity < 1 || initial_capacity > 1024) {
        fprintf(stderr, "Invalid capacity for RX PDU queue.\n");
        return NULL;
    }

    RX_PDU_QUEUE* queue = malloc(sizeof(RX_PDU_QUEUE));
    if (!queue) {
        perror("Malloc failed.");
        return NULL;
    }

    queue->head = NULL;
    queue->capacity = initial_capacity;
    queue->count = 0;
    pthread_rwlock_init(&queue->lock, NULL);

    return queue;
}

void destroy_rx_pdu_queue(RX_PDU_QUEUE* queue) {
    if (!queue) return;

    Node *current = queue->head, *next;
    while (current) {
        next = current->next;
        free(current);
        current = next;
    }

    pthread_rwlock_destroy(&queue->lock);
    free(queue);
}

