#include <memory>
#include <mutex>
#include <vector>

class MemoryPool {
public:
    virtual std::unique_ptr<LTE_DL_FRAME_TRANSPORT_CONTEXT_T> allocate() = 0;
    virtual void deallocate(std::unique_ptr<LTE_DL_FRAME_TRANSPORT_CONTEXT_T>&) = 0;
};

class DynamicArray {
private:
    std::vector<LTE_DL_FRAME_TRANSPORT_CONTEXT_T> data;
    std::mutex mtx;
    MemoryPool& memoryPool;

public:
    explicit DynamicArray(MemoryPool& pool) : memoryPool(pool) {}

    void insert(const LTE_DL_FRAME_TRANSPORT_CONTEXT_T& context) {
        std::unique_ptr<LTE_DL_FRAME_TRANSPORT_CONTEXT_T> newContext = memoryPool.allocate();
        std::lock_guard<std::mutex> lock(mtx);
        *newContext = context;
        data.push_back(std::move(newContext));
    }

    LTE_DL_FRAME_TRANSPORT_CONTEXT_T* find(int cellId) {
        std::lock_guard<std::mutex> lock(mtx);
        for (auto& context : data) {
            if (context.cellId == cellId)
                return &context;
        }
        return nullptr;
    }

    void remove(int cellId) {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = std::remove_if(data.begin(), data.end(),
                                [cellId](const LTE_DL_FRAME_TRANSPORT_CONTEXT_T& context) {
                                    return context.cellId == cellId;
                                });
        data.erase(it, data.end());
    }
};
```

