typedef struct {
    pcap_t *handle;
    char *buffer;
    size_t buffer_size;
    void (*process)(u_char *, const struct pcap_pkthdr *, const u_int8_t *);
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} pcap_context;

void init_pcap(pcap_context *ctx, const char *device, void (*process)(u_char *, const struct pcap_pkthdr *, const u_int8_t *)) {
    ctx->handle = pcap_open_live(device, 65536, 1, 1000, NULL, errbuf);
    if (!ctx->handle) {
        fprintf(stderr, "Failed to open device %s: %s\n", device, errbuf);
        exit(EXIT_FAILURE);
    }

    ctx->buffer = mmap(NULL, 4096, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (!ctx->buffer) {
        perror("mmap failure");
        exit(EXIT_FAILURE);
    }

    ctx->buffer_size = 4096;
    ctx->process = process;

    pthread_mutex_init(&ctx->mutex, NULL);
    pthread_cond_init(&ctx->cond, NULL);
}

void stop_pcap(pcap_context *ctx) {
    pcap_breakloop(ctx->handle, 1);
    munmap(ctx->buffer, ctx->buffer_size);
    pcap_close(ctx->handle);
    pthread_mutex_destroy(&ctx->mutex);
    pthread_cond_destroy(&ctx->cond);
}

void packet_handler(u_char *user, const struct pcap_pkthdr *h, const u_int8_t *packet) {
    pcap_context *ctx = (pcap_context *)user;

    pthread_mutex_lock(&ctx->mutex);
    if (ctx->process) ctx->process(packet, *h, user);
    pthread_mutex_unlock(&ctx->mutex);
}

void start_capture(pcap_context *ctx) {
    ctx->handle->datalink = DLT_EN10MB;
    ctx->handle->snaplen = 65535;
    ctx->handle->promisc = 1;

    if (pcap_loop(ctx->handle, -1, &packet_handler, ctx) < 0) {
        perror("pcap_loop failure");
        exit(EXIT_FAILURE);
    }
}

// External data processing service integration
void process_packet(u_char *packet, const struct pcap_pkthdr *h, const u_int8_t *user) {
    // ... Code for real-time analysis of packet metadata ...
}
