        *list = (MAC_CONTEXT_T*)malloc(sizeof(MAC_CONTEXT_T));
        init_mac_context(*list, config);
        return 1;
    }

    MAC_CONTEXT_T** new_list = realloc(*list, sizeof(MAC_CONTEXT_T) * ((*list - list[0]) + 2));
    if (!new_list) {
        fprintf(stderr, "Failed to allocate memory for expanded MAC context list\n");
        return 0;
    }

    init_mac_context(new_list[(*list - list[0]) + 1], config);
