void remove_mac_context(MAC_CONTEXT_T** list, int index) {
    if (index >= (*list - list[0])) {
        fprintf(stderr, "Invalid MAC context index\n");
        return;
    }

    MAC_CONTEXT_T* temp = (*list + index);
    memmove(temp, temp + 1, sizeof(MAC_CONTEXT_T) * ((*list - list[0]) - index));
    free(*(list + (*list - list[0])));
    *list = realloc(*list, sizeof(MAC_CONTEXT_T) * ((*list - list[0]) - 1));
}

