#include <arpa/inet.h>
#include <netdb.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct nic {
    in_addr_t ip;
    in_addr_t netmask;
    in_addr_t gateway;
    int* ports;
    size_t port_count;
} NIC;

NIC* create_nic(const char* ip, const char* netmask, const char* gateway, size_t port_count) {
    // Validate IP addresses and ensure they are in a valid format.
    struct in_addr addr;
    if (inet_pton(AF_INET, ip, &addr) <= 0 ||
        inet_pton(AF_INET, netmask, &addr) <= 0 ||
        inet_pton(AF_INET, gateway, &addr) <= 0) {
        perror("Invalid IP address or netmask");
        return NULL;
    }

    NIC* nic = malloc(sizeof(NIC));
    if (!nic) {
        perror("Memory allocation failure");
        return NULL;
    }

    memset(nic, 0, sizeof(NIC));
    nic->ip = addr.s_addr;
    nic->netmask = addr.s_addr;
    nic->gateway = addr.s_addr;
    nic->port_count = port_count;

    // Allocate memory for the active ports list.
    nic->ports = malloc(sizeof(int) * nic->port_count);
    if (!nic->ports) {
        perror("Memory allocation failure");
        free(nic);
        return NULL;
    }

    return nic;
}

void destroy_nic(NIC* nic) {
    if (nic && nic->ports) {
        free(nic->ports);
        free(nic);
    }
}

