typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_tag;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* allocate_NFAPI_CRC_INDICATION_PDUs(size_t N) {
    if (N <= 0) {
        return NULL;
    }

    size_t structure_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    size_t total_bytes = N * structure_size;

    NFAPI_CRC_INDICATION_PDU_T* pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(total_bytes);

    if (!pdus) {
        return NULL;
    }

    time_t current_time = time(NULL);
    srandom(current_time);

    for (size_t i = 0; i < N; ++i) {
        pdus[i].tag.CRCFLAG = random();
        pdus[i].rnti.CRCFLAG = random();
        pdus[i].crc_indication_tag.CRCFLAG = random();
    }

    // Validate the integrity of each structure and memory alignment
    for (size_t i = 0; i < N; ++i) {
        if (!aligned(pdus + i, sizeof(NFAPI_CRC_INDICATION_PDU_T))) {
            free(pdus);
            return NULL;
        }

        // Add validation checks for other fields here
    }

    return pdus;
}

// Helper function to check if a given pointer is properly aligned for the requested size.
bool aligned(const void* ptr, size_t alignment) {
    return (((size_t)ptr & (alignment - 1)) == 0);
}
