typedef struct {
    time_t timestamp;
    char *metric_name;
    double value;
    int source_id;
} NetworkMetricData;

struct SourceData {
    FILE *file;
    csv_parser_t *csv;
    json_object *json;
};

struct ProcessorConfig {
    int sampling_rate;
    double threshold;
    int max_threads;
};

void process_source(struct SourceData *src, NetworkMetricData **data, struct ProcessorConfig *config) {
    while (1) {
        time_t current_time = time(NULL);

        if (current_time - src->timestamp > config->sampling_rate) {
            src->timestamp = current_time;

            if (src->csv != NULL) {
                csv_row_t *row;
                while ((row = csv_get_row(src->csv))) {
                    if (!validate_csv_row(row)) continue;

                    NetworkMetricData *nd = malloc(sizeof(NetworkMetricData));
                    nd->timestamp = src->timestamp;
                    nd->metric_name = strdup(row->fields[0]);
                    nd->value = atof(row->fields[1]);
                    nd->source_id = src->source_id;

                    pthread_mutex_lock(&data_mutex);
                    data[pthread_self()] = nd;
                    pthread_mutex_unlock(&data_mutex);
                }
            } else if (src->json != NULL) {
                json_object *obj;
                while ((obj = json_tokener_parse_ex(src->json, &src->json))) {
                    if (!validate_json_object(obj)) continue;

                    NetworkMetricData *nd = malloc(sizeof(NetworkMetricData));
                    nd->timestamp = src->timestamp;
                    nd->metric_name = json_object_get_string(json_object_dereference(obj)->key);
                    nd->value = json_object_get_double(obj);
                    nd->source_id = src->source_id;

                    pthread_mutex_lock(&data_mutex);
                    data[pthread_id] = nd;
                    pthread_mutex_unlock(&data_mutex);
                }
            }
        }

        if (getrusage(RUSAGE_SELF, &ru).ru_maxrss > config->threshold) {
            usleep(config->sampling_rate * 1000000);
        }
    }
}

NetworkMetricData** processNetworkMetrics(const char *csv_files[], const char *json_files[], struct ProcessorConfig config) {
    NetworkMetricData **data = malloc(config.max_threads * sizeof(NetworkMetricData*));
    pthread_mutex_init(&data_mutex, NULL);

    struct SourceData sources[array_size(csv_files) + array_size(json_files)];
    for (int i = 0; i < array_size(csv_files); i++) {
        sources[i].file = fopen(csv_files[i], "r");
        sources[i].csv = csv_parser_new();
        sources[i].source_id = i;
    }
    for (int i = array_size(csv_files); i < array_size(sources); i++) {
        json_object *obj = json_tokener_parse(json_files[i - array_size(csv_files)]);
        sources[i].json = obj;
        sources[i].source_id = i;
    }

    pthread_t threads[config.max_threads];
    for (int i = 0; i < config.max_threads; i++) {
        pthread_create(&threads[i], NULL, process_source, &sources[i], &data[i], &config);
    }

    for (int i = 0; i < config.max_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    return data;
}
