#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct LTE_RRC_CU_UP_CONFIG {
    // Define your structure here, for example:
    int param1;
    int param2;
    // ... other parameters
} LTE_RRC_CU_UP_CONFIG;

struct dynamic_array {
    LTE_RRC_CU_UP_CONFIG* data;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
};

void da_init(struct dynamic_array* array, size_t initial_capacity) {
    array->data = malloc(initial_capacity * sizeof(LTE_RRC_CU_UP_CONFIG));
    if (!array->data) {
        fprintf(stderr, "Failed to allocate memory\n");
        exit(EXIT_FAILURE);
    }

    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);
}

void da_destroy(struct dynamic_array* array) {
    free(array->data);
    pthread_mutex_destroy(&array->mutex);
}

void da_resize(struct dynamic_array* array, size_t new_capacity) {
    LTE_RRC_CU_UP_CONFIG* temp = malloc(new_capacity * sizeof(LTE_RRC_CU_UP_CONFIG));
    if (!temp) {
        fprintf(stderr, "Failed to allocate memory\n");
        exit(EXIT_FAILURE);
    }

    memcpy(temp, array->data, array->size * sizeof(LTE_RRC_CU_UP_CONFIG));
    free(array->data);

    array->data = temp;
    array->capacity = new_capacity;
}

bool da_add(struct dynamic_array* array, const LTE_RRC_CU_UP_CONFIG* config) {
    // Validate the configuration parameters here and return false if invalid

    pthread_mutex_lock(&array->mutex);

    if (array->size == array->capacity) {
        da_resize(array, array->capacity * 2);
    }

    memcpy((void*)&array->data[array->size], config, sizeof(LTE_RRC_CU_UP_CONFIG));
    array->size++;

    pthread_mutex_unlock(&array->mutex);
    return true;
}

bool da_update(struct dynamic_array* array, size_t index, const LTE_RRC_CU_UP_CONFIG* config) {
    // Validate the index and configuration parameters here and return false if invalid

    pthread_mutex_lock(&array->mutex);

    if (index >= array->size || index < 0) {
        pthread_mutex_unlock(&array->mutex);
        return false;
    }

    memcpy((void*)&array->data[index], config, sizeof(LTE_RRC_CU_UP_CONFIG));

    pthread_mutex_unlock(&array->mutex);
    return true;
}

size_t da_remove(struct dynamic_array* array, size_t index) {
    // Validate the index here and return -1 if invalid

    pthread_mutex_lock(&array->mutex);

    if (index >= array->size || index < 0) {
        pthread_mutex_unlock(&array->mutex);
        return -1;
    }

    memmove(array->data + index, array->data + index + 1, --array->size - index);

    pthread_mutex_unlock(&array->mutex);
    return 0;
}
