fn read_config<S>(path: &str) -> Result<Config, Box<dyn std::error::Error>>
where S: AsRef<str> + std::fmt::Display {
    let ext = path.extension().and_then(AsRef::as_ref);
    match ext {
        Some("json") => {
            let file = File::open(path).map_err(|e| e.into())?;
            let reader = BufReader::new(file);
            let config: serde_json::Value = serde_json::from_reader(reader)?;
            Ok(Config::Json(config))
        }
        Some("yaml") => {
            let file = File::open(path).map_err(|e| e.into())?;
            let reader = BufReader::new(file);
            let config: serde_yaml::Value = serd_yaml::from_reader(reader)?;
            Ok(Config::Yaml(config))
        }
        _ => Err("Invalid configuration file format.".into()),
    }
}
