class MemoryPool {
public:
    virtual std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T> allocate() = 0;
    virtual void deallocate(std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T>& pdu) = 0;
};

class Allocator : public MemoryPool {
private:
    std::unordered_map<uint64_t, std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T>> pool;
    size_t currentSize;

public:
    Allocator(size_t maxAllocations) : currentSize(0) {
        // Initialize maxAllocations allocations from the memory pool
    }

    std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T> allocate() override {
        if (pool.empty() && currentSize < maxAllocations) {
            auto pdu = std::make_unique<NFAPI_CRC_INDICATION_PDU_T>();
            // Initialize PDUs here
            pool[currentSize++] = std::move(pdu);
            return pdu;
        } else if (!pool.empty()) {
            auto it = pool.begin();
            currentSize--;
            return it->second;
        }
        return nullptr; // No available allocations, handle error gracefully
    }

    void deallocate(std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T>& pdu) override {
        if (pool.find(currentSize - 1) != pool.end()) {
            pool[currentSize - 1] = std::move(pdu);
        } else {
            // Log error: Deallocating PDUs out of order or when the maximum number of allocations is reached
        }
    }
};

std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T> createPDU(MemoryPool& pool) {
