    if (pdu != nullptr) {
        pdu->RX_UE_INFORMATION_TAG = config.tags[randomEngine() % config.tags.size()];
        pdu->RNTI = randomEngine() % (config.maxRNTI - config.minRNTI + 1) + config.minRNTI; // RNTI is in the range [minRNTI, maxRNTI]
        pdu->CRCFLAG = config.crcflagProbability > randomEngine() / static_cast<double>(RAND_MAX);
    }

    return pdu;
}
