#define MAX_STRUCTURES 128
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static int num_structures = 0, max_concurrent = 4;
static NFAPI_CRC_INDICATION_PDU_T *structures;
static int fd = -1;
static char *persist_buf;

void cleanup() {
    if (fd != -1) close(fd);
    if (persist_buf) munmap(persist_buf, 4096);
    free(structures);
}

void on_exit(void (*func)(void), void *arg) {
    struct sigaction sa;

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = func;
    sa.sa_flags = SA_ONSTACK | SA_RESTART;
    if (sigaction(SIGTERM, &sa, NULL) == -1 || sigaction(SIGHUP, &sa, NULL) == -1) {
        perror("Failed to set up on_exit handler");
        exit(EXIT_FAILURE);
    }
}

void log_state() {
    struct stat st;
    char buf[4096];

    if (stat(persist_buf, &st) == -1) {
        perror("Failed to get persist file status");
        return;
    }

    snprintf(buf, sizeof(buf), "Num structures: %d\nMax concurrent: %d\n", num_structures, max_concurrent);
    write(fd, buf, strlen(buf));
}

NFAPI_CRC_INDICATION_PDU_T *allocate() {
    NFAPI_CRC_INDICATION_PDU_T *p;
    size_t size = sizeof(NFAPI_CRC_INDICATION_PDU_T);

    pthread_mutex_lock(&mutex);
    if (num_structures + 1 > max_concurrent) {
        pthread_mutex_unlock(&mutex);
        return NULL;
    }
    p = realloc(structures, sizeof(NFAPI_CRC_INDICATION_PDU_T) * ++num_structures);
    if (!p) {
        pthread_mutex_unlock(&mutex);
        perror("Failed to allocate memory");
        return NULL;
    }
    structures[num_structures - 1].tag = RX_UE_INFORMATION_TAG_INVALID;
    structures[num_structures - 1].rnti = RNTI_INVALID;
    structures[num_structures - 1].crcflag = (uint8_t)rand();
    pthread_mutex_unlock(&mutex);
    return &structures[num_structures - 1];
}

void deallocate(NFAPI_CRC_INDICATION_PDU_T *p) {
    if (!p || num_structures == 0) return;
    pthread_mutex_lock(&mutex);
    --num_structures;
    structures = realloc(structures, sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_structures);
    if (!structures) {
        pthread_mutex_unlock(&mutex);
        perror("Failed to deallocate memory");
        return;
    }
    structures[num_structures].tag = RX_UE_INFORMATION_TAG_INVALID;
    structures[num_structures].rnti = RNTI_INVALID;
    pthread_mutex_unlock(&mutex);
}

void init() {
    if ((fd = open("state.txt", O_WRONLY | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR)) == -1) {
        perror("Failed to open state file");
        exit(EXIT_FAILURE);
    }
    persist_buf = mmap(NULL, 4096, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (persist_buf == MAP_FAILED) {
        perror("Failed to allocate persist buffer");
        exit(EXIT_FAILURE);
    }
    signal(SIGTERM, cleanup);
    signal(SIGHUP, cleanup);
}
