#include <arpa/inet.h>
#include <pthread.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <sys/socket.h>
#include <time.h>

typedef struct Connection {
    int socket_fd;
    sockaddr_in addr;
    pthread_t thread_id;
    time_t last_active;
} Connection;

struct ConnManager {
    Connection** connections;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
    int timeout_sec;
};

Connection* connection_new(int socket_fd, const sockaddr_in* addr) {
    Connection* conn = malloc(sizeof(Connection));
    if (!conn) {
        perror("malloc");
        return nullptr;
    }

    conn->socket_fd = socket_fd;
    memcpy(&conn->addr, addr, sizeof(sockaddr_in));
    conn->thread_id = 0;
    conn->last_active = time(NULL);

    return conn;
}

void connection_delete(Connection** conn) {
    free(*conn);
    *conn = nullptr;
}

bool connection_get_addr(const Connection* conn, sockaddr_in* out_addr) {
    if (out_addr) {
        memcpy(out_addr, &conn->addr, sizeof(sockaddr_in));
    }
    return true;
}

int connection_get_socket_fd(const Connection* conn) {
    return conn->socket_fd;
}

void connd_manager_init(ConnManager* manager, size_t capacity, int timeout_sec) {
    manager->connections = calloc(capacity, sizeof(Connection*));
    if (!manager->connections) {
        perror("calloc");
        exit(EXIT_FAILURE);
    }
    manager->capacity = capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->mutex, nullptr);
    manager->timeout_sec = timeout_sec;
}

void connd_manager_deinit(ConnManager* manager) {
    for (size_t i = 0; i < manager->capacity; ++i) {
        Connection* conn = manager->connections[i];
        if (conn) {
            connection_delete(&conn);
        }
    }
    pthread_mutex_destroy(&manager->mutex);
}

void connd_manager_add(ConnManager* manager, const Connection* conn) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->count < manager->capacity) {
        size_t i;
        for (i = 0; i < manager->count; ++i) {
            if (!manager->connections[i]) {
                manager->connections[i] = conn;
                break;
            }
        }
        if (i == manager->count) {
            manager->connections[manager->count++] = conn;
        }
    }
    pthread_mutex_unlock(&manager->mutex);
}

bool connd_manager_remove(ConnManager* manager, int socket_fd) {
    Connection** itr = manager->connections;
    for (size_t i = 0; i < manager->count; ++i, ++itr) {
        if ((*itr)->socket_fd == socket_fd) {
            connection_delete(itr);
            memmove(*itr, *(itr + 1), (manager->count - i - 1) * sizeof(Connection*));
            manager->count--;
            break;
        }
    }
    return false; // Not found
}

bool connd_manager_remove_by_addr(ConnManager* manager, const sockaddr_in* addr) {
    Connection** itr = manager->connections;
    for (size_t i = 0; i < manager->count; ++i, ++itr) {
        if (connection_get_addr(*itr, addr)) {
            connection_delete(itr);
            memmove(*itr, *(itr + 1), (manager->count - i - 1) * sizeof(Connection*));
            manager->count--;
            break;
        }
    }
    return false; // Not found
}

size_t connd_manager_get_active_count(const ConnManager* manager) {
    size_t count = 0;
    for (size_t i = 0; i < manager->count; ++i) {
        time_t current_time = time(NULL);
        if (difftime(current_time, manager->connections[i]->last_active) < manager->timeout_sec) {
            ++count;
        }
    }
    return count;
}

void connd_manager_cleanup(ConnManager* manager) {
    // Implement a cleanup mechanism here to remove inactive connections.
}
```

