typedef struct {
    sem_t mutex;
    size_t capacity;
    size_t head;
    size_t tail;
    LTE_DL_FRAME_TRANSPORT_CONTEXT *buffer;
} FrameBuffer;

FrameBuffer *frame_buffer;
unsigned int last_processed_frame;

void init_frame(LTE_DL_FRAME_TRANSPORT_CONTEXT *frame) {
    frame->frame_number = last_processed_frame++;
    frame->srs.rc_factor = rand() % 16 + 2; // Generate random SRS configuration
}

void populate_buffer(size_t count) {
    for (size_t i = 0; i < count; ++i) {
        LTE_DL_FRAME_TRANSPORT_CONTEXT *frame = &frame_buffer[frame_buffer->head];
        sem_wait(&frame_buffer->mutex);
        if (frame_buffer->capacity == (frame_buffer->head + 1) % frame_buffer->capacity) {
            // Buffer is full, expand it
            LTE_DL_FRAME_TRANSPORT_CONTEXT *new_buffer = realloc(frame_buffer->buffer, sizeof(LTE_DL_FRAME_TRANSPORT_CONTEXT) * (2 * frame_buffer->capacity));
            if (!new_buffer) {
                fprintf(stderr, "Error: Out of memory\n");
                exit(1);
            }
            frame_buffer->buffer = new_buffer;
            frame_buffer->capacity *= 2;
        }
        init_frame(frame);
        frame_buffer->head = (frame_buffer->head + 1) % frame_buffer->capacity;
        sem_post(&frame_buffer->mutex);
    }
}

void process_frames() {
