            LTE_DL_FRAME_TRANSPORT_CONTEXT *new_buffer = realloc(frame_buffer->buffer, sizeof(LTE_DL_FRAME_TRANSPORT_CONTEXT) * (2 * frame_buffer->capacity));
            if (!new_buffer) {
