typedef struct {
    Node* head;
    int size;
    int capacity;
    pthread_mutex_t lock;
    logging_function log;
} List;

void list_init(List* list, logging_function log) {
    list->head = NULL;
    list->size = 0;
    list->capacity = 10000;
    list->log = log;
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);
    list->lock = lock;
}

void* node_mempool = malloc(sizeof(Node) * 10000);

int is_unique(List* list, RNTI rnti) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->rnti == rnti) {
            return false;
        }
        current = current->next;
    }
    return true;
}

void push(List* list, const NFAPI_CRC_INDICATION_PDU_T *pdu) {
    Node* newNode = (Node*)(node_mempool + list->size);

    // Initialize the new node with given values
    newNode->tag = pdu->rxUEInfo.ueIdentity.ueIdentity_rni;
    newNode->rnti = pdu->rnTI;
    newNode->crc_indication = pdu->crcIndication;
    newNode->crcflag = (bool)(rand() % 2);
    newNode->next = NULL;

    if (!is_unique(list, newNode->rnti)) {
        list->log("Error: Duplicate RNTI encountered.");
        return;
    }

    pthread_mutex_lock(&list->lock);
    if (list->size == list->capacity) {
        // Resize the memory pool if it's full
        Node* newPool = malloc(sizeof(Node) * list->capacity * 2);
        memcpy(newPool, node_mempool, sizeof(Node) * list->size);
        free(node_mempool);
        node_mempool = newPool;
    }
    newNode->next = list->head;
    list->head = newNode;
    list->size++;
    pthread_mutex_unlock(&list->lock);
}

void list_destroy(List* list) {
    pthread_mutex_destroy(&list->lock);
    free(node_mempool);
}
