typedef struct pdsch_entry {
    uint16_t rrc_conn_id;
    // PDSCH transmission settings...
} pdsch_entry;

typedef struct buffer {
    pdsch_entry* entries;
    size_t capacity;
    size_t count;
    sem_t mutex;
    sem_t not_full;
    sem_t not_empty;
} buffer;

buffer* init_buffer(size_t initial_capacity) {
    buffer* buf = (buffer*) malloc(sizeof(buffer));
    buf->entries = (pdsch_entry*) calloc(initial_capacity, sizeof(pdsch_entry));
    buf->capacity = initial_capacity;
    buf->count = 0;
    sem_init(&buf->mutex, 0, 1);
    sem_init(&buf->not_full, 0, initial_capacity);
    sem_init(&buf->not_empty, 0, 0);
    return buf;
}

void enqueue(buffer* buf, const pdsch_entry entry) {
    sem_wait(&buf->not_full);
    sem_wait(&buf->mutex);

    if (buf->count == buf->capacity) {
        // Resize buffer if necessary
        pdsch_entry* temp = realloc(buf->entries, buf->capacity * 2 * sizeof(pdsch_entry));
        if (!temp) {
            fprintf(stderr, "Error resizing buffer\n");
            sem_post(&buf->mutex);
            return;
        }
        buf->entries = temp;
        buf->capacity *= 2;
    }

    buf->entries[buf->count] = entry;
    ++(buf->count);
    sem_post(&buf->not_empty);
    sem_post(&buf->mutex);
}

pdsch_entry dequeue(buffer* buf) {
    pdsch_entry ret_val;
    sem_wait(&buf->not_empty);
    sem_wait(&buf->mutex);

    if (buf->count == 0) {
        sem_post(&buf->mutex);
        return (pdsch_entry) { .rrc_conn_id = 0, /* placeholders for transmission settings */ };
    }

    ret_val = buf->entries[0];
