            usleep(1000 * i++); // Introduce delay to simulate varying loads and network jitter
        }
        return NULL;
    }

    pthread_t threads[1000]; // Initialize thread array with maximum capacity for concurrent operations

    for (int i = 0; i < 1000; ++i) {
