    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
} Node;

static const int MAX_STRUCTURES = 10000;
static Node *head = NULL, **tail = &head;
static pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;
static int error_code = 0;

void add_to_list(NFAPI_CRC_INDICATION_PDU_T data) {
    if (error_code != 0) return;

    pthread_mutex_lock(&list_lock);
    Node *new_node = malloc(sizeof(Node));
    if (!new_node) {
        error_code = MEMORY_ALLOCATION_FAILURE;
        pthread_mutex_unlock(&list_lock);
        return;
    }

    new_node->data = data;
    new_node->next = NULL;
    if (*tail) (*tail)->next = new_node;
    else head = new_node;
    *tail = &new_node->next;
    pthread_mutex_unlock(&list_lock);
}

NFAPI_CRC_INDICATION_PDU_T get_from_list() {
    pthread_mutex_lock(&list_lock);
    Node *temp = head;
    if (head) head = head->next;
    else *tail = NULL;
    NFAPI_CRC_INDICATION_PDU_T data = temp->data;
    free(temp);
    pthread_mutex_unlock(&list_lock);
    return data;
}

void handle_RSSI(int rssi) {
    pthread_mutex_lock(&list_lock);
    Node *current = head;
    while (current != NULL) {
        if (rssi > MINIMUM_THRESHOLD)
            current->data.crc_indication.CRCFLAG = true;
        else
            current->data.crc_indication.CRCFLAG = false;
        current = current->next;
    }
    pthread_mutex_unlock(&list_lock);
}
