typedef struct TrafficFlow {
    struct in_addr sourceIP;
    struct in_addr destinationIP;
    unsigned int packetCount;
} TrafficFlow;

struct TrafficData {
    TrafficFlow *trafficFlows;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
};

static void initTrafficData(struct TrafficData *td, size_t initialCapacity) {
    td->capacity = initialCapacity;
    td->size = 0;
    td->trafficFlows = calloc(initialCapacity, sizeof(TrafficFlow));
    pthread_mutex_init(&td->mutex, NULL);
}

static TrafficData* createTrafficData() {
    size_t initialCapacity = 16;
    struct TrafficData *td = malloc(sizeof(struct TrafficData));
    initTrafficData(td, initialCapacity);
    return td;
}

static void resizeTrafficFlows(struct TrafficData *td) {
    size_t newCapacity = td->capacity * 2;
    TrafficFlow *newTrafficFlows = realloc(td->trafficFlows, newCapacity * sizeof(TrafficFlow));
    if (!newTrafficFlows) {
        perror("realloc failed");
        return;
    }
    td->capacity = newCapacity;
    td->trafficFlows = newTrafficFlows;
}

static TrafficFlow* findOrAddTrafficFlow(struct TrafficData *td, const struct in_addr sourceIP, const struct in_addr destinationIP) {
    pthread_mutex_lock(&td->mutex);
    for (size_t i = 0; i < td->size; ++i) {
        if (!memcmp(&td->trafficFlows[i].sourceIP, &sourceIP, sizeof(struct in_addr)) && !memcmp(&td->trafficFlows[i].destinationIP, &destinationIP, sizeof(struct in_addr))) {
            pthread_mutex_unlock(&td->mutex);
            return &td->trafficFlows[i];
        }
    }

    if (td->size == td->capacity) {
        resizeTrafficFlows(td);
    }

    TrafficFlow *tf = &td->trafficFlows[td->size++];
    tf->sourceIP = sourceIP;
    tf->destinationIP = destinationIP;
    tf->packetCount = 0;

    pthread_mutex_unlock(&td->mutex);
    return tf;
}

static void incrementPacketCount(TrafficFlow *tf) {
    ++tf->packetCount;
}

void addOrUpdateTrafficFlow(struct TrafficData *td, const struct in_addr sourceIP, const struct in_addr destinationIP, unsigned int packetCount) {
    if (!validIP(sourceIP) || !validIP(destinationIP)) {
        return;
    }

    pthread_mutex_lock(&td->mutex);
    TrafficFlow *tf = findOrAddTrafficFlow(td, sourceIP, destinationIP);
    incrementPacketCount(tf);
    pthread_mutex_unlock(&td->mutex);
}

unsigned int getTotalPacketsBySourceIP(const struct TrafficData *td, const struct in_addr sourceIP) {
    unsigned int total = 0;
    for (size_t i = 0; i < td->size; ++i) {
        if (!memcmp(&td->trafficFlows[i].sourceIP, &sourceIP, sizeof(struct in_addr))) {
            total += td->trafficFlows[i].packetCount;
        }
    }
    return total;
}
