#include <stdio.h>
#include <stdlib.h>
#include <sys/ioctl.h>
#include <ifaddrs.h>
#include <pthread.h>
#include <sys/mman.h>

typedef struct {
    char ifname[IF_NAMESIZE];
    uint64_t rx_bytes;
    uint64_t tx_bytes;
    pthread_mutex_t lock;
} nic_stat;

struct ifaddrs *ifa_list = NULL;
size_t ifa_max = 0;

void init_nica() {
    if (getifaddrs(&ifa_list) == -1) {
        perror("getifaddrs");
        exit(EXIT_FAILURE);
    }

    ifa_max = IF_NAMESIZE * sizeof(nic_stat);
    nic_stat *nica = mmap(NULL, ifa_max, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (nica == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }

    for (struct ifaddrs *ifa = ifa_list; ifa != NULL; ifa = ifa->ifa_next) {
        nic_stat *nic = &nica[ifa - ifa_list];
        strncpy(nic->ifname, ifa->ifa_name, IF_NAMESIZE);
        nic->rx_bytes = 0;
        nic->tx_bytes = 0;
        pthread_mutex_init(&nic->lock, NULL);
    }
}

void free_nica() {
    munmap(nica, ifa_max);
    freeifaddrs(ifa_list);
}

uint64_t get_rx_bytes(const char *iface) {
    for (size_t i = 0; i < ifa_max; ++i) {
        if (strcmp(iface, ((nic_stat*)(&nica[i]))->ifname) == 0) {
            pthread_mutex_lock(&((nic_stat*)(&nica[i])->lock));
            uint64_t rx = ((nic_stat*)(&nica[i]))->rx_bytes;
            pthread_mutex_unlock(&((nic_stat*)(&nica[i])->lock));
            return rx;
        }
    }
    return 0;
}

void inc_rx_bytes(const char *iface, uint64_t bytes) {
    for (size_t i = 0; i < ifa_max; ++i) {
        if (strcmp(iface, ((nic_stat*)(&nica[i]))->ifname) == 0) {
            pthread_mutex_lock(&((nic_stat*)(&nica[i])->lock));
            ((nic_stat*)(&nica[i]))->rx_bytes += bytes;
            pthread_mutex_unlock(&((nic_stat*)(&nica[i])->lock));
            break;
        }
    }
}
