#include <time.h>

typedef enum {
    IPV4,
    IPV6
} address_type_t;

struct hostname {
    char name[256];
    u_char ip_address[16];
};

struct cache_entry {
    struct hostname key;
    u_char value[16];
    time_t expiration_time;
    pthread_mutex_t lock;
};

const int CACHE_SIZE = 1024;
const int LOGGING_LEVEL = 3; // Logging levels: 0 (none), 1 (error only), 2 (warnings and errors), 3 (verbose)
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;
struct cache_entry *cache;

int get_ip(const char *hostname, u_char *ip_address) {
    struct hostent *host_info;
    struct addrinfo hints, *res;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;

    int error = getaddrinfo(hostname, NULL, &hints, &res);
    if (error) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(error));
        return -1;
    }

    address_type_t address_type = res->ai_family == AF_INET ? IPV4 : IPV6;
    void *address_ptr;

    if (res->ai_addrlen > sizeof(*ip_address)) { // Handle IPv6 addresses
        memcpy(ip_address, &((struct sockaddr_in6 *)res->ai_addr)->sin6_addr, 16);
    } else { // Handle IPv4 addresses
        memcpy(ip_address, &((struct sockaddr_in *)res->ai_addr)->sin_addr, 4);
    }

    freeaddrinfo(res);

    if (LOGGING_LEVEL >= 3) {
        printf("Resolved %s to IP: %s\n", hostname, inet_ntoa(*((struct sockaddr_in *)res->ai_addr)));
    }

    // Cache resolution results for a specified period
    cache_and_return(hostname, ip_address);

    return 0;
}

void cache_and_return(const char *hostname, u_char *ip_address) {
    pthread_mutex_lock(&cache_lock);

    // Search for an existing entry in the cache
    int index = hash(hostname) % CACHE_SIZE;
    for (int i = index; i < CACHE_SIZE; ++i) {
        if (!cache[i].key.name || strcmp(cache[i].key.name, hostname)) continue;

        pthread_mutex_lock(&cache[i].lock);
        if (time(NULL) <= cache[i].expiration_time) {
            memcpy(ip_address, cache[i].value, 16);
            pthread_mutex_unlock(&cache[i].lock);
            pthread_mutex_unlock(&cache_lock);
            return;
        }
        pthread_mutex_unlock(&cache[i].lock);
    }

    // Create a new cache entry if not found
    int index = hash(hostname) % CACHE_SIZE;
    for (int i = index; i < CACHE_SIZE; ++i) {
        if (!cache[i].key.name) {
            strcpy(cache[i].key.name, hostname);
            memcpy(cache[i].value, ip_address, 16);
            cache[i].expiration_time = time(NULL) + 60; // Cache duration is 1 minute
            pthread_mutex_init(&cache[i].lock, NULL);
            pthread_mutex_unlock(&cache_lock);
            return;
        }
    }

    // Extend the cache if it's full
    if (CACHE_SIZE == cache_size) {
        struct cache_entry *new_cache = realloc(cache, 2 * CACHE_SIZE);
        if (!new_cache) {
            perror("realloc");
            pthread_mutex_unlock(&cache_lock);
            return;
        }
        memset(new_cache + CACHE_SIZE, 0, CACHE_SIZE * sizeof(*new_cache));
        cache = new_cache;
        CACHE_SIZE *= 2;
    }

    // Create a new cache entry if not found and the cache is not full
    int index = hash(hostname) % CACHE_SIZE;
    struct cache_entry *new_entry = &cache[index];
    strcpy(new_entry->key.name, hostname);
    memcpy(new_entry->value, ip_address, 16);
    new_entry->expiration_time = time(NULL) + 60; // Cache duration is 1 minute
    pthread_mutex_init(&new_entry->lock, NULL);
    pthread_mutex_unlock(&cache_lock);
}

int hash(const char *str) {
    unsigned long hash = 5381;
    int c;

    while ((c = *str++))
        hash = (hash << 5) + hash + c; /* hash * 33 + c */

    return hash % CACHE_SIZE;
}

