// Profile structure
struct UserProfile {
    std::string name;
    std::string email;
    std::string address;
};

// Thread-safe container for profiles
class ProfilesContainer {
private:
    std::map<std::string, std::unique_ptr<UserProfile>> profiles;
    pthread_mutex_t lock;

public:
    // Get profile by key (email) or create a new one if not found.
    UserProfile* getOrCreateProfile(const std::string& email) {
        pthread_mutex_lock(&this->lock);

        auto it = this->profiles.find(email);
        if (it != this->profiles.end()) {
            UserProfile* profile = it->second.get();
            pthread_mutex_unlock(&this->lock);
            return profile;
        }

        // Create new user profile and add to the container
        auto new_profile = std::make_unique<UserProfile>();
        this->profiles[email] = std::move(new_profile);
        UserProfile* profile = this->profiles[email].get();

        pthread_mutex_unlock(&this->lock);
        return profile;
    }
};
