struct LinkedList {
    size_t size;
    size_t max_size;
    Node* head;
    sem_t lock;
    pthread_mutexattr_t attr;
};

void init_list(struct LinkedList* list, size_t max_size) {
    list->max_size = max_size;
    list->head = NULL;
    list->size = 0;
    sem_init(&list->lock, 0, 1);
    pthread_mutexattr_init(&list->attr);
}

void destroy_list(struct LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    sem_destroy(&list->lock);
    pthread_mutexattr_destroy(&list->attr);
}

void add_to_list(struct LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->attr);
    if (list->size >= list->max_size) {
        printf("Memory limit exceeded\n");
        pthread_mutex_unlock(&list->attr);
        return;
    }

    Node* newNode = malloc(sizeof(Node));
    if (!newNode) {
        printf("Allocation failure\n");
        pthread_mutex_unlock(&list->attr);
        return;
    }

    newNode->data = data;
    newNode->next = list->head;
    list->head = newNode;
    list->size++;
    pthread_mutex_unlock(&list->attr);
