class PDUSync {
private:
    std::vector<NFAPI_CRC_INDICATION_PDU_T> pdus;
    std::mutex mutex;
    pthread_cond_t cond;
    int numAllocated = 0;
    static bool logEnabled;
    static boost::circular_buffer<std::string> logs;

public:
    PDUSync() {
        srand(time(NULL));
        pdus.resize(MAX_PDU_COUNT);
        for (auto& pdu : pdus) {
            pdu.crc_indication.crcflag = rand() % 2;
        }
