        std::unique_lock<std::mutex> lock(mutex);
        pthread_cond_wait(&cond, &mutex.native_handle());
        if (numAllocated >= MAX_PDU_COUNT) {
            throw std::runtime_error("Max PDU count reached");
        }
        int index = numAllocated++;
        lock.unlock();
        return &pdus[index];
    }

