                array[i].RX_UE_INFORMATION_TAG = (i + 1) % 0xFFFFFFFF; // Validating RX_UE_INFORMATION_TAG integrity
                array[i].RNTI = new_RNTI;
                array[i].CRC_INDICATION_REL8_TAG = rand() % 2;
            }
        } while (found_match);
    }
}
