#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define NFAPI_CRCI_PDU_SIZE 1024 /* Size of each structure in bytes */

typedef struct NFAPI_CRCI_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint64_t RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRCI_PDU_T;

typedef struct NODE {
    NFAPI_CRCI_PDU_T data;
    struct NODE *next;
} NODE;

/* Memory pool for efficient allocation and deallocation */
NODE *memory_pool = NULL;
size_t num_nodes_in_pool = 0;
const size_t max_pool_size = 1024;

/* Custom logging function with timestamp */
void log(char *message) {
    time_t t;
    struct tm *tm;
    char buffer[80];

    time(&t);
    tm = localtime(&t);

    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(stderr, "[%s] : %s\n", buffer, message);
}

/* Custom allocator to handle memory pool */
NODE* custom_malloc(size_t size) {
    if (num_nodes_in_pool > 0 && num_nodes_in_pool < max_pool_size) {
        log("Reusing node from pool");
        NODE *temp = memory_pool;
        memory_pool = memory_pool->next;
        num_nodes_in_pool--;
        return temp;
    }
    return malloc(size);
}

/* Custom deallocator to handle memory pool */
void custom_free(void *ptr) {
    if (ptr != NULL) {
        log("Returning node to pool");
        NODE *node = (NODE*) ptr;
        node->next = memory_pool;
        memory_pool = node;
        num_nodes_in_pool++;
    }
}

/* Function to create and populate array of structures */
void* create_array(size_t size) {
    NODE **array = (NODE**) malloc(sizeof(NODE*) * size);

    if (!array) {
        log("Out of memory, exiting gracefully");
        for (int i = 0; i < size; i++) {
            custom_free(array[i]);
        }
        free(array);
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < size; i++) {
        array[i] = custom_malloc(sizeof(NFAPI_CRCI_PDU_T));
        if (!array[i]) {
            log("Out of memory, exiting gracefully");
            for (size_t j = 0; j <= i; j++) {
                custom_free(array[j]);
            }
            free(array);
            exit(EXIT_FAILURE);
        }
        memset(array[i], 0, sizeof(NFAPI_CRCI_PDU_T));
    }

    return array;
}

/* Cleanup function to deallocate memory on exit */
void cleanup() {
    for (int i = 0; i < num_nodes_in_pool; i++) {
        custom_free(memory_pool);
    }
    free(memory_pool);
}
```

