#define MAX_PACKETS 10000

DataPacket* createDynamicArray() {
    DataPacket* array = (DataPacket*)malloc(MAX_PACKETS * sizeof(DataPacket));
    if (!array) {
        perror("Memory allocation failed");
        return NULL;
    }

    for (size_t i = 0; i < MAX_PACKETS; ++i) {
        array[i].packetID = i + 1;
        array[i].payloadLength = rand() % 100 + 1;
        array[i].payload = malloc(array[i].payloadLength);
        if (!array[i].payload) {
            perror("Memory allocation failed for payload");
            return NULL;
        }
        memset(array[i].payload, rand() % 256, array[i].payloadLength);
        array[i].timestamp = time(NULL);
    }

    return array;
}

DataPacket* findPacketsInTimeRange(DataPacket* packets, time_t startTime, time_t endTime) {
    size_t count = 0;
    for (size_t i = 0; i < MAX_PACKETS; ++i) {
        if (packets[i].timestamp >= startTime && packets[i].timestamp <= endTime) {
            ++count;
        }
    }

    if (!count) return NULL;

    size_t index = 0;
    DataPacket* result = malloc(count * sizeof(DataPacket));
    for (size_t i = 0; i < MAX_PACKETS; ++i) {
        if (packets[i].timestamp >= startTime && packets[i].timestamp <= endTime) {
            result[index++] = packets[i];
        }
    }
    return result;
}

void destroyDynamicArray(DataPacket* array) {
    if (!array) return;

    for (size_t i = 0; i < MAX_PACKETS; ++i) {
        free(array[i].payload);
    }
    free(array);
}
