    ctx->lte_ue_identity = identity;
    ctx->rrc_conn_info = conn_info;
    ctx->results = NULL;
    ctx->capacity = 0;
    ctx->size = 0;
    ctx->retention_policy = time(NULL) - CONFIG_RETENTION_POLICY_DURATION;
    pthread_mutex_init(&ctx->results_lock, NULL);
}

void add_measurement_result(lte_ue_context *ctx, time_t timestamp, int signal_strength) {
    measurement_result *new_res = malloc(sizeof(measurement_result));
    new_res->timestamp = timestamp;
    new_res->signal_strength = signal_strength;

    pthread_mutex_lock(&ctx->results_lock);
    if (ctx->size == ctx->capacity) {
        ctx->capacity *= 2;
        ctx->results = realloc(ctx->results, sizeof(measurement_result *) * ctx->capacity);
    }
    ctx->results[ctx->size] = new_res;
    ctx->size++;
    pthread_mutex_unlock(&ctx->results_lock);
}

void update_measurement_result(lte_ue_context *ctx, size_t index, time_t timestamp, int signal_strength) {
    pthread_mutex_lock(&ctx->results_lock);
    if (index < ctx->size && index >= 0) {
        ctx->results[index]->timestamp = timestamp;
        ctx->results[index]->signal_strength = signal_strength;
    }
    pthread_mutex_unlock(&ctx->results_lock);
}

void remove_outdated_measurements(lte_ue_context *ctx) {
    pthread_mutex_lock(&ctx->results_lock);
    for (size_t i = 0; i < ctx->size; ++i) {
        if (ctx->results[i]->timestamp < ctx->retention_policy) {
            measurement_result *temp = ctx->results[i];
            for (size_t j = i + 1; j < ctx->size; ++j) {
                ctx->results[j - 1] = ctx->results[j];
            }
            free(ctx->results[--ctx->size]);
        }
    }
    pthread_mutex_unlock(&ctx->results_lock);
}

