} NFAPI_CRC_INDICATION_PDU_T;

static NFAPI_CRC_INDICATION_PDU_T* data = NULL;
static size_t capacity = 0;
static size_t size = 0;
static pthread_rwlock_t rwlock;

void init_data() {
    if (data != NULL) return;
    capacity = getpagesize() - 1; // Align to page boundary
    capacity = (MAX_ENTRIES > capacity ? MAX_ENTRIES : capacity);
    data = mmap(NULL, capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (data == MAP_FAILED) {
        fprintf(stderr, "Error: mmap failed\n");
        exit(EXIT_FAILURE);
    }
    size = capacity;
    pthread_rwlock_init(&rwlock, NULL);
}

void destroy_data() {
    if (munmap(data, capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T)) == -1) {
        fprintf(stderr, "Error: munmap failed\n");
        exit(EXIT_FAILURE);
    }
    data = NULL;
    size = 0;
    pthread_rwlock_destroy(&rwlock);
}

size_t get_size() {
    return size;
}

bool add_entry(const NFAPI_CRC_INDICATION_PDU_T* entry) {
    pthread_rwlock_wrlock(&rwlock);
    if (size >= capacity) {
        void* temp_data = realloc(data, (capacity << 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (temp_data == NULL) {
            pthread_rwlock_unlock(&rwlock);
            return false;
        }
        data = temp_data;
        capacity <<= 1;
    }
    data[size++] = *entry;
    pthread_rwlock_unlock(&rwlock);
    return true;
}
