    pthread_mutex_lock(&list_mutex);
    if (!head) {
        head = tail = new_node;
    } else {
        tail->next = new_node;
        tail = new_node;
    }
    num_nodes++;
    pthread_mutex_unlock(&list_mutex);
}

ListNode* remove_from_list(size_t index) {
    ListNode* current = head;
    ListNode* prev = NULL;
    size_t i = 0;

    if (!current || num_nodes == 0) return NULL;

    pthread_mutex_lock(&list_mutex);
    while (i < index && current != NULL) {
        prev = current;
        current = current->next;
        i++;
    }
    if (i != index || current == NULL) {
        pthread_mutex_unlock(&list_mutex);
        return NULL;
    }
    if (prev == NULL) {
        head = current->next;
    } else {
        prev->next = current->next;
    }
    ListNode* result = current;
    num_nodes--;
    pthread_mutex_unlock(&list_mutex);
    return result;
}

