NFAPI_CRC_INDICATION_PDU_T* read_and_allocate(const char *filename) {
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        perror("open");
        return NULL;
    }

    struct stat sb;
    if (fstat(fd, &sb) == -1) {
        perror("fstat");
        close(fd);
        return NULL;
    }

    size_t file_size = sb.st_size;
    void *mapped_file = mmap(NULL, file_size, PROT_READ, MAP_PRIVATE, fd, 0);
    if (mapped_file == MAP_FAILED) {
        perror("mmap");
        close(fd);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdus = calloc(MAX_ELEMENTS, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        perror("calloc");
        munmap(mapped_file, file_size);
        close(fd);
        return NULL;
    }

    const char *data = mapped_file;
    size_t counter = 0;
    for (size_t i = 0; i < file_size / sizeof(NFAPI_CRC_INDICATION_PDU_T); ++i) {
        if (!memcmp(data, &RX_UE_INFORMATION_TAG, sizeof(RX_UE_INFORMATION_TAG))) {
            memcpy(&pdus[counter], data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            counter++;
            data += sizeof(NFAPI_CRC_INDICATION_PDU_T);
        } else if (!memcmp(data, &CRC_INDICATION_REL8_TAG, sizeof(CRC_INDICATION_REL8_TAG))) {
            memcpy(&pdus[counter].crc_indication, data, sizeof(CRC_INDICATION_REL8_TAG));
            data += sizeof(CRC_INDICATION_REL8_TAG);
        } else if (!memcmp(data, &RNTI, sizeof(RNTI))) {
            memcpy(&pdus[counter].rnti, data, sizeof(RNTI));
            data += sizeof(RNTI);
        } else {
            fprintf(stderr, "Corrupted input data at offset: %zu\n", (size_t)(data - mapped_file));
            free(pdus);
            munmap(mapped_file, file_size);
            close(fd);
            return NULL;
        }
    }

    if ((size_t)(data - mapped_file) != file_size) {
        fprintf(stderr, "Corrupted input data at offset: %zu (expected: %zu)\n", (size_t)(data - mapped_file), file_size);
        free(pdus);
        munmap(mapped_file, file_size);
        close(fd);
        return NULL;
    }

    munmap(mapped_file, file_size);
    close(fd);

    // Replace corrupted CRC flags with random values based on predefined rules
    for (size_t i = 0; i < counter; ++i) {
        if (!(pdus[i].crcflag & pdus[i].crc_indication.CRCFLAG)) {
            pdus[i].crcflag |= pdus[i].crc_indication.CRCFLAG;
        }
    }

    return pdus;
}
