    if (fseek(file, 0, SEEK_END) || ftell(file) != bufferSize || (bytesRead = fread(buffer, 1, bufferSize, file)) != bufferSize) {
        fprintf(stderr, "Error reading file %s or file is corrupted.\n", filePath);
        isFileCorrupted = true;
    } else {
        fseek(file, 0, SEEK_SET); // Reset the file position to the beginning for future reads
    }

    if (isFileCorrupted) {
        fprintf(stderr, "Generating random CRC indications...\n");
        for (size_t i = 0; i < bufferSize; ++i) {
            ((uint8_t*)crcIndications)[i] = rand() % 256;
        }
    } else {
        // Copy data from the buffer into the CRC indications array and initialize CRC flags if needed
        memcpy(crcIndications, buffer, bufferSize);
        for (size_t i = 0; i < bufferSize; ++i) {
            if (((uint8_t*)crcIndications)[i] == CRASH_INDICATION) {
                ((uint8_t*)crcIndications)[i].crcFlag = rand() % 256;
            }
        }
    }

    // Compute and log the MD5 hash of the file path for debugging purposes (if not corrupted)
    if (!isFileCorrupted) {
        char md5Hash[33];
        MD5_Digest(&mdContext, (const unsigned char*)filePath, strlen(filePath));
        bzero(md5Hash, sizeof(md5Hash));
        for (int i = 0; i < 16; ++i) {
            sprintf(&md5Hash[i*2], "%02x", mdContext.digest[i]);
        }
        fprintf(stderr, "Computed MD5 hash of file: %s\n", md5Hash);
    }

    // Validate the array and return it if valid
    for (size_t i = 0; i < bufferSize; ++i) {
        if (!isValidCRCIndication((NFAPI_CRC_INDICATION_PDU_T*)&crcIndications[i])) {
            fprintf(stderr, "Invalid CRC indication at index %ld\n", i);
            free(crcIndications);
            free(buffer);
            return NULL;
        }
    }

    fclose(file); // Close the file after validation

    return crcIndications;
}

bool isValidCRCIndication(const NFAPI_CRC_INDICATION_PDU_T *indication) {
