} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    unsigned int max_sessions;
    unsigned int current_count;
    NFAPI_CRC_INDICATION_PDU_T **list;
    pthread_mutex_t list_lock;
    pthread_cond_t cond;
} UE_SESSION_MANAGER_T;

UE_SESSION_MANAGER_T *ue_session_manager_init(unsigned int max_sessions) {
    UE_SESSION_MANAGER_T *manager = malloc(sizeof(UE_SESSION_MANAGER_T));
    if (!manager) return NULL;

    manager->max_sessions = max_sessions;
    manager->current_count = 0;
    manager->list = calloc(max_sessions, sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!manager->list) {
        free(manager);
        return NULL;
    }

    pthread_mutex_init(&manager->list_lock, NULL);
    pthread_cond_init(&manager->cond, NULL);

    for (unsigned int i = 0; i < max_sessions; ++i) {
        manager->list[i] = calloc(1, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!manager->list[i]) {
            // Garbage collection here.
            ue_session_manager_cleanup(manager);
            return NULL;
        }
    }

    return manager;
}

void ue_session_manager_add(UE_SESSION_MANAGER_T *manager, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&manager->list_lock);

    for (unsigned int i = 0; i < manager->max_sessions; ++i) {
        if (!manager->list[i]) {
            manager->list[i] = pdu;
            manager->current_count++;
            pthread_mutex_unlock(&manager->list_lock);
            return;
        }
    }

    // Garbage collection here.
    ue_session_manager_cleanup(manager);
    manager->list[i % manager->max_sessions] = pdu;
    manager->current_count++;
    pthread_mutex_unlock(&manager->list_lock);
}

NFAPI_CRC_INDICATION_PDU_T *ue_session_manager_get(UE_SESSION_MANAGER_T *manager, RX_UE_INFORMATION_TAG tag) {
    pthread_mutex_lock(&manager->list_lock);

    for (unsigned int i = 0; i < manager->current_count; ++i) {
        if (manager->list[i]->tag == tag) {
            NFAPI_CRC_INDICATION_PDU_T *pdu = manager->list[i];
            pthread_mutex_unlock(&manager->list_lock);
            return pdu;
        }
    }

    pthread_mutex_unlock(&manager->list_lock);
    return NULL;
}

void ue_session_manager_cleanup(UE_SESSION_MANAGER_T *manager) {
    if (manager->current_count == 0) return;

    pthread_mutex_lock(&manager->list_lock);

    for (unsigned int i = 0; i < manager->max_sessions; ++i) {
        if (manager->list[i]) {
            free(manager->list[i]);
            manager->list[i] = NULL;
        }
    }

    manager->current_count = 0;

    pthread_mutex_unlock(&manager->list_lock);
}
```

