#include <memory>
#include <boost/asio.hpp>

struct CellularTrafficEvent {
    std::chrono::steady_clock::time_point timestamp;
    int cellId;
    int ueId;
    int packetSize;
};

class TrafficList {
public:
    void addEvent(const CellularTrafficEvent& event) {
        events_.emplace_back(event);
    }

    const std::vector<CellularTrafficEvent>& getEventsInRange(
            std::chrono::steady_clock::time_point startTime,
            std::chrono::steady_clock::time_point endTime) const {
        std::vector<CellularTrafficEvent> result;
        for (const auto& event : events_) {
            if (event.timestamp >= startTime && event.timestamp <= endTime) {
                result.push_back(event);
            }
        }
        return result;
    }

    void cleanup() {
        std::chrono::steady_clock::time_point now = std::chrono::steady_clock::now();
        auto it = events_.begin();
        while (it != events_.end()) {
            if ((now - it->timestamp) > 1min) {
                it = events_.erase(it);
            } else {
                ++it;
            }
        }
    }

private:
    std::vector<std::shared_ptr<CellularTrafficEvent>> events_;
};

class DataCenter {
public:
    DataCenter() : service_(io_) {}

    void start() {
        cleanupThread_ = std::thread(&DataCenter::cleanup, this);
        boost::asio::io_service::work work(io_);
        io_.run();
    }

    void stop() {
        io_.stop();
        cleanupThread_.join();
    }

private:
    void cleanup() {
        std::this_thread::sleep_for(1s); // Sleep for 1 second to allow other operations to run.
        trafficList_.cleanup();
    }

    boost::asio::io_service io_;
    TrafficList trafficList_;
    std::thread cleanupThread_;
};
