#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_LIST_SIZE 1000

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication_tag;
    time_t timestamp;
    struct Node *next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    int size;
    pthread_mutex_t mutex;
} List;

List* create_list() {
    List *list = malloc(sizeof(List));
    if (!list) {
        perror("Error allocating list");
        return NULL;
    }
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

Node* create_node(RX_UE_INFORMATION_TAG tag, uint32_t rnti, CRC_INDICATION_REL8_TAG crc_indication_tag) {
    Node *new_node = malloc(sizeof(Node));
    if (!new_node) {
        perror("Error allocating node");
        return NULL;
    }
    new_node->tag = tag;
    new_node->rnti = rnti;
    new_node->crc_indication_tag = crc_indication_tag;
    new_node->next = NULL;
    new_node->timestamp = time(NULL);
    return new_node;
}

void insert_node(List *list, Node *new_node) {
    pthread_mutex_lock(&list->mutex);
    if (list->head == NULL) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }
    list->size++;
    pthread_mutex_unlock(&list->mutex);
}

Node* remove_node(List *list, uint32_t rnti) {
    Node* current = list->head;
    Node* previous = NULL;

    pthread_mutex_lock(&list->mutex);
    while (current != NULL && current->rnti == rnti) {
        if (previous == NULL) {
            list->head = current->next;
        } else {
            previous->next = current->next;
        }
        Node* temp = current;
        current = current->next;
        free(temp);
        list->size--;
        pthread_mutex_unlock(&list->mutex);
        return current;
    }
    pthread_mutex_unlock(&list->mutex);
    return NULL;
}

void delete_list(List **list) {
    Node *current = (*list)->head;
    Node *next;

    if (!*list) return;

    pthread_mutex_destroy(&(*list)->mutex);
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    (*list)->head = NULL;
    (*list)->tail = NULL;
    (*list)->size = 0;
    free(*list);
    *list = NULL;
}
```
