            return NULL;
        }

        if (log_enabled) {
            pthread_mutex_lock(&log_mutex);
            // Write logging information here
            pthread_mutex_unlock(&log_mutex);
        }

        if (!head) {
            head = current;
            current->next = NULL;
        } else {
            current->next = NULL;
            current->prev = head;
            head = current;
        }
    }

    return head;
}

void clean_up(NFAPI_RX_FRAME_PDU_T *head) {
    if (!head) return;

    NFAPI_RX_FRAME_PDU_T *current = head;
    while (current != NULL) {
        NFAPI_RX_FRAME_PDU_T *temp = current->next;
        free(current->frame_data);
        free(current);
        current = temp;
    }
}
