typedef struct LTE_UE_Context {
    unsigned long UE_ID;
    sem_t channels_mutex;
    struct RLC_Channel* downlink_channels;
    struct Beamforming_Config config;
    pthread_mutex_t config_mutex;
} LTE_UE_Context;

typedef struct RLC_Channel {
    unsigned int channel_id;
    enum RLC_Status status;
    // Add other relevant fields here
} RLC_Channel;

struct Beamforming_Config {
    // Define your beamforming configuration structure here
};

sem_t contexts_mutex;
size_t num_contexts = 0;
LTE_UE_Context** contexts;

void init_UE_Contexts(size_t initial_capacity) {
    contexts = malloc(initial_capacity * sizeof(LTE_UE_Context*));
    sem_init(&contexts_mutex, 0, 1);
}

LTE_UE_Context* get_UE_Context_by_ID(unsigned long UE_ID) {
    sem_wait(&contexts_mutex);
    for (size_t i = 0; i < num_contexts; ++i) {
        if (contexts[i]->UE_ID == UE_ID) {
            sem_post(&contexts_mutex);
            return contexts[i];
        }
    }
    sem_post(&contexts_mutex);
    return NULL;
}

void add_UE_Context(LTE_UE_Context* context) {
    sem_wait(&contexts_mutex);
    context->channels_mutex = sem_init(0, 0, 1);
    context->config_mutex = PTHREAD_MUTEX_INITIALIZER;
    contexts = realloc(contexts, (num_contexts + 1) * sizeof(LTE_UE_Context*));
    contexts[num_contexts++] = context;
    sem_post(&contexts_mutex);
}

void remove_UE_Context(unsigned long UE_ID) {
    LTE_UE_Context* context = get_UE_Context_by_ID(UE_ID);
    if (!context) return;

    sem_wait(&contexts_mutex);
    size_t index = 0;
    for (; index < num_contexts; ++index) {
        if (contexts[index] == context) {
            break;
        }
    }

    if (index == num_contexts) {
        sem_post(&contexts_mutex);
        return;
    }

    memmove(contexts + index, contexts + index + 1, --num_contexts * sizeof(LTE_UE_Context*));
    free(context->downlink_channels);
    free(context);
    sem_post(&contexts_mutex);
}

void update_UE_Context(unsigned long UE_ID, void (*func)(LTE_UE_Context*)) {
    LTE_UE_Context* context = get_UE_Context_by_ID(UE_ID);
    if (!context) return;

    pthread_mutex_lock(&context->config_mutex);
    func(context);
    pthread_mutex_unlock(&context->config_mutex);
}

void apply_beamforming_adjustments() {
    sem_wait(&contexts_mutex);
    for (size_t i = 0; i < num_contexts; ++i) {
        // Apply periodic beamforming adjustments based on received downlink feedback
        LTE_UE_Context* context = contexts[i];
        sem_wait(&context->channels_mutex);
        // Iterate over all downlink channels and apply beamforming adjustments
        RLC_Channel* channel;
        sem_getprioce(&context->channels_mutex, &channel);
        while (channel != NULL) {
            // Apply periodic beamforming adjustments based on the channel's status
            // ...
            sem_getprioce(&context->channels_mutex, &channel);
        }
        sem_post(&context->channels_mutex);
    }
    sem_post(&contexts_mutex);
}
```

