    threadsafe_list_t* list = malloc(sizeof(threadsafe_list_t));
    if (!list) {
        perror("Memory Allocation Failure");
        return NULL;
    }

    list->head = NULL;
    list->tail = NULL;
    list->capacity = initial_capacity;
    list->size = 0;

    // Initialize mutex
    if (pthread_mutex_init(&list->mutex, NULL) != 0) {
        perror("Mutex Initialization Failure");
        free(list);
        return NULL;
    }

    return list;
}

int bulk_insert_frames(threadsafe_list_t* list, size_t num_frames, NFAPI_RX_FRAME_TAG* tags, uint64_t* rntis) {
    if (num_frames == 0) return SUCCESS;

    pthread_mutex_lock(&list->mutex);

    for (size_t i = 0; i < num_frames; ++i) {
        NFAPI_RX_FRAME_PDU_T* frame = malloc(sizeof(NFAPI_RX_FRAME_PDU_T));
        if (!frame) {
            pthread_mutex_unlock(&list->mutex);
            return MEMORY_ALLOCATION_FAILURE;
        }

        frame->tag = tags[i];
        frame->RNTI = rntis[i];
        frame->data = allocate_data_buffer(DEFAULT_BUFFER_SIZE); // Replace DEFAULT_BUFFER_SIZE with appropriate initial buffer size

        if (!frame->data) {
            free(frame);
            pthread_mutex_unlock(&list->mutex);
            return MEMORY_ALLOCATION_FAILURE;
        }

        if (list->size == list->capacity) {
            list->capacity *= GROW_FACTOR;
            resize_list(list);
        }

        // Append frame to the tail of the list
        if (list->head == NULL) {
            list->head = frame;
            list->tail = frame;
        } else {
            list->tail->next = frame;
            list->tail = frame;
        }

        ++(list->size);
    }

    pthread_mutex_unlock(&list->mutex);
    return SUCCESS;
}

