class FramePool {
private:
    std::list<NFAPI_TX_FRAME_PDU> frames_;
    std::mutex frames_mutex_;
    std::atomic_size_t next_id_{0};

    void initializeFrame(NFAPI_TX_FRAME_PDU& frame, size_t buffer_size) {
