        frame.rnti = 0; // Replace with actual RNTI initialization logic
        frame.buffer.reset(new uint8_t[buffer_size], [](uint8_t* ptr) { delete[] ptr; });
    }

public:
    FramePool(size_t buffer_size, bool use_ecc, bool priority, size_t pool_size) : frames_(pool_size), next_id_{0} {
        for (auto& frame : frames_)
            initializeFrame(frame, buffer_size);

        // Configure ECC and packet prioritization if needed
        // ...
    }

    NFAPI_TX_FRAME_PDU acquire() {
        std::lock_guard<std::mutex> lock(frames_mutex_);
        auto it = frames_.begin();
        if (it != frames_.end()) {
            auto frame = std::move(*it);
            frames_.erase(it);
            return frame;
        }

        // Allocate a new frame if the pool is empty
        NFAPI_TX_FRAME_PDU frame;
        initializeFrame(frame, /* buffer_size */);
        frames_.push_back(std::move(frame));
        return frame;
    }

    void release(NFAPI_TX_FRAME_PDU& frame) {
        std::lock_guard<std::mutex> lock(frames_mutex_);
        frames_.emplace_back(frame);
    }

