    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void destroy_list(List *list) {
    NFAPI_CRC_INDICATION_PDU_T *current, *next;
    pthread_mutex_lock(&list->mutex);
    current = list->head;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    list->size = 0;
    list->head = NULL;
    pthread_mutex_unlock(&list->mutex);
}

bool add_entry(List *list, const RX_UE_INFORMATION_TAG tag, uint32_t rnti, const CRC_INDICATION_REL8_TAG crc_indication, bool crcflag) {
