    new_entry->tag = tag;
    new_entry->rnti = rnti;
    new_entry->crc_indication = crc_indication;
    new_entry->crcflag = crcflag;
    new_entry->next = list->head;
    pthread_mutex_lock(&list->mutex);
    if (list->size == 0) {
        list->head = new_entry;
    } else {
        list->head = new_entry;
    }
    list->size++;
    compact_list(list);
    pthread_mutex_unlock(&list->mutex);
    return true;
}

