    pthread_mutex_lock(&list->mutex);
    current = list->head;
    while (current != NULL) {
        if (current->rnti == rnti) {
            if (current == list->head) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            list->size--;
            compact_list(list);
            break;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
}

void iterate_and_print(List *list) {
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        printf("Tag: %d, RNTI: %d, CRC_INDICATION: %d, CRCFLAG: %d\n", current->tag, current->rnti, current->crc_indication, current->crcflag);
        current = current->next;
    }
}

void compact_list(List *list) {
    NFAPI_CRC_INDICATION_PDU_T *current, *temp;
    pthread_mutex_lock(&list->mutex);
    current = list->head;
    while (current != NULL) {
        if (!current->crcflag) {
            temp = current;
            current = current->next;
            free(temp);
            list->size--;
        } else {
            current = current->next;
        }
    }
    pthread_mutex_unlock(&list->mutex);
}
