NFAPI_CRC_INDICATION_PDU_T* create_list(unsigned int seed, unsigned int size) {
    NFAPI_CRC_INDICATION_PDU_T* list = NULL;
    unsigned int i, j, array_size;
    pthread_mutex_t sync_mutex = PTHREAD_MUTEX_INITIALIZER;
    RNTI rntis[MAX_RNTIS] = {0}; // To store unique RNTIs and prevent duplicates
    unsigned int used_rntis = 0;

    // Validate input parameters and adjust array size if necessary
    if (size > MAX_ARRAY_SIZE) {
        fprintf(stderr, "Error: Requested array size exceeds system memory limits.\n");
        return NULL;
    }

    array_size = size * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(array_size);
