        fprintf(stderr, "Error: Failed to allocate memory for the array.\n");
        return NULL;
    }

    // Populate and validate the list
    for (i = 0; i < size; ++i) {
        pthread_mutex_lock(&sync_mutex);
        j = used_rntis;
        while (!is_valid_rnti(rntis[j]) && j < MAX_RNTIS) ++j;
        if (j == MAX_RNTIS) { // No valid RNTI found, reduce the array size and try again
            fprintf(stderr, "Error: Maximum RNTI capacity exceeded. Reducing array size.\n");
            free(list);
            size--;
            continue;
        }
        used_rntis[j] = 1;
        pthread_mutex_unlock(&sync_mutex);

        list[i].tag = i + 1; // Assign a unique tag value for each element
        list[i].rnti = rntis[j];
        list[i].crc_indication_tag = i % 256 + 1;
        list[i].crcflag = prng(seed); // Apply the pseudo-random number generator
    }

    // Verify integrity of allocated memory and ensure thread safety
    pthread_mutex_lock(&sync_mutex);
    if (used_rntis != size) {
        fprintf(stderr, "Error: Memory corruption detected during list population.\n");
        free(list);
        return NULL;
    }
    pthread_mutex_unlock(&sync_mutex);

    log_element(&list[0]); // Log the first element to indicate successful creation of the list
    return list;
}
