        $subAction = $data['sub_action'];
        unset($data['sub_action']);

        // Data validation
        if (!isset($data['id']) || !$data['name'] || !filter_var($data['email'], FILTER_VALIDATE_EMAIL) || !preg_match('/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]{8,}$/', $data['password'])) {
