        if (!in_array($data['role'], $allowedRoles)) {
            return json_encode(['message' => 'error', 'data' => []]);
        }

        $allowedStatuses = ['active', 'inactive'];
        if (!in_array($data['status'], $allowedStatuses)) {
            return json_encode(['message' => 'error', 'data' => []]);
        }

        // Concurrency handling
        $currentUser = $this->db->getRow('users', ['id' => $data['id']], ['timestamp']);
        if ($currentUser && time() - strtotime($currentUser['timestamp']) > 60) {
            $currentUser = $this->db->getRow('users', ['id' => $data['id']]);
            if (!$currentUser) {
