    pthread_mutex_init(&arrayMutex, NULL);

    // Allocate memory for initial array elements
    array = safe_malloc(MAX_ARRAY_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        // Handle error and clean up resources
    }

    // Periodically compact the array (e.g., every N insertions or M seconds)
    // Implement the compaction logic here, balancing between efficiency, memory usage, and lookup times

    // Function to add an element to the array
    void add_element(const NFAPI_CRC_INDICATION_PDU_T *newElement) {
        pthread_mutex_lock(&arrayMutex);

        // Check for duplicate RNTI, log error and skip if found
        for (size_t i = 0; i < arraySize; ++i) {
            if (array[i].rnti == newElement->rnti) {
                printf("Error: Duplicate RNTI detected!\n");
                pthread_mutex_unlock(&arrayMutex);
                continue;
            }
        }

        // Find an empty slot in the array and add the new element
        for (size_t i = 0; i < arraySize; ++i) {
            if (!array[i].tag) {
                array[i] = *newElement;
                break;
            }
        }

        // If no empty slot is found, reallocate the array and add the new element
        if (i == arraySize) {
            NFAPI_CRC_INDICATION_PDU_T *newArray = safe_realloc(array, (MAX_ARRAY_SIZE + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!newArray) {
                // Handle error and clean up resources
            }
            array = newArray;
            MAX_ARRAY_SIZE++;
            array[arraySize - 1] = *newElement;
        }

        arraySize++;
        pthread_mutex_unlock(&arrayMutex);
    }

    // Function to clear the array and release all allocated resources
    void clear_array(void) {
        pthread_mutex_lock(&arrayMutex);
        free(array);
        array = NULL;
        arraySize = 0;
        pthread_mutex_unlock(&arrayMutex);
    }
}
