    new_element->rnti = rnti;
    new_element->crcs = malloc(NUM_CRCS * sizeof(CRC_INDICATION_REL8_TAG)); // Adjust NUM_CRCS to the desired number of CRC indications
    new_element->num_crcs = 0;

    list->length++;
}

void removeElementByRnti(List* list, uint32_t rnti) {
    for (size_t i = 0; i < list->length; ++i) {
        if (list->elements[i].rnti == rnti) {
            // Shift all elements after the deleted one to fill the gap
            for (size_t j = i + 1; j < list->length; ++j) {
                list->elements[j - 1] = list->elements[j];
            }

            // Decrement the length and free the memory of the deleted element
            free(list->elements[list->length - 1].crcs);
            list->length--;
            break;
        }
    }
}

void updateCrcFlag(List* list, uint32_t rnti, bool new_crcflag) {
    for (size_t i = 0; i < list->length; ++i) {
        if (list->elements[i].rnti == rnti) {
            list->elements[i].crcs[list->elements[i].num_crcs].CRCFLAG = new_crcflag;
            break;
        }
    }
}
