    memset(*pdu_array, 0, MAX_PDUS * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Use a loop counter to maintain proper indexing and prevent concurrent access issues
