<?php

class ClinicUpdater {
    private $db;
    private $api;
    private $cache;
    private $logFile;
    private $cacheDuration = 60 * 60 * 24; // Cache for 1 day

    public function __construct($db, $api, $cache) {
        $this->db = $db;
        $this->api = $api;
        $this->cache = $cache;
        $this->logFile = "clinic_updates.log";
        $this->initLog();
    }

    private function initLog() {
        if (!file_exists($this->logFile)) {
            touch($this->logFile);
        }
    }

    public function updateClinics() {
        $cutoff = time() - 30 * 24 * 60 * 60; // 30 days ago timestamp
        $clinics = $this->db->getClinics('active', $cutoff);

        $successCount = 0;
        $failureCount = 0;
        $cacheMisses = 0;

        foreach ($clinics as $clinic) {
            if (!$this->canUpdate($clinic)) continue;

            try {
                $details = $this->api->getClinicDetails($clinic['id']);
                if (empty($details)) throw new Exception("API returned empty details for clinic ID {$clinic['id']}");

                $updated = false;

                // Compare updated fields with API response and update the database if necessary
                // ...

                if ($updated) {
                    $this->db->updateClinic($clinic['id'], $details);
                    $successCount++;
                    $this->logUpdateSuccess($clinic, $details);
                } else {
                    $cacheMisses++;
                }
            } catch (Exception $e) {
                if ($e->getCode() == 3) continue; // API request limit exceeded, retry after some delay
                $failureCount++;
                $this->logUpdateFailure($clinic, $e->getMessage());
            }
        }

        return "Updated {$successCount} clinics. Missed updates: {$cacheMisses}. Failed operations: {$failureCount}";
    }

    private function canUpdate(array $clinic) {
        if (!$this->cache->has($clinic['id'])) return true;

        $cacheData = $this->cache->get($clinic['id']);
        $cacheAge = time() - strtotime($cacheData['timestamp']);

        return ($cacheAge > $this->cacheDuration) || ($cacheAge <= $this->cacheDuration && mt_rand(0, 99) < 5); // 5% chance to update even if cache is fresh
    }

    private function logUpdateSuccess(array $clinic, array $details) {
        $logEntry = "{$time} - UPDATE - {$clinic['id']} - Success\n";
        $logEntry .= implode(", ", array_keys($clinic)) . ",";
        $logEntry .= implode(", ", array_values($details));
        $this->logToFile($logEntry);
    }

    private function logUpdateFailure(array $clinic, string $message) {
        $time = date("Y-m-d H:i:s");
        $logEntry = "{$time} - UPDATE - {$clinic['id']} - Failure (API Error: {$message})\n";
        $this->logToFile($logEntry);
    }

    private function logToFile($entry) {
        file_put_contents($this->logFile, $entry, FILE_APPEND | LOCK_EX);

        if (filesize($this->logFile) > 1048576) { // 1 MB
            rename($this->logFile, "clinic_updates_{$time}.log");
            $this->initLog();
        }
    }
}
