typedef struct _MEMORY_POOL_T {
    void* data;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
    semaphore_t sem;
} MEMORY_POOL_T;

void memory_pool_init(MEMORY_POOL_T* pool, size_t initial_size) {
    // Initialize pool with specified initial size
    pool->data = mmap(NULL, initial_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (pool->data == MAP_FAILED) {
        perror("mmap failed");
        exit(EXIT_FAILURE);
    }

    pool->size = initial_size;
    pool->capacity = initial_size;
    pthread_mutex_init(&pool->mutex, NULL);
    sem_init(&pool->sem, 0, pool->capacity);
}

void* memory_pool_alloc(MEMORY_POOL_T* pool) {
    void* ptr;

    pthread_mutex_lock(&pool->mutex);

    if (pool->size == pool->capacity) {
        sem_wait(&pool->sem);
    }

    ptr = pool->data + pool->size;
    pool->size += sizeof(NFAPI_CRC_INDICATION_PDU_T);

    pthread_mutex_unlock(&pool->mutex);

    return ptr;
}

void memory_pool_free(MEMORY_POOL_T* pool, void* ptr) {
    // Free the allocated memory back to the pool
    pthread_mutex_lock(&pool->mutex);

    pool->size -= sizeof(NFAPI_CRC_INDICATION_PDU_T);
    memset(ptr, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (pool->size < pool->capacity / 2 && pool->capacity > initial_size) {
        pool->data = realloc(pool->data, pool->size);
        if (!pool->data) {
            perror("realloc failed");
            exit(EXIT_FAILURE);
        }
        pool->capacity = pool->size;
    }

    pthread_mutex_unlock(&pool->mutex);

    sem_post(&pool->sem);
}

