// External audit system interface
extern "C" {
    void log_event(const char *event);
}

class EncryptionModule {
private:
    std::map<std::string, AES_KEY> aesKeys;
    RSA *rsaKey;
    std::string rsaKeyId;
    std::string auditLogUrl;

    // Cache for AES keys to reduce lookup time
    std::map<std::string, AES_KEY*> aesCache;
    pthread_mutex_t cacheMutex;

public:
    EncryptionModule(const std::string &rsaKeyId, const std::string &auditLogUrl)
        : rsaKeyId(rsaKeyId), auditLogUrl(auditLogUrl), rsaKey(nullptr), cacheMutex(PTHREAD_MUTEX_INITIALIZER) {
        log4cxx::BasicConfigurator::configure();
    }

    ~EncryptionModule() {
        RSA_free(rsaKey);
    }

    void loadRSAKey() {
        // Implement key retrieval from external service using libcurl
        CURL *curl;
        CURLcode res;

        curl = curl_easy_init();
        if (curl) {
            std::stringstream ss;
            ss << "https://key-service.com/rsa/" << rsaKeyId;

            curl_easy_setopt(curl, CURLOPT_URL, ss.str().c_str());
            curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, nullptr); // Use callback function for key handling
            curl_easy_perform(curl);

            res = curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE);
            if (res != CURLE_OK) {
                log_event("Error loading RSA key");
            }
            curl_easy_cleanup(curl);
        } else {
            log_event("Failed to initialize libcurl for RSA key retrieval");
        }
    }

    void encryptAES(const std::string &data, const std::string &keyId, std::string &encryptedData) {
        AES_KEY *key;

        // Cache management with pthread mutex
        pthread_mutex_lock(&cacheMutex);
        if (aesCache.find(keyId) == aesCache.end()) {
            AES_set_encrypt_key((const unsigned char *)keyId.c_str(), 128, &key);
            aesKeys[keyId] = *key;
            aesCache[keyId] = &aesKeys[keyId];
        }
        key = aesCache[keyId];
        pthread_mutex_unlock(&cacheMutex);

        unsigned char encrypted[AES_BLOCK_SIZE];
        AES_cbc_encrypt((unsigned char *)data.c_str(), (unsigned char *)encrypted, data.length(), key, (unsigned char *)&aesKeys[keyId].iv, AES_ENCRYPT);

        encryptedData.assign((char*)encrypted, data.length());
    }

    void decryptAES(const std::string &encryptedData, const std::string &keyId, std::string &decryptedData) {
        AES_KEY *key;

        // Cache management with pthread mutex
        pthread_mutex_lock(&cacheMutex);
        if (aesCache.find(keyId) == aesCache.end()) {
            AES_set_decrypt_key((const unsigned char *)keyId.c_str(), 128, &key);
            aesKeys[keyId] = *key;
            aesCache[keyId] = &aesKeys[keyId];
        }
        key = aesCache[keyId];
        pthread_mutex_unlock(&cacheMutex);

        unsigned char decrypted[AES_BLOCK_SIZE];
        AES_cbc_encrypt((unsigned char *)encryptedData.c_str(), (unsigned char *)decrypted, encryptedData.length(), key, (unsigned char *)&aesKeys[keyId].iv, AES_DECRYPT);

        decryptedData.assign((char*)decrypted, data.length());
    }
};
