pthread_mutex_t log_mutex;

void error_log(const char *msg) {
    pthread_mutex_lock(&log_mutex);
    printf("[ERROR] %s\n", msg);
    pthread_mutex_unlock(&log_mutex);
}

int create_ue_structures(NFAPI_CRC_INDICATION_PDU_T **ues, int n, bool override_crc) {
    *ues = calloc(n, sizeof(**ues));
    if (!*ues) {
        error_log("Memory allocation failure");
        return 0;
    }

    pthread_mutex_init(&log_mutex, NULL);

    int success_count = 0;

    // Fetch UE information using an external data source (not shown for brevity)
    // Implement fallback mechanism to initialize structures with default values if data retrieval fails

    #pragma omp parallel for reduction(+:success_count)
    for (int i = 0; i < n; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *ue = &((*ues)[i]);

        // Initialize structure fields with default values if data retrieval fails

        ue->RX_UE_INFORMATION_TAG = 0x1234;
        ue->RNTI = i + 1;

        bool retry = true;
        while (retry) {
            // Set CRC_INDICATION_REL8_TAG with a randomly set CRCFLAG or overridden value if provided
            ue->CRC_INDICATION_REL8_TAG = (rand() & 0xFFFF);
            ue->CRCFLAG = (override_crc ? override_crc : (ue->CRC_INDICATION_REL8_TAG % 2 == 0));

            // Verify the integrity of each CRC_INDICATION_REL8_TAG after creation
            if (ue->CRCFLAG == ((ue->CRC_INDICATION_REL8_TAG + 1) & 0xFFFF)) {
                retry = false;
                success_count++;
            } else {
                error_log("Integrity check failed for UE");
            }
        }
    }

    pthread_mutex_destroy(&log_mutex);
