#include <pthread.h>
#include <stdbool.h>
#include <stdlib.h>
#include <stdio.h>
#include <semaphore.h>

typedef struct {
    int PCI;
    float RSRP;
    float RSRQ;
} LTE_UESearchResult_t;

struct list_node {
    LTE_UESearchResult_t data;
    struct list_node* next;
};

static sem_t list_mutex = SEM_INITIALIZER_NP;
static struct list_node *head = NULL, *tail = NULL;
static int rsrp_threshold = 0;

void enqueue(LTE_UESearchResult_t data) {
    struct list_node* new_node = malloc(sizeof(struct list_node));
    if (!new_node) return;

    sem_wait(&list_mutex);
    new_node->data = data;
    new_node->next = NULL;

    if (tail) tail->next = new_node;
    else head = new_node;
    tail = new_node;
    sem_post(&list_mutex);
}

LTE_UESearchResult_t* dequeue() {
    LTE_UESearchResult_t *result = NULL;

    sem_wait(&list_mutex);
    if (head) {
        result = &head->data;
        head = head->next;
        if (!head) tail = NULL;
    }
    sem_post(&list_mutex);

    return result;
}

void filter_results(int threshold) {
    struct list_node *current, *temp;
    sem_wait(&list_mutex);
    current = head;

    while (current != NULL) {
        if (current->data.RSRP <= threshold) {
            temp = current->next;
            free(current);
            current = temp;
        } else {
            current = current->next;
        }
    }

    sem_post(&list_mutex);
}

void process_data(LTE_UESearchResult_t data) {
    LTE_UESearchResult_t* result = dequeue();
    if (result && data.RSRP > result->RSRP) {
        enqueue(data);
        *result = data;
    }
}

// Thread-safe function to process new data from external source
void update_data(LTE_UESearchResult_t data) {
    process_data(data);
    filter_results(rsrp_threshold);
}
