#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <inttypes.h>

typedef struct UEStatsRecord {
    int64_t UE_ID;
    int RRC_Connection_Status;
    struct Traffic_Statistics {
        uint64_t uplink_traffic;
        uint64_t downlink_traffic;
    } Traffic;
} UEStatsRecord;

typedef struct DynArray {
    size_t capacity;
    size_t size;
    UEStatsRecord* data;
} DynArray;

DynArray* create_dyn_array(size_t capacity) {
    DynArray* array = malloc(sizeof(DynArray));
    array->capacity = capacity;
    array->size = 0;
    array->data = calloc(capacity, sizeof(UEStatsRecord));
    return array;
}

void add_record(DynArray* array, const UEStatsRecord* record) {
    if (array->size >= array->capacity) {
        array->capacity *= 2;
        array->data = realloc(array->data, array->capacity * sizeof(UEStatsRecord));
    }
    memcpy(&array->data[array->size], record, sizeof(UEStatsRecord));
    array->size++;
}

void remove_record(DynArray* array, size_t index) {
    if (index >= array->size || index < 0) return;

    for (size_t i = index + 1; i < array->size; ++i) {
        memcpy(&array->data[i - 1], &array->data[i], sizeof(UEStatsRecord));
    }

    array->size--;
}

void serialize_to_file(const char* filename, const DynArray* array) {
    FILE* file = fopen(filename, "w");
    if (!file) return;

    for (size_t i = 0; i < array->size; ++i) {
        fprintf(file, "%" PRId64 " %d %" PRIu64 " %" PRIu64 "\n", array->data[i].UE_ID,
                array->data[i].RRC_Connection_Status,
                array->data[i].Traffic.uplink_traffic,
                array->data[i].Traffic.downlink_traffic);
    }

    fclose(file);
}

void* load_from_file(const char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) return NULL;

    size_t capacity = 0;
    UEStatsRecord* data = NULL;

    while (!feof(file)) {
        UEStatsRecord record;
        fscanf(file, "%" PRId64 " %d %" PRIu64 " %" PRIu64 "\n", &record.UE_ID,
               &record.RRC_Connection_Status,
               &record.Traffic.uplink_traffic,
               &record.Traffic.downlink_traffic);
        if (capacity == 0) {
            capacity = 1;
            data = malloc(capacity * sizeof(UEStatsRecord));
        } else if (capacity == data->size) {
            capacity *= 2;
            data = realloc(data, capacity * sizeof(UEStatsRecord));
        }
        memcpy(&data[capacity - 1], &record, sizeof(UEStatsRecord));
    }

    fclose(file);
    return data;
}
