        std::shared_ptr<NFAPI_CRC_INDICATION_PDU_T> data;
        Node* prev;
        Node* next;
    };

    boost::circular_buffer<Node*> buffer_; // buffer for the nodes of the list
    boost::mutex mutex_;                   // lock for synchronization
    pthread_mutexattr_t attr;             // attributes for the thread mutex

public:
    DoublyLinkedList() {
