        if (!lock) {
            std::cerr << "Error acquiring mutex. Aborting add operation." << std::endl;
            delete node;
            return;
        }

        Node* tail = buffer_.back();
        if (tail != nullptr) {
            tail->next = node;
            node->prev = tail;
        } else {
            buffer_.push_back(node);
        }
    }

