void register_algorithm(const char* name, void* implementation) {
    if (num_algorithms >= MAX_ALGORITHMS) {
        fprintf(stderr, "Cannot register more than %zu algorithms\n", MAX_ALGORITHMS);
        return;
    }

    ALGORITHM** new_algorithms = realloc(algorithms, sizeof(ALGORITHM*) * (num_algorithms + 1));
    if (!new_algorithms) {
        fprintf(stderr, "Failed to allocate memory for algorithm registry\n");
        return;
    }
    algorithms = new_algorithms;

    ALGORITHM* algorithm = &algorithms[num_algorithms];
    pthread_mutex_init(&algorithm->lock, NULL);
    algorithm->name = name;
    algorithm->implementation = implementation;
    num_algorithms++;
}

void unregister_algorithm(const char* name) {
    if (num_algorithms <= 0) return;

    pthread_mutex_lock(&algorithm_registry_lock);
    for (size_t i = 0; i < num_algorithms; ++i) {
        if (strcmp(algorithms[i]->name, name) == 0) {
            ALGORITHM* algorithm = algorithms[i];
            memmove(&algorithms[i], &algorithms[i + 1], sizeof(ALGORITHM*) * (num_algorithms - i - 1));
            --num_algorithms;
            pthread_mutex_destroy(&algorithm->lock);
            free(algorithm);
            break;
        }
    }
    pthread_mutex_unlock(&algorithm_registry_lock);
}

