#include <mqtt/async_client.h>

typedef struct {
    uint8_t* payload;
    size_t payload_len;
} MQTT_MESSAGE_PDU_T;

static SSL_CTX* tls_context = NULL;
static mqtt_client_t* client = NULL;
static pthread_mutex_t buffer_lock = PTHREAD_MUTEX_INITIALIZER;
static size_t max_messages = 10;
static MQTT_MESSAGE_PDU_T* message_buffer[MAX_MESSAGES];

void process_and_forward_mqtt_messages(const char* host, int port, const char* app_id) {
    mqtt_message_handler_func_setter_t handler = mqtt_message_handler;

    // Initialize MQTT client with TLS support
    mqtt_init(client, host, port, MQTT_PROTOCOL_VERSION_3_1_1);
    mqtt_set_tls_context(client, tls_context);
    mqtt_will(client, app_id, 0, NULL, 0);
    mqtt_connect(client, app_id, 0);

    // Process messages and forward to the designated application
    while (1) {
        pthread_mutex_lock(&buffer_lock);

        for (size_t i = 0; i < max_messages && message_buffer[i] != NULL; ++i) {
            MQTT_MESSAGE_PDU_T* msg = message_buffer[i];
            mqtt_message_handler(client, msg->payload, msg->payload_len);
            free(msg->payload);
            message_buffer[i] = NULL;
        }

        pthread_mutex_unlock(&buffer_lock);

        // Receive incoming MQTT messages and store in the buffer if full
        mqtt_loop(client, ASYNC_BLOCKING);
        mqtt_message_t* msg = mqtt_get_message(client);
        if (msg != NULL) {
            size_t num_full = 0;
            pthread_mutex_lock(&buffer_lock);

            for (size_t i = 0; i < max_messages && message_buffer[i] == NULL; ++i) {
                message_buffer[i] = malloc(sizeof(MQTT_MESSAGE_PDU_T));
                if (message_buffer[i] != NULL) {
                    message_buffer[i]->payload = malloc(msg->payloadlen);
                    memcpy(message_buffer[i]->payload, msg->payload, msg->payloadlen);
                    message_buffer[i]->payload_len = msg->payloadlen;
                } else {
                    num_full++;
                }
            }

            pthread_mutex_unlock(&buffer_lock);

            if (num_full == max_messages) {
                // Log full buffer and drop incoming message
                printf("Buffer is full, dropping message\n");
                free(msg->payload);
            }
        }
    }
}
```
