#include <iostream>
#include <vector>
#include <mutex>
#include <atomic>

struct TrafficFlow {
    int PDCP_SN;
    int SFN;
    int LOGICAL_CHANNEL_ID;
    enum class TRAFFIC_FLOW_STATUS { IDLE, ACTIVE };
    TRAFFIC_FLOW_STATUS traffic_flow_status = TRAFFIC_FLOW_STATUS::IDLE;
};

class TrafficFlowManager {
private:
    std::vector<TrafficFlow> trafficFlows;
    std::mutex mtx;
    std::atomic<int> size{ 0 };

public:
    void add(const TrafficFlow& tf) {
        std::unique_lock<std::mutex> lock(mtx);
        trafficFlows.push_back(tf);
        ++size;
    }

    bool updateStatus(int index, const TRAFFIC_FLOW_STATUS& newStatus) {
        std::unique_lock<std::mutex> lock(mtx);
        if (index >= size || index < 0) return false;
        trafficFlows[index].traffic_flow_status = newStatus;
        return true;
    }

    int getSize() const {
        std::unique_lock<std::mutex> lock(mtx);
        return size;
    }

    const TrafficFlow& getTrafficFlow(int index) const {
        if (index >= size || index < 0) throw std::out_of_range("Index out of range");
        std::unique_lock<std::mutex> lock(mtx);
        return trafficFlows[index];
    }
};
