    NFAPI_CRC_INDICATION_PDU_T *array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        log_error("Memory allocation failed.");
        return NULL;
    }

    allocated_count = N;
    pthread_mutex_init(&array[0].crc_indication.crcflag_lock, NULL);

    for (size_t i = 0; i < N; ++i) {
