        log_error("Invalid or duplicate RNTI provided.");
        pthread_mutex_unlock(&array_lock);
        return;
    }

    data->ue_information.tag = RX_UE_INFORMATION_TAG_VALID; // Replace placeholder value
    data->rnti = index;

    pthread_mutex_unlock(&array_lock);

