    if (list->count < list->capacity) {
        NFAPI_CRC_INDICATION_PDU_T* element = &list->elements[list->count];
        element->rx_ue_information_tag = *tag;
        element->rnti = rnti;
        element->crc_indication_rel8_tag.crcflag = rand() % 2; // Randomly set CRCFLAG

        list->count++;
    }

    pthread_mutex_unlock(&list->mutex);
}

NFAPI_CRC_INDICATION_LIST* manage_crc_indication_list(NFAPI_CRC_INDICATION_LIST* list, size_t n) {
    if (!list) return create_crc_indication_list(n);

    pthread_mutex_lock(&list->mutex);

    if (list->capacity - list->count < n) {
        void* temp = realloc(list->elements, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (list->capacity + n));
        if (!temp) {
            pthread_mutex_unlock(&list->mutex);
            log_error("Failed to resize list");
            return NULL;
        }

        list->elements = temp;
        list->capacity += n;
    }

    pthread_mutex_unlock(&list->mutex);
    return list;
}
