            const xmlChar* text = xmlNodeGetContent(child);
            size_t length = xmlStrlen(text);

            accumulated_length += length;
            if (accumulated_length + length > max_text_length) {
                *(output + (*output_capacity - 1)) = NULL; // terminate output array
                return;
            }

            // Allocate space for the text and concatenate with existing output
            if (accumulated_length + length >= *output_capacity) {
                *output_capacity *= 2;
                char* new_output = realloc(output, *output_capacity * sizeof(char));
                if (!new_output) {
                    // Handle memory allocation failure
                    return;
                }
                output = new_output;
            }

            strncpy((output + accumulated_length), (const char*)text, length);
            accumulated_length += length;
        } else if (xmlStrcasecmp(child->name, selector)) { // handle element matching the CSS selector
            process_html(child, output, output_capacity);
        }
    }

    // If we've reached a leaf node without exceeding the text limit, append a forward slash if necessary
    if (accumulated_length < max_text_length) {
        *(output + accumulated_length) = '/';
        output[accumulated_length + 1] = '\0';
    } else { // indicate unsuccessful processing for this element
        output[accumulated_length] = '\0';
    }
}
