// Custom memory management system
typedef struct mem_block {
    void *data;
    size_t size;
    struct mem_block *next;
} MemBlock;

MemBlock *mem_head = NULL;
pthread_mutex_t mem_lock = PTHREAD_MUTEX_INITIALIZER;

void log_event(const char *message) {
    // Replace this with your preferred logging method
    printf("[%s]\n", message);
}

void *mem_alloc(size_t size) {
    pthread_mutex_lock(&mem_lock);
    MemBlock *new_block = (MemBlock *)malloc(sizeof(MemBlock));
    if (!new_block) {
        log_event("Out of memory");
        pthread_mutex_unlock(&mem_lock);
        return NULL;
    }
    new_block->data = malloc(size);
    if (!new_block->data) {
        free(new_block);
        log_event("Out of memory");
        pthread_mutex_unlock(&mem_lock);
        return NULL;
    }
    new_block->size = size;
    new_block->next = mem_head;
    mem_head = new_block;
    pthread_mutex_unlock(&mem_lock);
    return new_block->data;
}

void mem_free(void *ptr) {
    if (!ptr) return;
    MemBlock *curr = mem_head, *prev = NULL;
    while (curr != NULL) {
        if (curr->data == ptr) {
            if (prev == NULL) {
                mem_head = curr->next;
            } else {
                prev->next = curr->next;
            }
            free(curr);
            break;
        }
        prev = curr;
        curr = curr->next;
    }
}

