void init_ue_info(RX_UE_INFORMATION_TAG* tag, RNTI* rnti, unsigned int seed) {
    time_t currentTime = time(NULL);
    srand((unsigned int)currentTime + seed);
    *tag = (RX_UE_INFORMATION_TAG){ .timeStamp = currentTime };
    *rnti = (RNTI){ .rntiValue = rand() };
}

int crcCheck(const unsigned char* data, size_t length) {
    unsigned long crc = 0xFFFFFFFF;
    for (size_t i = 0; i < length; ++i) {
        unsigned char byte = data[i];
        for (size_t j = 0; j < 8; ++j) {
            if (((crc << 1) ^ (byte & 0x80)) & POLYNOMIAL) {
                crc ^= POLYNOMIAL >> 1;
            }
            byte <<= 1;
            crc = crc << 1 ^ (crc & 0x80000000 ? POLYNOMIAL >> 27 : 0);
        }
    }
    return ~crc & 0xFFFFFFFF;
}

NFAPI_CRC_INDICATION_PDU_T* createPDUs(unsigned int numElements, unsigned int seed) {
