            }

            if (min > max) {
                std::cerr << "Error: Invalid range specified for record '" << id << "': min value must be less than max value." << std::endl;
                continue;
            }

            std::uniform_int_distribution<> dist(min, max);
            records.push_back({dist(rng)});
        }
    }

    std::vector<std::string> getRecordIds(const boost::property_tree::ptree& pt, const std::string& elementName) {
        std::vector<std::string> ids;
        BOOST_FOREACH (boost::property_tree::ptree::value_type& v, pt.get_child(elementName)) {
            ids.push_back(v.first);
        }
        return ids;
    }
};
```

