// External logging library
extern void log_message(const char* message);

#define MAX_STRUCTURES 1000000
#define MEMORY_THRESHOLD (MAX_STRUCTURES * sizeof(NFAPI_CRC_INDICATION_PDU_T) / 2) // Adjustable threshold

struct rnti {
    uint32_t value;
    struct rnti* next;
};

typedef struct _NFAPI_CRC_INDICATION_PDU_T NFAPI_CRC_INDICATION_PDU_T;
struct _NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
};

static pthread_mutex_t rnti_list_mutex = PTHREAD_MUTEX_INITIALIZER;
static struct rnti free_rntis = { .value = 0, .next = NULL };
static struct rnti used_rntis = { .value = 0, .next = NULL };

NFAPI_CRC_INDICATION_PDU_T* allocate_array(unsigned int N) {
    if (N > MAX_STRUCTURES || MEMORY_THRESHOLD < sysconf(_SC_PAGE_SIZE)) {
        log_message("Error: Requested array size is too large or memory threshold is too low.");
        return NULL;
    }

    unsigned int structures_allocated = 0;
    NFAPI_CRC_INDICATION_PDU_T* structures = mmap(NULL, sizeof(NFAPI_CRC_INDICATION_PDU_T) * N, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (structures == MAP_FAILED) {
        log_message("Error: Memory allocation failure.");
        return NULL;
    }

    // Initialize pseudo-random number generator with user provided seed
    srand(N);

    pthread_mutex_lock(&rnti_list_mutex);
    struct rnti* current = &free_rntis;
    for (unsigned int i = 0; i < N && structures_allocated < N; ++i) {
        if (!current->next) { // All RNTIs are used, need to allocate a new one
            current->value = rand();
            current->next = malloc(sizeof(struct rnti));
            if (!current->next) {
                log_message("Error: Memory allocation failure.");
                goto cleanup;
            }
            current = current->next;
        }

        // Ensure RNTI is unique within the array and update used list
        while (used_rntis.value == current->value || find_in_list(&used_rntis, current)) {
            current->value = rand();
        }
        current->next->value = current->value;
        structures[structures_allocated].rnti = current->value;
        used_rntis.value = current->value;
        used_rntis.next = used_rntis.next ? used_rntis.next : &used_rntis;
        structures[structures_allocated++].crc_indication.CRCFLAG = (rand() % 2) == 0;
    }
    pthread_mutex_unlock(&rnti_list_mutex);

cleanup:
    if (structures_allocated > 0) {
        msync(structures, sizeof(NFAPI_CRC_INDICATION_PDU_T) * structures_allocated, MS_SYNC);
    } else {
        munmap(structures, sizeof(NFAPI_CRC_INDICATION_PDU_T) * N);
    }

    return structures;
}

bool find_in_list(struct rnti* list, struct rnti* node) {
    for (struct rnti* current = list; current != NULL; current = current->next) {
        if (current == node || current->value == node->value) {
            return true;
        }
    }
    return false;
}
```

