        std::lock_guard<std::mutex> lock(mutex);
        activeSessions.emplace(userSession.getUserId(), &userSession);
    }

    bool updateUserSessionStatus(int userId, const std::string& newStatus) {
        auto it = activeSessions.find(userId);
        if (it == activeSessions.end()) return false;

        std::lock_guard<std::mutex> lock(mutex);
        it->second->setStatus(newStatus);
        return true;
    }

