using System;
using System.Collections.Generic;
using UnityEngine;
using static NFAPI_CRC_INDICATION_PDU_T;

public struct RX_UE_INFORMATION_TAG { public readonly ushort tag; }
public struct RNTI { public readonly ulong rnti; }
public struct CRC_INDICATION_REL8_TAG { public readonly bool crcFlag; }

public class NFAPI_CRC_INDICATION_PDU_Generator
{
    private const int DEFAULT_MAX_SIZE = 1024;
    private const float DEFAULT_SEED = 123456789f;

    private List<NFAPI_CRC_INDICATION_PDU_T> _pduList;
    private int _maxSize;
    private float _seed;
    private System.Random _random;

    public NFAPI_CRC_INDICATION_PDU_Generator(int maxSize, float seed)
    {
        _maxSize = Mathf.Max(1, maxSize);
        _seed = seed;
        Initialize();
    }

    public NFAPI_CRC_INDICATION_PDU_Generator(int maxSize) : this(maxSize, DEFAULT_SEED) {}

    public NFAPI_CRC_INDICATION_PDU_Generator() : this(DEFAULT_MAX_SIZE, DEFAULT_SEED) {}

    private void Initialize()
    {
        _pduList = new List<NFAPI_CRC_INDICATION_PDU_T>(_maxSize);
        _random = new System.Random((int)_seed);
    }

    public void Reset(float seed)
    {
        _seed = seed;
        _random = new System.Random((int)_seed);
        Initialize();
    }

    public NFAPI_CRC_INDICATION_PDU_T[] GeneratePDUs()
    {
        if (_pduList.Count == 0)
            PopulatePduList();

        var pdus = _pduList.ToArray();
        _pduList.Clear(); // Thread-safe due to concurrent collection issue

        return pdus;
    }

    private void PopulatePduList()
    {
        for (int i = 0; i < _maxSize; ++i)
            _pduList.Add(GeneratePDU());
    }

    private NFAPI_CRC_INDICATION_PDU_T GeneratePDU()
    {
        var pdu = new NFAPI_CRC_INDICATION_PDU_T();

        pdu.rxUEInformationTag = (RX_UE_INFORMATION_TAG) UnityEngine.Mathf.Clamp(UnityEngine.Random.Range(0, 256), 1, 255);
        pdu.rnti = UnityEngine.Mathf.Pow(2, 48) * UnityEngine.Random.Range((long)Mathf.Pow(2, 32), (long)Mathf.Pow(2, 64));
        pdu.crcIndicationRel8Tag.crcFlag = _random.Next(0, 100) > 95; // 95% chance of true value

        return pdu;
    }
}
