    std::mutex mtx;
    std::unordered_map<uint32_t, size_t> tagToIndex;

public:
    void add(const NFAPI_CRC_INDICATION_PDU_T& pdu) {
        std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T> newPdu(new NFAPI_CRC_INDICATION_PDU_T(pdu));
        std::lock_guard<std::mutex> lock(mtx);

        uint32_t tag = newPdu->RX_UE_INFORMATION_TAG ^ newPdu->RNTI;
        newPdu->CRC_INDICATION_REL8_TAG = tag;
        data.push_back(std::move(newPdu));
        tagToIndex[tag] = data.size() - 1;
    }

    bool update(uint32_t rnti, const NFAPI_CRC_INDICATION_PDU_T& pdu) {
        std::lock_guard<std::mutex> lock(mtx);

        auto it = tagToIndex.find(rnti ^ pdu.RX_UE_INFORMATION_TAG);
        if (it == tagToIndex.end()) return false;

        data[it->second]->RX_UE_INFORMATION_TAG = pdu.RX_UE_INFORMATION_TAG;
        data[it->second]->RNTI = rnti;
        data[it->second]->CRC_INDICATION_REL8_TAG = rnti ^ pdu.RX_UE_INFORMATION_TAG;

        return true;
    }

    bool remove(uint32_t rnti) {
        std::lock_guard<std::mutex> lock(mtx);

        auto it = tagToIndex.find(rnti ^ pdu.RX_UE_INFORMATION_TAG);
        if (it == tagToIndex.end()) return false;

        data[it->second].reset();
        tagToIndex.erase(it);

        // Re-index elements with smaller RX_UE_INFORMATION_TAG value that have the same RNTI value
        for (size_t i = it->second + 1; i < data.size(); ++i) {
            if (data[i]->RNTI == rnti && data[i]->RX_UE_INFORMATION_TAG <= it->first) {
                tagToIndex[data[i]->RX_UE_INFORMATION_TAG ^ data[i]->RNTI] = i - 1;
            }
        }

        return true;
    }
};
