#include <pthread.h>
#include <time.h>
#include <stdlib.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <stdbool.h>
#include <semaphore.h>

struct logging_data {
    sem_t file_access;
    FILE *file;
    NFAPI_LOGGING_REQUEST_PDU_T template;
};

typedef struct thread_args {
    struct logging_data *data;
    size_t index;
} ThreadArgs;

void update_logging_service(struct logging_data *data) {
    // Implement logic to interact with the external logging service
}

NFAPI_LOGGING_REQUEST_PDU_T* generate_log_entry(const struct logging_data *data) {
    time_t current_time = time(NULL);
    return calloc(1, sizeof(NFAPI_LOGGING_REQUEST_PDU_T)) && (
        data->template.LOG_TAG = random() % 0xFF,
        data->template.LOG_LEVEL = (rand() % 3) + 1,
        data->template.UE_ID = rand(),
        data->template.timestamp = current_time);
}

void* worker(void *arg) {
    ThreadArgs *thread_args = arg;
    struct logging_data *data = thread_args->data;

    sem_wait(&data->file_access);

    NFAPI_LOGGING_REQUEST_PDU_T *log_entry = generate_log_entry(data);
    if (log_entry) {
        fwrite(log_entry, sizeof(NFAPI_LOGGING_REQUEST_PDU_T), 1, data->file);
        free(log_entry);
    }

    sem_post(&data->file_access);

    return NULL;
}

int generate_logs(size_t N, struct logging_data *data) {
    pthread_t threads[N];
    ThreadArgs args[N];
    size_t thread_index = 0;

    sem_init(&data->file_access, 1, 1);

    for (size_t i = 0; i < N; ++i) {
        args[thread_index].data = data;
        args[thread_index].index = i;
        pthread_create(&threads[thread_index], NULL, worker, &args[thread_index]);
        thread_index++;
    }

    for (size_t i = 0; i < N; ++i) {
        pthread_join(threads[i], NULL);
    }

    sem_destroy(&data->file_access);
}
