        printf("Transaction ID: %u\n", transaction->transaction_identifier);
        printf("Sequence Number: %u\n", transaction->sequence_number);
    }
}

TRANSACTION_MANAGER_T* transaction_manager_create(size_t initial_capacity, bool enable_logging) {
    TRANSACTION_MANAGER_T* manager = malloc(sizeof(TRANSACTION_MANAGER_T));
    if (!manager) return NULL;

    manager->transactions = calloc(initial_capacity, sizeof(PHY_LAYER_TRANSACTION_T));
    if (!manager->transactions) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

int transaction_manager_add_transaction(TRANSACTION_MANAGER_T* manager, const PHY_LAYER_TRANSACTION_T* transaction) {
    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        PHY_LAYER_TRANSACTION_T* new_transactions = realloc(manager->transactions, new_capacity * sizeof(PHY_LAYER_TRANSACTION_T));
        if (!new_transactions) return -1; // allocation failure
        manager->transactions = new_transactions;
        manager->capacity = new_capacity;
    }

    pthread_mutex_lock(&manager->lock);

    PHY_LAYER_TRANSACTION_T* transaction_ptr = &manager->transactions[manager->count];
    memcpy(transaction_ptr, transaction, sizeof(PHY_LAYER_TRANSACTION_T));

    if (transaction->checksum) {
        int validation_result = checksum_validation(transaction_ptr);
        if (validation_result < 0) { // checksum calculation failed
            pthread_mutex_unlock(&manager->lock);
            return -1;
        } else if (validation_result > 0) { // validation failed, log error message
            pthread_mutex_unlock(&manager->lock);
            log_transaction(transaction_ptr, manager->enable_logging);
            printf("Error: Checksum validation failed for transaction %zu\n", manager->count);
            return -1;
        }
    }

    manager->count++;
    pthread_mutex_unlock(&manager->lock);

    if (manager->enable_logging) {
        log_transaction(transaction_ptr, manager->enable_logging);
    }

    return 0;
}

void transaction_manager_destroy(TRANSACTION_MANAGER_T* manager) {
    pthread_mutex_destroy(&manager->lock);
    free(manager->transactions);
    free(manager);
}
