typedef struct node {
    NFAPI_CRTC_INDICATION_PDU_T data;
    struct node *next;
} node_t;

node_t* head = NULL;
pthread_mutex_t lock;
size_t num_elements = 0, window_count = 0;

void init_pool() {
    pthread_mutex_init(&lock, NULL);
}

void destroy_pool() {
    node_t* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
    pthread_mutex_destroy(&lock);
}

node_t* allocate() {
    if (num_elements >= MAX_STRUCTURES) return NULL;

    node_t *newNode = malloc(sizeof(node_t));
    if (!newNode) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    newNode->data.crcflag = rand() % 2;
    newNode->next = NULL;
    num_elements++;

    return newNode;
}

void free_node(node_t *n) {
