void process_queue() {
    node_t *temp, *next;
    pthread_mutex_lock(&lock);

    while (head != NULL && window_count < WINDOW_SIZE) {
        temp = head;
        head = head->next;
        next = temp->next;

        if (manage_data(&temp->data)) { // If an error occurs, handle it and continue.
            free(temp);
            continue;
        }

        free_node(temp);
        window_count++;
    }

    pthread_mutex_unlock(&lock);
}

void enqueue(NFAPI_CRC_INDICATION_PDU_T* data) {
    node_t *newNode = allocate();

    if (newNode == NULL) return;

    memcpy(newNode, data, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    pthread_mutex_lock(&lock);

    newNode->next = head;
    head = newNode;

    pthread_mutex_unlock(&lock);
}
