        auto key = std::make_pair(event.imsi, event.msisdn);
        if (imsiMsisdnMap.find(key) == imsiMsisdnMap.end()) { // no duplicate found
            events.push_back(event);
            imsiMsisdnMap[key] = events.size() - 1;
        }
    }

    size_t countEventsByDirection(TrafficDirection direction) const {
        size_t count = 0;
        for (const auto& event : events) {
            if (event.traffic_direction == direction) {
                ++count;
            }
        }
        return count;
    }
};
