#include <pthread.h>

// Define the structure
struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
};

class DynamicArray {
private:
    std::vector<NFAPI_CRC_INDICATION_PDU_T> data;
    size_t capacity;
    pthread_mutex_t mutex;
    // Statistics variables
    size_t successfulAllocations = 0;
    size_t reallocations = 0;
    double avgTimeForReallocation = 0.0;
    size_t failedAllocationAttempts = 0;

public:
    DynamicArray(size_t initialCapacity) : capacity(initialCapacity), mutex(PTHREAD_MUTEX_INITIALIZER) {}

    // Add an element to the array, handle resizing if necessary
    void push_back(const NFAPI_CRC_INDICATION_PDU_T& pdu) {
        pthread_mutex_lock(&mutex);

        if (data.size() >= capacity) {
            reallocations++;
            // Perform resizing off-critical path to minimize overhead
            resize(std::max(capacity * 2, data.size() + 1));
        }

        data.push_back(pdu);
        successfulAllocations++;

        pthread_mutex_unlock(&mutex);
    }

    // Implement the strategies to minimize overhead associated with dynamic memory management
    void resize(size_t newCapacity) {
        capacity = newCapacity;
        std::vector<NFAPI_CRC_INDICATION_PDU_T> temp(newCapacity);
        pthread_mutex_lock(&mutex);
        std::copy(data.begin(), data.end(), temp.begin());
        data.swap(temp);
        pthread_mutex_unlock(&mutex);
    }

    // Validate RNTI values and handle invalid inputs gracefully
    void validateRnti(uint16_t rnti) const {
        assert((rnti >= 0) && (rnti <= 65535));
    }

    // Log warnings without introducing significant performance penalties
    void logWarning(const char* msg) const {
        std::cerr << "[" << std::clock() / CLOCKS_PER_SEC << "] Warning: " << msg << std::endl;
    }

    // Implement robust error handling for memory allocation failures
    NFAPI_CRC_INDICATION_PDU_T* allocatePDU() {
        NFAPI_CRC_INDICATION_PDU_T* pdu = nullptr;

        pthread_mutex_lock(&mutex);
        try {
            pdu = new NFAPI_CRC_INDICATION_PDU_T();
            if (!pdu) {
                logWarning("Failed to allocate PDU memory");
                failedAllocationAttempts++;
            }
        } catch (const std::bad_alloc& e) {
            logWarning("Failed to allocate PDU memory: " + std::string(e.what()));
            failedAllocationAttempts++;
        }
        pthread_mutex_unlock(&mutex);

        return pdu;
    }

    // Ensure thread safety if this function is used in a multi-threaded environment
    void setRnti(NFAPI_CRC_INDICATION_PDU_T* pdu, uint16_t rnti) {
        validateRnti(rnti);
        pthread_mutex_lock(&mutex);
        pdu->rnti = rnti;
        pthread_mutex_unlock(&mutex);
    }

    // Provide detailed statistics about the number of successful allocations and reallocations
    void printStatistics() const {
        double avgTimeForReallocationSec = avgTimeForReallocation / reallocations;
        std::cout << "Successful allocations: " << successfulAllocations << "\n";
        std::cout << "Reallocations: " << reallocations << "\n";
        std::cout << "Average time for reallocations (s): " << avgTimeForReallocationSec << "\n";
        std::cout << "Failed allocation attempts: " << failedAllocationAttempts << "\n";
    }
};
