} NFAPI_CRC_INDICATION_PDU_T;

int initialize_rx_ues(NFAPI_CRC_INDICATION_PDU_T **ue_info, pthread_mutex_t *mutex) {
    NFAPI_CRC_INDICATION_PDU_T *ues = NULL;

    if (!ue_info || !mutex)
        return -1;

    ues = (NFAPI_CRC_INDICATION_PDU_T *)malloc(NUM_UES * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!ues) {
        perror("Memory allocation failed");
        return -1;
    }

    pthread_mutexattr_t attr;
    int rc = pthread_mutexattr_init(&attr);
    if (rc) {
        free(ues);
        perror("Mutex attributes initialization failed");
        return -1;
    }

    rc = pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE);
    if (rc) {
        free(ues);
        pthread_mutexattr_destroy(&attr);
        perror("Mutex type setting failed");
        return -1;
    }

    rc = pthread_mutex_init(mutex, &attr);
    pthread_mutexattr_destroy(&attr);
    if (rc) {
        free(ues);
        perror("Mutex initialization failed");
        return -1;
    }

    for (size_t i = 0; i < NUM_UES; ++i) {
        ues[i].RX_UE_INFORMATION_TAG = i + 1;
        ues[i].RNTI = i + 10000;
        for (size_t j = 0; j < 4; ++j)
            ues[i].CRC_INDICATION_REL8_TAG[j] = rand() % 256;
    }

    return NUM_UES;
}
