        if (numPDUs > pduArray.size()) {
            pduArray.resize(numPDUs);
        }

        std::vector<std::future<void>> tasks;
        for (size_t i = 0; i < numPDUs; ++i) {
            tasks.emplace_back(std::async(std::launch::async, [this, i]() { createPDU(i); }));
        }

        for (auto& task : tasks) {
            if (!task.wait_for(std::chrono::seconds(1)) && !task.ready()) {
