    uint16_t RNTI;
    uint16_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_RNTIS 256
#define LOG_THRESHOLD 500
typedef enum { LOG_INFO, LOG_WARNING, LOG_ERROR } log_level_t;
static log_level_t log_level = LOG_INFO;
static pthread_mutex_t log_mutex;
static pthread_mutexattr_t mutex_attr;
static pthread_sem_t semaphore;

void create_semaphore_and_cleanup(int initial) {
    pthread_mutexattr_init(&mutex_attr);
    pthread_mutexattr_settype(&mutex_attr, PTHREAD_MUTEX_RECURSIVE);
    pthread_mutex_init(&log_mutex, &mutex_attr);
    pthread_sem_init(&semaphore, NULL, initial);
}

void cleanup() {
    pthread_mutex_destroy(&log_mutex);
    pthread_mutexattr_destroy(&mutex_attr);
    pthread_sem_destroy(&semaphore);
}

NFAPI_CRC_INDICATION_PDU_T* create_and_populate_crc_list(int N) {
    if (N > MAX_RNTIS || N < 1) return NULL;

    pthread_mutex_lock(&log_mutex);
    log_level_t old_log_level = log_level;
    if (old_log_level >= LOG_WARNING && N >= LOG_THRESHOLD) {
        log_level = LOG_INFO;
    }
    pthread_mutex_unlock(&log_mutex);

    NFAPI_CRC_INDICATION_PDU_T *list, *item;
    list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        if (--N > 0) return create_and_populate_crc_list(N);
        return NULL;
    }

    item = list;
    pthread_mutex_lock(&log_mutex);
    for (int i = 0; i < N; ++i, ++item) {
        if (item->RNTI >= MAX_RNTIS || item->RX_UE_INFORMATION_TAG >= UINT32_MAX
            || item->CRC_INDICATION_REL8_TAG >= UINT16_MAX) {
            free(list);
            return NULL;
        }

        if (i > 0 && item->RNTI == list[i - 1].RNTI) {
            item->CRC_INDICATION_REL8_TAG = item->CRC_INDICATION_REL8_TAG ^ 1;
        }

        item->RX_UE_INFORMATION_TAG = rand();
        item->RNTI = rand() % MAX_RNTIS + 1;
        item->CRC_INDICATION_REL8_TAG = rand() & ((uint16_t)UINT16_MAX >> 3);
    }
    pthread_mutex_unlock(&log_mutex);

    return list;
}
