void init_db() {
    bolt_err err = bolt_open("graph.edb", &g_txn);
    if (err != BOLT_OK) {
        fprintf(stderr, "Error opening database: %s\n", bolt_error_message(err));
        exit(1);
    }
}

void create_cell(NFAPI_CELL_INFO_PDU_T *cell) {
    pthread_mutex_lock(&g_mutex);
    boltd_vint key;
    errno_t rc = bolt_key_create(&key, sizeof(uint64_t), BOLT_VINT);
    if (rc != EOK) {
        fprintf(stderr, "Error creating key: %s\n", bolt_error_message(rc));
        pthread_mutex_unlock(&g_mutex);
        exit(1);
    }

    rc = memcpy_s(key.vint, sizeof(uint64_t), &cell->UE_ID, sizeof(uint64_t));
    if (rc != EOK) {
        fprintf(stderr, "Error copying UE_ID: %s\n", bolt_error_message(rc));
        pthread_mutex_unlock(&g_mutex);
        exit(1);
    }

    boltd_blob val;
    rc = bolt_blob_init(&val, sizeof(NFAPI_CELL_INFO_PDU_T), 0);
    if (rc != EOK) {
        fprintf(stderr, "Error initializing value: %s\n", bolt_error_message(rc));
        pthread_mutex_unlock(&g_mutex);
        exit(1);
    }

    NFAPI_CELL_INFO_PDU_T *pCell = (NFAPI_CELL_INFO_PDU_T *)val.blob;
    memcpy_s(pCell, sizeof(NFAPI_CELL_INFO_PDU_T), cell, sizeof(NFAPI_CELL_INFO_PDU_T));

    bolt_stmts stmt = {0};
    stmt.upsert = "UPSERT cell_info SET RSRP=?, RSRQ=?, SINR=? WHERE id=?";
    stmt.params[0] = (void *)&pCell->RSRP;
    stmt.params[1] = (void *)&pCell->RSRQ;
    stmt.params[2] = (void *)&pCell->SINR;
    stmt.params[3] = &key;

    bolt_txn_reset(g_txn);
    bolt_stmt_bind(&stmt, g_txn);

    int retries = 5;
    while (retries--) {
        if (bolt_txn_execute(g_txn) == BOLT_OK) {
            break;
        } else {
            fprintf(stderr, "Error executing statement: %s\n", bolt_error_message(bolt_last_err(g_txn)));
            sleep(1); // Exponential backoff
        }
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to execute statement after retries\n");
    }

    pthread_mutex_unlock(&g_mutex);
}

