#include <boost/circular_buffer.hpp>
#include <boost/lockfree/spsc_queue.hpp>
#include <boost/checksum/adler32.hpp>

std::deque<std::string> dynamicList;
std::unordered_map<std::string, size_t> mapKeyToIndex;
std::mutex mtx;
std::optional<size_t> loggingLevel;
boost::lockfree::spsc_queue<std::tuple<size_t, std::string>> logQueue;

void log(size_t level, const std::string& message) {
    if (!loggingLevel || level <= *loggingLevel) {
        std::cout << "[LOG] " << message << std::endl;
        boost::circular_buffer<std::string> cb(100);
        cb.push_back("[LOG] " + message);
        logQueue.push([&](auto) mutex{cb, mtx});
    }
}

void logThread() {
    while (true) {
        std::tuple<size_t, std::string> tuple;
        if (!logQueue.pop(tuple)) break;

        auto& level = std::get<0>(tuple);
        auto& message = std::get<1>(tuple);

        log(level, message);
    }
}

void appendOrInsertInDynamicList(const std::string& key, const std::string& value) {
    std::unique_lock<std::mutex> lock(mtx);
    auto it = mapKeyToIndex.find(key);
    size_t index;

    if (it != mapKeyToIndex.end()) {
        index = it->second;
        dynamicList.insert(dynamicList.begin() + (index + 1), value);
    } else {
        dynamicList.push_back(value);
        index = dynamicList.size() - 1;
        mapKeyToIndex[key] = index;
    }

    log(1, "Appended or inserted: " + key);
}

