                    if (head.compare_exchange_weak(currentHead, newNode.get())) {
                        break;
                    }
                } else {
                    std::atomic_thread_fence(std::memory_order_acq_rel);
                    prev->next.store(newNode.release(), std::memory_order_release);
                }
            }
        }

        NFAPI_CRC_INDICATION_PDU_T dequeue() {
            for (;;) {
