    if (len > 256) return NULL; // Validate maximum length

    int chars[128] = {};
    for (int i = 0; i < len; ++i) {
        char c = original[i];
        if (c == '/' || c == '.' || !isalnum(c)) continue; // Exclude directory separators and invalid path components
