    int total = 0;
    for (int i = 0; i < 128; ++i)
        total += chars[i] > 0 ? chars[i] : 0;

    if (total > 99999) return NULL; // Validate sequence length

    char *new_filename = malloc(len + 6);
    memset(new_filename, '_', len); // Replace spaces and special characters with underscores

