    for (int i = 0; i < len; ++i) {
        if (original[i] == '/' || original[i] == '.') continue; // Exclude directory separators and invalid path components
        new_filename[pos++] = original[i];
    }

    char sequence[5] = "";
    while (total-- > 0) {
        sequence[4 - strlen(sequence)] = total % 10 + '0';
        total /= 10;
    }

    strcat(new_filename, ".");
    strcat(new_filename, sequence);
    strcat(new_filename, extension);

