2. Thread-safe queue (`Queue`) implementation using a circular buffer and locks for synchronization:

```c
#include <stdbool.h>

struct Queue {
    Record* buf;
    size_t capacity;
    size_t head;
    size_t tail;
    pthread_mutex_t lock;
    sem_t not_empty;
};
```

3. `init_queue()` function for initializing the queue with a given capacity:

```c
void init_queue(struct Queue* q, size_t capacity) {
    q->capacity = capacity;
    q->buf = malloc(sizeof(Record) * capacity);
    q->head = q->tail = 0;
    pthread_mutex_init(&q->lock, NULL);
    sem_init(&q->not_empty, 0, 0);
}
```

4. `enqueue()` function for adding a record to the queue:

```c
bool enqueue(struct Queue* q, Record* r) {
    pthread_mutex_lock(&q->lock);

    // Check if the queue is full and return false when it is.
    while (q->head == ((q->tail + 1) % q->capacity)) {
        pthread_mutex_unlock(&q->lock);
        sem_wait(&q->not_empty);
        pthread_mutex_lock(&q->lock);
    }

    // Add the record to the queue.
    memcpy(q->buf + (q->tail), r, sizeof(*r));
    q->tail = (q->tail + 1) % q->capacity;

    pthread_mutex_unlock(&q->lock);
    sem_post(&q->not_empty);
    return true;
}
```

5. `dequeue()` function for removing a record from the queue:

```c
Record* dequeue(struct Queue* q) {
    pthread_mutex_lock(&q->lock);

    // Check if the queue is empty and return NULL when it is.
    while (q->head == q->tail) {
        pthread_mutex_unlock(&q->lock);
        sem_wait(&q->not_empty);
        pthread_mutex_lock(&q->lock);
    }

    // Remove the record from the queue.
    Record* r = q->buf + (q->head);
    q->head = (q->head + 1) % q->capacity;

    pthread_mutex_unlock(&q->lock);
    return r;
}
