    context->num_failed_attempts = 0;
    pthread_mutex_init(&context->mutex, NULL);
}

// Function to handle a connection attempt and update the number of failed attempts accordingly
void handle_connection_attempt(LTE_RRC_ENB_UE_CONTEXT* context, bool success) {
    if (!success) {
        pthread_mutex_lock(&context->mutex);
        context->num_failed_attempts++;
        pthread_mutex_unlock(&context context->mutex);
    }
}

// Dynamic array management function using a linked list for scalability and memory efficiency
typedef struct NODE {
    LTE_RRC_ENB_UE_CONTEXT* context;
    struct NODE* next;
} NODE;

void add_ue_context(NODE** head, LTE_RRC_ENB_UE_CONTEXT* context) {
    if (*head == NULL) {
        *head = (NODE*)malloc(sizeof(NODE));
        (*head)->context = context;
        (*head)->next = NULL;
    } else {
        NODE* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = (NODE*)malloc(sizeof(NODE));
        current->next->context = context;
        current->next->next = NULL;
    }
}

// Function to remove a UE context from the dynamic array when it is no longer in use
void remove_ue_context(NODE** head, LTE_RRC_ENB_UE_CONTEXT* context) {
    if (*head == NULL) {
        return;
    }

    NODE* current = *head;
    NODE* prev = NULL;

    while (current != NULL && current->context != context) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        return;
    }

    if (prev == NULL) {
        *head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);
}
