#include <pthread.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

#define MAX_POOL_SIZE 1024
#define WINDOW_SIZE 64
#define BUFFER_SIZE (WINDOW_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T))

typedef struct {
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    size_t count;
    size_t head, tail;
    void* buffer;
} Pool;

typedef struct {
    void(*callback)(NFAPI_CRC_INDICATION_PDU_T*);
    struct callback* next;
} CallbackHandler;

struct callback {
    CallbackHandler handlers;
};

void nfapi_crc_indication_pdu_init(Pool* pool) {
    pool->buffer = malloc(BUFFER_SIZE);
    if (!pool->buffer) exit(-1);
    pthread_mutex_init(&pool->mutex, NULL);
    pthread_cond_init(&pool->cond, NULL);
    pool->head = pool->tail = 0;
    pool->count = 0;
}

void nfapi_crc_indication_pdu_push(Pool* pool, NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&pool->mutex);
    while (pool->count == MAX_POOL_SIZE) {
        pthread_cond_wait(&pool->cond, &pool->mutex);
    }
    memcpy((char*)(pool->buffer + pool->head), data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pool->head = (pool->head + 1) % BUFFER_SIZE;
    pool->count++;
    pthread_mutex_unlock(&pool->mutex);
}

void* nfapi_crc_indication_pdu_pop(Pool* pool, CallbackHandler callbacks, size_t num_callbacks) {
    void* ret;
    pthread_mutex_lock(&pool->mutex);
    while (pool->count == 0 && pool->head != pool->tail) {
        pthread_cond_wait(&pool->cond, &pool->mutex);
    }
    if (pool->count == 0) {
        ret = NULL;
    } else {
        ret = (char*)(pool->buffer + pool->tail);
        memcpy(ret, (char*)(pool->buffer + pool->head), sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pool->tail = (pool->tail + 1) % BUFFER_SIZE;
        pool->count--;
    }
    pthread_mutex_unlock(&pool->mutex);

    if (ret != NULL) {
        for (size_t i = 0; i < num_callbacks; ++i) {
            callbacks.callback(static_cast<NFAPI_CRC_INDICATION_PDU_T*>(ret));
            callbacks = callbacks.next;
        }
    }

    return ret;
}

void nfapi_crc_indication_pdu_destroy(Pool* pool) {
    free(pool->buffer);
    pthread_mutex_destroy(&pool->mutex);
    pthread_cond_destroy(&pool->cond);
}
