typedef void (*crypt_final)(EVP_MD_CTX *, unsigned char []);

void *get_func_ptr(const char *name, void *handle) {
    void *(*func)(...) = dlsym(handle, name);
    return func;
}

void populate_list(NFAPI_CRC_INDICATION_PDU_T **list, size_t n, uint32_t *rnti_arr, const char *crypto_lib) {
    void *handle = dlopen(crypto_lib, RTLD_NOW);
    if (!handle) return;

    crypt_init crypt_init_func = get_func_ptr("EVP_sha256", handle);
    crypt_update crypt_update_func = get_func_ptr("EVP_sha256_update", handle);
    crypt_final crypt_final_func = get_func_ptr("EVP_sha256_final", handle);

    *list = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    EVP_MD_CTX ctx;
    unsigned char digest[EVP_MAX_MD_SIZE];

    for (size_t i = 0; i < n; ++i) {
        if (!crypt_init_func(&ctx)) continue;
        EVP_SHA256(&ctx); // initialize context with zero padding

        EVP_MD_CTX *ctx_copy = malloc(sizeof(EVP_MD_CTX));
        memcpy(ctx_copy, &ctx, sizeof(EVP_MD_CTX));

        crypt_update_func(ctx_copy, (const unsigned char *)&rnti_arr[i], sizeof(uint32_t));
        crypt_final_func(ctx_copy, digest);

        NFAPI_CRC_INDICATION_PDU_T *entry = &(*list)[i];
        entry->rnti = rnti_arr[i];
        entry->crcflag = rand() % 2;
        memcpy(&entry->rx_ue_information_tag, digest, sizeof(RX_UE_INFORMATION_TAG));
        entry->crc_indication_rel8_tag.len = sizeof(digest);
        memcpy(entry->crypt_func, &crypt_init_func, sizeof(void *));

        if (i + 1 < n) {
            free(ctx_copy);
        } else {
            entry->crypt_func = malloc(sizeof(EVP_MD_CTX));
            memcpy(entry->crypt_func, &ctx, sizeof(EVP_MD_CTX));
        }
    }

    dlclose(handle);
}
