#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <pthread.h>

// Define the NFAPI_CRC_INDICATION_PDU_T structure here
typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the maximum number of elements in the array (for scalability)
#define MAX_ELEMENTS 10000

// Function to initialize pseudo-random number generator
void init_rand(unsigned int* seed) {
    time_t t;
    struct tm *now;

    // Seed with current time if seed is not provided
    if (!seed) {
        t = time(&t);
        now = localtime(&t);
        seed = (unsigned int*) malloc(sizeof(unsigned int));
        *seed = (now->tm_year + 1900) * 16817L * (now->tm_mon + 1) * 32375L + now->tm_mday;
    }
}

// Function to generate a pseudo-random number within the range [0, 1]
unsigned int rand_range(unsigned int* seed) {
    unsigned int temp = (*seed * 268582165 + 1);
    *seed = temp;
    return (temp & 0x7fffffff) / (1LL << 31);
}

// Function to manage the array of NFAPI_CRC_INDICATION_PDU_T structures
void manage_array(NFAPI_CRC_INDICATION_PDU_T*** array, unsigned int num_elements, unsigned int* seed) {
    // Initialize pseudo-random number generator with provided or default seed
    init_rand(seed);

    *array = (NFAPI_CRC_INDICATION_PDU_T**) malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    // Allocate and populate the array with unique tags and pseudo-random CRCFLAG values
    for (unsigned int i = 0; i < num_elements && i < MAX_ELEMENTS; ++i) {
        unsigned int tag = i;
        bool found_dup = false;

        // Ensure unique tags within the array
        for (unsigned int j = 0; j < i; ++j) {
            if ((*array)[j]->tag == tag) {
                found_dup = true;
                break;
            }
        }

        if (!found_dup) {
            // Allocate new structure and set its fields
            (*array)[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            (*array)[i]->tag = tag;
            (*array)[i]->rnti = (RNTI) i; // Assuming RNTI is an unsigned integer type
            (*array)[i]->crc_indication.CRCFLAG = rand_range(seed);
        }
    }
}

// Validation function to check the integrity of the populated array
bool validate_array(NFAPI_CRC_INDICATION_PDU_T* array, unsigned int num_elements) {
    // Track unique tags using a bitmask
    unsigned long tag_bitmask = 0;

    for (unsigned int i = 0; i < num_elements && i < MAX_ELEMENTS; ++i) {
        // Check for duplicate tags and out-of-range CRCFLAG values
        if ((tag_bitmask & (1 << array[i]->tag)) ||
            (array[i]->crc_indication.CRCFLAG != 0 && array[i]->crc_indication.CRCFLAG != 1)) {
            return false;
        }

        tag_bitmask |= (1 << array[i]->tag);
    }

    return true;
}
```

