    size_t capacity;
    size_t length;
    NicConfig** data;
    pthread_mutex_t lock;
} List;

List* list_create(size_t initial_capacity) {
    List* list = malloc(sizeof(List));
    if (!list) return NULL;

    list->data = calloc(initial_capacity, sizeof(NicConfig*));
    if (!list->data) {
        free(list);
        return NULL;
    }

    list->length = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void* nic_config_init(void* data) {
    NicConfig* config = data;
    config->status = 0;
    pthread_mutex_init(&config->lock, NULL);
    return NULL;
}

NicConfig* list_add(List* list) {
    if (list->length >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NicConfig** new_data = realloc(list->data, new_capacity * sizeof(NicConfig*));
        if (!new_data) return NULL;

        list->data = new_data;
        list->capacity = new_capacity;
    }

    NicConfig* config = list->data[list->length] = malloc(sizeof(NicConfig));
    if (!config) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    pthread_mutex_init(&config->lock, NULL);
    config->status = 0;

    list->length++;
    return config;
}

void list_delete(List* list, size_t index) {
    if (index >= list->length || index >= list->capacity) return;

    free(list->data[index]);
    for (size_t i = index + 1; i < list->length; ++i)
        list->data[i - 1] = list->data[i];

    list->length--;
}

