[" ```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    bool crcflag; // 1 if CRC flag is set, 0 otherwise
} NFAPI_CRC_INDICATION_PDU;

typedef struct NODE {
    NFAPI_CRC_INDICATION_PDU data;
    struct NODE* next;
    pthread_mutex_t mutex; // For thread safety
} NODE;

struct DYNAMIC_LIST {
    NODE* head;
    size_t size;
};

// Function to initialize the dynamic linked list with 'N' elements
int init_list(struct DYNAMIC_LIST* list, size_t N) {
    if (!list || N == 0) return -1; // Invalid input check

    list->head = NULL;
    list->size = 0;

    for (size_t i = 0; i < N; ++i) {
        NODE* newNode = malloc(sizeof(NODE));
        if (!newNode) return -2; // Memory allocation error

        newNode->data.rnti = (uint32_t)rand();
        newNode->next = list->head;
        list->head = newNode;
        ++list->size;
    }
    return 0;
}

// Function to insert a new element into the list with unique RNTI and valid tag
int add_element(struct DYNAMIC_LIST* list, const NFAPI_CRC_INDICATION_PDU_T* data) {
    if (!list || !data) return -1; // Invalid input check

    NODE* current = list->head;
    NODE* newNode = malloc(sizeof(NODE));
    if (!newNode) return -2; // Memory allocation error

    newNode->data = *data;
    newNode->next = NULL;

    while (current && current->data.rnti == newNode->data.rnti) {
        current = current->next;
    }

    if (!current) { // List empty or unique RNTI found, insert at the beginning
        newNode->next = list->head;
        list->head = newNode;
    } else { // Find appropriate position and insert after current
        newNode->next = current->next;
        current->next = newNode;
    }
    ++list->size;
    return 0;
}

// Function to remove an element from the list by RNTI (assuming unique RNTIs)
int remove_element(struct DYNAMIC_LIST* list, uint32_t rnti) {
    if (!list || !rnti) return -1; // Invalid input check

    NODE** current = &list->head;
    while (*current && ((*current)->data.rnti != rnti)) {
        current = &((*current)->next);
    }

    if (!(*current)) return -2; // RNTI not found

    NODE* temp = *current;
    *current = (*current)->next;
    free(temp);
    --list->size;
    return 0;
}

// Function to iterate over the list and apply a user-defined function to each element
void for_each(struct DYNAMIC_LIST* list, void(*func)(NFAPI_CRC_INDICATION_PDU_T*)) {
    if (!list || !func) return; // Invalid input check

    NODE* current = list->head;
    while (current) {
        func(&current->data);
        current = current->next;
    }
}

// Function to destroy the entire list and release resources
void destroy_list(struct DYNAMIC_LIST* list) {
    if (!list) return; // Invalid input check

    NODE* current = list->head;
    while (current) {
        NODE* temp = current;
        current = current->next;
        free(temp);
    }
    list->size = 0;
    list->head = NULL;
}
```

This implementation uses a singly-linked list with each node containing a mutex for thread safety. The init_list function initializes the list with unique RNTIs, and add_element ensures that only unique elements are added to the list. The remove_element function allows removing an element by its RNTI.

The for_each function provides an easy way to iterate over the list and apply user-defined functions to each element. Lastly, destroy_list releases all resources allocated during the life of the list.

