#include <memory>
#include <future>

class LTE_RRC_ENB_UE_CONTEXT {
public:
    std::atomic<uint64_t> attempt_count; // Track number of failed connection attempts for each UE context
    uint32_t ue_id;                     // Unique UE identifier
    uint32_t cell_id;                   // Cell identifier
    uint64_t timestamp;                // RRC connexion establishment request timestamp
};

class UE_CONTEXT_MANAGER {
public:
    void update(const LTE_RRC_ENB_UE_CONTEXT& context, bool success);
    void clean();
    void exportStateToFile();
private:
    std::map<uint32_t, std::unique_ptr<LTE_RRC_ENB_UE_CONTEXT>> contexts;
    std::mutex mtx;
    std::atomic<uint64_t> total_failed_attempts{0};
    std::condition_variable cv;
    std::chrono::steady_clock::time_point lastCleanupTime = std::chrono::steady_clock::now();

    void cleanupThread() {
        // Periodically clean up inactive UE contexts
        while (true) {
            std::unique_lock<std::mutex> lock(mtx);
            cv.wait_until(lock, lastCleanupTime + std::chrono::minutes(10), []() { return true; });

            auto it = contexts.begin();
            while (it != contexts.end()) {
                if (std::chrono::steady_clock::now() - it->second->timestamp > std::chrono::minutes(10)) {
                    total_failed_attempts += it->second->attempt_count;
                    it = contexts.erase(it);
                } else {
                    ++it;
                }
            }
            lastCleanupTime = std::chrono::steady_clock::now();
        }
    }
};
```

