    for (size_t i = 0; i < numPackets; ++i) {
        if (remainingBandwidth - packetHeaders[i].PayloadLength < 0) {
            free(packetHeaders);
            return NULL;
            // handle BANDWIDTH_EXCEEDED error here
        }

        remainingBandwidth -= packetHeaders[i].PayloadLength;
    }

    return packetHeaders;
}

int comparePayloadLength(const void* a, const void* b) {
    return (*(PacketHeader*)a).PayloadLength - (*(PacketHeader*)b).PayloadLength;
}
