struct CacheEntry {
    unsigned long hash;
    size_t index;
    pthread_mutex_t lock;
};

// Function prototypes
void initCache(size_t cacheSize);
NetworkFlow* getFlowFromCache(unsigned long hash);
void putFlowInCache(unsigned long hash, int FlowID, const char *SourceIP, const char *DestinationIP);

// Main function for initializing the dynamic array of NetworkFlow structures
void initDynamicArray(int *dynamicArraySize, NetworkFlow ***dynamicArray) {
    // Initialize cache with user-defined size and configure mutex for concurrent access
    initCache(*dynamicArraySize);

    // Allocate memory for the dynamic array and create a new array pointer
    *dynamicArray = (NetworkFlow **) mmap(NULL, sizeof(NetworkFlow) * (*dynamicArraySize), PROT_READ | PROT_WRITE, MAP_ANONYMOUS | MAP_SHARED, -1, 0);

    // Populate the array with unique FlowIDs and assign SourceIP and DestinationIP values
    for (int i = 0; i < *dynamicArraySize; ++i) {
        int j = i;
        while (true) {
            if (!getFlowFromCache(j)) {
                (*dynamicArray)[i].FlowID = j;
                snprintf((*dynamicArray)[i].SourceIP, sizeof((*dynamicArray)[i].SourceIP), "SourceIP%d", i);
                snprintf((*dynamicArray)[i].DestinationIP, sizeof((*dynamicArray)[i].DestinationIP), "DestIP%d", i);
                putFlowInCache(j, (*dynamicArray)[i].FlowID, (*dynamicArray)[i].SourceIP, (*dynamicArray)[i].DestinationIP);
                break;
            }
            ++j;
        }
    }
}

// Function for initializing the cache
void initCache(size_t cacheSize) {
    // Allocate memory for the hash table and create an array of CacheEntry structures
    size_t entriesPerBucket = 1024;
    size_t bucketCount = (cacheSize + entriesPerBucket - 1) / entriesPerBucket;
    struct CacheEntry *cache = malloc(sizeof(struct CacheEntry) * bucketCount);

    // Initialize each cache entry with a mutex and zeroed hash and index values
    for (size_t i = 0; i < bucketCount; ++i) {
        cache[i].hash = 0;
        cache[i].index = ~0ULL;
        pthread_mutex_init(&(cache[i].lock), NULL);
    }
}

// Function for looking up a FlowID in the cache
NetworkFlow* getFlowFromCache(unsigned long hash) {
    // Find the bucket index based on the hash value using a division method (e.g., Jenkins Hash)
    size_t index = hash % BUCKET_COUNT;

    struct CacheEntry *entry = &(cache[index]);
    pthread_mutex_lock(&(entry->lock));

    // If the cache entry contains a valid FlowID, return it; otherwise return NULL
    if (entry->hash != 0 && entry->index < BUCKET_SIZE) {
        NetworkFlow *flow = &((*dynamicArray)[entry->index]);
        if (hash == flow->FlowID) {
            pthread_mutex_unlock(&(entry->lock));
            return flow;
        }
    }
    pthread_mutex_unlock(&(entry->lock));
    return NULL;
}

// Function for adding a FlowID to the cache and updating the corresponding dynamic array entry
void putFlowInCache(unsigned long hash, int FlowID, const char *SourceIP, const char *DestinationIP) {
    // Find the bucket index based on the hash value using a division method (e.g., Jenkins Hash)
    size_t index = hash % BUCKET_COUNT;

    struct CacheEntry *entry = &(cache[index]);
    pthread_mutex_lock(&(entry->lock));

    // If the cache entry is empty, set its hash and index values and unlock the mutex
    if (entry->hash == 0) {
        entry->hash = hash;
        entry->index = 0;
        pthread_mutex_unlock(&(entry->lock));
        return;
    }

    // If the cache entry contains a valid FlowID, compare it to the new FlowID and update as needed
    NetworkFlow *flow = &((*dynamicArray)[entry->index]);
    if (hash == flow->FlowID) {
        strncpy(flow->SourceIP, SourceIP, sizeof(flow->SourceIP));
        strncpy(flow->DestinationIP, DestinationIP, sizeof(flow->DestinationIP));
        pthread_mutex_unlock(&(entry->lock));
    } else {
        // If the cache entry already contains a different FlowID, search for an empty slot in the dynamic array
        int i = 0;
        while (true) {
            if (!getFlowFromCache((*dynamicArray)[i].FlowID)) {
                NetworkFlow temp = (*dynamicArray)[i];
                temp.FlowID = FlowID;
                strncpy(temp.SourceIP, SourceIP, sizeof(temp.SourceIP));
                strncpy(temp.DestinationIP, DestinationIP, sizeof(temp.DestinationIP));

                (*dynamicArray)[i] = temp;
                entry->index = i;
                entry->hash = hash;

                // Notify other threads about the cache update (e.g., using a condition variable or signal)
                pthread_mutex_unlock(&(entry->lock));
                break;
            }
            ++i;
        }
    }
