    uint64_t PacketCount;
} NetworkFlow;

// Validate IP address (assumes already checked for uniqueness within array)
bool isValidIP(struct in_addr ip) {
    return (ip.s_addr != 0 && (ip.s_addr & ~((1 << (32 - sizeof(ip.s_addr)))) == 0));
}

// Validate NetworkFlow structure
bool validateNetworkFlow(const NetworkFlow* nf) {
    return isValidIP(nf->SourceIP) && isValidIP(nf->DestinationIP);
}

void initNetworkFlowArray(NetworkFlow** array, size_t numEntries, pthread_mutex_t* lock) {
    *array = malloc(numEntries * sizeof(NetworkFlow));

    if (!(*array)) {
        perror("Memory allocation failure");
        return;
    }

    for (size_t i = 0; i < numEntries; ++i) {
        pthread_mutex_init(&((*array)[i].lock), NULL);
        (*array)[i].FlowID = (uint32_t)(arc4random() & UINT32_MAX);
        (*array)[i].SourceIP.s_addr = 0;
        (*array)[i].DestinationIP.s_addr = 0;
    }
}

void processNetworkData(const char* data, NetworkFlow** array, size_t numEntries, pthread_mutex_t* lock) {
    char sourceIP[INET_ADDRSTRLEN], destinationIP[INET_ADDRSTRLEN];
    sscanf(data, "%s %s", sourceIP, destinationIP);

    for (size_t i = 0; i < numEntries; ++i) {
        pthread_mutex_lock(&((*array)[i].lock));

        if (isValidIP((struct in_addr){inet_addr(sourceIP)}) &&
            isValidIP((struct in_addr){inet_addr(destinationIP)})) {

            (*array)[i].SourceIP = (struct in_addr){inet_addr(sourceIP)};
            (*array)[i].DestinationIP = (struct in_addr){inet_addr(destinationIP)};
            pthread_mutex_unlock(&((*array)[i].lock));
            return;
        }

        pthread_mutex_unlock(&((*array)[i].lock));
    }
}
