class RandomValueGenerator {
private:
    int min_, max_;

public:
    explicit RandomValueGenerator(int min, int max) : min_(min), max_(max) {}

    float GenerateFloat() const {
        std::random_device seed;
        std::mt19937 generator(seed());
        std::uniform_real_distribution<float> distribution(min_, max_);
        return distribution(generator);
    }

    int GenerateInt() const {
        std::random_device seed;
        std::mt19937 generator(seed());
        std::uniform_int_distribution<int> distribution(min_, max_);
        return distribution(generator);
    }

    float Range() const { return static_cast<float>(max_ - min_); }

    std::string ToString() const {
        return "[" + std::to_string(min_) + ", " + std::to_string(max_) + ")";
    }
};

struct PacketHeader {
    uint32_t PayloadLength;
    uint32_t SourceAddress;
    uint32_t DestinationAddress;
};

class BandwidthLimitExceededException : public std::runtime_error {
public:
    explicit BandwidthLimitExceededException(const char* message) : std::runtime_error(message) {}
};

std::vector<PacketHeader> InitializePackets(int numPackets, uint32_t maxBandwidth, const RandomValueGenerator& generator) {
    std::vector<PacketHeader> packets;
    std::vector<uint32_t> payloadLengths;

    // Reserve memory to optimize for large arrays.
    packets.reserve(numPackets);
    payloadLengths.reserve(numPackets);

    uint32_t totalPayload = 0;

    for (size_t i = 0; i < numPackets; ++i) {
        uint32_t pl = static_cast<uint32_t>(generator.GenerateFloat() * generator.Range());
        payloadLengths.push_back(pl);

        totalPayload += pl;

        if (totalPayload > maxBandwidth) {
            throw BandwidthLimitExceededException("The sum of PayloadLengths exceeded the maximum bandwidth limit.");
        }

        packets.push_back({ pl, generator.GenerateInt(), generator.GenerateInt() });
    }

    return packets;
}
