// Maximum bandwidth limit (in bytes per second)
#define MAX_BANDWIDTH 1000000

// Structure for PacketHeader
typedef struct PacketHeader {
    size_t payloadLength;
    uint32_t sourceAddress;
    uint32_t destinationAddress;
} PacketHeader;

// Global variables for logging and synchronization
pthread_mutex_t logMutex = PTHREAD_MUTEX_INITIALIZER;
int failureCount = 0;
long long totalPayloadLength = 0;
sem_t memorySemaphore;

// Function to initialize dynamic array of PacketHeader structures
PacketHeader* initPackets(size_t numPackets, size_t bandwidthLimit) {
    // Calculate the maximum payload per packet based on the bandwidth limit
    double maxPayload = (double)bandwidthLimit / numPackets;

    // Allocate memory for the dynamic array and semaphore for memory management
    PacketHeader* packets = (PacketHeader*)malloc(numPackets * sizeof(PacketHeader));
    if (!packets) {
        printf("Error: Memory allocation failed.\n");
        return NULL;
    }
    sem_init(&memorySemaphore, 0, numPackets);

    // Initialize the packets with given payload length, source/destination addresses and handle bandwidth limit
    for (size_t i = 0; i < numPackets; ++i) {
        sem_wait(&memorySemaphore);

        // Calculate current available bandwidth for this packet
        double curBandwidth = maxPayload - (totalPayloadLength / numPackets);

        // Adjust payload length to fit the bandwidth limit if necessary
        size_t payload = (size_t)(curBandwidth > 0 ? curBandwidth : maxPayload);
        totalPayloadLength += payload;

        packets[i].payloadLength = payload;
        packets[i].sourceAddress = i + 1; // for simplicity, let's assume the source address is the packet index plus one
        packets[i].destinationAddress = (i + 1) % numPackets + 1; // cyclic destination addressing scheme
    }

    return packets;
}

// Logging function to record initialization failures and performance metrics
void logEvent(const char* event, int errorCode) {
    pthread_mutex_lock(&logMutex);

    if (errorCode != 0) {
        printf("Error: %s (ErrorCode: %d)\n", event, errorCode);
        failureCount++;
    } else {
        printf("%s\n", event);
    }

    pthread_mutex_unlock(&logMutex);
}
