    validateConfig(config);

    size_t N = json_integer_value(json_object_get(config, "N"));
    *len = N * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    *list = malloc(*len);
    if (*list == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        json_decref(config);
        return NULL;
    }

    pthread_mutex_lock(&json_mutex);
    srand((uint32_t)time(NULL));
    pthread_mutex_unlock(&json_mutex);

