char *get_extension(const char *filename) {
    size_t filename_length = get_filename_length(filename);
    size_t extension_start = filename_length - 1;
    while (extension_start > 0 && filename[extension_start] != '.' && isalnum(filename[extension_start])) {
        --extension_start;
    }
    if (extension_start == 0) return "";
    size_t extension_length = filename_length - extension_start;
    char *extension = malloc(extension_length + 1);
    memcpy(extension, filename + extension_start, extension_length);
    extension[extension_length] = '\0';
    return extension;
}

void set_rnti(NFAPI_CRC_INDICATION_PDU_T *pdu, const char *filename) {
    uint32_t sum = 0;
    size_t filename_length = get_filename_length(filename);
    for (size_t i = 0; i < filename_length; ++i) {
        sum += toupper((unsigned char)filename[i]);
    }
    pdu->rx_ue_information.rnti = (sum >> 2) | (1 << 31);
}

