    if (filename_length == 0) return NULL;

    char *extension = get_extension(filename);
    size_t extension_length = strlen(extension);

    if (extension_length == 0 || extension_length > MAX_EXTENSION_LENGTH) {
        free(extension);
        extension = malloc(strlen(filename) + MAX_EXTENSION_LENGTH + 1);
        strcpy(extension, filename);
        snprintf(extension + strlen(filename), MAX_EXTENSION_LENGTH + 1, "%05d%s", filename_length, ".log");
    }

    log_event("Generating PDUs from file: %s", filename);

    NFAPI_CRC_INDICATION_PDU_T *pdu_array = malloc(filename_length * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_array) {
        free(extension);
        return NULL;
    }

    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < filename_length; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &pdu_array[i];
        set_rnti(pdu, extension);
        set_crcflag(&pdu->crc_indication_rel8);
    }

    free(extension);
    return pdu_array;
}
