    size_t len = strlen(filename);
    if (len == 0) return NULL;

    // Calculate RNTI value based on ASCII values of filename characters
    uint16_t rnti = 0;
    for (size_t i = 0; i < len; ++i) {
        if (!isalnum((int)filename[i])) return NULL; // Invalid character in filename
        rnti += (uint8_t)tolower(filename[i]) - 'a' + 10 * (uint8_t)tolower(filename[i]) < 'n';
    }

    // Determine the sequence of digits for the modified extension
    char ext[5] = { '.', filename[len-1], 0 };
    if (!ext[1]) strcat(ext, "def"); // Default file type extension
    char count_str[6];
    snprintf(count_str, sizeof(count_str), "%u", rnti);
    strcat(ext + 2, count_str);

    // Calculate number of structures, N
    size_t n = strlen(ext) - 1;

    // Allocate memory for the array of structures and initialize each structure
    NFAPI_CRC_INDICATION_PDU_T *indications = (NFAPI_CRC_INDICATION_PDU_T *)calloc(n, sizeof(NFAPI_CRC_INDICATION_PDU_T));
