RXTABLE rxtable_create(size_t limit) {
    RXTABLE table = {.data = NULL, .size = 0, .capacity = 0, .lock = PTHREAD_MUTEX_INITIALIZER};
    table.data = calloc(limit, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!table.data) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    table.capacity = limit;
    return table;
}

void rxtable_free(RXTABLE* table) {
    free((*table).data);
    (*table).data = NULL;
}

bool is_unique(const NFAPI_CRC_INDICATION_PDU_T* element, const void* data, size_t index, size_t nmemb, void* userp) {
    const RXTABLE* table = (const RXTABLE*)userp;
    for (size_t i = 0; i < index; ++i) {
        if (table->data[i].rnti == element->rnti) {
            return false;
        }
    }
    return true;
}

size_t rxtable_add(RXTABLE* table, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    size_t new_capacity = table->capacity + 1;
    if (new_capacity <= table->size) {
        new_capacity *= 2;
    }
    NFAPI_CRC_INDICATION_PDU_T* new_data = realloc(table->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    table->data = new_data;
    table->capacity = new_capacity;

    pthread_mutex_lock(&table->lock);
    size_t index = 0;
    while (index < table->size && table->data[index].rnti != pdu->rnti) {
        ++index;
    }
    if (index == table->size) {
        table->data[index] = *pdu;
        table->checksum += pdu->crc_indication_rel8_tag;
        table->size++;
    }
    pthread_mutex_unlock(&table->lock);

    return index;
}

uint16_t rxtable_get_checksum(const RXTABLE* table) {
    return table->checksum;
}
