typedef struct mem_pool_s {
    void *memory;
    size_t size;
    size_t allocated;
    size_t num_structures;
    pthread_mutex_t lock;
    pthread_cond_t not_full, not_empty;
} MemPool;

MemPool* mem_pool_init(size_t structure_size) {
    MemPool *pool = malloc(sizeof(MemPool));
    pool->size = 1 << (32 - __builtin_lg((double)structure_size + sizeof(void*) * 2));
    pool->memory = mmap(NULL, pool->size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (pool->memory == MAP_FAILED) {
        free(pool);
        perror("mmap");
        exit(EXIT_FAILURE);
    }
    pool->allocated = 0;
    pool->num_structures = NUM_STRUCTURES;
    pool->lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_init(&pool->not_full, NULL);
    pthread_cond_init(&pool->not_empty, NULL);
    return pool;
}

NFAPI_CRC_INDICATION_PDU_T* mem_pool_acquire(MemPool *pool) {
    void *ptr = NULL;
    size_t structure_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    pthread_mutex_lock(&pool->lock);
    while (pool->allocated == pool->num_structures) {
        pthread_cond_wait(&pool->not_empty, &pool->lock);
    }
    if (pool->allocated + structure_size > pool->size) {
        void *new_memory = mmap(NULL, pool->size * 2, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (new_memory == MAP_FAILED) {
            pthread_mutex_unlock(&pool->lock);
            perror("mmap");
            exit(EXIT_FAILURE);
        }
        memmove(new_memory, pool->memory, pool->size);
        munmap(pool->memory, pool->size);
        pool->memory = new_memory;
        pool->size *= 2;
    }
    ptr = (char *)pool->memory + pool->allocated;
    memset(ptr, 0, structure_size);
    pool->allocated += structure_size;
    pthread_cond_signal(&pool->not_full);
    pthread_mutex_unlock(&pool->lock);
    return ptr;
}

void mem_pool_release(MemPool *pool, NFAPI_CRC_INDICATION_PDU_T *structure) {
    pthread_mutex_lock(&pool->lock);
    pthread_cond_signal(&pool->not_full);
    pthread_mutex_unlock(&pool->lock);
}

