// Thread-safe function to add a log entry to the logger.
bool add_log_entry(struct Logger* logger, struct LogEntry entry) {
    validate_log_entry(&entry, __func__);

    pthread_mutex_lock(&logger->lock);

    // Handle memory fragmentation by circularly iterating through entries array
    size_t next_index = (logger->head + 1) % MAX_LOG_ENTRIES;
    if ((next_index != logger->tail) || (logger->tail == SIZE_MAX)) {
        memcpy(&logger->entries[logger->head], &entry, sizeof(struct LogEntry));
        logger->head = next_index;
    } else {
        // Buffer overflow: drop or replace entries if full
        free(logger->entries);
        logger->entries = realloc(logger->entries, MAX_LOG_ENTRIES * 2 * sizeof(struct LogEntry));
        memcpy(&logger->entries[logger->head], &entry, sizeof(struct LogEntry));
        logger->head = next_index;
    }

    pthread_mutex_unlock(&logger->lock);
    return true;
}
