        pool[i].RX_UE_INFORMATION_TAG = rand() % 256;
        pool[i].RNTI = rand() % MAX_RNTI + MIN_RNTI;
        pool[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        pool[i].CRCFLAG = rand() % 3;
