    NFAPI_CRC_INDICATION_PDU* result = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU));
    if (!result) {
        fprintf(stderr, "Error: Failed to allocate memory for the requested number of elements\n");
        free(pool);
        return NULL;
    }

    // Use a duplicate detection mechanism based on hash table lookups
    pthread_mutex_t hash_table_mutex = PTHREAD_MUTEX_INITIALIZER;
    size_t hash_table_size = HASH_TABLE_SIZE;
    NFAPI_CRC_INDICATION_PDU* hash_table = calloc(hash_table_size, sizeof(NFAPI_CRC_INDICATION_PDU));
    if (!hash_table) {
        fprintf(stderr, "Error: Failed to allocate memory for the hash table\n");
        free(result);
        free(pool);
        return NULL;
    }

    // Implement a dynamic resizing strategy
    size_t current_size = 0;
    NFAPI_CRC_INDICATION_PDU* current_array = result;

    for (size_t i = 0; i < N; ++i) {
        pthread_mutex_lock(&pool_mutex);

        // Find a free structure in the pool
        size_t j;
        for (j = 0; j < POOL_SIZE; ++j) {
            if (!pool[j].RNTI) {
                break;
            }
        }

        if (j == POOL_SIZE) {
            // Pool is empty, resize the array and pool
            if (current_size + POOL_SIZE >= current_array + N * sizeof(NFAPI_CRC_INDICATION_PDU)) {
                NFAPI_CRC_INDICATION_PDU* new_result = realloc(current_array, (current_size + POOL_SIZE) * sizeof(NFAPI_CRC_INDICATION_PDU));
                if (!new_result) {
                    fprintf(stderr, "Error: Failed to resize the array\n");
                    pthread_mutex_unlock(&pool_mutex);
                    free(hash_table);
                    free(result);
                    free(pool);
                    return NULL;
                }

                current_array = new_result;
            }

            // Move the pool structures to the array
            memcpy(current_array + current_size, pool, POOL_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU));
            // Update the pool structures and unlock the mutex
            for (j = 0; j < POOL_SIZE; ++j) {
                pool[j].RNTI = 1;
            }
