bool is_valid_filename(const char *filename) {
    // Check for empty strings, excessively long filenames, invalid characters etc.
    if (!filename || strlen(filename) > 256 || strchr(filename, '/')) return false;

    char pattern[128];
    snprintf(pattern, sizeof(pattern), ".*[%s]*", filename);

