    int sequence_length = strlen(sequence);
    int base_filename_length = strlen(basename(original_filename));
    char modified_filename[256];

    if (base_filename_length + sequence_length > 256) {
        sequence_length = 256 - base_filename_length;
        sequence[sequence_length] = '\0';
    }

    snprintf(modified_filename, sizeof(modified_filename), "%s%s", original_filename, sequence);

    sem_post(&unique_files_semaphore);

    log_operation(original_filename, modified_filename, time(NULL));

    // Modify the file here based on the new filename (e.g., rename)

    return NULL;
}

void modify_filename(const char *filename) {
    if (!is_valid_filename(filename)) return;

    WorkItem work_item = { .filename = filename, .sem = PTHREAD_SEM_INITIALIZER };
    pthread_t thread;
    pthread_create(&thread, NULL, modify_filename_worker, &work_item);
}
