#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <sys/mman.h>

#define MAX_LIST_SIZE 1024
#define CRCFLAG_THRESHOLD 0x12345678

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct list {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} List;

List* create_list() {
    List* list = mmap(NULL, sizeof(List), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (list == MAP_FAILED) {
        perror("mmap failed");
        return NULL;
    }

    list->data = calloc(MAX_LIST_SIZE, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        perror("calloc failed");
        munmap(list, sizeof(List));
        return NULL;
    }

    list->size = 0;
    list->capacity = MAX_LIST_SIZE;
    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

void destroy_list(List* list) {
    free(list->data);
    munmap((void*)list, sizeof(List));
}

size_t find_empty_slot(const List* list) {
    for (size_t i = 0; i < list->capacity && list->size > i; ++i) {
        if (!list->data[i].tag.present || !list->data[i].crc_indication.present) {
            return i;
        }
    }

    return MAX_LIST_SIZE;
}

int push(List* list, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    size_t empty_slot = find_empty_slot(list);
    if (empty_slot == MAX_LIST_SIZE) {
        return -1; // List is full
    }

    pthread_mutex_lock(&list->mutex);

    list->data[empty_slot].tag = *pdu->tag;
    list->data[empty_slot].rnti = pdu->rnti;
    list->data[empty_slot].crc_indication.present = (pdu->crc_indication.value >= CRCFLAG_THRESHOLD);
    list->size++;

    pthread_mutex_unlock(&list->mutex);

    return 0; // Success
}

NFAPI_CRC_INDICATION_PDU_T* pop(List* list) {
    if (list->size == 0) {
        return NULL;
    }

    pthread_mutex_lock(&list->mutex);

    size_t first = 0;
    while (!list->data[first].tag.present || !list->data[first].crc_indication.present) {
        if (++first >= list->capacity) {
            first = 0;
        }
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = &list->data[first];
    memcpy(pdu, &list->data[first], sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->size--;

    pthread_mutex_unlock(&list->mutex);

    return pdu; // Success
}
