typedef struct MemoryPoolNode {
    void *memory;
    struct MemoryPoolNode *next;
} MemoryPoolNode;

struct MemoryPool {
    size_t capacity;
    size_t num_allocated;
    MemoryPoolNode *head;
    pthread_mutex_t mutex;
    sem_t semaphore;
};

void destroy_memory_pool(struct MemoryPool *pool) {
    while (pool->head != NULL) {
        MemoryPoolNode *temp = pool->head;
        pool->head = pool->head->next;
        free(temp->memory);
        free(temp);
    }
}

struct MemoryPool* create_memory_pool(size_t capacity, size_t alignment) {
    struct MemoryPool *pool = malloc(sizeof(struct MemoryPool));
    if (!pool) return NULL;
    pool->capacity = capacity;
    pool->num_allocated = 0;
    pool->head = NULL;
    pthread_mutex_init(&pool->mutex, NULL);
    sem_init(&pool->semaphore, 0, capacity);

    // Align the memory block for the pool header
    void *aligned_ptr = malloc(sizeof(struct MemoryPool) + alignment - 1) + (alignment - 1);
    aligned_ptr = (void *)(((size_t)aligned_ptr + alignment - 1) & ~(alignment - 1));

    pool->memory = mmap(aligned_ptr, capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (pool->memory == MAP_FAILED) {
        free(pool);
        return NULL;
    }

    return pool;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_from_memory_pool(struct MemoryPool *pool) {
    pthread_mutex_lock(&pool->mutex);
    sem_wait(&pool->semaphore);
    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *)((char *)pool->memory + pool->num_allocated * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pool->num_allocated++;
    pthread_mutex_unlock(&pool->mutex);

    return pdu;
}

void free_to_memory_pool(struct MemoryPool *pool, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&pool->mutex);
    pool->num_allocated--;
    pthread_mutex_unlock(&pool->mutex);
}

