    if (!*arr) {
        printf("Error: Failed to allocate memory for LTE_RRC_Reconfiguration array\n");
        return -1;
    }

    size_t used_sib_count = 0;
    for (size_t i = 0; i < num_configs; ++i) {
        (*arr)[i].c_rnti = c_rnti++; /* Increment CRNTI for each structure */
        (*arr)[i].cell_groups = malloc(cell_count * sizeof(MCG_CellGroupIdentity_t));
        if (!(*arr)[i].cell_groups) {
            printf("Error: Failed to allocate memory for cell_groups in configuration %zu\n", i);
            free(*arr);
            return -1;
