        memcpy((*arr)[i].cell_groups, cell_groups, cell_count * sizeof(MCG_CellGroupIdentity_t));

        /* Populate unique SIBs for each configuration */
        for (size_t j = 0; j < num_configs && used_sib_count < SIZE_MAX / num_configs; ++j) {
            if (i != j && (*arr)[i].configs[used_sib_count].si_type == (*arr)[j].configs[used_sib_count].si_type) {
                used_sib_count++;
                continue;
            }
            (*arr)[i].configs[used_sib_count].si_type = (used_sib_count % num_configs); /* Set a unique SIB type for each configuration */
            ++used_sib_count;
        }
    }

    return 0;
}
