struct NFAPI_CRC_INDICATION_PDU_T {
    unsigned short RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned short CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
};

class DynamicValueGenerator {
private:
    std::mt19937_64 rng;
    int minValue, maxValue;
    std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T[]> data;
    unsigned long long totalAllocations = 0;
    unsigned long long successfulAllocations = 0;
    std::ofstream logFile;
    enum class LogLevel { INFO, WARNING, ERROR };
    LogLevel logLevel = LogLevel::INFO;

public:
    DynamicValueGenerator(int min, int max, const std::string& logFilePath, LogLevel logLevel)
        : rng(std::chrono::steady_clock::now().time_since_epoch().count()), minValue(min), maxValue(max) {
        if (!logFile.open(logFilePath)) {
            throw std::runtime_error("Failed to open log file");
        }
    }

    void setLogLevel(LogLevel level) {
        logLevel = level;
    }

    float getRandomFloat() {
        std::uniform_real_distribution<> distribution(minValue, maxValue);
        return distribution(rng);
    }

    int getRandomInt() {
        std::uniform_int_distribution<> distribution(minValue, maxValue);
        return distribution(rng.get());
    }

    void allocateData(size_t count) {
        if (count == 0) throw std::invalid_argument("Count cannot be zero");
        data.reset(new NFAPI_CRC_INDICATION_PDU_T[count]);
        totalAllocations += count;
        for (auto& element : *data) {
            try {
                element.RX_UE_INFORMATION_TAG = static_cast<unsigned short>(getRandomInt());
                element.RNTI = getRandomInt();
                element.CRC_INDICATION_REL8_TAG = static_cast<unsigned short>(getRandomInt());
                element.CRCFLAG = getRandomInt() % 2 == 0;
                successfulAllocations++;
            } catch (...) {
                totalAllocations -= count;
                throw;
            }
        }
    }

    ~DynamicValueGenerator() {
        if (data) delete[] data.get();
    }

    void log(const std::string& message, LogLevel level = LogLevel::INFO) {
        if (level >= logLevel) {
            if (logFile.is_open()) {
                logFile << message << std::endl;
            }
            std::cout << message << std::endl;
        }
    }
};
