#include <string.h>

typedef struct {
    int ueId;
    char measurementTag[256];
    int *signalStrength;
    size_t signalStrengthSize;
    pthread_mutex_t mutex;
} UeMeasurementResult;

UeMeasurementResult* initializeAndManageMeasurements(size_t initialCapacity) {
    UeMeasurementResult *measurements = malloc(initialCapacity * sizeof(UeMeasurementResult));

    if (!measurements) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < initialCapacity; ++i) {
        measurements[i].ueId = -1;
        measurements[i].signalStrengthSize = 0;
        measurements[i].signalStrength = NULL;
        pthread_mutex_init(&measurements[i].mutex, NULL);
    }

    return measurements;
}

void resizeMeasurementArray(UeMeasurementResult *measurements, size_t currentCapacity, size_t newCapacity) {
    if (newCapacity <= currentCapacity) {
        return;
    }

    UeMeasurementResult *temp = malloc((newCapacity - currentCapacity) * sizeof(UeMeasurementResult));

    if (!temp) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }

    for (size_t i = currentCapacity; i < newCapacity; ++i) {
        measurements[i].ueId = -1;
        measurements[i].signalStrengthSize = 0;
        measurements[i].signalStrength = NULL;
        pthread_mutex_init(&measurements[i].mutex, NULL);
    }
}

void addMeasurement(UeMeasurementResult *measurements, size_t index, int ueId, const char *measurementTag, int signalStrengthSize, int *signalStrength) {
    pthread_mutex_lock(&measurements[index].mutex);

    if (measurements[index].ueId == -1) {
        measurements[index].ueId = ueId;
        strcpy(measurements[index].measurementTag, measurementTag);
        measurements[index].signalStrengthSize = signalStrengthSize;
        measurements[index].signalStrength = malloc(signalStrengthSize * sizeof(int));

        if (!measurements[index].signalStrength) {
            perror("malloc");
            exit(EXIT_FAILURE);
        }

        memcpy(measurements[index].signalStrength, signalStrength, signalStrengthSize * sizeof(int));
    } else {
        resizeMeasurementArray(measurements, index, measurements[index].signalStrengthSize + signalStrengthSize);

        memcpy(&measurements[index].signalStrength[measurements[index].signalStrengthSize], signalStrength, signalStrengthSize * sizeof(int));
    }

    pthread_mutex_unlock(&measurements[index].mutex);
}

void destroyMeasurement(UeMeasurementResult *measurements, size_t index) {
    pthread_mutex_lock(&measurements[index].mutex);

    if (measurements[index].signalStrength) {
        free(measurements[index].signalStrength);
        measurements[index].signalStrength = NULL;
    }

    pthread_mutex_unlock(&measurements[index].mutex);
}
