void aes_init(unsigned char *key, const unsigned char *password, unsigned int salt) {
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256_CTX ctx;
    SHA256_Init(&ctx);
    SHA256_Update(&ctx, password, strlen((char*)password));
    SHA256_Update(&ctx, &salt, sizeof(unsigned int));
    SHA256_Final(hash, &ctx);
    AES_keygen(RSA_F4, hash, key);
    AES_set_encrypt_key(key, AES_KEYSIZE_256, &key schedule);
}

void aes_encrypt(unsigned char *output, const unsigned char *input, size_t length) {
    AES_cbc_encrypt(input, output, length, key schedule, IV, AES_ENCRYPT);
}

NFAPI_CRC_INDICATION_PDU_T* generate_pdu(size_t n, const unsigned char *password, unsigned int salt) {
    aes_init(key, password, salt);
    NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) return NULL;

    for (size_t i = 0; i < n; ++i) {
