    struct list_node *next;
} ListNode;

static ListNode *head = NULL;
static unsigned long count = 0; // Number of entries in the list
pthread_mutex_t list_mutex; // For thread safety on list operations

void nfapi_crc_indication_pdu_init(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pdu->crc_indication.crcflag = rand() % 2;
