#define MAX_ELEMENTS 10000
static_assert(MAX_ELEMENTS >= 1, "Maximum number of elements must be greater than zero");

typedef struct _LIST {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t capacity;
    size_t count;
    sem_t mutex;
} LIST;

void list_init(LIST* list) {
    list->data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * MAX_ELEMENTS);
    if (!list->data) {
        fprintf(stderr, "Failed to allocate memory for list data\n");
        exit(1);
    }
    list->capacity = MAX_ELEMENTS;
    list->count = 0;
    sem_init(&list->mutex, 0, 1);
}

void push(LIST* list, const NFAPI_CRC_INDICATION_PDU_T* element) {
    sem_wait(&list->mutex);
    if (list->count >= list->capacity ||
        ((list->count > 0) && (element->CRCFLAG == list->data[list->count - 1].CRCFLAG))) {
        fprintf(stderr, "Failed to add element: List is full or consecutive elements have the same CRCFLAG\n");
        sem_post(&list->mutex);
        return;
    }
    memcpy(&list->data[list->count], element, sizeof(*element));
    list->count++;
    sem_post(&list->mutex);
}

void pop(LIST* list) {
    if (list->count == 0) {
        fprintf(stderr, "Failed to remove element: List is empty\n");
        return;
    }
    sem_wait(&list->mutex);
    size_t index = list->count - 1;
    list->count--;
    memcpy(list->data + index, list->data + index, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    sem_post(&list->mutex);
}

void reset(LIST* list) {
    if (list->count != 0) {
        memset(list->data, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T) * list->capacity);
        list->count = 0;
    }
