#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct MAC_PDU_T {
    unsigned int L2_PDU_TAG;
    unsigned int L2SDU_TAG;
    unsigned int payload_length;
    struct MAC_PDU_T *next;
    struct MAC_PDU_T *prev;
} MAC_PDU;

MAC_PDU* init_list(unsigned capacity) {
    if (capacity <= 0) return NULL;

    MAC_PDU* head = malloc(sizeof(MAC_PDU));
    if (!head) {
        perror("malloc error: ");
        return NULL;
    }

    head->next = head;
    head->prev = head;

    unsigned cur_capacity = 1;
    MAC_PDU* current = head;

    for (unsigned i = 1; i < capacity; ++i) {
        MAC_PDU* new_node = malloc(sizeof(MAC_PDU));
        if (!new_node) {
            perror("malloc error: ");
            return current->next; // Free previous nodes and exit
        }

        current->next = new_node;
        new_node->prev = current;
        new_node->next = head;
        head->prev = new_node;
        current = new_node;
        cur_capacity++;
    }

    return head->next;
}

void populate(MAC_PDU* list, unsigned min_payload, unsigned max_payload) {
    srand(time(NULL));

    MAC_PDU* current = list;

    while (current != list) {
        current->L2_PDU_TAG = rand();
        current->L2SDU_TAG = rand();
        current->payload_length = rand() % (max_payload - min_payload + 1) + min_payload;

        current = current->next;
    }
}

void resize(MAC_PDU** list, unsigned capacity) {
    if (capacity <= 0) return;

    MAC_PDU* new_list = init_list(capacity);
    if (!new_list) return; // Free previous nodes and exit

    MAC_PDU* current = *list;
    while (current != (*list)->next) {
        MAC_PDU* next = current->next;
        MAC_PDU* new_node = malloc(sizeof(MAC_PDU));
        if (!new_node) {
            perror("malloc error: ");
            // Free previously allocated nodes and exit
            return;
        }

        *new_node = *current;
        new_node->next = next;
        new_node->prev = current->prev;

        if (current->prev)
            current->prev->next = new_node;
        else
            new_list = new_node;

        current->prev = new_node;

