void init_list(struct List* list) {
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void add_to_list(struct List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    struct Node* new_node = malloc(sizeof(struct Node));
    if (!new_node) return;

    new_node->data = data;
    new_node->next = NULL;
    new_node->timestamp = time(NULL);

    pthread_mutex_lock(&list->lock);

    // Check if the list is full and remove least recently added element.
    if (list->size == MAX_LIST_SIZE) {
        struct Node* last = list->head;
        while (last->next && list->size > 1) {
            last = last->next;
            free(list->head);
            list->head = last->next;
            list->size--;
        }
    }

    // Add new element to the head of the list.
    new_node->next = list->head;
    list->head = new_node;
    list->size++;

