static pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;

void list_push(NFAPI_CRC_INDICATION_PDU_T data) {
    ListNode* new_node = (ListNode*)malloc(sizeof(ListNode));
    if (!new_node) {
        fprintf(stderr, "Error: Memory allocation failure\n");
        return;
    }

    new_node->data = data;
    new_node->next = NULL;

    pthread_mutex_lock(&list_lock);
    if (head == NULL) {
        head = new_node;
        tail = new_node;
    } else {
        tail->next = new_node;
        tail = new_node;
    }

    if ((unsigned int)(tail - head) >= MAX_CAPACITY && capacity < MAX_CAPACITY) {
        resize_list();
    }

    pthread_mutex_unlock(&list_lock);
}

void list_pop(NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&list_lock);
    if (head == NULL) {
        pthread_mutex_unlock(&list_lock);
        *data = (NFAPI_CRC_INDICATION_PDU_T){0};
        return;
    }

    ListNode* temp = head;
    head = head->next;
    if (head == NULL) tail = NULL;

    *data = temp->data;
    free(temp);

    pthread_mutex_unlock(&list_lock);
}

void resize_list() {
    ListNode* new_head = (ListNode*)malloc((capacity << 1) * sizeof(ListNode));
    if (!new_head) {
        fprintf(stderr, "Error: Memory allocation failure during resizing\n");
        return;
    }

    ListNode* iter = head;
    unsigned int index = 0;

    pthread_mutex_lock(&list_lock);
    while (iter != NULL) {
        new_head[index] = iter->data;
        new_head[(index + 1) & ((capacity << 1) - 1)] = iter->next ? iter->next : tail->data;
        index++;
        iter = iter->next;
    }

    head = new_head;
    tail = new_head + capacity;
    capacity <<= 1;
    pthread_mutex_unlock(&list_lock);
}
