typedef struct list_node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct list_node* next;
} list_node_t;

static sem_t cache_mutex;
static list_node_t* cache = NULL;
static size_t cache_size = 0;
static const size_t MAX_CACHE_SIZE = 1024;

void init_cache() {
    sem_init(&cache_mutex, 0, 1);
}

list_node_t* get_from_cache() {
    list_node_t* node;

    sem_wait(&cache_mutex);
    if (cache && cache_size > 0) {
        node = cache->next;
        cache->next = NULL;
        cache_size--;
    } else {
        node = NULL;
    }
    sem_post(&cache_mutex);

    return node;
}

void put_into_cache(list_node_t* node) {
    if (cache && cache_size >= MAX_CACHE_SIZE) {
        free(node);
    } else {
        sem_wait(&cache_mutex);
        node->next = cache;
        cache = node;
        if (!++cache_size > MAX_CACHE_SIZE) {
            sem_post(&cache_mutex);
        }
    }
}

