}

void manage_list(size_t max_entries, size_t* num_entries) {
    list_node_t* head = NULL;
    list_node_t* current = NULL;
    size_t threshold = *num_entries > max_entries ? max_entries : *num_entries;

    while (true) {
        list_node_t* new_entry = create_entry();
        if (!new_entry) {
            break; // Handle error or continue with an empty entry
        }

        if (head == NULL) {
            head = current = new_entry;
        } else {
            current->next = new_entry;
            current = new_entry;
        }

        (*num_entries)++;
        if ((*num_entries) >= threshold) {
            list_node_t* temp = get_from_cache();
            if (temp) {
                temp->data = *new_entry;
                free(new_entry);
            } else {
                current = head;
                while (current != NULL && (*num_entries) >= threshold) {
                    list_node_t* to_remove = current;
                    current = current->next;
                    free(to_remove);
                    (*num_entries)--;
                }
            }
        }
    }
}
