#include <openssl/aes.h>
#include <openssl/pbkdf2.h>
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <arpa/memory.h>

typedef struct {
    AES_KEY cipher;
    unsigned char iv[AES_BLOCK_SIZE];
} aes_context_t;

aes_context_t* aes_init(const char* passwd, size_t len) {
    EVP_PKEY *key;
    unsigned char kdf2_salt[EVP_MAX_KDF_SALT_SIZE];
    unsigned int kdf2_iter, key_len;

    if (len < 8 || len % 8 != 0) {
        fprintf(stderr, "Invalid password length\n");
        return NULL;
    }

    kdf2_iter = 10000; // Balance between computational overhead and security
    key_len = AES_KEYSIZE_256 / 8;

    if (NULL == (key = PBKDF2_init(NULL))) {
        perror("PBKDF2_init");
        return NULL;
    }

    if (1 != PBKDF2_pbkdf2(
            NULL,
            passwd, len, kdf2_salt, EVP_MAX_KDF_SALT_SIZE,
            kdf2_iter, EVP_sha256(), key_len, &key_len)) {
        perror("PBKDF2_pbkdf2");
        return NULL;
    }

    aes_context_t *ctx = malloc(sizeof(aes_context_t));
    if (!ctx) {
        perror("malloc");
        return NULL;
    }

    memset(ctx->iv, 0x00, AES_BLOCK_SIZE); // Generate secure IV

    if (1 != AES_set_key(&key->pkey.k_ecc, ctx->cipher.encrypt, ctx->iv)) {
        perror("AES_set_key");
        free(ctx);
        return NULL;
    }

    EVP_PKEY_free(key);
    return ctx;
}
