```c
void parse_and_store(const char* filename, int** records, size_t* count) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("fopen");
        return;
    }

    unsigned long long seed = chrono::steady_clock::now().time_since_epoch().count();
    srand((unsigned int)seed);

    size_t capacity = 1024, current = 0;
    *records = malloc(capacity * sizeof(int));
    if (!*records) {
        perror("malloc");
        fclose(file);
        return;
    }

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        int num = strtol(line, NULL, 10);
        if (num > INT_MAX || num < INT_MIN) continue; // Validation check

        (*records)[current++] = num;
        if (current == capacity) {
            capacity *= 2;
            *records = realloc(*records, capacity * sizeof(int));
            if (!*records) {
                perror("realloc");
                fclose(file);
                return;
            }
        }
    }

    *count = current;
    fclose(file);
}
