// Custom validation function for JSON fields
bool validateField(const std::string& fieldName, const Json::Value& json) {
    if (!json[fieldName].isString() || json[fieldName].asString().empty())
        return false;

    if (fieldName == "expires_in") {
        int expiresIn = json[fieldName].asInt();
        if (expiresIn <= 0)
            return false;
    } else if (fieldName == "refresh_token" && json["token_type"].asString() != "Refresh")
        return false;

    return true;
}

// Token validation function
bool validateToken(const std::string& tokenJson) {
    try {
        Json::CharReaderBuilder builder;
        Json::CharReaderPtr reader = builder.newCharReader();
        Json::Value json;
        std::istringstream iss(tokenJson);
        bool parsingSuccessful = reader->parse(iss, json, false);

        if (!parsingSuccessful || !json["access_token"].isString() || json["token_type"].asString() != "Bearer")
            return false;

        if (validateField("expires_in", json) && json.count("refresh_token")) {
            if (!validateField("refresh_token", json))
                return false;
        }

    } catch (const std::exception& e) {
        // Log the error and provide a fallback mechanism if possible
        std::cerr << "Error parsing JSON: " << e.what() << std::endl;
        return false;
    }

    return true;
}

// Function to log detailed information about each authentication attempt
void logAuthenticationAttempt(const std::string& tokenJson, bool isValid) {
    using namespace boost::posix_time;
    ptime currentTime = microsec_clock::local_time();

    std::stringstream ss;
    ss << currentTime << " - Token Validation: " << (isValid ? "Successful" : "Failed") << ": ";
    ss << tokenJson << std::endl;

    // Log the detailed information to a file or other logging mechanism
}

int main() {
    const std::string tokenResponse = "{ \"access_token\":\"abcdefg123\", \"expires_in\":456, \"token_type\":\"Bearer\", \"refresh_token\":\"hijklmnopqrstuvwxyz\" }";

    if (validateToken(tokenResponse)) {
        logAuthenticationAttempt(tokenResponse, true);
        std::cout << "The token is valid." << std::endl;
    } else {
        logAuthenticationAttempt(tokenResponse, false);
        std::cout << "The token is invalid." << std::endl;
    }

    return 0;
}
```

