typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
    semaphore_t cache_sem;
} CRCI_LIST_T;

CRCI_LIST_T* crci_list_init(size_t m) {
    CRCI_LIST_T* list = malloc(sizeof(CRCI_LIST_T));
    if (!list) return NULL;
    list->capacity = m;
    list->count = 0;
    list->data = calloc(m, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        return NULL;
    }
    pthread_mutex_init(&list->mutex, NULL);
    sem_init(&list->cache_sem, 0, m / 10); // 10% of capacity for caching
    return list;
}

bool crci_list_add(CRCI_LIST_T* list, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (list->count >= list->capacity) return false;

    // Find an available RNTI value within the capacity
    for (size_t i = 0; i < list->capacity; ++i) {
        size_t rnti = list->data[i].RNTI;
        if (!rnti || rnti == pdu->RNTI) {
            // RNTI is available or unique, use it for the new PDU
            list->data[list->count++] = *pdu;
            list->data[list->count - 1].RNTI = list->count;
            sem_post(&list->cache_sem); // Release the cached RNTI if available
            return true;
        }
    }

    return false; // No unique or available RNTIs found, failed to add PDU
}

NFAPI_CRC_INDICATION_PDU_T* crci_list_get(CRCI_LIST_T* list, uint16_t rnti) {
    if (!rnti || rnti > list->capacity) return NULL;

    // Lock the list to ensure thread safety
    pthread_mutex_lock(&list->mutex);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->data[i].RNTI == rnti) {
            // Found the requested RNTI, return its corresponding PDU
            NFAPI_CRC_INDICATION_PDU_T* pdu = &list->data[i];
            pthread_mutex_unlock(&list->mutex);
            return pdu;
        }
    }

    // RNTI not found, unlock the list and continue search with cached RNTIs
    pthread_mutex_unlock(&list->mutex);

    sem_wait(&list->cache_sem); // Wait for a cached RNTI to be released
    if (list->data[rnti - 1].RNTI == rnti) {
        // Found the requested RNTI in the cache, return its corresponding PDU
        NFAPI_CRC_INDICATION_PDU_T* pdu = &list->data[rnti - 1];
        sem_post(&list->cache_sem); // Release the cached RNTI after use
        return pdu;
    }

    return NULL; // RNTI not found in the cache, failed to get PDU
}

void crci_list_free(CRCI_LIST_T* list) {
    if (!list || !list->data) return;

    free(list->data);
    pthread_mutex_destroy(&list->mutex);
    sem_destroy(&list->cache_sem);
    free(list);
}
```

