void* custom_alloc(custom_allocator_t* allocator, size_t size) {
    if (allocator->used + size > allocator->allocated) {
        void* new_base = realloc(allocator->base, allocator->allocated * 2);
        if (!new_base) goto error;
        allocator->base = new_base;
        allocator->allocated *= 2;
    }
    void* result = (char*)allocator->base + allocator->used;
    allocator->used += size;
    return result;

error:
    fprintf(stderr, "Error allocating memory\n");
    return NULL;
}

void custom_free(custom_allocator_t* allocator, void* ptr) {
    if (!ptr || !allocator->base) return;
    allocator->used -= (char*)ptr - (char*)allocator->base;
