// LRU Cache for RNTIs
struct lru_cache {
    int cache[CACHE_SIZE];
    int head, tail, len;
};

struct mem_pool {
    void *mem;
    size_t size;
    struct lru_cache rnti_cache;
    pthread_mutex_t lock;
};

void init_mem_pool(struct mem_pool *pool) {
    pool->mem = mmap(NULL, M*sizeof(NFAPI_CRC_INDICATION_PDU_T), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANON, -1, 0);
    if (pool->mem == MAP_FAILED) {
        perror("mmap failed");
        exit(EXIT_FAILURE);
    }
    pool->size = M*sizeof(NFAPI_CRC_INDICATION_PDU_T);
    memset(&pool->rnti_cache, 0, sizeof(struct lru_cache));
    pthread_mutex_init(&pool->lock, NULL);
}

void* get_pdu(struct mem_pool *pool) {
    pthread_mutex_lock(&pool->lock);
    void *pdu = pool->mem;
    if (pool->rnti_cache.len == CACHE_SIZE) {
        int eviction_index = pool->rnti_cache.head;
        ((NFAPI_CRC_INDICATION_PDU_T*)(pud + sizeof(NFAPI_CRC_INDICATION_PDU_T) * eviction_index))->RNTI = 0;
        pool->rnti_cache.cache[eviction_index] = -1;
    }
    int index = (pool->rnti_cache.tail + 1) % M;
    while (((NFAPI_CRC_INDICATION_PDU_T*)(pud + sizeof(NFAPI_CRC_INDICATION_PDU_T)*index))->RNTI != 0) {
