    uint16_t rnti;
    uint32_t cii;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct thread_safe_queue {
    size_t capacity;
    size_t size;
    NFAPI_CRC_INDICATION_PDU_T* data;
    pthread_mutex_t lock;
    pthread_cond_t not_full;
    pthread_cond_t not_empty;
} thread_safe_queue_t;

void thread_safe_queue_init(thread_safe_queue_t* q, size_t capacity) {
    q->capacity = capacity;
    q->size = 0;
    q->data = (NFAPI_CRC_INDICATION_PDU_T*) malloc(q->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!q->data) {
        fprintf(stderr, "Failed to allocate memory for thread-safe queue\n");
        exit(EXIT_FAILURE);
    }
    q->lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_init(&q->not_full, NULL);
    pthread_cond_init(&q->not_empty, NULL);
}

void thread_safe_queue_push(thread_safe_queue_t* q, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&q->lock);
    while (q->size == q->capacity) {
        pthread_cond_wait(&q->not_full, &q->lock);
    }
    q->data[q->size++] = item;
    if (q->size == 1) {
        pthread_cond_signal(&q->not_empty);
    }
    pthread_mutex_unlock(&q->lock);
}

void thread_safe_queue_pop(thread_safe_queue_t* q, NFAPI_CRC_INDICATION_PDU_T* out) {
    pthread_mutex_lock(&q->lock);
    while (q->size == 0) {
        pthread_cond_wait(&q->not_empty, &q->lock);
    }
    *out = q->data[--q->size];
    if (q->size == q->capacity - 1) {
        pthread_cond_signal(&q->not_full);
    }
    pthread_mutex_unlock(&q->lock);
}

void populate_crc_indications(thread_safe_queue_t* queue, size_t num_elements) {
