    if (numOffsets > RAM_LIMIT || numRecords * sizeof(record) > RAM_LIMIT) {
        perror("Insufficient memory for requested configuration.\n");
        return NULL;
    }

    Container *container = malloc(sizeof(Container));
    if (!container) {
        perror("Failed to allocate container structure.\n");
        return NULL;
    }

    container->minValue = minValue;
    container->maxValue = maxValue;

    size_t numKeys = (numRecords > numOffsets) ? numOffsets : numRecords;

    container->offsets = malloc(numOffsets * sizeof(long));
    if (!container->offsets) {
        perror("Failed to allocate offsets array.\n");
        free(container);
        return NULL;
    }

    container->keys = malloc(numKeys * sizeof(int));
    if (!container->keys) {
