    if (!data || !is_rnti_unique(data->rnti)) return -1;

    pthread_mutex_lock(&list_lock);
    if (head == NULL) {
        head = create_node(data);
        if (!head) {
            pthread_mutex_unlock(&list_lock);
            return -1;
        }
    } else {
        node_t* current = head;
        while (current->next != NULL && current->next->rnti == data->rnti) current = current->next;
        if (current->next == NULL && current->rnti == data->rnti) {
            pthread_mutex_unlock(&list_lock);
            return -1;
        }
        node_t* new_node = create_node(data);
        if (!new_node) {
            pthread_mutex_unlock(&list_lock);
            return -1;
        }
        current->next = new_node;
    }
    pthread_mutex_unlock(&list_lock);
    return 0;
}

void delete_from_list(unsigned int rnti) {
    pthread_mutex_lock(&list_lock);
    node_t* current = head;
    node_t* previous = NULL;

    while (current != NULL && current->rnti == rnti) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&list_lock);
        return;
    }

    if (previous != NULL) previous->next = current->next;
    else head = current->next;

    free(current);
    pthread_mutex_unlock(&list_lock);
}
```

