#include <pthread.h>
#include <stdbool.h>

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct element {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct element* next;
} Element;

static Element* head = NULL;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static size_t size = 0, capacity = 1;

void add_element(NFAPI_CRC_INDICATION_PDU_T data) {
    Element* new_element = (Element*) malloc(sizeof(Element));

    if (!new_element) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    new_element->data = data;
    new_element->next = NULL;

    pthread_mutex_lock(&mutex);

    if (size == capacity) {
        Element** array = realloc(head, capacity * 2 * sizeof(Element*));

        if (!array) {
            fprintf(stderr, "Memory allocation failed\n");
            free(new_element);
            pthread_mutex_unlock(&mutex);
            return;
        }

        head = array;
        capacity *= 2;
    }

    new_element->next = head[size];
    head[size] = new_element;

    size++;

    pthread_mutex_unlock(&mutex);
}

void iterate(void (*func)(NFAPI_CRC_INDICATION_PDU_T)) {
    pthread_mutex_lock(&mutex);
    Element* current = head;

    for (size_t i = 0; i < size; ++i) {
        func(current->data);
        current = current->next;
    }

    pthread_mutex_unlock(&mutex);
}
```

