    NFAPI_CRC_INDICATION_PDU_T *list = malloc(max_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        fprintf(log_file, "Error: Failed to allocate memory\n");
        return NULL;
