    size_t current_structure = 0;
    uint16_t unique_tags[rnti_count];

    // Use bitmask for RNTI values to ensure uniqueness and efficient comparison
    unsigned long rnti_bitmask = (1 << rnti_count) - 1;

    while (current_structure < max_structures) {
        uint8_t rnti = 0;
