    struct node *next;
} node;

node* create_list(int size) {
    if (size <= 0 || size > 10000) {
        fprintf(stderr, "Invalid list size. Must be between 1 and 10000\n");
        return NULL;
    }

    node *head = malloc(sizeof(node));
    if (!head) {
        perror("Memory allocation failed.\n");
        return NULL;
    }

    head->data = malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU));
    if (!head->data) {
        perror("Memory allocation failed.\n");
        free(head);
        return NULL;
    }

    head->next = NULL;

    for (int i = 0; i < size; ++i) {
        NFAPI_CRC_INDICATION_PDU *pdu = &head->data[i];

        pdu->tag.value = (uint32_t)(rand() % UINT32_MAX);
        pdu->rnti = (uint32_t)(rand() % 0xFFFFFFFF);
        pdu->crc_indication.crcFlag = rand() % 2;

        if (pdu->crc_indication.crcFlag != 1 && pdu->crc_indication.crcFlag != 3) {
            fprintf(stderr, "Invalid CRCFLAG value: %d\n", pdu->crc_indication.crcFlag);
            continue;
        }

        if (i > 0) head = &head->next;
    }

    if (size % 2 == 1) qsort(head->data, size, sizeof(NFAPI_CRC_INDICATION_PDU), compare_fun);
    else shuffle_list(head->data, size);

    return head;
}

void shuffle_list(NFAPI_CRC_INDICATION_PDU *arr, int size) {
    srand((unsigned int)time(NULL));
    for (int i = 0; i < size - 1; ++i) {
        int j = rand() % (size - i) + i;
        swap(&arr[i], &arr[j]);
    }
}

void swap(NFAPI_CRC_INDICATION_PDU *a, NFAPI_CRC_INDICATION_PDU *b) {
    NFAPI_CRC_INDICATION_PDU temp = *a;
    *a = *b;
    *b = temp;
}

int compare_fun(const void *a, const void *b) {
    return (*(NFAPI_CRC_INDICATION_PDU *)a)->rnti - *(NFAPI_CRC_INDICATION_PDU *)b)->rnti;
}
