// Function to initialize a queue
Queue* queue_init(size_t capacity) {
    Queue *q = malloc(sizeof(Queue));
    q->data = malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    q->size = 0;
    q->capacity = capacity;
    pthread_mutex_init(&q->lock, NULL);
    return q;
}

// Function to add a structure to the queue
void queue_push(Queue* q, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&q->lock);
    if (q->size >= q->capacity) {
        // Resize the queue if it is full
        NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(q->data, (2 * q->capacity) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
