static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static size_t allocated_elements = 0;
static NFAPI_CRC_INDICATION_PDU_T *data = NULL;

void allocate_and_init(size_t n) {
    if (n <= allocated_elements) return;

    pthread_mutex_lock(&mutex);
    while ((data + n) - data > allocated_elements && !pthread_mutex_trylock(&mutex)) {
        // wait for lock and try again
    }

    if (data + n <= data + allocated_elements) {
        // already allocated, no reallocation needed
        allocated_elements = n;
    } else {
        NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(data, n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            fprintf(stderr, "Failed to allocate memory for %d elements\n", n);
            pthread_mutex_unlock(&mutex);
            return;
        }
        data = new_data;
        allocated_elements = n;
    }

    printf("Allocated %d elements for data processing\n", n);
    pthread_mutex_unlock(&mutex);

    // Initialize CRCFLAG with a random value to avoid identical CRC flags
    for (size_t i = allocated_elements - 1; i < n; ++i) {
        data[i].CRCFLAG = (rand() & 1) != 0;
    }
}

void free_data() {
    if (data == NULL || allocated_elements == 0) return;

    pthread_mutex_lock(&mutex);
    NFAPI_CRC_INDICATION_PDU_T *temp = data;
    data = NULL;
    allocated_elements = 0;
    free(temp);
    pthread_mutex_unlock(&mutex);
}
