    CRC_INDICATION_REL8_TAG crc_ind;
};

static LTE_DL_FRAME_TRANSPORT_CONTEXT* dl_ctx;
static size_t num_frames = 0;
static size_t max_pending_frames = 100;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t cond_var = PTHREAD_COND_INITIALIZER;
static int last_processed_frame = -1;
static bool self_healing_enabled = true;
static bool external_source_available = true;

void initialize_dl_ctx() {
    if (dl_ctx) return; // already initialized

    dl_ctx = malloc(max_pending_frames * sizeof(LTE_DL_FRAME_TRANSPORT_CONTEXT));
    if (!dl_ctx) {
        fprintf(stderr, "Failed to allocate memory for LTE DL context\n");
        return;
    }

    memset(dl_ctx, 0, max_pending_frames * sizeof(LTE_DL_FRAME_TRANSPORT_CONTEXT));
}

void process_frame(size_t idx) {
    // Populate structures with simulated data
    if (!external_source_available || !self_healing_enabled) {
        dl_ctx[idx].FRAME_NUMBER = idx;
        generate_random_srs_config(&dl_ctx[idx].srs_config);
        // ... populate other structures with random data
    } else {
        // Retrieve and validate data from external source
        if (!get_frame_data(idx, &dl_ctx[idx])) {
            fprintf(stderr, "Failed to retrieve frame data for index %zu\n", idx);
            // Implement fallback mechanisms here
        }
    }

    dl_ctx[idx].NFAPI_CRC_INDICATION_PDU_T.CRCFLAG = rand() % 2;
    // ... populate NFAPI_CRC_INDICATION_PDU_T with valid tag, RNTI, etc.
}

void manage_frames(void* arg) {
    size_t frame_rate_threshold = (size_t)(1000 * clock() / CLOCKS_PER_SEC);
    clock_t next_frame_update = clock();
    while (true) {
        pthread_mutex_lock(&mutex);
        if (!external_source_available) break; // Graceful degradation

        size_t num_pending_frames = num_frames - last_processed_frame;
        if (num_pending_frames >= max_pending_frames || clock() > next_frame_update) {
            next_frame_update += frame_rate_threshold * (1 + rand() / RAND_MAX * 2);
            process_frame(last_processed_frame + 1);
            last_processed_frame++;
            num_frames++;

            pthread_cond_signal(&cond_var);
        }
        pthread_mutex_unlock(&mutex);

        usleep(1000); // Adjust based on external scheduler intervals and performance constraints
    }
}

void enqueue_frame(LTE_DL_FRAME_TRANSPORT_CONTEXT* frame) {
    if (num_frames >= max_pending_frames) return;

    pthread_mutex_lock(&mutex);
    memcpy(&dl_ctx[num_frames], frame, sizeof(LTE_DL_FRAME_TRANSPORT_CONTEXT));
    num_frames++;
    pthread_mutex_unlock(&mutex);

    pthread_cond_signal(&cond_var);
}
