NFAPI_CRC_INDICATION_PDU_T* create_dynamic_array(size_t n) {
    if (n == 0) return NULL;

    NFAPI_CRC_INDICATION_PDU_T* data = (NFAPI_CRC_INDICATION_PDU_T*) calloc(n, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!data) {
        log("Memory allocation failed.");
        return NULL;
    }

    pthread_mutex_lock(&mutex);
    allocated_count += n;
    max_allocated_count = (max_allocated_count > allocated_count) ? max_allocated_count : allocated_count;
    pthread_mutex_unlock(&mutex);

    for (size_t i = 0; i < n; ++i) {
        data[i].RX_UE_INFORMATION_TAG = i + 1;
