#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define GROWTH_FACTOR 1.5 // Adjust this value based on estimated traffic patterns

typedef struct FrameBufferEntry {
    time_t timestamp;
    size_t packet_length;
    uint32_t checksum;
} FrameBufferEntry;

struct FrameBuffer {
    FrameBufferEntry* buffer;
    size_t capacity;
    size_t length;
};

void frame_buffer_init(struct FrameBuffer* buffer, size_t initial_size) {
    if (!buffer) return;

    buffer->capacity = initial_size;
    buffer->length = 0;
    buffer->buffer = malloc(initial_size * sizeof(FrameBufferEntry));

    if (!buffer->buffer) {
        fprintf(stderr, "Error: Failed to allocate memory for FrameBuffer\n");
        return;
    }
}

void frame_buffer_add(struct FrameBuffer* buffer, const FrameBufferEntry* entry) {
    if (!buffer || !entry) return;

    if (buffer->length >= buffer->capacity) {
        size_t new_capacity = buffer->capacity * GROWTH_FACTOR;
        FrameBufferEntry* temp_buffer = realloc(buffer->buffer, new_capacity * sizeof(FrameBufferEntry));

        if (!temp_buffer) {
            fprintf(stderr, "Error: Failed to reallocate memory for FrameBuffer\n");
            return;
        }

        buffer->buffer = temp_buffer;
        buffer->capacity = new_capacity;
    }

    buffer->buffer[buffer->length] = *entry;
    buffer->length++;
}

void frame_buffer_flush(struct FrameBuffer* buffer, const char* filename) {
    if (!buffer || !filename) return;

    FILE* file = fopen(filename, "w");

    if (!file) {
        fprintf(stderr, "Error: Failed to open output file for flushing\n");
        return;
    }

    // Implement data formatting and logging here based on the requirements of your existing logging framework.

    fclose(file);
}

void frame_buffer_destroy(struct FrameBuffer* buffer) {
    if (buffer->buffer) free(buffer->buffer);
}
```

This code defines a `FrameBufferEntry` structure and a `FrameBuffer` structure containing an array of `FrameBufferEntry` elements, along with the capacity and length of the buffer. The functions included are:

- `frame_buffer_init()` initializes the buffer with a given initial size.
- `frame_buffer_add()` adds a new entry to the buffer, ensuring that it scales dynamically without reallocating the entire array.
- `frame_buffer_flush()` allows for periodic flushing of the buffer contents to an external data source.
- `frame_buffer_destroy()` deallocates the memory used by the buffer.

The code makes some trade-offs in terms of memory efficiency and performance:

- The buffer is pre-allocated with a fixed growth factor, but this can be adjusted based on estimated traffic patterns.
- When adding new entries, if the current capacity is reached, the buffer will grow by a specified factor rather than reallocating the entire array each time. This improves performance at the cost of some additional memory usage.
- The average packet length calculation is not performed explicitly in this code; however, you can modify `frame_buffer_flush()` to calculate it based on your logging requirements.']

