typedef struct {
    unsigned char mac_header[6];
    uint16_t vlan_id;
    uint8_t eth_dst[6];
} NICB;

struct list_node {
    NICB *nicb;
    struct list_node *next;
};

typedef struct {
    pthread_mutex_t lock;
    struct list_node *head;
    size_t size;
} NICList;

void init_list(NICList *list) {
    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;
    list->size = 0;
}

void free_list(NICList *list) {
    struct list_node *node, *temp;
    pthread_mutex_lock(&list->lock);
    node = list->head;
    while (node != NULL) {
        temp = node;
        node = node->next;
        free(temp);
    }
    list->size = 0;
    pthread_mutex_unlock(&list->lock);
}

void add_nicb(NICList *list, const NICB *nicb) {
    struct list_node *node = malloc(sizeof(struct list_node));
    if (!node) return;

    node->nicb = malloc(sizeof(NICB));
    if (!node->nicb) {
        free(node);
        return;
    }

    memcpy(node->nicb, nicb, sizeof(NICB));
    node->next = list->head;
    pthread_mutex_lock(&list->lock);
    list->head = node;
    list->size++;
    pthread_mutex_unlock(&list->lock);
}

