#include <unistd.h>

#define MAX_CONNECTIONS 1024
#define RETRY_ATTEMPTS 8
#define BACKOFF_BASE 1000 // milliseconds
#define MEMORY_POOL_SIZE 64

typedef struct {
    SOCKET_DESCRIPTOR sd;
    struct sockaddr_in remote_addr;
    uint16_t local_port;
} TCP_CONNECTION_PDU_T;

TCP_CONNECTION_PDU_T* connection_pool[MAX_CONNECTIONS];
pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;

// Memory pool for efficient allocation and deallocation of TCP_CONNECTION_PDU_T structures
TCP_CONNECTION_PDU_T* connection_memory_pool[MEMORY_POOL_SIZE];
size_t memory_pool_head = 0;
size_t memory_pool_tail = 0;

// Function for initializing a TCP_CONNECTION_PDU_T structure and adding it to the connection pool
TCP_CONNECTION_PDU_T* create_connection(SOCKET_DESCRIPTOR sd, struct sockaddr_in remote_addr, uint16_t local_port) {
    TCP_CONNECTION_PDU_T* conn = NULL;

    if (memory_pool_head != memory_pool_tail) {
        conn = &connection_memory_pool[memory_pool_head];
        memcpy(conn, connection_memory_pool + memory_pool_tail, sizeof(TCP_CONNECTION_PDU_T));
        memory_pool_head = (memory_pool_head + 1) % MEMORY_POOL_SIZE;
    } else {
        conn = malloc(sizeof(TCP_CONNECTION_PDU_T));
        memset(conn, 0, sizeof(TCP_CONNECTION_PDU_T));
    }

    conn->sd = sd;
    conn->remote_addr = remote_addr;
    conn->local_port = local_port;

    pthread_mutex_lock(&pool_mutex);
    for (size_t i = 0; i < MAX_CONNECTIONS; ++i) {
        if (!connection_pool[i]) {
            connection_pool[i] = conn;
            break;
        }
    }
    pthread_mutex_unlock(&pool_mutex);

    return conn;
}

// Function for retrieving a connection from the pool, optionally initializing it if necessary
TCP_CONNECTION_PDU_T* get_connection(struct sockaddr_in remote_addr, uint16_t local_port) {
    TCP_CONNECTION_PDU_T* conn = NULL;

    pthread_mutex_lock(&pool_mutex);
    for (size_t i = 0; i < MAX_CONNECTIONS; ++i) {
        if (!connection_pool[i]) continue;

        if (connection_pool[i]->remote_addr.sin_addr.s_addr == remote_addr.sin_addr.s_addr &&
            connection_pool[i]->local_port == local_port) {

            conn = connection_pool[i];
            memset(&conn->remote_addr, 0, sizeof(struct sockaddr_in));
            break;
        }
    }
    pthread_mutex_unlock(&pool_mutex);

    if (!conn) {
        conn = create_connection(socket(AF_INET, SOCK_STREAM, IPPROTO_TCP), remote_addr, local_port);
    }

    return conn;
}

// Function for updating the connection status with the external network service and handling retries with exponential backoff
void update_connection_status(TCP_CONNECTION_PDU_T* conn) {
    int attempts = RETRY_ATTEMPTS;
    uint64_t backoff = BACKOFF_BASE;

    while (attempts > 0) {
        int response = send_status_update(conn->sd);

        if (response == 0) { // Success
            break;
        } else if (response < 0 && errno != EINTR && errno != EAGAIN) { // Transient error or other failure
            backoff *= 2;
            usleep(backoff);
        }

        --attempts;
    }
}

// Function for deallocating a connection, returning it to the memory pool if possible
void release_connection(TCP_CONNECTION_PDU_T* conn) {
    if (conn->sd >= 0) close(conn->sd);

    pthread_mutex_lock(&pool_mutex);
    for (size_t i = 0; i < MAX_CONNECTIONS; ++i) {
        if (connection_pool[i] == conn) {
            connection_pool[i] = NULL;
            break;
        }
    }
    pthread_mutex_unlock(&pool_mutex);

    if (memory_pool_head != memory_pool_tail) {
        memcpy(connection_memory_pool + memory_pool_tail, conn, sizeof(TCP_CONNECTION_PDU_T));
        memory_pool_tail = (memory_pool_tail + 1) % MEMORY_POOL_SIZE;
    } else {
        free(conn);
    }
}
```

