#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct FrameBufferEntry {
    time_t timestamp;
    size_t packet_length;
    uint32_t checksum;
} FrameBufferEntry;

struct FrameBuffer {
    FrameBufferEntry *buffer;
    size_t capacity;
    size_t length;
    size_t window_size;
    double moving_avg;
};

void init_frame_buffer(struct FrameBuffer *fb, size_t initial_capacity) {
    fb->buffer = malloc(initial_capacity * sizeof(FrameBufferEntry));
    if (!fb->buffer) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        exit(1);
    }

    fb->capacity = initial_capacity;
    fb->length = 0;
    fb->window_size = initial_capacity / 10; // Use a conservative estimate for window size
}

void free_frame_buffer(struct FrameBuffer *fb) {
    free(fb->buffer);
}

void grow_frame_buffer(struct FrameBuffer *fb) {
    if (fb->length >= fb->capacity * 3 / 4) { // Grow when the buffer is 75% full
        size_t new_capacity = fb->capacity * 2;
        FrameBufferEntry *new_buffer = realloc(fb->buffer, new_capacity * sizeof(FrameBufferEntry));
        if (!new_buffer) {
            fprintf(stderr, "Error: Memory reallocation failed.\n");
            exit(1);
        }
        fb->buffer = new_buffer;
        fb->capacity = new_capacity;
    }
}

void add_entry(struct FrameBuffer *fb, const FrameBufferEntry *entry) {
    if (!fb || !entry) return; // Handle null pointers gracefully

    grow_frame_buffer(fb);

    fb->buffer[fb->length] = *entry;
    fb->length++;
}

double calculate_moving_avg(struct FrameBuffer *fb) {
    if (fb->window_size > fb->length) return 0.0; // Handle window size larger than buffer length gracefully

    double sum = 0.0;
    for (size_t i = fb->length - fb->window_size; i < fb->length; ++i) {
        sum += fb->buffer[i].packet_length;
    }

    return sum / fb->window_size;
}

void log_entry(const struct FrameBufferEntry *entry, FILE *logfile) {
    // Implement logging format according to existing logging framework requirements
}

void flush_buffer(struct FrameBuffer *fb, FILE *logfile) {
    for (size_t i = 0; i < fb->length; ++i) {
        log_entry(&fb->buffer[i], logfile);
    }

    fb->length = 0; // Reset buffer length after flushing
}
