    unsigned short RNTI;
    CRC_INDICATION_REL8_TAG cInd;
};

std::vector<NFAPI_CRC_INDICATION_PDU_T> createArray(unsigned int N) {
    static std::mt19937 engine(std::random_device{}());
    static atomic_ullong baseTag{1}; // Base tag to start from
    static mutex tagsMutex; // Protect tags list access
    static std::list<unsigned long long> tagsList; // Store unique RX_UE_INFORMATION_TAGs

    if (tagsList.empty()) {
        for (auto i = 0u; i < N; ++i)
            tagsList.push_back(baseTag++);
    }

    std::vector<NFAPI_CRC_INDICATION_PDU_T> data;

    auto timestamps = std::chrono::steady_clock::now().time_since_epoch().count();

    for (auto i = 0u; i < N; ++i) {
        RX_UE_INFORMATION_TAG& rxi = data[i].rxi;
        auto currentTag = tagsList.front();
        std::lock_guard<std::mutex> lock(tagsMutex);
        rxi.tag = baseTag++;
        tagsList.pop_front();

        // Set remaining fields with thread-safe operations
        data[i].RNTI = i;
        data[i].cInd.CRCFLAG = (rand() % 2 == 0) ? true : false;
    }

    auto shuffleIndexes = [&data]() {
        for (auto i = N - 1; i > 0; --i) {
            auto j = rand() % i;
            std::swap(data[j], data[i]);
        }
    };

    // Shuffle array to ensure each element has an equal probability of being in any position
    shuffleIndexes();

    return data;
}

void deallocateArray(std::vector<NFAPI_CRC_INDICATION_PDU_T>& data) {
    // Empty list for unique tags to avoid memory leaks
    std::list<unsigned long long> emptyTagsList;
    std::lock_guard<std::mutex> lock(tagsMutex);
    std::move(tagsList.begin(), tagsList.end(), std::inserter(emptyTagsList, emptyTagsList.end()));
}
