typedef struct memory_block {
    size_t size;
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct memory_block *next;
} MEMORY_BLOCK;

static MEMORY_BLOCK *head = NULL;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static int log_fd = -1;

void* memory_pool_init() {
    if (log_fd == -1) {
        log_fd = open("memory.log", O_WRONLY | O_CREAT | O_APPEND, 0644);
    }

    return &head;
}

void* get_block(size_t size) {
    MEMORY_BLOCK *current, *new_block;

    pthread_mutex_lock(&mutex);

    if (head == NULL) {
        new_block = malloc(sizeof(MEMORY_BLOCK));
        if (!new_block) {
            fprintf(log_fd, "Memory allocation failed\n");
            pthread_mutex_unlock(&mutex);
            return NULL;
        }
        new_block->size = size;
        new_block->data = malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_block->data) {
            free(new_block);
            fprintf(log_fd, "Memory allocation failed\n");
            pthread_mutex_unlock(&mutex);
            return NULL;
        }
        new_block->next = head;
        head = new_block;
    } else {
        current = head;
        while (current->next && current->next->size >= size) {
            current = current->next;
        }

        if (current->next == NULL || current->next->size < size) {
            new_block = malloc(sizeof(MEMORY_BLOCK));
            if (!new_block) {
                fprintf(log_fd, "Memory allocation failed\n");
                pthread_mutex_unlock(&mutex);
                return NULL;
            }
            new_block->size = size;
            new_block->data = malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!new_block->data) {
                free(new_block);
                fprintf(log_fd, "Memory allocation failed\n");
                pthread_mutex_unlock(&mutex);
                return NULL;
            }
            new_block->next = current->next;
            current->next = new_block;
        }
    }

    pthread_mutex_unlock(&mutex);

    // Initialize the structures
    NFAPI_CRC_INDICATION_PDU_T *pdus = head->data;
    for (size_t i = 0; i < size; ++i) {
        pdus[i].rx_ue_info.tag = RX_UE_INFORMATION_TAG_INITIAL_VALUE;
        pdus[i].rnti = RNTI_INITIAL_VALUE;
        pdus[i].crc_indication.crcflag = rand() % 2;
    }

    return head;
}

void free_block(void *data) {
    MEMORY_BLOCK *current, *temp;

    pthread_mutex_lock(&mutex);

    current = head;
    while (current != NULL) {
        if (current == data) {
            temp = current->next;
            free(current->data);
            free(current);
            head = temp;
            break;
        } else {
            current = current->next;
        }
    }

    pthread_mutex_unlock(&mutex);
}
