typedef struct _NFAPI_CRC_INDICATION_COLLECTION {
    size_t capacity;
    size_t count;
    NFAPI_CRC_INDICATION_PDU_T* data;
    pthread_mutex_t mutex;
    pthread_cond_t not_full;
    pthread_cond_t not_empty;
    int sliding_window_size;
} NFAPI_CRC_INDICATION_COLLECTION;

void init_collection(NFAPI_CRC_INDICATION_COLLECTION* collection, size_t capacity, int sliding_window_size) {
    collection->capacity = capacity;
    collection->count = 0;
    collection->data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * capacity);
    collection->sliding_window_size = sliding_window_size;
    pthread_mutex_init(&collection->mutex, NULL);
    pthread_cond_init(&collection->not_full, PTHREAD_COND_INITIALIZER);
    pthread_cond_init(&collection->not_empty, PTHREAD_COND_INITIALIZER);
}

bool enqueue(NFAPI_CRC_INDICATION_COLLECTION* collection, const NFAPI_CRC_INDICATION_PDU_T* element) {
    bool success = false;
    pthread_mutex_lock(&collection->mutex);

    if (collection->count < collection->capacity) {
        memcpy(collection->data + collection->count, element, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        ++collection->count;
        success = true;

        // Wake up any waiting threads if the queue is no longer full.
        pthread_cond_signal(&collection->not_full);
    } else {
        // If the collection is full, wait for another thread to dequeue an element and then try again.
        pthread_cond_wait(&collection->not_empty, &collection->mutex);
    }

    pthread_mutex_unlock(&collection->mutex);
    return success;
}

bool dequeue(NFAPI_CRC_INDICATION_COLLECTION* collection, NFAPI_CRC_INDICATION_PDU_T* element) {
    bool success = false;
    pthread_mutex_lock(&collection->mutex);

    if (collection->count > 0) {
        --collection->count;
        memcpy(element, collection->data + collection->count, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        success = true;

        // Wake up any waiting threads if an element has been dequeued.
        pthread_cond_signal(&collection->not_empty);
    } else {
        // If the collection is empty, wait for another thread to enqueue an element and then try again.
        pthread_cond_wait(&collection->not_full, &collection->mutex);
    }

    pthread_mutex_unlock(&collection->mutex);
    return success;
}
