typedef struct node {
    NFAPI_CRUC_INDICATION_PDU_T data;
    struct node *next;
} node_t;

struct pool {
    size_t capacity;
    node_t **pool;
    pthread_mutex_t lock;
};

void init_pool(struct pool *p, size_t capacity) {
    p->capacity = capacity;
    p->pool = calloc(1 + p->capacity, sizeof(node_t*));
    for (size_t i = 0; i < p->capacity; ++i) {
        p->pool[i] = NULL;
    }
    pthread_mutex_init(&p->lock, NULL);
}

node_t *allocate(struct pool *p) {
    pthread_mutex_lock(&p->lock);
    for (size_t i = 0; i < p->capacity; ++i) {
        if (p->pool[i] == NULL) {
            p->pool[i] = malloc(sizeof(node_t));
            if (p->pool[i] == NULL) {
                pthread_mutex_unlock(&p->lock);
                break;
            }
            memset(p->pool[i], 0, sizeof(node_t));
            p->pool[i]->next = NULL;
            pthread_mutex_unlock(&p->lock);
            return p->pool[i];
        }
    }
    pthread_mutex_unlock(&p->lock);
    return calloc(1, sizeof(node_t));
}

void free_node(struct pool *p, node_t *n) {
    if (n == NULL) return;
    pthread_mutex_lock(&p->lock);
    for (size_t i = 0; i < p->capacity; ++i) {
        if (p->pool[i] == NULL) {
            p->pool[i] = n;
            pthread_mutex_unlock(&p->lock);
            break;
        }
    }
    free(n);
    pthread_mutex_unlock(&p->lock);
}

void free_pool(struct pool *p) {
    for (size_t i = 0; i < p->capacity; ++i) {
        node_t* n = p->pool[i];
        while (n != NULL) {
            node_t *tmp = n;
            n = n->next;
            free(tmp);
        }
    }
    free(p->pool);
}

