void addPDU(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (pdus.size >= pdus.capacity) {
        pdus.capacity *= 2;
        pdus.list = realloc(pdus.list, pdus.capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    }

    pthread_mutex_lock(&pdus.mutex);
    bool foundDuplicate = false;
    for (size_t i = 0; i < pdus.size; ++i) {
        if ((*(pdus.list[i])).RX_UE_INFORMATION_TAG == pdu->RX_UE_INFORMATION_TAG &&
            *(pdus.list[i])->RNTI == pdu->RNTI) {
            foundDuplicate = true;
            break;
        }
    }
    if (!foundDuplicate) {
        *(pdus.list[pdus.size]) = pdu;
        ++pdus.size;
    }
    pthread_mutex_unlock(&pdus.mutex);
}

void serializePDUs() {
    if (storageFile == NULL) {
        log_error("Storage file not initialized");
        return;
    }

    for (size_t i = 0; i < pdus.size; ++i) {
