NFAPI_CRCI_PDU_T* create_nfapi_crc_indication_pdu(unsigned int n) {
    NFAPI_CRCI_PDU_T *pdus = malloc(n * sizeof(NFAPI_CRCI_PDU_T));
    if (!pdus) {
        perror("Memory allocation failed");
        return NULL;
    }

    for (unsigned int i = 0; i < n; ++i) {
        pdus[i].rnti = rand() % 65536; // Ensure RNTI values are within the valid range (0 to 65535)
        pdus[i].crc_flag = rand() % 2; // Randomly set CRCFLAG
        pdus[i].rx_ue_information_tag = i + 1;
    }

    pthread_mutex_lock(&mutex);

    for (unsigned int i = 0; i < n; ++i) {
        for (unsigned int j = 0; j < MAX_CRC_INDICATIONS && i * MAX_CRC_INDICATIONS + j < n; ++j) {
            pdus[i * MAX_CRC_INDICATIONS + j].crc_indication_rel8_tag[j % MAX_CRC_INDICATIONS] = rand() % 65536; // Set CRC_INDICATION_REL8_TAG values within the valid range (0 to 65535)
        }
        pthread_mutex_unlock(&mutex);
        pthread_mutex_lock(&mutex);
    }

    pthread_mutex_unlock(&mutex);

    return pdus;
}
