NR_RRC_SIB1_MESSAGE* messages = NULL;
struct logging_data* log_data = NULL;

void init_logging(FILE* file) {
    if (!log_data) {
        log_data = malloc(sizeof(struct logging_data));
        log_data->log_file = file;
    }
}

void log_event(const char* message) {
    if (log_data) {
        fprintf(log_data->log_file, "%s\n", message);
    }
}

void initialize_sib1_messages() {
    if (!messages) {
        messages = malloc(max_messages * sizeof(NR_RRC_SIB1_MESSAGE));
        if (!messages) {
            log_event("Failed to allocate memory for SIB1 messages.");
            return;
        }

        sem_init(&messages_mutex, 0, 1);
    }
}

void add_sib1_message(NR_RRC_SIB1_MESSAGE* msg) {
    if (!messages) {
        log_event("Trying to add SIB1 message before initialization.");
        return;
    }

    sem_wait(&messages_mutex);

    if (sizeof(messages) / sizeof(NR_RRC_SIB1_MESSAGE) == max_messages) {
        NR_RRC_SIB1_MESSAGE* new_messages = realloc(messages, (max_messages + 10) * sizeof(NR_RRC_SIB1_MESSAGE));
        if (!new_messages) {
            log_event("Failed to resize SIB1 messages array.");
            sem_post(&messages_mutex);
            return;
        }

        max_messages += 10;
        messages = new_messages;
    }

    memcpy(messages + (sizeof(messages) / sizeof(NR_RRC_SIB1_MESSAGE) - 1), msg, sizeof(NR_RRC_SIB1_MESSAGE));

    sem_post(&messages_mutex);
}

void update_cell_id(CELL_GLOBAL_ID new_cell_id) {
    if (!messages) {
        log_event("Trying to update cell ID before initialization.");
        return;
    }

    for (int i = 0; i < (sizeof(messages) / sizeof(NR_RRC_SIB1_MESSAGE)); ++i) {
        messages[i].cell_id = new_cell_id;
    }
}
