typedef struct NetworkDataPacket {
    time_t timestamp;
    unsigned int id;
    size_t payload_size;
} NetworkDataPacket;

struct NetworkDataPacketQueue {
    NetworkDataPacket** data;
    size_t capacity;
    size_t count;
};

void network_packet_queue_init(struct NetworkDataPacketQueue* q, size_t initial_capacity) {
    q->data = malloc(initial_capacity * sizeof(NetworkDataPacket*));
    if (!q->data) {
        fprintf(stderr, "Failed to allocate memory for packet queue\n");
        exit(1);
    }
    q->capacity = initial_capacity;
    q->count = 0;
}

void network_packet_queue_add(struct NetworkDataPacketQueue* q, const NetworkDataPacket* packet) {
    if (q->count == q->capacity) {
        q->capacity *= 2;
        q->data = realloc(q->data, q->capacity * sizeof(NetworkDataPacket*));
        if (!q->data) {
            fprintf(stderr, "Failed to reallocate memory for packet queue\n");
            exit(1);
        }
    }
    q->data[q->count++] = malloc(sizeof(NetworkDataPacket));
    if (!q->data[q->count - 1]) {
        fprintf(stderr, "Failed to allocate memory for packet data\n");
        exit(1);
    }
    memcpy(q->data[q->count - 1], packet, sizeof(NetworkDataPacket));
}

bool network_packet_queue_remove(struct NetworkDataPacketQueue* q, unsigned int id) {
    for (size_t i = 0; i < q->count; ++i) {
        if (q->data[i]->id == id) {
            NetworkDataPacket* packet = q->data[i];
            memmove(q->data + i, q->data + i + 1, --q->count - i);
            free(packet);
            return true;
        }
    }
    return false;
}

const NetworkDataPacket* network_packet_queue_get(const struct NetworkDataPacketQueue* q, unsigned int id) {
    for (size_t i = 0; i < q->count; ++i) {
        if (q->data[i]->id == id) {
            return q->data[i];
        }
    }
    return NULL;
}

void network_packet_queue_clear(struct NetworkDataPacketQueue* q) {
    for (size_t i = 0; i < q->count; ++i) {
        free(q->data[i]);
    }
    q->count = 0;
}

void network_packet_queue_statistics(const struct NetworkDataPacketQueue* q) {
    size_t total_payload_size = 0;
    unsigned int packet_count = 0;
    unsigned int max_payload_size = 0;

    for (size_t i = 0; i < q->count; ++i) {
        if (q->data[i]->payload_size > max_payload_size) {
            max_payload_size = q->data[i]->payload_size;
        }
        total_payload_size += q->data[i]->payload_size;
        packet_count++;
    }

    printf("Total packets: %u\n", packet_count);
    printf("Average payload size: %.2f\n", (double)total_payload_size / packet_count);
    printf("Maximum payload size: %u\n", max_payload_size);
}
