typedef struct {
    time_t timestamp;
    unsigned int id;
    size_t payloadSize;
} NetworkDataPacket;

NetworkDataPacket* createNetworkDataPacket(time_t ts, unsigned int id, size_t payloadSize) {
    NetworkDataPacket *np = malloc(sizeof(NetworkDataPacket));
    if (!np) return NULL;
    np->timestamp = ts;
    np->id = id;
    np->payloadSize = payloadSize;
    return np;
}

void destroyNetworkDataPacket(NetworkDataPacket *np) {
    free(np);
}

void addPacket(NetworkDataPacket **array, size_t *size, unsigned int id, NetworkDataPacket *packet) {
    *size += 1;
    *array = realloc(*array, (*size)*sizeof(NetworkDataPacket));
    if (!*array) return;
    memcpy((*array + (*size - 1)), packet, sizeof(NetworkDataPacket));
}

void removePacketById(NetworkDataPacket **array, size_t *size, unsigned int id) {
    for (size_t i = 0; i < *size; ++i) {
        if ((*array + i)->id == id) {
            memmove((*array + i), (*array + i + 1), (sizeof(NetworkDataPacket) * (*size - (i+1))));
            *size -= 1;
            break;
        }
    }
}

void updatePacketById(NetworkDataPacket **array, size_t *size, unsigned int id, NetworkDataPacket newPacket) {
    for (size_t i = 0; i < *size; ++i) {
        if ((*array + i)->id == id) {
            memcpy((*array + i), &newPacket, sizeof(NetworkDataPacket));
            break;
        }
    }
}

void getStats(const NetworkDataPacket *const *array, size_t size, double *avgPayloadSize) {
    size_t sumPayloadSize = 0;
    *avgPayloadSize = 0.0;

    for (size_t i = 0; i < size; ++i)
        sumPayloadSize += (*array + i)->payloadSize;

    if (size > 0)
        *avgPayloadSize = (double)sumPayloadSize / size;
}
