#include <time.h>

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

#define HASH_MODULO 1000003 // A large prime number for collision resistance and performance.

void set_seed(unsigned long seed) {
    srand(seed);
}

long hash(long x, long y) {
    long result = x + (y * HASH_MODULO);
    return result < 0 ? -result : result;
}

NFAPI_CRC_INDICATION_PDU_T* init_pdu_array(size_t N, unsigned long seed) {
    set_seed(seed);

    NFAPI_CRC_INDICATION_PDU_T *pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        perror("Memory allocation failed");
        return NULL;
    }

    for (size_t i = 0; i < N; ++i) {
        pdus[i].tag = (RX_UE_INFORMATION_TAG)(i + 1); // Ensure uniqueness within the same allocation.
        pdus[i].rnti = (RNTI)(rand() % UINT32_MAX);
        pdus[i].crc_indication.CRCFLAG = hash(pdus[i].tag, pdus[i].rnti);
    }

    return pdus;
}
```

