        if (it != packets_.end()) {
            --avgPayload_;
            it->payloadSize = newPayloadSize;
            avgPayload_ += newPayloadSize;
            logQueue_.enqueue(std::make_unique<LogEntry>(LogEntry::Type::Update, *it, std::chrono::system_clock::now()));
        }
