    return newCache;
}

bool insertData(Cache* cache, const char *symbol, double bid, double ask) {
    if (cache->size >= cache->capacity) {
        // Cache is full. Handle eviction strategy here.
        // For simplicity, we'll remove the least recently used element.
        cacheNode *leastRecentlyUsed = NULL;
        pthread_mutex_lock(&cache->lock);
        if (cache->head != NULL) {
            leastRecentlyUsed = cache->head;
            cache->head = cache->head->next;
            while(leastRecentlyUsed->next != NULL) {
                leastRecentlyUsed = leastRecentlyUsed->next;
            }
        }
        pthread_mutex_unlock(&cache->lock);

        free(leastRecentlyUsed->data.symbol);
        free(leastRecentlyUsed);
