    if (cache->head == NULL) {
        cache->head = newNode;
    } else {
        cacheNode *current = cache->head;
        while(current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }
    pthread_mutex_unlock(&cache->lock);

    ++cache->size;
    return true;
