            NFAPI_CRC_INDICATION_PDU_T* foundData = &current->data;
            pthread_mutex_unlock(&cache->lock);
            return foundData;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&cache->lock);

    // Not found in cache.
    return NULL;
